fn read_all_available(peer: &mut impl TestPeer) -> Vec<u8> {
    peer.set_nonblocking(true).expect("set_nonblocking");
    let mut out = Vec::new();
    let mut buf = [0u8; 512];
    loop {
        match peer.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => out.extend_from_slice(&buf[..n]),
            Err(err) if err.kind() == io::ErrorKind::WouldBlock => break,
            Err(err) => panic!("read failed: {err}"),
        }
    }
    peer.set_nonblocking(false).expect("unset_nonblocking");
    out
}

fn read_all_or_buffered(state: &mut ServerState, client_id: u32, peer: &mut UnixStream) -> Vec<u8> {
    let mut out = read_all_available(peer);
    let client = state.clients.get_mut(&client_id).expect("test client");
    out.extend(client.outbound.drain(..));
    out
}

fn poly_fill_rectangle_body(drawable: u32, gc: u32) -> Vec<u8> {
    let mut body = Vec::with_capacity(16);
    body.extend_from_slice(&drawable.to_le_bytes());
    body.extend_from_slice(&gc.to_le_bytes());
    body.extend_from_slice(&0i16.to_le_bytes());
    body.extend_from_slice(&0i16.to_le_bytes());
    body.extend_from_slice(&1u16.to_le_bytes());
    body.extend_from_slice(&1u16.to_le_bytes());
    body
}

fn free_pixmap_body(pixmap: u32) -> Vec<u8> {
    pixmap.to_le_bytes().to_vec()
}

/// Wire body for a ConfigureWindow request: window, value_mask, the
/// 2-byte request pad, then one CARD32 per set value-mask bit in bit
/// order (x,y,w,h,border,sibling,stack_mode).
fn cw_restack_body(window: u32, value_mask: u16, values: &[u32]) -> Vec<u8> {
    let mut body = Vec::new();
    body.extend_from_slice(&window.to_le_bytes());
    body.extend_from_slice(&value_mask.to_le_bytes());
    body.extend_from_slice(&[0u8, 0u8]); // request pad
    for v in values {
        body.extend_from_slice(&v.to_le_bytes());
    }
    body
}

/// Two children (0x200 created first, then 0x300 → 0x300 ends on top)
/// under root, plus client 1's drained peer socket.
fn two_children_under_root() -> (ServerState, UnixStream) {
    let mut state = ServerState::new();
    let peer = install_client(&mut state, 1);
    for id in [0x200u32, 0x300u32] {
        state.resources.create_window(
            ClientId(1),
            CreateWindowRequest {
                depth: 24,
                window: ResourceId(id),
                parent: ROOT_WINDOW,
                width: 50,
                height: 50,
                ..Default::default()
            },
        );
    }
    (state, peer)
}

fn count_configure_notifies(bytes: &[u8]) -> usize {
    // X11 events are 32 bytes; ConfigureNotify event code is 22.
    bytes.chunks(32).filter(|e| e[0] & 0x7f == 22).count()
}

/// Extract the `mode` byte (wire offset 11) of every Present
/// `CompleteNotify` in a raw byte stream, in wire order — an
/// emit_idle-independent delivery-order oracle for tests mixing Copy
/// and Skip (Skip's gated `signal_present_wake` means
/// `RecordingBackend::signalled_present_wakes` alone can't order
/// them). Callers must select ONLY `EVENT_MASK_COMPLETE_NOTIFY` (no
/// `IdleNotify`/`ConfigureNotify`), so every event in the stream is a
/// fixed 40-byte `CompleteNotify` and the chunking can't desync.
fn complete_notify_modes(bytes: &[u8]) -> Vec<u8> {
    bytes
        .chunks(40)
        .map(|chunk| {
            assert_eq!(chunk.len(), 40, "truncated CompleteNotify");
            assert_eq!(chunk[0], 35, "GenericEvent");
            assert_eq!(chunk[1], 145, "PRESENT major opcode");
            chunk[11]
        })
        .collect()
}

#[test]
fn configure_window_noop_restack_emits_no_configure_notify() {
    // Regression (Enlightenment e27 restack war): a stacking-only
    // ConfigureWindow that does NOT change the child order must emit
    // zero ConfigureNotify, matching Xorg dix/window.c. A spurious
    // notify makes the WM re-restack forever (~8000 req/s observed),
    // pegging the desktop so clicks never get processed.
    let (mut state, mut peer) = two_children_under_root();
    // 0x300 was created last → already on top. Subscribe to its
    // StructureNotify, then drain any setup traffic.
    state
        .clients
        .get_mut(&1)
        .unwrap()
        .event_masks
        .insert(ResourceId(0x300), 0x0002_0000);
    let _ = read_all_available(&mut peer);

    // Raise the already-top window to the top: a positional no-op.
    let body = cw_restack_body(0x300, 0x0040, &[0]); // CWStackMode=Above
    let mut backend = RecordingBackend::new();
    handle_configure_window(
        &mut state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_configure_window");

    let out = read_all_available(&mut peer);
    assert_eq!(
        count_configure_notifies(&out),
        0,
        "no-op restack must not emit ConfigureNotify (got {} bytes)",
        out.len()
    );
}

#[test]
fn configure_window_real_restack_emits_one_configure_notify() {
    // Guard against over-suppression: a restack that DOES reorder the
    // children must still emit exactly one ConfigureNotify.
    let (mut state, mut peer) = two_children_under_root();
    // 0x200 was created first → currently at the bottom.
    state
        .clients
        .get_mut(&1)
        .unwrap()
        .event_masks
        .insert(ResourceId(0x200), 0x0002_0000);
    let _ = read_all_available(&mut peer);

    // Raise 0x200 to the top: a real reorder.
    let body = cw_restack_body(0x200, 0x0040, &[0]); // CWStackMode=Above
    let mut backend = RecordingBackend::new();
    handle_configure_window(
        &mut state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_configure_window");

    let out = read_all_available(&mut peer);
    assert_eq!(
        count_configure_notifies(&out),
        1,
        "a real restack must emit exactly one ConfigureNotify"
    );
}

// ── #143 — a resize must report the window exposed, either way ──
//
// Xorg's `miResizeWindow` copies the NEW clip list wholesale into
// `after.exposed` — "the entire window is trashed unless bitGravity
// recovers portions of it" (`mi/miwindow.c:466-472`) — and only a
// non-Forget `bitGravity` subtracts the bits it actually moved
// (`:596-599`). There is no grow/shrink branch: under the default
// ForgetGravity the full window is reported in both directions.
// Nor does the background gate the EVENT — `miWindowExposures`
// paints, then sends (`mi/miexpose.c:387-389`), and the
// background-None early-out is inside the paint (`:438-440`).
//
// We emitted this for a grow only. On HW that is the #143 xterm:
// awesome retiles it smaller, the leaf is re-tiled from the
// window's black background, and with no Expose nothing asks xterm
// to repaint its static banner rows — they stay black while the
// prompt line, which xterm redraws unprompted, comes back.

/// One viewable, Expose-selecting child of root at `w`x`h`, plus
/// client 1's already-drained peer socket. `background_pixel` picks
/// the two shapes that matter here: `Some` is the xterm case (the
/// resize re-tiles the leaf and destroys the content), `None` is the
/// background-None case (the content survives).
fn one_viewable_expose_child(
    w: u16,
    h: u16,
    background_pixel: Option<u32>,
) -> (ServerState, UnixStream) {
    const XID: u32 = 0x400;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(XID),
            parent: ROOT_WINDOW,
            width: w,
            height: h,
            background_pixel,
            ..Default::default()
        },
    );
    assert_eq!(
        state
            .resources
            .window(ResourceId(XID))
            .map(|win| win.background_none),
        Some(background_pixel.is_none()),
        "harness sanity: the background shape under test",
    );
    state
        .resources
        .window_mut(ResourceId(XID))
        .expect("child installed")
        .map_state = crate::resources::MapState::Viewable;
    state
        .clients
        .get_mut(&1)
        .expect("test client")
        .event_masks
        .insert(ResourceId(XID), 0x0000_8000); // ExposureMask
    let _ = read_all_available(&mut peer);
    (state, peer)
}

/// Every Expose in `bytes` for `window`, as `(x, y, width, height)`.
fn expose_rects(bytes: &[u8], window: u32) -> Vec<(u16, u16, u16, u16)> {
    bytes
        .chunks(32)
        .filter(|e| {
            e.len() == 32
                && e[0] & 0x7f == 12
                && u32::from_le_bytes([e[4], e[5], e[6], e[7]]) == window
        })
        .map(|e| {
            (
                u16::from_le_bytes([e[8], e[9]]),
                u16::from_le_bytes([e[10], e[11]]),
                u16::from_le_bytes([e[12], e[13]]),
                u16::from_le_bytes([e[14], e[15]]),
            )
        })
        .collect()
}

/// Resize `window` to `w`x`h` (CWWidth|CWHeight) and return whatever
/// reached the client.
fn resize_and_read(
    state: &mut ServerState,
    peer: &mut UnixStream,
    window: u32,
    w: u32,
    h: u32,
) -> Vec<u8> {
    let body = cw_restack_body(window, 0x000C, &[w, h]);
    let mut backend = RecordingBackend::new();
    handle_configure_window(
        state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_configure_window");
    read_all_available(peer)
}

#[test]
fn configure_window_shrink_exposes_the_whole_window() {
    // The #143 case. `configure_subwindow` re-tiles the leaf from
    // the window's background on a shrink, so without this Expose
    // the discarded pixels are unrecoverable.
    let (mut state, mut peer) = one_viewable_expose_child(200, 100, Some(0x0000_0000));
    let out = resize_and_read(&mut state, &mut peer, 0x400, 100, 60);
    assert_eq!(
        expose_rects(&out, 0x400),
        vec![(0, 0, 100, 60)],
        "a shrink must report the whole NEW window exposed, exactly once \
             (`mi/miwindow.c:466-472`); emitting none leaves an idle client \
             showing the background fill forever (#143)",
    );
}

#[test]
fn configure_window_grow_exposes_the_whole_window() {
    // Over-suppression guard: the grow path predates the shrink one
    // and must keep its single full-window Expose.
    let (mut state, mut peer) = one_viewable_expose_child(100, 60, Some(0x0000_0000));
    let out = resize_and_read(&mut state, &mut peer, 0x400, 200, 100);
    assert_eq!(
        expose_rects(&out, 0x400),
        vec![(0, 0, 200, 100)],
        "a grow must still report exactly one full-window Expose",
    );
}

#[test]
fn configure_window_shrink_exposes_a_background_none_window_too() {
    // A background-None window keeps its pixels across the resize
    // (`mi/miexpose.c:438-440` returns before painting) but STILL
    // gets the Expose: `miWindowExposures` calls `PaintWindow` and
    // `miSendExposures` in sequence and only the paint is skipped
    // (`mi/miexpose.c:387-389`). Nothing on this path may start
    // reading the background state to suppress the event.
    let (mut state, mut peer) = one_viewable_expose_child(200, 100, None);
    let out = resize_and_read(&mut state, &mut peer, 0x400, 100, 60);
    assert_eq!(
        expose_rects(&out, 0x400),
        vec![(0, 0, 100, 60)],
        "a background-None window is not painted but is still told what \
             was exposed",
    );
}

#[test]
fn configure_window_pure_move_emits_no_expose() {
    // Under-suppression guard: `after.exposed` is seeded from the
    // clip list only when the size changes; a pure move of an
    // unobscured window exposes nothing of the window itself.
    let (mut state, mut peer) = one_viewable_expose_child(200, 100, Some(0x0000_0000));
    let body = cw_restack_body(0x400, 0x0003, &[37, 41]); // CWX|CWY
    let mut backend = RecordingBackend::new();
    handle_configure_window(
        &mut state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_configure_window");
    let out = read_all_available(&mut peer);
    assert_eq!(
        expose_rects(&out, 0x400),
        Vec::new(),
        "a move is not a resize and must not expose the window",
    );
}

/// Present family: a Present ConfigureNotify selector over
/// `OUTBOUND_CAP` is flagged for the core loop to disconnect, and the
/// reading selector still gets the event.
#[test]
fn overflowing_present_selector_is_flagged_for_disconnect() {
    use crate::server::PresentEventSelection;
    use yserver_protocol::x11::present as x11present;

    const WINDOW: ResourceId = ResourceId(0x200);
    let mut state = ServerState::new();
    let _slow = install_client(&mut state, 1);
    let mut fast = install_client(&mut state, 2);
    for (eid, owner) in [(0x0010_0042, 1), (0x0020_0042, 2)] {
        state.present_event_selections.insert(
            eid,
            PresentEventSelection {
                owner: ClientId(owner),
                window: WINDOW,
                event_mask: x11present::EVENT_MASK_CONFIGURE_NOTIFY,
            },
        );
    }
    client_io::saturate_for_test(state.clients.get_mut(&1).unwrap());
    fire_present_configure_notify_for_window(
        &mut state,
        WINDOW,
        yserver_protocol::x11::Geometry {
            root: crate::resources::ROOT_WINDOW,
            x: 1,
            y: 2,
            width: 30,
            height: 40,
            border_width: 0,
            depth: 24,
        },
    );
    assert_eq!(client_io::failed_writers(&state.clients), [ClientId(1)]);
    let bytes = read_all_available(&mut fast);
    assert_eq!(bytes.first(), Some(&35), "Present GenericEvent");
}

/// Xorg's Present screen hook receives every real ConfigNotify, including
/// a pure move. Steam's DRI3 popup windows select this event and use its
/// x/y to keep the presentation surface synchronized with the native
/// override-redirect window.
#[test]
fn configure_window_pure_move_emits_present_configure_notify() {
    use crate::server::PresentEventSelection;
    use yserver_protocol::x11::present as x11present;

    const WINDOW: ResourceId = ResourceId(0x200);
    const PRESENT_EID: u32 = 0x0010_0042;

    let (mut state, mut peer) = two_children_under_root();
    state
        .clients
        .get_mut(&1)
        .unwrap()
        .event_masks
        .insert(WINDOW, 0x0002_0000);
    state.present_event_selections.insert(
        PRESENT_EID,
        PresentEventSelection {
            owner: ClientId(1),
            window: WINDOW,
            event_mask: x11present::EVENT_MASK_CONFIGURE_NOTIFY,
        },
    );
    let _ = read_all_available(&mut peer);

    let body = cw_restack_body(WINDOW.0, 0x0003, &[610, 250]); // CWX|CWY
    let mut backend = RecordingBackend::new();
    handle_configure_window(
        &mut state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_configure_window");

    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes.len(), 72, "Present XGE plus core ConfigureNotify");
    // Xorg dix/window.c invokes the Present ConfigNotify screen hook
    // before DeliverEvents sends the core ConfigureNotify. This ordering
    // matters to clients which merge the two configure streams.
    assert_eq!(bytes[0], 35, "GenericEvent");
    assert_eq!(bytes[1], 145, "PRESENT major opcode");
    assert_eq!(
        u16::from_le_bytes(bytes[8..10].try_into().unwrap()),
        u16::from(x11present::EVENT_CONFIGURE_NOTIFY),
    );
    assert_eq!(
        u32::from_le_bytes(bytes[12..16].try_into().unwrap()),
        PRESENT_EID,
    );
    assert_eq!(
        u32::from_le_bytes(bytes[16..20].try_into().unwrap()),
        WINDOW.0,
    );
    assert_eq!(i16::from_le_bytes(bytes[20..22].try_into().unwrap()), 610);
    assert_eq!(i16::from_le_bytes(bytes[22..24].try_into().unwrap()), 250);
    assert_eq!(u16::from_le_bytes(bytes[24..26].try_into().unwrap()), 50);
    assert_eq!(u16::from_le_bytes(bytes[26..28].try_into().unwrap()), 50);
    assert_eq!(bytes[40] & 0x7f, 22, "core ConfigureNotify follows Present");
    assert_eq!(
        u32::from_le_bytes(bytes[48..52].try_into().unwrap()),
        WINDOW.0,
    );
}

/// ProcTranslateCoords applies child input shapes. The Composite Overlay
/// Window is the top root child and, like Xorg's, starts unshaped, so it
/// is the `child` over a popup until the compositor empties its input
/// region; then the popup below it is (measured on Xvfb 21.1,
/// tools/vng-scenarios/cow-input-shape).
#[test]
fn translate_coordinates_skips_empty_input_shaped_cow() {
    use crate::{backend::WindowHandle, resources::COMPOSITE_OVERLAY_WINDOW};

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let popup = ResourceId(0x200);
    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: popup,
            parent: ROOT_WINDOW,
            x: 715,
            y: 327,
            width: 132,
            height: 165,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(popup);
    state
        .resources
        .materialize_cow_resource(WindowHandle::from_raw_for_test(COMPOSITE_OVERLAY_WINDOW.0));
    let _ = read_all_available(&mut peer);

    let mut translate = |state: &mut ServerState| {
        let mut body = Vec::with_capacity(12);
        body.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
        body.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
        body.extend_from_slice(&715i16.to_le_bytes());
        body.extend_from_slice(&327i16.to_le_bytes());
        handle_translate_coordinates(state, ClientId(1), SequenceNumber(1), &body)
            .expect("handle_translate_coordinates");
        let bytes = read_all_available(&mut peer);
        assert_eq!(bytes.len(), 32);
        assert_eq!(bytes[0], 1, "reply");
        assert_eq!(i16::from_le_bytes(bytes[12..14].try_into().unwrap()), 715);
        assert_eq!(i16::from_le_bytes(bytes[14..16].try_into().unwrap()), 327);
        u32::from_le_bytes(bytes[8..12].try_into().unwrap())
    };
    assert_eq!(
        translate(&mut state),
        COMPOSITE_OVERLAY_WINDOW.0,
        "an unshaped COW is the child over the popup",
    );
    state
        .shape_windows
        .entry(COMPOSITE_OVERLAY_WINDOW)
        .or_default()
        .input = Some(Vec::new());
    assert_eq!(
        translate(&mut state),
        popup.0,
        "empty-input COW must not hide the popup child",
    );
}

#[test]
fn configure_window_resize_applies_win_gravity_and_emits_gravity_notify() {
    // X11 window gravity: growing a parent moves a South-gravity child
    // down by the height delta and delivers a GravityNotify (Xorg
    // ResizeChildrenWinSize). fvwm's window-shade relies on exactly
    // this to reveal a client it parked above the fold.
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let parent = ResourceId(0x400);
    let child = ResourceId(0x401);
    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: parent,
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(parent);
    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: child,
            parent,
            x: 10,
            y: -100,
            width: 100,
            height: 100,
            win_gravity: Some(8), // South
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(child);
    state
        .clients
        .get_mut(&1)
        .unwrap()
        .event_masks
        .insert(child, 0x0002_0000); // StructureNotify
    let _ = read_all_available(&mut peer);

    // Grow the parent 100×100 → 100×200 (dh=+100): CWWidth|CWHeight.
    let body = cw_restack_body(0x400, 0x000C, &[100, 200]);
    let mut backend = RecordingBackend::new();
    handle_configure_window(
        &mut state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_configure_window");

    // South gravity: child.y += 100 → (10, 0).
    let c = state.resources.window(child).expect("child");
    assert_eq!(
        (c.x, c.y),
        (10, 0),
        "South-gravity child follows the parent's height growth",
    );

    // Exactly one GravityNotify (type 24) delivered to the child.
    let out = read_all_available(&mut peer);
    let gravity: Vec<&[u8]> = out
        .chunks(32)
        .filter(|e| e.len() == 32 && e[0] & 0x7f == 24)
        .collect();
    assert_eq!(gravity.len(), 1, "exactly one GravityNotify to the child");
    let g = gravity[0];
    assert_eq!(&g[4..8], &child.0.to_le_bytes(), "event window = child");
    assert_eq!(&g[8..12], &child.0.to_le_bytes(), "reported window = child");
    assert_eq!(i16::from_le_bytes([g[12], g[13]]), 10, "GravityNotify x");
    assert_eq!(i16::from_le_bytes([g[14], g[15]]), 0, "GravityNotify y");
}

#[test]
fn active_monitors_matches_outputs_and_order() {
    let mut state = ServerState::new();
    state.randr.outputs = vec![
        crate::randr::RandrOutput {
            name: "DP-1".into(),
            output_id: 1,
            crtc_id: 1,
            mode_id: 1,
            connected: true,
            x: 0,
            y: 0,
            width: 2560,
            height: 1440,
            vrefresh: 60,
            timing: None,
            mm_width: 0,
            mm_height: 0,
            mode_ids: vec![1],
            num_preferred: 1,
            pending_transform: Default::default(),
            current_transform: Default::default(),
            rotation: crate::randr::RR_ROTATE_0,
        },
        crate::randr::RandrOutput {
            name: "HDMI-A-1".into(),
            output_id: 2,
            crtc_id: 2,
            mode_id: 1,
            connected: false,
            x: 2560,
            y: 0,
            width: 2560,
            height: 1440,
            vrefresh: 60,
            timing: None,
            mm_width: 0,
            mm_height: 0,
            mode_ids: vec![1],
            num_preferred: 1,
            pending_transform: Default::default(),
            current_transform: Default::default(),
            rotation: crate::randr::RR_ROTATE_0,
        },
    ];

    let monitors = active_monitors(&state, true);
    assert_eq!(monitors.len(), state.randr.outputs.len());
    assert_eq!(monitors.len(), 2);
    assert!(monitors[0].primary);
    assert!(!monitors[1].primary);
    assert_eq!(monitors[1].x, 2560);
    assert_eq!(
        (monitors[1].width_mm, monitors[1].height_mm),
        (677, 381),
        "automatic monitor geometry still derives physical size from its retained CRTC",
    );
}

/// The two-output guest of `tools/vng-scenarios/xrandr-monitors.sh
/// --outputs 2` after `--right-of`: Virtual-1 1920x1440+0+0 (primary),
/// Virtual-2 1360x768+1920+0, both 325x203 mm.
fn monitor_fixture(byte_order: ClientByteOrder) -> (ServerState, UnixStream) {
    let output = |name: &str, id: u32, x: i16, width: u16, height: u16| crate::randr::RandrOutput {
        name: name.into(),
        output_id: id,
        crtc_id: id + 2,
        mode_id: id + 4,
        connected: true,
        x,
        y: 0,
        width,
        height,
        vrefresh: 60,
        timing: None,
        mm_width: 325,
        mm_height: 203,
        mode_ids: vec![id + 4],
        num_preferred: 1,
        pending_transform: Default::default(),
        current_transform: Default::default(),
        rotation: crate::randr::RR_ROTATE_0,
    };
    let mut state = ServerState::new();
    state.randr = crate::randr::RandrState::from_outputs(
        7,
        vec![
            output("Virtual-1", 1, 0, 1920, 1440),
            output("Virtual-2", 2, 1920, 1360, 768),
        ],
    );
    let peer = install_client(&mut state, 1);
    state.clients.get_mut(&1).unwrap().byte_order = byte_order;
    (state, peer)
}

/// A request body in the client's byte order.
struct WireBody(ClientByteOrder, Vec<u8>);

impl WireBody {
    fn u32(mut self, v: u32) -> Self {
        match self.0 {
            ClientByteOrder::LittleEndian => self.1.extend_from_slice(&v.to_le_bytes()),
            ClientByteOrder::BigEndian => self.1.extend_from_slice(&v.to_be_bytes()),
        }
        self
    }
    fn u16(mut self, v: u16) -> Self {
        match self.0 {
            ClientByteOrder::LittleEndian => self.1.extend_from_slice(&v.to_le_bytes()),
            ClientByteOrder::BigEndian => self.1.extend_from_slice(&v.to_be_bytes()),
        }
        self
    }
    fn bytes(mut self, v: &[u8]) -> Self {
        self.1.extend_from_slice(v);
        self
    }
}

fn wire_u32(bo: ClientByteOrder, b: &[u8]) -> u32 {
    let b: [u8; 4] = b[..4].try_into().unwrap();
    match bo {
        ClientByteOrder::LittleEndian => u32::from_le_bytes(b),
        ClientByteOrder::BigEndian => u32::from_be_bytes(b),
    }
}

fn wire_u16(bo: ClientByteOrder, b: &[u8]) -> u16 {
    let b: [u8; 2] = b[..2].try_into().unwrap();
    match bo {
        ClientByteOrder::LittleEndian => u16::from_le_bytes(b),
        ClientByteOrder::BigEndian => u16::from_be_bytes(b),
    }
}

/// Swap `body` as the reader would, then dispatch it as RANDR `minor`.
fn randr_wire_request(
    state: &mut ServerState,
    peer: &mut UnixStream,
    minor: u8,
    body: WireBody,
) -> Vec<u8> {
    let WireBody(byte_order, mut body) = body;
    yserver_protocol::x11::request_swap::swap_request_body(128, minor, byte_order, &mut body);
    handle_randr_request(
        state,
        &mut RecordingBackend::new(),
        ClientId(1),
        SequenceNumber(1),
        RequestHeader {
            opcode: 128,
            data: minor,
            length_units: u32::try_from(1 + body.len() / 4).unwrap(),
        },
        &body,
    )
    .expect("RANDR request");
    read_all_available(peer)
}

/// `SetMonitor` body: window, then name primary automatic noutput x y
/// width height mm-width mm-height outputs.
#[allow(clippy::too_many_arguments)]
fn set_monitor_body(
    bo: ClientByteOrder,
    window: u32,
    name: u32,
    primary: bool,
    noutput: u16,
    geometry: (i16, i16, u16, u16),
    mm: (u32, u32),
    outputs: &[u32],
) -> WireBody {
    #[allow(clippy::cast_sign_loss)]
    let mut body = WireBody(bo, Vec::new())
        .u32(window)
        .u32(name)
        .bytes(&[u8::from(primary), 0])
        .u16(noutput)
        .u16(geometry.0 as u16)
        .u16(geometry.1 as u16)
        .u16(geometry.2)
        .u16(geometry.3)
        .u32(mm.0)
        .u32(mm.1);
    for &output in outputs {
        body = body.u32(output);
    }
    body
}

fn set_monitor(
    state: &mut ServerState,
    peer: &mut UnixStream,
    name: &str,
    primary: bool,
    geometry: (i16, i16, u16, u16),
    mm: (u32, u32),
    outputs: &[u32],
) -> Vec<u8> {
    let bo = state.clients[&1].byte_order;
    let atom = state.atoms.intern(name, false).0;
    #[allow(clippy::cast_possible_truncation)]
    let body = set_monitor_body(
        bo,
        ROOT_WINDOW.0,
        atom,
        primary,
        outputs.len() as u16,
        geometry,
        mm,
        outputs,
    );
    randr_wire_request(state, peer, x11randr_minor::SET_MONITOR, body)
}

fn delete_monitor(state: &mut ServerState, peer: &mut UnixStream, name: u32) -> Vec<u8> {
    let bo = state.clients[&1].byte_order;
    let body = WireBody(bo, Vec::new()).u32(ROOT_WINDOW.0).u32(name);
    randr_wire_request(state, peer, x11randr_minor::DELETE_MONITOR, body)
}

mod x11randr_minor {
    pub const SET_MONITOR: u8 = yserver_protocol::x11::randr::RR_SET_MONITOR;
    pub const DELETE_MONITOR: u8 = yserver_protocol::x11::randr::RR_DELETE_MONITOR;
}

/// One decoded `GetMonitors` entry: name, primary, automatic,
/// "WxH+X+Y", "mmWxmmH", outputs.
type WireMonitor = (String, bool, bool, String, (u32, u32), Vec<u32>);

fn get_monitors(
    state: &mut ServerState,
    peer: &mut UnixStream,
    get_active: bool,
) -> Vec<WireMonitor> {
    let bo = state.clients[&1].byte_order;
    let body = WireBody(bo, Vec::new())
        .u32(ROOT_WINDOW.0)
        .bytes(&[u8::from(get_active), 0, 0, 0]);
    let r = randr_wire_request(
        state,
        peer,
        yserver_protocol::x11::randr::RR_GET_MONITORS,
        body,
    );
    assert_eq!(r[0], 1, "GetMonitors reply: {r:02x?}");
    assert_eq!(
        wire_u32(bo, &r[4..]) as usize * 4 + 32,
        r.len(),
        "reply length"
    );
    let count = wire_u32(bo, &r[12..]);
    let mut total_outputs = 0;
    let mut offset = 32;
    let mut monitors = Vec::new();
    for _ in 0..count {
        let m = &r[offset..];
        let n_out = usize::from(wire_u16(bo, &m[6..]));
        #[allow(clippy::cast_possible_wrap)]
        let geometry = format!(
            "{}x{}+{}+{}",
            wire_u16(bo, &m[12..]),
            wire_u16(bo, &m[14..]),
            wire_u16(bo, &m[8..]) as i16,
            wire_u16(bo, &m[10..]) as i16,
        );
        let name = state
            .atoms
            .name(AtomId(wire_u32(bo, m)))
            .unwrap_or("?")
            .to_string();
        let outputs = (0..n_out).map(|i| wire_u32(bo, &m[24 + i * 4..])).collect();
        monitors.push((
            name,
            m[4] != 0,
            m[5] != 0,
            geometry,
            (wire_u32(bo, &m[16..]), wire_u32(bo, &m[20..])),
            outputs,
        ));
        total_outputs += n_out;
        offset += 24 + n_out * 4;
    }
    assert_eq!(offset, r.len());
    assert_eq!(wire_u32(bo, &r[16..]) as usize, total_outputs, "noutputs");
    monitors
}

fn wm(
    name: &str,
    primary: bool,
    automatic: bool,
    geometry: &str,
    mm: (u32, u32),
    outputs: &[u32],
) -> WireMonitor {
    (
        name.into(),
        primary,
        automatic,
        geometry.into(),
        mm,
        outputs.to_vec(),
    )
}

/// XINERAMA `(GetScreenCount, QueryScreens)` in the client's order.
fn xinerama_heads(state: &mut ServerState, peer: &mut UnixStream) -> (u8, Vec<String>) {
    use yserver_protocol::x11::xinerama as xin;
    let bo = state.clients[&1].byte_order;
    let mut send = |state: &mut ServerState, minor: u8, body: &[u8]| {
        handle_xinerama_request(
            state,
            ClientId(1),
            SequenceNumber(1),
            RequestHeader {
                opcode: 151,
                data: minor,
                length_units: u32::try_from(1 + body.len() / 4).unwrap(),
            },
            body,
        )
        .expect("XINERAMA request");
        read_all_available(peer)
    };
    let window = WireBody(bo, Vec::new()).u32(ROOT_WINDOW.0).1;
    let count = send(state, xin::GET_SCREEN_COUNT, &window);
    let screens = send(state, xin::QUERY_SCREENS, &[]);
    let n = wire_u32(bo, &screens[8..]) as usize;
    #[allow(clippy::cast_possible_wrap)]
    let heads = (0..n)
        .map(|i| {
            let s = &screens[32 + i * 8..];
            format!(
                "{}x{}+{}+{}",
                wire_u16(bo, &s[4..]),
                wire_u16(bo, &s[6..]),
                wire_u16(bo, s) as i16,
                wire_u16(bo, &s[2..]) as i16,
            )
        })
        .collect();
    (count[1], heads)
}

const BOTH_ORDERS: [ClientByteOrder; 2] =
    [ClientByteOrder::LittleEndian, ClientByteOrder::BigEndian];

/// Measured split: `--setmonitor left 960/170x1440/211+0+0 Virtual-1`
/// and `right ...+960+0 none` hide Virtual-1's automatic monitor, keep
/// Virtual-2's, and nobody is primary (the primary output is covered).
#[test]
fn set_monitor_split_replaces_the_covered_automatic_monitor() {
    for bo in BOTH_ORDERS {
        let (mut state, mut peer) = monitor_fixture(bo);
        let r = set_monitor(
            &mut state,
            &mut peer,
            "left",
            false,
            (0, 0, 960, 1440),
            (170, 211),
            &[1],
        );
        assert!(r.is_empty(), "{r:02x?}");
        let r = set_monitor(
            &mut state,
            &mut peer,
            "right",
            false,
            (960, 0, 960, 1440),
            (170, 211),
            &[],
        );
        assert!(r.is_empty(), "{r:02x?}");
        let want = vec![
            wm("left", false, false, "960x1440+0+0", (170, 211), &[1]),
            wm("right", false, false, "960x1440+960+0", (170, 211), &[]),
            wm(
                "Virtual-2",
                false,
                true,
                "1360x768+1920+0",
                (325, 203),
                &[2],
            ),
        ];
        assert_eq!(get_monitors(&mut state, &mut peer, false), want, "{bo:?}");
        assert_eq!(get_monitors(&mut state, &mut peer, true), want, "{bo:?}");
        assert_eq!(
            xinerama_heads(&mut state, &mut peer),
            (
                3,
                vec![
                    "960x1440+0+0".into(),
                    "960x1440+960+0".into(),
                    "1360x768+1920+0".into()
                ]
            ),
        );
    }
}

/// Measured: a 0x0+0+0 monitor over both outputs is their union, and
/// its physical size is Xorg 21.1's integer `last_w / first_w *
/// first_mm` — 1360/1920 = 0 — so 0x0 mm. With Virtual-2 off it is
/// Virtual-1's geometry alone.
#[test]
fn automatic_geometry_client_monitor_follows_the_crtc_layout() {
    for bo in BOTH_ORDERS {
        let (mut state, mut peer) = monitor_fixture(bo);
        set_monitor(
            &mut state,
            &mut peer,
            "both",
            false,
            (0, 0, 0, 0),
            (0, 0),
            &[1, 2],
        );
        assert_eq!(
            get_monitors(&mut state, &mut peer, false),
            vec![wm("both", false, false, "3280x1440+0+0", (0, 0), &[1, 2])],
        );
        state.randr.outputs[1].mode_id = 0;
        assert_eq!(
            get_monitors(&mut state, &mut peer, false),
            vec![wm(
                "both",
                false,
                false,
                "1920x1440+0+0",
                (325, 203),
                &[1, 2]
            )],
        );
    }
}

/// Measured `cprim`: a primary client monitor leads the list, and the
/// uncovered CRTC of the primary output is ALSO reported primary —
/// Xorg's leading entry does not count towards `has_primary`.
#[test]
fn client_primary_and_uncovered_primary_output_are_both_primary() {
    for bo in BOTH_ORDERS {
        let (mut state, mut peer) = monitor_fixture(bo);
        state.randr.primary_output = 2;
        set_monitor(
            &mut state,
            &mut peer,
            "autogeo",
            false,
            (0, 0, 0, 0),
            (0, 0),
            &[1],
        );
        set_monitor(
            &mut state,
            &mut peer,
            "cprim",
            true,
            (0, 0, 0, 0),
            (0, 0),
            &[1],
        );
        assert_eq!(
            get_monitors(&mut state, &mut peer, true),
            vec![
                wm("cprim", true, false, "1920x1440+0+0", (325, 203), &[1]),
                wm("autogeo", false, false, "1920x1440+0+0", (325, 203), &[1]),
                wm("Virtual-2", true, true, "1360x768+1920+0", (325, 203), &[2]),
            ],
        );
    }
}

/// Measured `extra-primary`: a new primary monitor clears the old one's
/// flag; deleting it leaves no primary client monitor behind.
#[test]
fn a_new_primary_client_monitor_clears_the_previous_one() {
    for bo in BOTH_ORDERS {
        let (mut state, mut peer) = monitor_fixture(bo);
        set_monitor(
            &mut state,
            &mut peer,
            "left",
            false,
            (0, 0, 960, 1440),
            (170, 211),
            &[1],
        );
        set_monitor(
            &mut state,
            &mut peer,
            "right",
            true,
            (960, 0, 960, 1440),
            (100, 50),
            &[],
        );
        set_monitor(
            &mut state,
            &mut peer,
            "extra",
            true,
            (0, 0, 10, 10),
            (100, 50),
            &[],
        );
        let names = |m: Vec<WireMonitor>| m.into_iter().map(|m| (m.0, m.1)).collect::<Vec<_>>();
        assert_eq!(
            names(get_monitors(&mut state, &mut peer, false)),
            vec![
                ("extra".into(), true),
                ("left".into(), false),
                ("right".into(), false),
                ("Virtual-2".into(), false),
            ],
        );
        let extra = state.atoms.intern("extra", true).0;
        assert!(delete_monitor(&mut state, &mut peer, extra).is_empty());
        assert_eq!(
            names(get_monitors(&mut state, &mut peer, false)),
            vec![
                ("left".into(), false),
                ("right".into(), false),
                ("Virtual-2".into(), false),
            ],
        );
    }
}

/// Measured `empty`: a 0x0 monitor with no outputs is listed by
/// `GetMonitors(get_active=0)` and counted by XINERAMA GetScreenCount,
/// but neither `get_active=1` nor QueryScreens reports it.
#[test]
fn an_empty_monitor_is_counted_but_not_active() {
    for bo in BOTH_ORDERS {
        let (mut state, mut peer) = monitor_fixture(bo);
        set_monitor(
            &mut state,
            &mut peer,
            "empty",
            false,
            (0, 0, 0, 0),
            (100, 50),
            &[],
        );
        let all = get_monitors(&mut state, &mut peer, false);
        assert_eq!(all.len(), 3);
        assert_eq!(all[1], wm("empty", false, false, "0x0+0+0", (100, 50), &[]));
        assert_eq!(get_monitors(&mut state, &mut peer, true).len(), 2);
        let (count, heads) = xinerama_heads(&mut state, &mut peer);
        assert_eq!((count, heads.len()), (3, 2));
    }
}

/// The error table measured on Xorg 21.1 (`mon.py errors`): codes and
/// wire values, no state change on failure, and no validation of the
/// output ids.
#[test]
fn set_and_delete_monitor_errors_match_xorg() {
    use yserver_protocol::x11::error;
    for bo in BOTH_ORDERS {
        let (mut state, mut peer) = monitor_fixture(bo);
        let err = |r: &[u8]| {
            assert_eq!(r.len(), 32, "one error: {r:02x?}");
            assert_eq!(r[0], 0);
            (r[1], wire_u32(bo, &r[4..]), wire_u16(bo, &r[8..]), r[10])
        };
        let output_atom = state.atoms.intern("Virtual-1", false).0;
        let name = state.atoms.intern("errmon", false).0;
        let root = ROOT_WINDOW.0;
        let set = |state: &mut ServerState,
                   peer: &mut UnixStream,
                   window,
                   name,
                   noutput,
                   outputs: &[u32]| {
            let body = set_monitor_body(
                bo,
                window,
                name,
                false,
                noutput,
                (0, 0, 10, 10),
                (100, 50),
                outputs,
            );
            randr_wire_request(state, peer, x11randr_minor::SET_MONITOR, body)
        };
        let cases: Vec<(&str, Vec<u8>, (u8, u32))> = vec![
            (
                "name=output",
                set(&mut state, &mut peer, root, output_atom, 0, &[]),
                (error::BAD_VALUE, output_atom),
            ),
            (
                "name=None",
                set(&mut state, &mut peer, root, 0, 0, &[]),
                (error::BAD_ATOM, root),
            ),
            (
                "name=0x7fffff",
                set(&mut state, &mut peer, root, 0x7f_ffff, 0, &[]),
                (error::BAD_ATOM, root),
            ),
            (
                "bad window",
                set(&mut state, &mut peer, 0x7ff_fffe, name, 0, &[]),
                (error::BAD_WINDOW, 0x7ff_fffe),
            ),
            (
                "noutput=1, none sent",
                set(&mut state, &mut peer, root, name, 1, &[]),
                (error::BAD_LENGTH, 0),
            ),
            (
                "noutput=0, one sent",
                set(&mut state, &mut peer, root, name, 0, &[1]),
                (error::BAD_LENGTH, 0),
            ),
        ];
        for (label, r, (code, value)) in cases {
            assert_eq!(err(&r), (code, value, 43, 128), "SetMonitor {label} {bo:?}");
        }
        let short = randr_wire_request(
            &mut state,
            &mut peer,
            x11randr_minor::SET_MONITOR,
            WireBody(bo, Vec::new()).u32(root).u32(name),
        );
        assert_eq!(err(&short).0, error::BAD_LENGTH);
        assert!(state.randr_client_monitors.is_empty());

        // Output ids are not validated (measured: `bogusout` succeeded).
        let bogus = state.atoms.intern("bogusout", false).0;
        assert!(set(&mut state, &mut peer, root, bogus, 1, &[0x7777]).is_empty());
        assert_eq!(
            err(&set(&mut state, &mut peer, root, bogus, 0, &[])),
            (error::BAD_VALUE, bogus, 43, 128),
            "21.1 refuses a name already in use",
        );

        let never = state.atoms.intern("nosuchmon", false).0;
        let del = |state: &mut ServerState, peer: &mut UnixStream, window: u32, name: u32| {
            let body = WireBody(bo, Vec::new()).u32(window).u32(name);
            randr_wire_request(state, peer, x11randr_minor::DELETE_MONITOR, body)
        };
        let cases: Vec<(&str, Vec<u8>, (u8, u32))> = vec![
            (
                "never set",
                del(&mut state, &mut peer, root, never),
                (error::BAD_VALUE, never),
            ),
            (
                "None",
                del(&mut state, &mut peer, root, 0),
                (error::BAD_ATOM, 0),
            ),
            (
                "0x7fffff",
                del(&mut state, &mut peer, root, 0x7f_ffff),
                (error::BAD_ATOM, 0x7f_ffff),
            ),
            (
                "bad window",
                del(&mut state, &mut peer, 0x7ff_fffe, bogus),
                (error::BAD_WINDOW, 0x7ff_fffe),
            ),
            (
                "output name",
                del(&mut state, &mut peer, root, output_atom),
                (error::BAD_VALUE, output_atom),
            ),
        ];
        for (label, r, (code, value)) in cases {
            assert_eq!(
                err(&r),
                (code, value, 44, 128),
                "DeleteMonitor {label} {bo:?}"
            );
        }
        let long = randr_wire_request(
            &mut state,
            &mut peer,
            x11randr_minor::DELETE_MONITOR,
            WireBody(bo, Vec::new()).u32(root).u32(bogus).u32(0),
        );
        assert_eq!(err(&long).0, error::BAD_LENGTH);
        assert_eq!(
            state.randr_client_monitors.len(),
            1,
            "bogusout survived every failure"
        );
        assert!(del(&mut state, &mut peer, root, bogus).is_empty());
        assert!(state.randr_client_monitors.is_empty());
    }
}

/// Measured `mon.py events`: each successful Set/DeleteMonitor sends one
/// core ConfigureNotify on the root (`RRSendConfigNotify`) and no RANDR
/// event; a failed one sends nothing.
#[test]
fn set_and_delete_monitor_notify_with_a_root_configure_notify() {
    for bo in BOTH_ORDERS {
        let (mut state, mut peer) = monitor_fixture(bo);
        state
            .clients
            .get_mut(&1)
            .unwrap()
            .event_masks
            .insert(ROOT_WINDOW, 0x0002_0000);
        state.randr_select_masks.insert((1, ROOT_WINDOW), 0x1f);
        let root = state
            .resources
            .window(ROOT_WINDOW)
            .map(|w| (w.width, w.height))
            .unwrap();
        let configure_notify = |r: &[u8]| {
            assert_eq!(r.len(), 32, "exactly one event: {r:02x?}");
            assert_eq!(r[0], 22, "ConfigureNotify");
            assert_eq!(wire_u32(bo, &r[4..]), ROOT_WINDOW.0, "event window");
            assert_eq!(wire_u32(bo, &r[8..]), ROOT_WINDOW.0, "window");
            assert_eq!(wire_u32(bo, &r[12..]), 0, "above-sibling None");
            assert_eq!((wire_u16(bo, &r[20..]), wire_u16(bo, &r[22..])), root);
        };
        configure_notify(&set_monitor(
            &mut state,
            &mut peer,
            "evmon",
            false,
            (0, 0, 100, 100),
            (100, 50),
            &[],
        ));
        let again = set_monitor(
            &mut state,
            &mut peer,
            "evmon",
            false,
            (0, 0, 200, 100),
            (100, 50),
            &[],
        );
        assert_eq!(
            (again.len(), again[0]),
            (32, 0),
            "reused name: an error, no event"
        );
        let evmon = state.atoms.intern("evmon", true).0;
        configure_notify(&delete_monitor(&mut state, &mut peer, evmon));
        let again = delete_monitor(&mut state, &mut peer, evmon);
        assert_eq!(
            (again.len(), again[0]),
            (32, 0),
            "unknown name: an error, no event"
        );
    }
}

#[test]
fn vidmode_retains_a_light_disconnected_assigned_primary() {
    let mut state = ServerState::new();
    let primary = state.randr.primary_output;
    let expected = state
        .randr
        .outputs
        .iter_mut()
        .find(|output| output.output_id == primary)
        .map(|output| {
            output.connected = false;
            (output.output_id, output.crtc_id)
        })
        .unwrap();

    let current = current_vidmode_output(&state).expect("the CRTC remains assigned");
    assert_eq!((current.output_id, current.crtc_id), expected);
}

#[test]
fn xybitmap_to_zpixmap_preserves_lsb_first_bits_without_left_pad() {
    let src = [
        0b0000_1101u8,
        0,
        0,
        0, // row 0: 1 0 1 1
        0b0000_0010u8,
        0,
        0,
        0, // row 1: 0 1 0 0
    ];
    let out = xybitmap_to_zpixmap(&src, 4, 2, 0).expect("convert");
    assert_eq!(out, src);
}

#[test]
fn xybitmap_to_zpixmap_strips_left_pad_bits() {
    let src = [
        0b0011_0100u8,
        0,
        0,
        0, // left_pad=2, payload bits => 1 0 1 1
    ];
    let out = xybitmap_to_zpixmap(&src, 4, 1, 2).expect("convert");
    assert_eq!(out, vec![0b0000_1101u8, 0, 0, 0]);
}

#[test]
fn xybitmap_to_target_zpixmap_expands_bits_with_fg_bg_at_depth_24() {
    let src = [
        0b0000_0101u8,
        0,
        0,
        0, // row: 1 0 1
    ];
    let out =
        xybitmap_to_target_zpixmap(&src, 3, 1, 0, 24, 0x0000_00ff, 0x0000_ff00).expect("convert");
    assert_eq!(out.len(), 12);
    assert_eq!(&out[0..4], &0x0000_00ffu32.to_le_bytes());
    assert_eq!(&out[4..8], &0x0000_ff00u32.to_le_bytes());
    assert_eq!(&out[8..12], &0x0000_00ffu32.to_le_bytes());
}

#[test]
fn xybitmap_to_target_zpixmap_expands_bits_with_fg_bg_at_depth_4() {
    let src = [
        0b0000_0110u8,
        0,
        0,
        0, // row: 0 1 1
    ];
    let out = xybitmap_to_target_zpixmap(&src, 3, 1, 0, 4, 0x0d, 0x02).expect("convert");
    assert_eq!(out, vec![0xd2, 0x0d, 0, 0]);
}

fn sync_header(minor: u8) -> RequestHeader {
    RequestHeader {
        opcode: 142,
        data: minor,
        length_units: 0,
    }
}

fn counter_value_body(counter: u32, value: i64) -> Vec<u8> {
    let mut b = Vec::new();
    b.extend_from_slice(&counter.to_le_bytes());
    b.extend_from_slice(&xsync_i64(value));
    b
}

// The exact CreateAlarm muffin issues under Cinnamon: Relative
// value 1, PositiveComparison, delta 1, events true, watching
// counter 0x02600006.
fn muffin_alarm_body() -> Vec<u8> {
    let mut b = Vec::new();
    b.extend_from_slice(&0x01e0_0019u32.to_le_bytes());
    let mask = x11sync::CA_COUNTER
        | x11sync::CA_VALUE_TYPE
        | x11sync::CA_VALUE
        | x11sync::CA_TEST_TYPE
        | x11sync::CA_DELTA
        | x11sync::CA_EVENTS;
    b.extend_from_slice(&mask.to_le_bytes());
    b.extend_from_slice(&0x0260_0006u32.to_le_bytes());
    b.extend_from_slice(&x11sync::VALUE_TYPE_RELATIVE.to_le_bytes());
    b.extend_from_slice(&0i32.to_le_bytes()); // value hi
    b.extend_from_slice(&1u32.to_le_bytes()); // value lo
    b.extend_from_slice(&x11sync::TEST_POSITIVE_COMPARISON.to_le_bytes());
    b.extend_from_slice(&0i32.to_le_bytes()); // delta hi
    b.extend_from_slice(&1u32.to_le_bytes()); // delta lo
    b.push(1); // events = true
    b.extend_from_slice(&[0u8; 3]);
    b
}

#[test]
fn poly_fill_rectangle_unknown_drawable_returns_bad_drawable() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    state.resources.create_gc(
        ClientId(1),
        CreateGcRequest {
            gc: ResourceId(0x2000),
            drawable: ROOT_WINDOW,
            function: None,
            plane_mask: None,
            foreground: None,
            background: None,
            line_width: None,
            line_style: None,
            cap_style: None,
            join_style: None,
            fill_style: None,
            fill_rule: None,
            tile: None,
            stipple: None,
            tile_x_origin: None,
            tile_y_origin: None,
            font: None,
            subwindow_mode: None,
            graphics_exposures: None,
            clip_x_origin: None,
            clip_y_origin: None,
            clip_mask: None,
            dash_offset: None,
            dashes: None,
            arc_mode: None,
        },
    );

    let body = poly_fill_rectangle_body(0xdead_beef, 0x2000);
    process_request(
        &mut state,
        &mut backend,
        ClientId(1),
        SequenceNumber(1),
        RequestHeader {
            opcode: 70,
            data: 0,
            length_units: u32::try_from(1 + body.len().div_ceil(4)).unwrap(),
        },
        &body,
        None,
    )
    .expect("process_request");

    let bytes = read_all_available(&mut peer);
    assert!(
        bytes.len() >= 32,
        "expected 32-byte error reply, got {} bytes: {:02x?}",
        bytes.len(),
        bytes
    );
    let buf = &bytes[..32];
    assert_eq!(buf[1], x11::error::BAD_DRAWABLE);
    assert_eq!(buf[10], 70);
}

