// ---------------- Step 4: end-to-end vectors ----------------

/// Round-3 inversion vector, now driven by REAL scrap (Task 6's
/// version at `due_skip_is_held_back_behind_a_smaller_id_undrained_gate_entry`
/// inserted the Skip row by hand): P1 executes at arrival (no flip in
/// flight), P2 parks (a flip is in flight), P3 arrives full-frame at
/// the same effective target and scraps P2 via
/// `supersede_covered_pending_presents`. Skip(P2) must not deliver
/// before Copy(P1) even though it was parked first (at P3's arrival,
/// before P1's GPU fence retired).
#[test]
fn supersession_e2e_p1_executes_p2_parks_p3_scraps_p2_delivery_order_preserved() {
    use yserver_protocol::x11::present as x11present;

    const WINDOW: u32 = 0x0001_0201;
    const PRESENT_EID: u32 = 0x0020_1201;
    const P1_ID: u64 = 80;
    const P2_ID: u64 = 81;
    const P3_ID: u64 = 82;
    const CLOCK: u64 = 10;
    const TARGET: u64 = CLOCK + 1; // eff for target_msc=0/divisor=0/remainder=0

    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();
    backend.present_ust_msc = (CLOCK, 0x1000); // held fixed across all three arrivals
    seed_present_clock(&mut state, CLOCK, 0x1000);

    // P1: no flip in flight -> ExecuteNow.
    backend.present_flip_in_flight = false;
    let p1 = SupersessionFixture::new(P1_ID, WINDOW)
        .eff(Some(TARGET))
        .geometry(0, 0, 100, 100)
        .pending();
    supersede_covered_pending_presents(&mut state, &mut backend, &p1);
    arrival_execute_or_park_present_pixmap(&mut state, &mut backend, P1_ID, p1);
    assert!(
        state.present_complete_gate.contains_key(&P1_ID),
        "P1 executed at arrival and inserted its completion gate"
    );

    // P2: a flip is now in flight -> Park.
    backend.present_flip_in_flight = true;
    let p2 = SupersessionFixture::new(P2_ID, WINDOW)
        .eff(Some(TARGET))
        .geometry(0, 0, 100, 100)
        .pending();
    supersede_covered_pending_presents(&mut state, &mut backend, &p2);
    arrival_execute_or_park_present_pixmap(&mut state, &mut backend, P2_ID, p2);
    assert!(state.present_pending_exec.contains_key(&P2_ID));

    // P3: full-frame, same effective target -> scraps P2, then parks
    // itself (flip still in flight).
    let p3 = SupersessionFixture::new(P3_ID, WINDOW)
        .eff(Some(TARGET))
        .geometry(0, 0, 100, 100)
        .pending();
    supersede_covered_pending_presents(&mut state, &mut backend, &p3);
    assert!(
        !state.present_pending_exec.contains_key(&P2_ID),
        "P3 scrapped P2"
    );
    arrival_execute_or_park_present_pixmap(&mut state, &mut backend, P3_ID, p3);
    assert!(state.present_pending_exec.contains_key(&P3_ID));

    assert_eq!(
        state.present_pending_complete.len(),
        1,
        "Skip(P2) is parked"
    );
    assert_eq!(state.present_pending_complete[0].event.present_id, P2_ID);

    // Wire up the completion-notify subscriber now that the store
    // setup above is done, and drain its connection setup traffic.
    let mut peer = install_client(&mut state, 1);
    state.present_event_selections.insert(
        PRESENT_EID,
        crate::server::PresentEventSelection {
            owner: ClientId(1),
            window: ResourceId(WINDOW),
            event_mask: x11present::EVENT_MASK_COMPLETE_NOTIFY,
        },
    );
    let _ = read_all_available(&mut peer);

    let clock = crate::backend::PresentClockSample {
        msc: TARGET,
        ust: 0x2000,
        source: crate::backend::PresentClockSource::PageFlip,
    };
    fire_due_present_completions(&mut state, &mut backend, clock);
    assert_eq!(
        state.present_pending_complete.len(),
        1,
        "Skip(P2) held back behind P1's still-undrained completion gate"
    );

    // P1's fence retires late: the gate empties and its completion
    // joins the queue, as run.rs's Some(gate) arm does.
    state.present_complete_gate.remove(&P1_ID);
    state
        .present_pending_complete
        .push(crate::server::PendingPresentComplete {
            event: crate::backend::CompletedPresentEvent {
                client_id: ClientId(1),
                serial: 1,
                host_xid: 0x1,
                dst_host_xid: WINDOW,
                options: 0,
                present_id: P1_ID,
                window_generation: 0,
                crtc_id: 0,
                crtc_epoch: 0,
                msc_offset: 0,
                completion_clock: None,
                wake: crate::backend::PresentWake::Pixmap { idle_fence_xid: 0 },
                completion_mode: yserver_protocol::x11::present::COMPLETE_MODE_COPY,
                emit_idle: true,
            },
            effective_target_msc: TARGET,
            mode: x11present::COMPLETE_MODE_COPY,
            emit_idle: true,
        });

    fire_due_present_completions(&mut state, &mut backend, clock);
    assert!(state.present_pending_complete.is_empty());
    assert_eq!(
        complete_notify_modes(&read_all_available(&mut peer)),
        vec![
            x11present::COMPLETE_MODE_COPY,
            x11present::COMPLETE_MODE_SKIP
        ],
        "Copy(P1) must deliver before Skip(P2) — never inverted"
    );
}

/// Uncovered survivor (spec vector (ii)): A carries a sliver update
/// region NOT covered by successor C's extent, so C's scrap declines
/// it; B is full-frame and covered, so C scraps it. A later executes
/// via the due-pass; Skip(B) must not deliver before Copy(A) even
/// though B has the larger present_id and was scrapped (queued)
/// first.
#[test]
fn supersede_declined_uncovered_survivor_holds_back_covered_scrap_skip() {
    use yserver_protocol::x11::present as x11present;

    const WINDOW: u32 = 0x0001_0202;
    const PRESENT_EID: u32 = 0x0020_1202;
    const A_ID: u64 = 90;
    const B_ID: u64 = 91;
    const C_ID: u64 = 92;
    const TARGET: u64 = 500;

    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();
    backend.present_ust_msc = (TARGET, 0x1000); // due at TARGET.

    // A: sliver update region far outside C's extent (declines).
    let a = SupersessionFixture::new(A_ID, WINDOW)
        .eff(Some(TARGET))
        .geometry(0, 0, 100, 100)
        .update_rects(Some(vec![xfixes::RegionRect {
            x: 200,
            y: 200,
            width: 5,
            height: 5,
        }]))
        .entry();
    state.present_pending_exec.insert(A_ID, a);

    // B: full-frame, covered.
    let b = SupersessionFixture::new(B_ID, WINDOW)
        .eff(Some(TARGET))
        .geometry(0, 0, 100, 100)
        .entry();
    state.present_pending_exec.insert(B_ID, b);

    let c = SupersessionFixture::new(C_ID, WINDOW)
        .eff(Some(TARGET))
        .geometry(0, 0, 100, 100)
        .pending();
    supersede_covered_pending_presents(&mut state, &mut backend, &c);

    assert!(
        state.present_pending_exec.contains_key(&A_ID),
        "A's sliver update region is not covered by C's extent — declined"
    );
    assert!(
        !state.present_pending_exec.contains_key(&B_ID),
        "B is full-frame and covered — scrapped"
    );
    assert_eq!(state.present_pending_complete.len(), 1);
    assert_eq!(state.present_pending_complete[0].event.present_id, B_ID);

    let mut peer = install_client(&mut state, 1);
    state.present_event_selections.insert(
        PRESENT_EID,
        crate::server::PresentEventSelection {
            owner: ClientId(1),
            window: ResourceId(WINDOW),
            event_mask: x11present::EVENT_MASK_COMPLETE_NOTIFY,
        },
    );
    let _ = read_all_available(&mut peer);

    drain_due_present_pending_exec(&mut state, &mut backend);
    assert!(
        state.present_pending_exec.is_empty(),
        "A executes in the due-pass"
    );
    assert!(
        state.present_complete_gate.contains_key(&A_ID),
        "A's execute_present_pixmap_copy inserted its completion gate"
    );

    let clock = crate::backend::PresentClockSample {
        msc: TARGET,
        ust: 0x1000,
        source: crate::backend::PresentClockSource::PageFlip,
    };
    fire_due_present_completions(&mut state, &mut backend, clock);
    assert_eq!(
        state.present_pending_complete.len(),
        1,
        "Skip(B) held back behind A's still-undrained completion gate"
    );

    // A's fence retires: the gate empties and its completion joins
    // the queue, as run.rs's Some(gate) arm does.
    state.present_complete_gate.remove(&A_ID);
    state
        .present_pending_complete
        .push(crate::server::PendingPresentComplete {
            event: crate::backend::CompletedPresentEvent {
                client_id: ClientId(1),
                serial: 1,
                host_xid: 0x1,
                dst_host_xid: WINDOW,
                options: 0,
                present_id: A_ID,
                window_generation: 0,
                crtc_id: 0,
                crtc_epoch: 0,
                msc_offset: 0,
                completion_clock: None,
                wake: crate::backend::PresentWake::Pixmap { idle_fence_xid: 0 },
                completion_mode: yserver_protocol::x11::present::COMPLETE_MODE_COPY,
                emit_idle: true,
            },
            effective_target_msc: TARGET,
            mode: x11present::COMPLETE_MODE_COPY,
            emit_idle: true,
        });

    fire_due_present_completions(&mut state, &mut backend, clock);
    assert!(state.present_pending_complete.is_empty());
    assert_eq!(
        complete_notify_modes(&read_all_available(&mut peer)),
        vec![
            x11present::COMPLETE_MODE_COPY,
            x11present::COMPLETE_MODE_SKIP
        ],
        "Copy(A) must deliver before Skip(B): A < B for the same window"
    );
}

/// Same-target entries whose successor declines (or never arrives)
/// all execute at their due point in arrival (`present_id`) order.
#[test]
fn uncovered_same_target_entries_execute_in_arrival_order() {
    use crate::backend::recording::RecordedCall;

    const WINDOW: u32 = 0x0001_0203;
    const A_ID: u64 = 100;
    const B_ID: u64 = 101;
    const TARGET: u64 = 500;

    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();
    backend.present_ust_msc = (TARGET, 0x1000);

    // Both carry a sliver update region, so a would-be successor
    // would decline both — but here we just prove arrival order
    // survives when nothing scraps at all (present_id insertion
    // order == BTreeMap iteration order).
    let a = SupersessionFixture::new(A_ID, WINDOW)
        .eff(Some(TARGET))
        .update_rects(Some(vec![xfixes::RegionRect {
            x: 0,
            y: 0,
            width: 10,
            height: 10,
        }]))
        .entry();
    state.present_pending_exec.insert(A_ID, a);
    let b = SupersessionFixture::new(B_ID, WINDOW)
        .eff(Some(TARGET))
        .update_rects(Some(vec![xfixes::RegionRect {
            x: 20,
            y: 20,
            width: 10,
            height: 10,
        }]))
        .entry();
    state.present_pending_exec.insert(B_ID, b);

    drain_due_present_pending_exec(&mut state, &mut backend);

    let order: Vec<i16> = backend
        .calls()
        .iter()
        .filter_map(|c| match c {
            RecordedCall::CopyArea { dst_x, .. } => Some(*dst_x),
            _ => None,
        })
        .collect();
    // dst_x mirrors the rect's x (0 for A, 20 for B) — arrival order.
    assert_eq!(order, vec![0, 20], "A executes before B: arrival order");
    assert!(state.present_pending_exec.is_empty());
}

#[test]
fn distinct_effective_targets_never_supersede() {
    const WINDOW: u32 = 0x0001_0204;
    const A_ID: u64 = 110;
    const C_ID: u64 = 111;

    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();

    let mut a = SupersessionFixture::new(A_ID, WINDOW)
        .eff(Some(500))
        .geometry(0, 0, 100, 100)
        .entry();
    a.pending.masked_options = crate::present_scheduler::PRESENT_ALL_ASYNC_OPTIONS;
    state.present_pending_exec.insert(A_ID, a);

    let mut c = SupersessionFixture::new(C_ID, WINDOW)
        .eff(Some(600)) // distinct target
        .geometry(0, 0, 100, 100)
        .pending();
    c.masked_options = crate::present_scheduler::PRESENT_ALL_ASYNC_OPTIONS;
    supersede_covered_pending_presents(&mut state, &mut backend, &c);

    assert!(
        state.present_pending_exec.contains_key(&A_ID),
        "a distinct effective target must never supersede"
    );
    assert!(state.present_pending_complete.is_empty());
}

/// Scrap × window-destroy race: a present is scrapped first (fence
/// triggered, entry pin released, Skip parked), then the
/// window-destroy purge runs for the same window. The purge must not
/// find the (already-removed) entry again — no double fence trigger,
/// no double pin release. The purge's `signal_present_wake` on the
/// now-parked Skip row (a completion, not a pending-exec entry) is a
/// separate, harmless no-op backend-side; not exercised here.
#[test]
fn scrap_then_window_destroy_purge_releases_exactly_once() {
    const WINDOW: u32 = 0x0001_0205;
    const VICTIM_ID: u64 = 120;
    const SUCCESSOR_ID: u64 = 121;
    const TARGET: u64 = 500;
    const IDLE_FENCE: u32 = 0x0030_1205;
    const PIN_ID: u64 = 5;

    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();
    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );

    let mut victim = SupersessionFixture::new(VICTIM_ID, WINDOW)
        .eff(Some(TARGET))
        .geometry(0, 0, 50, 50)
        .idle_fence(IDLE_FENCE)
        .entry();
    victim.pin = Some(PIN_ID);
    state.present_pending_exec.insert(VICTIM_ID, victim);

    let successor = SupersessionFixture::new(SUCCESSOR_ID, WINDOW)
        .eff(Some(TARGET))
        .geometry(0, 0, 100, 100)
        .pending();
    supersede_covered_pending_presents(&mut state, &mut backend, &successor);

    assert_eq!(backend.triggered_dri3_fences, vec![IDLE_FENCE]);
    assert_eq!(backend.released_present_sources, vec![PIN_ID]);
    assert!(state.present_pending_exec.is_empty());

    // Now destroy the window: the by-XID purge scans
    // `present_pending_exec` for this window and finds nothing (the
    // entry is already gone), so it must not touch the backend again.
    destroy_window_subtree(&mut state, &mut backend, None, ResourceId(WINDOW));

    assert_eq!(
        backend.triggered_dri3_fences,
        vec![IDLE_FENCE],
        "the window-destroy purge must not re-trigger an already-scrapped fence"
    );
    assert_eq!(
        backend.released_present_sources,
        vec![PIN_ID],
        "the window-destroy purge must not re-release an already-released pin"
    );
    // Review fix (5c): the destroy purge's parked-completions sweep
    // (process_request.rs, `destroy_window_subtree`'s
    // `present_pending_complete` loop) DOES call `signal_present_wake`
    // for every row matching this window — including the Skip row the
    // scrap above just parked, since scrap does not remove it from
    // `present_pending_complete`. This is a no-op on a real backend
    // (the scrapped present_id was never retained as a `PinnedWake` —
    // scrap's own by-XID release is what actually signalled the
    // client), but `RecordingBackend` records the call regardless, so
    // pin the exact expected content: exactly the victim's id, and no
    // other wake.
    assert_eq!(
        backend.signalled_present_wakes,
        vec![VICTIM_ID],
        "the purge's parked-completion sweep signals the scrapped Skip row's \
             present_id (harmless no-op on a real backend) and nothing else"
    );
}

// ---------------- extract_shm_zpixmap_region ----------------
//
// The protocol-level byte-extraction for MIT-SHM PutImage. Until
// 2026-05-15 the handler ignored `total_width` / `src_x` /
// `src_y` and read a tightly-packed `src_width × src_height ×
// bpp` block at `offset`. That happens to be correct when the
// client sets `total == src` and `src_xy == 0` (the common
// case), but reads garbage when the client uploads a sub-region
// of a larger shm image. xfdesktop's thumbnail upload pattern
// and any cairo-padded surface trigger the latter, which
// manifests as horizontal-band corruption around the thumbnail.

#[test]
fn mit_shm_put_image_honors_gc_clip_rectangles() {
    const CLIENT: u32 = 1;
    const PIXMAP: u32 = 0x0020_0001;
    const GC: u32 = 0x0020_0002;
    const SHMSEG: u32 = 0x0020_0003;
    const HOST_PIXMAP: u32 = 0x0040_0001;

    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();
    state.resources.create_pixmap(
        ClientId(CLIENT),
        x11::CreatePixmapRequest {
            depth: 32,
            pixmap: ResourceId(PIXMAP),
            drawable: ROOT_WINDOW,
            width: 4,
            height: 4,
        },
    );
    assert!(state.resources.set_pixmap_host_xid(
        ResourceId(PIXMAP),
        crate::backend::PixmapHandle::from_raw(HOST_PIXMAP).expect("non-zero host pixmap"),
    ));
    state.resources.create_gc(
        ClientId(CLIENT),
        CreateGcRequest {
            gc: ResourceId(GC),
            drawable: ResourceId(PIXMAP),
            function: None,
            plane_mask: None,
            foreground: None,
            background: None,
            line_width: None,
            line_style: None,
            cap_style: None,
            join_style: None,
            fill_style: None,
            fill_rule: None,
            tile: None,
            stipple: None,
            tile_x_origin: None,
            tile_y_origin: None,
            font: None,
            subwindow_mode: None,
            graphics_exposures: None,
            clip_x_origin: None,
            clip_y_origin: None,
            clip_mask: None,
            dash_offset: None,
            dashes: None,
            arc_mode: None,
        },
    );
    let clip = x11::ClipRectangles {
        ordering: 0,
        x_origin: 0,
        y_origin: 0,
        rectangles: [
            0i16.to_le_bytes(),
            1i16.to_le_bytes(),
            4u16.to_le_bytes(),
            1u16.to_le_bytes(),
        ]
        .concat(),
    };
    state.resources.set_clip_rectangles(
        ClientId(CLIENT),
        x11::SetClipRectanglesRequest {
            gc: ResourceId(GC),
            clip: clip.clone(),
        },
    );

    let fd = unsafe { libc::memfd_create(c"mit-shm-put-image-test".as_ptr(), libc::MFD_CLOEXEC) };
    assert!(fd >= 0, "memfd_create failed");
    assert_eq!(unsafe { libc::ftruncate(fd, 64) }, 0, "ftruncate failed");
    let mut segment = crate::server::MitShmSegment::from_fd(ClientId(CLIENT), fd, false)
        .expect("map test SHM segment");
    segment
        .as_mut_slice()
        .expect("writable SHM segment")
        .fill(0xff);
    state.mit_shm_segments.insert(SHMSEG, segment);

    handle_mit_shm_put_image(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT),
        SequenceNumber(1),
        yserver_protocol::x11::mit_shm::PutImageRequest {
            drawable: PIXMAP,
            gc: GC,
            total_width: 4,
            total_height: 4,
            src_x: 0,
            src_y: 0,
            src_width: 4,
            src_height: 4,
            dst_x: 0,
            dst_y: 0,
            depth: 32,
            format: 2,
            send_event: false,
            shmseg: SHMSEG,
            offset: 0,
        },
    )
    .expect("MIT-SHM PutImage succeeds");

    assert!(backend.calls.lock().expect("calls lock").contains(
        &crate::backend::recording::RecordedCall::ApplyClipState(
            crate::backend::ClipState::Rectangles {
                origin: (0, 0),
                rects: clip,
            },
        ),
    ));
}

fn d32_pixel(b: u8, g: u8, r: u8, a: u8) -> [u8; 4] {
    // Wire byte order for a depth-32 ZPixmap is [B, G, R, A] —
    // see the comment in `try_vk_put_image`.
    [b, g, r, a]
}

#[test]
fn extract_d32_tight_packing_returns_input() {
    // total == src, src_xy == 0 → output is exactly the input.
    let mut bytes = Vec::new();
    for y in 0..4u8 {
        for x in 0..4u8 {
            bytes.extend_from_slice(&d32_pixel(x, y, x ^ y, 0xFF));
        }
    }
    let out = extract_shm_zpixmap_region(&bytes, 0, 4, 4, 0, 0, 4, 4, 32)
        .expect("tight extraction succeeds");
    assert_eq!(out, bytes);
}

/// 2026-05-28 perf-cliff fix: full-frame extracts MUST return
/// `Cow::Borrowed` (no allocation, no memcpy). On cinnamon the
/// hot-path PutImage of the 28MB compositor stage was spending
/// 8-10ms in the legacy per-row Vec::extend_from_slice loop.
/// Borrowing the SHM slice directly drops it to a bounds-check.
/// Tested both depth=24 and depth=32 at the boundary (full frame,
/// no offset, row_bytes == src_stride) and against a partial /
/// padded case that MUST still allocate.
#[test]
fn extract_full_frame_d32_returns_borrowed_slice() {
    // 8×4 full-frame extract, depth 32 → row_bytes == src_stride.
    let mut bytes = Vec::new();
    for y in 0..4u8 {
        for x in 0..8u8 {
            bytes.extend_from_slice(&d32_pixel(x, y, x ^ y, 0xFF));
        }
    }
    let out = extract_shm_zpixmap_region(&bytes, 0, 8, 4, 0, 0, 8, 4, 32)
        .expect("full-frame d32 extraction succeeds");
    assert!(
        matches!(out, std::borrow::Cow::Borrowed(_)),
        "full-frame extract must zero-copy (Cow::Borrowed)",
    );
    assert_eq!(out.as_ref(), bytes.as_slice());
}

#[test]
fn extract_full_frame_d24_returns_borrowed_slice() {
    // 8×4 full-frame, depth 24 (4 bytes per pixel — same as d32).
    let mut bytes = Vec::new();
    for y in 0..4u8 {
        for x in 0..8u8 {
            bytes.extend_from_slice(&d32_pixel(x, y, x ^ y, 0xFF));
        }
    }
    let out = extract_shm_zpixmap_region(&bytes, 0, 8, 4, 0, 0, 8, 4, 24)
        .expect("full-frame d24 extraction succeeds");
    assert!(
        matches!(out, std::borrow::Cow::Borrowed(_)),
        "full-frame d24 extract must zero-copy (Cow::Borrowed)",
    );
    assert_eq!(out.as_ref(), bytes.as_slice());
}

#[test]
fn extract_partial_region_returns_owned_vec() {
    // Same data but ask for a sub-region — the borrow fast path
    // MUST NOT trigger.
    let mut bytes = Vec::new();
    for y in 0..8u8 {
        for x in 0..8u8 {
            bytes.extend_from_slice(&d32_pixel(x, y, 0, 0xFF));
        }
    }
    let out = extract_shm_zpixmap_region(&bytes, 0, 8, 8, 2, 2, 4, 4, 32)
        .expect("partial extraction succeeds");
    assert!(
        matches!(out, std::borrow::Cow::Owned(_)),
        "partial extract must allocate (Cow::Owned)",
    );
}

#[test]
fn extract_d8_padded_full_frame_does_not_borrow() {
    // Depth-8 with src_width=5 → src_stride=8 (pad-to-32-bit).
    // row_bytes (5) < src_stride (8) — the borrow fast path's
    // `row_bytes == src_stride` precondition excludes this so
    // the slow padding path runs.
    let bytes: Vec<u8> = (0..16).map(|i| i as u8).collect();
    let out = extract_shm_zpixmap_region(&bytes, 0, 5, 2, 0, 0, 5, 2, 8)
        .expect("padded d8 extraction succeeds");
    assert!(
        matches!(out, std::borrow::Cow::Owned(_)),
        "padded full-frame d8 must NOT borrow (per-row padding required)",
    );
}

#[test]
fn extract_d32_subregion_of_larger_buffer() {
    // 8×8 total, take 4×4 at (2, 2). The handler must read row 2
    // bytes 8..24, row 3 bytes 8..24, etc. — NOT 64 contiguous
    // bytes from offset 0, which is what the pre-fix handler
    // did.
    let mut bytes = Vec::new();
    for y in 0..8u8 {
        for x in 0..8u8 {
            bytes.extend_from_slice(&d32_pixel(x, y, 0, 0xFF));
        }
    }
    let out = extract_shm_zpixmap_region(&bytes, 0, 8, 8, 2, 2, 4, 4, 32)
        .expect("subregion extraction succeeds");
    // Output must be the (2,2)..(6,6) tile, tightly packed.
    let mut want = Vec::new();
    for y in 2..6u8 {
        for x in 2..6u8 {
            want.extend_from_slice(&d32_pixel(x, y, 0, 0xFF));
        }
    }
    assert_eq!(out, want);
}

#[test]
fn extract_d32_total_wider_than_src() {
    // 16×4 total, take 4×4 at (0, 0). Each src row must skip the
    // unused 12 trailing pixels of the total row.
    let mut bytes = Vec::new();
    for y in 0..4u8 {
        for x in 0..16u8 {
            bytes.extend_from_slice(&d32_pixel(x, y, 0, 0xFF));
        }
    }
    let out = extract_shm_zpixmap_region(&bytes, 0, 16, 4, 0, 0, 4, 4, 32)
        .expect("wide-total extraction succeeds");
    let mut want = Vec::new();
    for y in 0..4u8 {
        for x in 0..4u8 {
            want.extend_from_slice(&d32_pixel(x, y, 0, 0xFF));
        }
    }
    assert_eq!(out, want);
}

#[test]
fn extract_honors_offset() {
    // Image starts partway into the shm segment.
    let mut bytes = vec![0xAAu8; 16];
    for y in 0..2u8 {
        for x in 0..2u8 {
            bytes.extend_from_slice(&d32_pixel(x, y, 0xFF, 0xFF));
        }
    }
    let out = extract_shm_zpixmap_region(&bytes, 16, 2, 2, 0, 0, 2, 2, 32)
        .expect("offset extraction succeeds");
    assert_eq!(out, &bytes[16..]);
}

#[test]
fn extract_d8_padding_total_wider_than_src() {
    // 6-wide total → 8 bytes/row (padded to 32-bit). Take a 5×2
    // tile. Output stride is `((5 + 3) & ~3) = 8` bytes/row so
    // we get 16 bytes; first 5 are image data, next 3 are pad.
    let bytes: Vec<u8> = (0..16).map(|i| i as u8).collect();
    let out =
        extract_shm_zpixmap_region(&bytes, 0, 6, 2, 0, 0, 5, 2, 8).expect("d8 extraction succeeds");
    assert_eq!(out.len(), 16);
    // Row 0 image bytes: 0..5 of the input; row 0 trailing pad: zero.
    assert_eq!(&out[..5], &bytes[..5]);
    assert_eq!(&out[5..8], &[0, 0, 0]);
    // Row 1 image bytes: 8..13 of the input.
    assert_eq!(&out[8..13], &bytes[8..13]);
    assert_eq!(&out[13..16], &[0, 0, 0]);
}

#[test]
fn extract_d8_src_x_offset() {
    // 8-wide total → 8 bytes/row. Take a 4×1 tile at src_x=2.
    let bytes: Vec<u8> = (0..8).map(|i| i as u8).collect();
    let out = extract_shm_zpixmap_region(&bytes, 0, 8, 1, 2, 0, 4, 1, 8)
        .expect("d8 src_x extraction succeeds");
    // src_width=4 → src_stride=4 (already 32-bit aligned). Output is bytes 2..6.
    assert_eq!(out, vec![2u8, 3, 4, 5]);
}

#[test]
fn extract_rejects_region_outside_total() {
    let bytes = vec![0u8; 64];
    // src_x + src_width > total_width
    assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, 2, 0, 4, 4, 32).is_none());
    // src_y + src_height > total_height
    assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, 0, 2, 4, 4, 32).is_none());
}

#[test]
fn extract_rejects_negative_src_xy() {
    let bytes = vec![0u8; 64];
    assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, -1, 0, 4, 4, 32).is_none());
    assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, 0, -1, 4, 4, 32).is_none());
}

#[test]
fn extract_rejects_offset_beyond_buffer() {
    let bytes = vec![0u8; 16];
    // 4×4 d32 = 64 bytes; only 16 available.
    assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, 0, 0, 4, 4, 32).is_none());
}

#[test]
fn extract_rejects_unsupported_depth() {
    let bytes = vec![0u8; 64];
    assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, 0, 0, 4, 4, 16).is_none());
}

#[test]
fn extract_d24_treats_padding_byte_as_image_data() {
    // d24 on the wire is 4 bytes per pixel like d32; the 4th
    // byte is undefined but transmitted. Extraction must copy
    // all 4 bytes — the put_image backend stamps 0xFF later.
    let mut bytes = Vec::new();
    for y in 0..2u8 {
        for x in 0..2u8 {
            bytes.extend_from_slice(&d32_pixel(x, y, 0xCC, 0x77));
        }
    }
    let out = extract_shm_zpixmap_region(&bytes, 0, 2, 2, 0, 0, 2, 2, 24)
        .expect("d24 extraction succeeds");
    assert_eq!(out, bytes);
}

