#[test]
fn redirect_invalid_mode_returns_bad_value() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    // Anything outside {0, 1} is a spec violation → BadValue.
    create_root_child(&mut state, 0x0010_0001);
    dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), 0x0010_0001, 2);
    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf).expect("error delivered");
    assert_eq!(buf[0], 0);
    // BAD_VALUE = 2
    assert_eq!(buf[1], 2, "expected BadValue (2), got {}", buf[1]);
    assert!(state.composite_redirects.is_empty());
}

// ---------------- Stage 4d gate: COW host_xid wiring ----------------
//
// Marco-with-compositing uses **pure PRESENT-pixmap onto COW** with zero
// `RedirectSubwindows` / `NameWindowPixmap` calls — it repeatedly emits
// `PRESENT::Pixmap(window=0x103 /* COW */, pixmap=client_offscreen)`.
//
// `process_present_pixmap` resolves both endpoints via
// `state.resources.host_drawable_target(...)`, which returns `None` when
// `window.host_xid` is `None`. Stage 4d allocated COW storage on the
// backend (`KmsBackend.cow_id`) and registered with the scene, but
// left `host_xid` `None` on the yserver-core resource record (seeded
// that way at `ResourceTable::new` since the COW xid pre-exists the
// backend-side allocation). Every `PresentPixmap → COW` therefore
// silently fell through the `if let (Some, Some)` guard at
// `process_request.rs:~4124` and dropped paint.
//
// Fix: on the GET_OVERLAY_WINDOW arm, after the backend hook lands
// successfully, wire `host_xid = Some(0x103)` and copy root dimensions
// onto the COW resource record. On the final RELEASE_OVERLAY_WINDOW,
// destroy the record so the next GET re-wires fresh storage.
//
// These tests use `RecordingBackend`. Which release is final is
// decided by core's claim list (`ServerState::cow_claims`), not by
// the backend — the backend counts nothing.

fn dispatch_composite_minor(
    state: &mut ServerState,
    backend: &mut dyn crate::backend::Backend,
    client_id: ClientId,
    sequence: u16,
    minor: u8,
    body: &[u8],
) -> RequestOutcome {
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body fits");
    process_request(
        state,
        backend,
        client_id,
        SequenceNumber(sequence),
        RequestHeader {
            opcode: 144, // COMPOSITE
            data: minor,
            length_units,
        },
        body,
        None,
    )
    .unwrap()
}

#[test]
fn name_window_pixmap_uses_redirected_backing_geometry() {
    use crate::{
        backend::{PixmapHandle, WindowHandle},
        resources::RedirectedBacking,
        server::{CompositeRedirectMode, RedirectRecord},
    };
    use yserver_protocol::x11::CreateWindowRequest;

    const WINDOW: ResourceId = ResourceId(0x10004a);
    const PIXMAP: ResourceId = ResourceId(0x300225);

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new().with_composite_support();
    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 32,
            window: WINDOW,
            parent: ROOT_WINDOW,
            width: 646,
            height: 501,
            border_width: 2,
            class: 1,
            visual: crate::resources::ARGB_VISUAL,
            ..Default::default()
        },
    );
    assert!(state.resources.map_window(WINDOW).mapping_changed);
    let window = state
        .resources
        .window_mut(WINDOW)
        .expect("window installed");
    window.host_xid = Some(WindowHandle::from_raw_for_test(0x40008a));
    window.redirected_backing = Some(RedirectedBacking {
        host_pixmap: PixmapHandle::from_raw_for_test(0x4000d),
        width: 650,
        height: 505,
        depth: 32,
    });
    state
        .composite_redirects
        .redirect_window(
            WINDOW,
            RedirectRecord {
                mode: CompositeRedirectMode::Manual,
                owner: ClientId(1),
            },
        )
        .unwrap();

    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&WINDOW.0.to_le_bytes());
    body.extend_from_slice(&PIXMAP.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::NAME_WINDOW_PIXMAP,
        &body,
    );

    let pixmap = state.resources.pixmap(PIXMAP).expect("named pixmap exists");
    assert_eq!((pixmap.width, pixmap.height), (650, 505));
    let aliases = &state
        .resources
        .window(WINDOW)
        .expect("window remains installed")
        .composite_named_pixmaps;
    assert_eq!(aliases.len(), 1);
    assert_eq!((aliases[0].width, aliases[0].height), (650, 505));
}

#[test]
fn get_overlay_window_wires_cow_host_xid() {
    // Pre-condition: COW resource record does NOT exist (post-Task-2.1
    // the pre-seed is gone; COW materialises only on GetOverlayWindow).
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    assert!(
        state
            .resources
            .window(crate::resources::COMPOSITE_OVERLAY_WINDOW)
            .is_none(),
        "COW must NOT be pre-seeded; the materialise-on-GET model \
             owns the entire COW lifecycle (Task 2.1 + Task 2.4)",
    );

    // GetOverlayWindow body: window xid (we use root, marco ignores
    // the reply's input and just trusts whatever XID we hand back).
    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );

    // Load-bearing assertion: after GET, host_drawable_target must
    // resolve. This is what makes PresentPixmap → COW actually paint.
    let target = state
        .resources
        .host_drawable_target(crate::resources::COMPOSITE_OVERLAY_WINDOW);
    match target {
        Some(crate::resources::HostDrawableTarget::Window {
            nested,
            host_xid,
            depth,
        }) => {
            assert_eq!(nested, crate::resources::COMPOSITE_OVERLAY_WINDOW);
            assert_eq!(
                host_xid.as_raw(),
                crate::resources::COMPOSITE_OVERLAY_WINDOW.0,
                "COW host_xid must equal its protocol xid (0x103)",
            );
            assert_eq!(depth, 24, "COW is depth-24");
        }
        other => panic!(
            "host_drawable_target(COW) must resolve to Window after \
                 GetOverlayWindow — got {other:?}. Pre-fix shape returned \
                 None (host_xid still unset on the resource record), which \
                 dropped every PresentPixmap → COW.",
        ),
    }

    // Dimensions: COW should track the root extent (the backend's
    // COW storage is screen-extent per the Stage 4d plan).
    let cow = state
        .resources
        .window(crate::resources::COMPOSITE_OVERLAY_WINDOW)
        .expect("COW record");
    let root = state
        .resources
        .window(crate::resources::ROOT_WINDOW)
        .expect("ROOT record");
    assert_eq!(cow.width, root.width, "COW must match root extent");
    assert_eq!(cow.height, root.height, "COW must match root extent");
}

#[test]
fn repeated_get_reuses_materialized_host_overlay() {
    // A compositor may emit GetOverlayWindow multiple times (e.g.
    // re-registration on a window-manager hand-off). What is stable
    // across those calls is the identity of the already-materialized
    // host overlay: the `host_xid.is_none()` guard prevents repeated
    // allocation and host_xid stays wired.
    //
    // The *request* is deliberately NOT idempotent — each call
    // records another claim in `state.cow_claims` (Xorg's N-record
    // model) and each needs its own ReleaseOverlayWindow.
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        2,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );

    let cow = state
        .resources
        .window(crate::resources::COMPOSITE_OVERLAY_WINDOW)
        .expect("COW record");
    assert_eq!(
        cow.host_xid.map(crate::backend::WindowHandle::as_raw),
        Some(crate::resources::COMPOSITE_OVERLAY_WINDOW.0),
        "host_xid stays wired across repeated GETs",
    );
    assert_eq!(
        state.cow_claims,
        vec![ClientId(1), ClientId(1)],
        "each GET records its own claim — what moved to the core claim \
             list is exactly what the backend refcount used to count",
    );
}

/// Xorg `compCreateOverlayWindow` (`composite/compoverlay.c:149`) gives the
/// overlay no input shape, so it takes the pointer over the whole screen
/// until the compositor empties its input region, and again after a reset
/// to None (measured on Xvfb 21.1, tools/vng-scenarios/cow-input-shape).
#[test]
fn overlay_window_takes_the_pointer_until_its_input_region_is_emptied() {
    use yserver_protocol::x11::{shape as x11shape, xfixes as x11xfixes};

    const APP: ResourceId = ResourceId(0x0020_0001);
    const REGION: u32 = 0x0010_0042;
    let cow = crate::resources::COMPOSITE_OVERLAY_WINDOW;
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: APP,
            parent: ROOT_WINDOW,
            x: 100,
            y: 100,
            width: 200,
            height: 200,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(APP);
    let hit = |state: &ServerState| state.root_pointer_target_at(150, 150).map(|h| h.0);
    assert_eq!(hit(&state), Some(APP));

    let mut body = ROOT_WINDOW.0.to_le_bytes().to_vec();
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    assert_eq!(hit(&state), Some(cow), "an unshaped COW takes the pointer");

    let mut xfixes = |state: &mut ServerState, minor: u8, body: Vec<u8>| {
        let header = yserver_protocol::x11::RequestHeader {
            opcode: XFIXES_MAJOR_OPCODE,
            data: minor,
            length_units: u32::try_from(1 + body.len() / 4).unwrap(),
        };
        handle_xfixes_request(
            state,
            &mut backend,
            None,
            ClientId(1),
            SequenceNumber(2),
            header,
            &body,
        )
        .expect("XFIXES request");
    };
    let input_region = |region: u32| {
        let mut body = cow.0.to_le_bytes().to_vec();
        body.extend_from_slice(&[x11shape::KIND_INPUT, 0, 0, 0, 0, 0, 0, 0]);
        body.extend_from_slice(&region.to_le_bytes());
        body
    };
    xfixes(
        &mut state,
        x11xfixes::CREATE_REGION,
        REGION.to_le_bytes().to_vec(),
    );
    xfixes(
        &mut state,
        x11xfixes::SET_WINDOW_SHAPE_REGION,
        input_region(REGION),
    );
    assert_eq!(
        hit(&state),
        Some(APP),
        "an empty input region passes through"
    );
    xfixes(
        &mut state,
        x11xfixes::SET_WINDOW_SHAPE_REGION,
        input_region(0),
    );
    assert_eq!(hit(&state), Some(cow), "None restores the default region");

    body[0..4].copy_from_slice(&cow.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        3,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &body,
    );
    assert_eq!(hit(&state), Some(APP));
}

#[test]
fn overlay_window_create_and_release_notify_root_substructure_listeners() {
    // Xorg compCreateOverlayWindow / DeleteWindow, measured on Xvfb 21.1
    // (tools/vng-scenarios/composite-reredirect): CreateNotify, MapNotify;
    // then UnmapNotify, DestroyNotify after the last release.
    const SUBSTRUCTURE_NOTIFY: u32 = 0x0008_0000;
    const STRUCTURE_NOTIFY: u32 = 0x0002_0000;
    let mut state = ServerState::new();
    let _compositor = install_client(&mut state, 1);
    let mut listener = install_client(&mut state, 2);
    let mut backend = RecordingBackend::new();
    state
        .clients
        .get_mut(&2)
        .expect("listener")
        .event_masks
        .insert(ROOT_WINDOW, SUBSTRUCTURE_NOTIFY);
    let cow = crate::resources::COMPOSITE_OVERLAY_WINDOW;
    let events = |bytes: &[u8]| -> Vec<(u8, u32, u32)> {
        let word =
            |e: &[u8], at: usize| u32::from_le_bytes([e[at], e[at + 1], e[at + 2], e[at + 3]]);
        bytes
            .chunks_exact(32)
            .map(|e| (e[0], word(e, 4), word(e, 8)))
            .collect()
    };
    let root_body = ROOT_WINDOW.0.to_le_bytes();
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &root_body,
    );
    assert_eq!(
        events(&read_all_available(&mut listener)),
        vec![(16, ROOT_WINDOW.0, cow.0), (19, ROOT_WINDOW.0, cow.0)],
        "CreateNotify(parent=root, window=COW), MapNotify(event=root)"
    );
    state
        .clients
        .get_mut(&2)
        .expect("listener")
        .event_masks
        .insert(cow, STRUCTURE_NOTIFY);
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        2,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &root_body,
    );
    assert_eq!(
        events(&read_all_available(&mut listener)),
        vec![
            (18, cow.0, cow.0),
            (18, ROOT_WINDOW.0, cow.0),
            (17, cow.0, cow.0),
            (17, ROOT_WINDOW.0, cow.0),
        ],
    );
}

#[test]
fn release_overlay_window_destroys_cow_resource_on_final_release() {
    // Final release (backend returns Ok(true)) must DESTROY the COW
    // resource record entirely (record removed from `windows`, edge
    // removed from `root.children`) so a subsequent `GetOverlayWindow`
    // re-materialises fresh storage via the 0→1 backend path. The
    // pre-Task-2.5 shape merely cleared `host_xid` on the still-existing
    // record; that diverged from Xorg (no record between
    // release-and-next-claim) and silently retained per-COW state
    // (event masks, properties) across the release boundary.
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    // Wire COW via GET first.
    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    assert!(
        state
            .resources
            .window(crate::resources::COMPOSITE_OVERLAY_WINDOW)
            .and_then(|w| w.host_xid)
            .is_some(),
    );
    let old_generation =
        state.present_window_generation(crate::resources::COMPOSITE_OVERLAY_WINDOW.0);
    state.present_window_msc.insert(
        crate::resources::COMPOSITE_OVERLAY_WINDOW.0,
        crate::server::PresentWindowMsc {
            last_crtc: 2,
            last_crtc_epoch: 1,
            msc_offset: 10,
            last_raw_msc: 20,
        },
    );
    state.present_event_selections.insert(
        0x0001_c0e1,
        crate::server::PresentEventSelection {
            owner: ClientId(1),
            window: crate::resources::COMPOSITE_OVERLAY_WINDOW,
            event_mask: yserver_protocol::x11::present::EVENT_MASK_COMPLETE_NOTIFY,
        },
    );
    state
        .present_pending_msc
        .push(crate::server::PendingNotifyMsc {
            owner: ClientId(1),
            window: crate::resources::COMPOSITE_OVERLAY_WINDOW.0,
            crtc_id: 2,
            crtc_epoch: 1,
            msc_offset: 10,
            serial: 1,
            target_msc: 30,
            divisor: 0,
            remainder: 0,
            byte_order: ClientByteOrder::LittleEndian,
        });
    let stale_event = crate::backend::CompletedPresentEvent {
        client_id: ClientId(1),
        serial: 1,
        host_xid: 0x0001_c002,
        dst_host_xid: crate::resources::COMPOSITE_OVERLAY_WINDOW.0,
        options: 0,
        present_id: 0x_c0,
        window_generation: old_generation,
        crtc_id: 2,
        crtc_epoch: 1,
        msc_offset: 10,
        completion_clock: None,
        wake: crate::backend::PresentWake::Pixmap { idle_fence_xid: 0 },
        completion_mode: yserver_protocol::x11::present::COMPLETE_MODE_COPY,
        emit_idle: true,
    };

    // Final release — client 1 holds the only claim.
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        2,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &[],
    );
    assert!(
        state
            .resources
            .window(crate::resources::COMPOSITE_OVERLAY_WINDOW)
            .is_none(),
        "final release (backend.Ok(true)) must destroy the COW resource \
             record entirely so the next GetOverlayWindow re-materialises \
             fresh storage",
    );
    assert!(
        !state
            .resources
            .window(crate::resources::ROOT_WINDOW)
            .unwrap()
            .children
            .contains(&crate::resources::COMPOSITE_OVERLAY_WINDOW),
        "final release must remove COW from root.children too",
    );
    assert!(
        !state
            .present_window_generations
            .contains_key(&crate::resources::COMPOSITE_OVERLAY_WINDOW.0)
    );
    assert!(
        !state
            .present_window_msc
            .contains_key(&crate::resources::COMPOSITE_OVERLAY_WINDOW.0)
    );
    assert!(state.present_pending_msc.is_empty());
    assert!(state.present_event_selections.is_empty());

    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        3,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    let new_generation =
        state.present_window_generation(crate::resources::COMPOSITE_OVERLAY_WINDOW.0);
    assert_ne!(new_generation, old_generation);
    state.present_event_selections.insert(
        0x0001_c0e2,
        crate::server::PresentEventSelection {
            owner: ClientId(1),
            window: crate::resources::COMPOSITE_OVERLAY_WINDOW,
            event_mask: yserver_protocol::x11::present::EVENT_MASK_COMPLETE_NOTIFY,
        },
    );
    let _ = read_all_available(&mut peer);
    backend.completed_present_events_to_drain.push(stale_event);
    crate::core_loop::run::run_iteration_tail(&mut state, &mut backend);
    assert_eq!(backend.signalled_present_wakes, vec![0x_c0]);
    assert!(read_all_available(&mut peer).is_empty());
}

#[test]
fn release_overlay_window_keeps_host_xid_on_non_final_release() {
    // Non-final release (a claim remains): storage is still live on
    // the backend, host_xid must stay wired so any remaining
    // compositor's PresentPixmap → COW keeps landing.
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let _peer_b = install_client(&mut state, 2);
    let mut backend = RecordingBackend::new();

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    // A second claimant, so client 2's release below is not the final
    // one. Which release is final is core's decision, taken from the
    // claim list — the backend has no say and no counter.
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(2),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );

    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(2),
        2,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &[],
    );
    let cow = state
        .resources
        .window(crate::resources::COMPOSITE_OVERLAY_WINDOW)
        .expect("COW record");
    assert_eq!(
        cow.host_xid.map(crate::backend::WindowHandle::as_raw),
        Some(crate::resources::COMPOSITE_OVERLAY_WINDOW.0),
        "non-final release must keep host_xid wired — \
             storage is still alive on the backend",
    );
}

/// Get by A, Release by B ⇒ `BadMatch`, and A's claim survives.
/// Xorg's `ProcCompositeReleaseOverlayWindow` looks the caller up
/// with `compFindOverlayClient` and refuses when it holds no record.
#[test]
fn release_overlay_window_by_non_claimant_is_badmatch() {
    let mut state = ServerState::new();
    let _peer_a = install_client(&mut state, 1);
    let mut peer_b = install_client(&mut state, 2);
    let mut backend = RecordingBackend::new();

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    let _ = read_all_available(&mut peer_b);

    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(2),
        1,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &[],
    );

    assert_error_code(
        &read_all_available(&mut peer_b),
        yserver_protocol::x11::error::BAD_MATCH,
        "ReleaseOverlayWindow from a client holding no claim",
    );
    assert!(
        backend.cow_materialized,
        "B's refused release must not tear the overlay out from under A",
    );
    assert!(
        state
            .resources
            .window(crate::resources::COMPOSITE_OVERLAY_WINDOW)
            .is_some(),
        "A's claim must survive B's refused release",
    );
}

/// `ReleaseOverlayWindow` from a client that never claimed anything,
/// with no claim outstanding anywhere, is `BadMatch` and changes
/// nothing. Xorg answers the same via `compFindOverlayClient`.
#[test]
fn release_overlay_window_with_no_claim_anywhere_is_badmatch() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &[],
    );

    assert_error_code(
        &read_all_available(&mut peer),
        yserver_protocol::x11::error::BAD_MATCH,
        "unpaired ReleaseOverlayWindow",
    );
    assert!(state.cow_claims.is_empty());
    assert!(
        !backend.cow_materialized,
        "a refused release must not touch the backend at all",
    );
}

/// N Gets need N Releases: Get and Release pair 1:1, as Xorg's
/// per-Get `CompOverlayClientRec` records do. The overlay survives
/// every release but the last.
#[test]
fn repeated_gets_need_matching_releases() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    for seq in 1..=3 {
        dispatch_composite_minor(
            &mut state,
            &mut backend,
            ClientId(1),
            seq,
            yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
            &body,
        );
    }
    assert_eq!(state.cow_claims.len(), 3);

    for seq in 4..=5 {
        dispatch_composite_minor(
            &mut state,
            &mut backend,
            ClientId(1),
            seq,
            yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
            &[],
        );
    }
    assert_eq!(state.cow_claims.len(), 1);
    assert!(
        backend.cow_materialized,
        "two of three claims released — the overlay must still be up",
    );
    let _ = read_all_available(&mut peer);

    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        6,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &[],
    );
    assert!(state.cow_claims.is_empty());
    assert!(
        !backend.cow_materialized,
        "the third release is the final one"
    );
    assert!(
        state
            .resources
            .window(crate::resources::COMPOSITE_OVERLAY_WINDOW)
            .is_none(),
    );

    // A fourth release has nothing left to pair with.
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        7,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &[],
    );
    assert_error_code(
        &read_all_available(&mut peer),
        yserver_protocol::x11::error::BAD_MATCH,
        "one release too many",
    );
}

/// Two claimants: the first Release is not the final one, so the
/// backend is not called and the overlay stays up for the other
/// claimant.
#[test]
fn two_claimants_first_release_is_not_final() {
    let mut state = ServerState::new();
    let _peer_a = install_client(&mut state, 1);
    let _peer_b = install_client(&mut state, 2);
    let mut backend = RecordingBackend::new();

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    for client in [1u32, 2] {
        dispatch_composite_minor(
            &mut state,
            &mut backend,
            ClientId(client),
            1,
            yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
            &body,
        );
    }

    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        2,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &[],
    );

    assert_eq!(
        state.cow_claims,
        vec![ClientId(2)],
        "A released exactly its own claim; B's is untouched",
    );
    assert!(backend.cow_materialized);

    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(2),
        2,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &[],
    );
    assert!(state.cow_claims.is_empty());
    assert!(!backend.cow_materialized);
}

/// Transactional first Get: if materialization fails, the claim is
/// rolled back and the caller gets `BadAlloc`. A claim recorded
/// against an overlay that does not exist is the desynchronisation
/// this model removes.
#[test]
fn first_get_materialization_failure_records_no_claim() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    backend.cow_materialize_fails = true;

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );

    assert_error_code(
        &read_all_available(&mut peer),
        yserver_protocol::x11::error::BAD_ALLOC,
        "GetOverlayWindow whose materialization failed",
    );
    assert!(
        state.cow_claims.is_empty(),
        "the claim must be rolled back — never leave one recorded \
             against an overlay that does not exist",
    );
    assert!(
        state
            .resources
            .window(crate::resources::COMPOSITE_OVERLAY_WINDOW)
            .is_none(),
    );

    // And the server is not poisoned: a retry that succeeds works.
    backend.cow_materialize_fails = false;
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        2,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    assert_eq!(state.cow_claims, vec![ClientId(1)]);
    assert!(backend.cow_materialized);
}

/// The headline case, and the bug at its own level: a compositor
/// takes the overlay and **disconnects without releasing**. Its claim
/// must be gone and the overlay torn down. No reset anywhere in this
/// test.
///
/// Not to be confused with `scene.root_overlay` /
/// `root_overlay_on_disconnect` (`kms/render/backend.rs`), a
/// different concept with a confusingly similar name that
/// `Backend::client_disconnected` already handles correctly —
/// finding that call is what makes this leak look handled.
#[test]
fn disconnect_releases_overlay_claim_and_tears_down_cow() {
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    assert_eq!(state.cow_claims, vec![ClientId(1)]);

    crate::core_loop::process_disconnect::process_disconnect(&mut state, &mut backend, ClientId(1));

    assert!(
        state.cow_claims.is_empty(),
        "no claim may outlive its owner",
    );
    assert!(
        !backend.cow_materialized,
        "the departing claimant held the last claim — the backend COW \
             must be torn down",
    );
    assert!(
        state
            .resources
            .window(crate::resources::COMPOSITE_OVERLAY_WINDOW)
            .is_none(),
        "the resources-side COW record must come down with it",
    );
}

/// Repeated Gets from one client, then it disconnects: all of its
/// claims go, matching Xorg's N-records model where the resource
/// system frees every `CompOverlayClientRec` the client owns.
#[test]
fn disconnect_releases_all_of_a_clients_repeated_overlay_claims() {
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    for seq in 1..=3 {
        dispatch_composite_minor(
            &mut state,
            &mut backend,
            ClientId(1),
            seq,
            yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
            &body,
        );
    }
    assert_eq!(state.cow_claims.len(), 3);

    crate::core_loop::process_disconnect::process_disconnect(&mut state, &mut backend, ClientId(1));

    assert!(state.cow_claims.is_empty(), "all three claims must go");
    assert!(!backend.cow_materialized);
}

/// Two claimants: the overlay survives the first departure and comes
/// down on the second.
#[test]
fn overlay_survives_first_claimants_disconnect_and_dies_with_the_second() {
    let mut state = ServerState::new();
    let _peer_a = install_client(&mut state, 1);
    let _peer_b = install_client(&mut state, 2);
    let mut backend = RecordingBackend::new();

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    for client in [1u32, 2] {
        dispatch_composite_minor(
            &mut state,
            &mut backend,
            ClientId(client),
            1,
            yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
            &body,
        );
    }

    crate::core_loop::process_disconnect::process_disconnect(&mut state, &mut backend, ClientId(1));
    assert_eq!(state.cow_claims, vec![ClientId(2)]);
    assert!(
        backend.cow_materialized,
        "B still holds a claim — the overlay must survive A's departure",
    );

    crate::core_loop::process_disconnect::process_disconnect(&mut state, &mut backend, ClientId(2));
    assert!(state.cow_claims.is_empty());
    assert!(!backend.cow_materialized);
}

/// `KillClient` on another client's resource calls
/// `process_disconnect` inline, bypassing
/// `disconnect_with_pending_cleanup`. That is exactly why the claim
/// release lives in `process_disconnect` and not in the funnel.
#[test]
fn kill_client_releases_the_victims_overlay_claim() {
    let mut state = ServerState::new();
    let _peer_a = install_client(&mut state, 1);
    let _peer_b = install_client(&mut state, 2);
    let mut backend = RecordingBackend::new();

    // Client 2 owns a window, so client 1 can name it in KillClient.
    let victim_window = ResourceId(0x2000_0001);
    state.resources.create_window(
        ClientId(2),
        CreateWindowRequest {
            depth: 24,
            window: victim_window,
            parent: ROOT_WINDOW,
            width: 64,
            height: 64,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(2),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    assert_eq!(state.cow_claims, vec![ClientId(2)]);

    handle_kill_client(
        &mut state,
        &mut backend,
        ClientId(1),
        SequenceNumber(1),
        &victim_window.0.to_le_bytes(),
    )
    .expect("KillClient");

    assert!(
        !state.clients.contains_key(&2),
        "precondition: the victim was force-disconnected",
    );
    assert!(
        state.cow_claims.is_empty(),
        "the killed compositor's claim must go with it — KillClient \
             bypasses disconnect_with_pending_cleanup, so the release has \
             to live in process_disconnect",
    );
    assert!(!backend.cow_materialized);
}

/// A `RetainPermanent` claimant's overlay claims are released anyway
/// when its connection goes. The overlay is a screen-wide singleton;
/// a zombie holding it would block every future compositor.
#[test]
fn retained_clients_overlay_claims_are_released_anyway() {
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    // RetainPermanent.
    state.close_down_modes.insert(1, 1);

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );

    crate::core_loop::process_disconnect::process_disconnect(&mut state, &mut backend, ClientId(1));

    assert!(
        state.zombie_clients.contains_key(&1),
        "precondition: the client was retained, not destroyed",
    );
    assert!(
        state.cow_claims.is_empty(),
        "a claim is not a retainable resource",
    );
    assert!(!backend.cow_materialized);
}

/// Protocol path, final release, teardown fails: `BadAlloc`, and the
/// caller **keeps** its claim — the release did not happen, so a
/// compositor can retry. Xorg maps allocation failure in this
/// extension to `BadAlloc` (`composite/compext.c:216,220,263,297`),
/// and a shadow-buffer allocation failing is exactly that.
///
/// The pre-fix handler swallowed the backend `Err` into `false` and
/// reported protocol success for a teardown that did not occur.
#[test]
fn final_release_teardown_failure_is_badalloc_and_keeps_the_claim() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    let _ = read_all_available(&mut peer);
    backend.cow_teardown_fails = true;

    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        2,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &[],
    );

    assert_error_code(
        &read_all_available(&mut peer),
        yserver_protocol::x11::error::BAD_ALLOC,
        "ReleaseOverlayWindow whose teardown failed",
    );
    assert_eq!(
        state.cow_claims,
        vec![ClientId(1)],
        "the caller keeps its claim — the claim is what keeps the \
             overlay alive, so dropping it here is precisely the leak",
    );
    assert!(backend.cow_materialized, "the overlay is still up");
    assert!(
        !state.cow_teardown_failed,
        "the protocol path is retryable: no session-fatal state",
    );

    // And the retry works.
    backend.cow_teardown_fails = false;
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        3,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &[],
    );
    assert!(state.cow_claims.is_empty());
    assert!(!backend.cow_materialized);
}

/// Disconnect path, final release, teardown fails: the claims are
/// released **and** `cow_teardown_failed` is set. The two are not
/// alternatives — a leftover claim would be indistinguishable from a
/// live one and the next compositor would wait on a dead client.
///
/// A later `GetOverlayWindow` from a fresh client is then `BadAlloc`:
/// whatever it would receive is inherited from a session that could
/// not be torn down.
#[test]
fn disconnect_teardown_failure_sets_cow_teardown_failed() {
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut peer_b = install_client(&mut state, 2);
    let mut backend = RecordingBackend::new();

    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&crate::resources::ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    backend.cow_teardown_fails = true;

    crate::core_loop::process_disconnect::process_disconnect(&mut state, &mut backend, ClientId(1));

    assert!(
        state.cow_claims.is_empty(),
        "no claim outlives its owner, teardown failure or not",
    );
    assert!(
        state.cow_teardown_failed,
        "the orphaned overlay needs an owner that is not a claim",
    );
    assert!(
        backend.cow_materialized,
        "the overlay really is still up — that is the whole problem",
    );

    let _ = read_all_available(&mut peer_b);
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(2),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    assert_error_code(
        &read_all_available(&mut peer_b),
        yserver_protocol::x11::error::BAD_ALLOC,
        "GetOverlayWindow under cow_teardown_failed",
    );
    assert!(
        state.cow_claims.is_empty(),
        "the refused Get records no claim",
    );
}

// ---------------- rotate_redirected_backing_on_resize ----------------
//
// Marco-with-compositing resizes the top mate-panel from 25 → 28 px
// tall after `RedirectSubwindows(root, Manual)`. The subsequent
// `NameWindowPixmap(panel)` must succeed against fresh storage at
// the new size. Pre-fix v2 returned `NotFound` because the rotate
// path allocated-then-released against an idempotent
// `host_window_to_backing[W]` cache and freed the very pixmap it
// had just chosen to keep. This test pins release-then-allocate
// ORDER — flipping it back would regress the hardware smoke bug.
#[test]
fn rotate_redirected_backing_on_resize_releases_old_then_allocates_new() {
    use crate::backend::recording::RecordedCall;

    const WINDOW_XID: u32 = 0x0010_0001;
    const HOST_XID: u32 = 0x0040_0001;
    const OLD_BACKING: u32 = 0x0050_0001;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    // Install a top-level child of root, then prime it with a
    // pretend-existing redirected backing (the state we'd be in
    // after `RedirectSubwindows` + activation but before the
    // resize). 100x50 → resize target 100x75.
    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 32,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 50,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
        w.redirected_backing = Some(crate::resources::RedirectedBacking {
            host_pixmap: crate::backend::PixmapHandle::from_raw_for_test(OLD_BACKING),
            width: 100,
            height: 50,
            depth: 32,
        });
    }

    rotate_redirected_backing_on_resize(
        &mut state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        100,
        75,
        false,
        0,
    );

    let calls = backend.calls();
    // RetainBackingStorage comes first to keep OLD's storage
    // alive across the release→copy gap (see
    // `rotate_redirected_backing_retains_old_storage_across_release_then_drops_after_copy`).
    // Release must then precede Allocate so the backend's
    // idempotent `host_window_to_backing[W]` lookup misses on
    // the subsequent allocate.
    assert_eq!(
        calls[0],
        RecordedCall::RetainBackingStorage(OLD_BACKING),
        "step 1 must be RetainBackingStorage on OLD — keeps storage \
             alive across the release→copy gap so the no-alias case \
             doesn't drop the rotate copy",
    );
    assert_eq!(
        calls[1],
        RecordedCall::ReleaseRedirectedBacking(OLD_BACKING),
        "step 2 must be ReleaseRedirectedBacking on the OLD backing — \
             release-before-allocate is load-bearing (see fn doc-comment)",
    );
    assert_eq!(
        calls[2],
        RecordedCall::AllocateRedirectedBacking {
            host_window: HOST_XID,
            width: 100,
            height: 75,
            depth: 32,
        },
        "step 3 must be AllocateRedirectedBacking at the NEW size",
    );

    // Window resource now points at the freshly-allocated backing
    // (RecordingBackend hands back fresh handles per allocate).
    let backing = state
        .resources
        .window(ResourceId(WINDOW_XID))
        .and_then(|w| w.redirected_backing)
        .expect("redirected_backing repointed after rotate");
    assert_ne!(
        backing.host_pixmap.as_raw(),
        OLD_BACKING,
        "redirected_backing must point at the NEW pixmap, not the old one",
    );
    assert_eq!(backing.width, 100);
    assert_eq!(backing.height, 75);
    assert_eq!(backing.depth, 32);
}

/// How a GLX-TFP compositor lets go of a named, resized window.
#[derive(Clone, Copy, Debug)]
enum GlxTeardown {
    DestroyGlxThenFree,
    FreeThenDestroyGlx,
    DestroyWindowFirst,
    Disconnect,
}

fn drive(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    opcode: u8,
    data: u8,
    body: &[u8],
) {
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("fits");
    process_request(
        state,
        backend,
        ClientId(1),
        SequenceNumber(1),
        RequestHeader {
            opcode,
            data,
            length_units,
        },
        body,
        None,
    )
    .expect("process_request");
}

/// picom-glx under a WM: NameWindowPixmap + glXCreatePixmap, `resizes` resizes, then teardown.
fn glx_export_ref_after_resizes(resizes: u16, teardown: GlxTeardown) -> RecordingBackend {
    use yserver_protocol::x11::glx as x11glx;
    const WIN: u32 = 0x0077_0001;
    const PIX: u32 = 0x0077_0002;
    const GLXPIX: u32 = 0x0077_0003;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new()
        .with_composite_support()
        .with_redirect_activation();
    let mut cw = Vec::new();
    cw.extend_from_slice(&WIN.to_le_bytes());
    cw.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
    cw.extend_from_slice(&[0, 0, 0, 0]); // x, y
    cw.extend_from_slice(&100u16.to_le_bytes());
    cw.extend_from_slice(&50u16.to_le_bytes());
    cw.extend_from_slice(&0u16.to_le_bytes()); // border
    cw.extend_from_slice(&1u16.to_le_bytes()); // InputOutput
    cw.extend_from_slice(&0u32.to_le_bytes()); // CopyFromParent visual
    cw.extend_from_slice(&0u32.to_le_bytes()); // no values
    drive(&mut state, &mut backend, 1, 0, &cw);
    let mut redirect = ROOT_WINDOW.0.to_le_bytes().to_vec();
    redirect.extend_from_slice(&[1, 0, 0, 0]); // Manual
    drive(
        &mut state,
        &mut backend,
        144,
        yserver_protocol::x11::composite::REDIRECT_SUBWINDOWS,
        &redirect,
    );
    drive(&mut state, &mut backend, 8, 0, &WIN.to_le_bytes());
    let mut name = WIN.to_le_bytes().to_vec();
    name.extend_from_slice(&PIX.to_le_bytes());
    drive(
        &mut state,
        &mut backend,
        144,
        yserver_protocol::x11::composite::NAME_WINDOW_PIXMAP,
        &name,
    );
    let mut glx = Vec::new();
    glx.extend_from_slice(&0u32.to_le_bytes()); // screen
    glx.extend_from_slice(&0x101u32.to_le_bytes()); // fbconfig
    glx.extend_from_slice(&PIX.to_le_bytes());
    glx.extend_from_slice(&GLXPIX.to_le_bytes());
    drive(&mut state, &mut backend, 148, x11glx::CREATE_PIXMAP, &glx);
    let first = state
        .resources
        .pixmap(ResourceId(PIX))
        .and_then(|p| p.host_xid)
        .expect("named pixmap")
        .as_raw();
    assert_eq!(
        backend.glx_pixmap_exports.get(&first),
        Some(&1),
        "glXCreatePixmap holds one export ref on the named backing",
    );

    for i in 1..=resizes {
        let mut cfg = WIN.to_le_bytes().to_vec();
        cfg.extend_from_slice(&0x0cu16.to_le_bytes());
        cfg.extend_from_slice(&0u16.to_le_bytes());
        cfg.extend_from_slice(&u32::from(100 + 10 * i).to_le_bytes());
        cfg.extend_from_slice(&u32::from(50 + 10 * i).to_le_bytes());
        drive(&mut state, &mut backend, 12, 0, &cfg);
        let current = state
            .resources
            .window(ResourceId(WIN))
            .and_then(|w| w.redirected_backing)
            .expect("redirected backing")
            .host_pixmap
            .as_raw();
        assert_ne!(current, first, "resize {i} rotated the backing");
        assert_eq!(
            state
                .glx_drawables
                .get(&GLXPIX)
                .and_then(|d| d.glx_export_host_xid),
            Some(current),
            "resize {i}: the GLX pixmap follows the retargeted alias",
        );
        assert_eq!(
            backend
                .glx_pixmap_exports
                .clone()
                .into_iter()
                .collect::<Vec<_>>(),
            vec![(current, 1)],
            "resize {i}: the export ref lives on the backing the GLX pixmap names",
        );
    }

    let destroy_glx = |state: &mut ServerState, backend: &mut RecordingBackend| {
        drive(
            state,
            backend,
            148,
            x11glx::DESTROY_PIXMAP,
            &GLXPIX.to_le_bytes(),
        );
    };
    let free = |state: &mut ServerState, backend: &mut RecordingBackend| {
        drive(state, backend, 54, 0, &PIX.to_le_bytes());
    };
    let destroy_win = |state: &mut ServerState, backend: &mut RecordingBackend| {
        drive(state, backend, 4, 0, &WIN.to_le_bytes());
    };
    match teardown {
        GlxTeardown::DestroyGlxThenFree => {
            destroy_glx(&mut state, &mut backend);
            free(&mut state, &mut backend);
            destroy_win(&mut state, &mut backend);
        }
        GlxTeardown::FreeThenDestroyGlx => {
            free(&mut state, &mut backend);
            destroy_glx(&mut state, &mut backend);
            destroy_win(&mut state, &mut backend);
        }
        GlxTeardown::DestroyWindowFirst => {
            destroy_win(&mut state, &mut backend);
            destroy_glx(&mut state, &mut backend);
            free(&mut state, &mut backend);
        }
        GlxTeardown::Disconnect => {
            crate::core_loop::process_disconnect::process_disconnect(
                &mut state,
                &mut backend,
                ClientId(1),
            );
        }
    }
    backend
}

/// A resize retargets picom's GLX pixmap; the export ref must move with it, or OLD leaks.
#[test]
fn glx_pixmap_export_ref_follows_the_resize_retarget() {
    for resizes in [0, 1, 2] {
        for teardown in [
            GlxTeardown::DestroyGlxThenFree,
            GlxTeardown::FreeThenDestroyGlx,
            GlxTeardown::DestroyWindowFirst,
            GlxTeardown::Disconnect,
        ] {
            let backend = glx_export_ref_after_resizes(resizes, teardown);
            assert!(
                backend.glx_pixmap_exports.is_empty(),
                "resizes={resizes} {teardown:?}: export refs left behind: {:?}",
                backend.glx_pixmap_exports,
            );
        }
    }
}

// compCopyWindow analog: when a redirected window resizes, the
// pre-existing backing's contents must be carried over into the new
// backing for the overlap region — otherwise any compositor that
// re-Names the post-resize backing (marco on mate-panel-top during
// the 25→28-px grow, etc.) samples an empty buffer and the panel
// renders without the icons that were already painted into the old
// backing. Xorg lands this via `compReallocPixmap` (save old
// pixmap) + `compCopyWindow` (copy_area old→new). See
// /home/jos/Projects/xserver/composite/compalloc.c:680-712 and
// compwindow.c:376-388.
#[test]
fn rotate_redirected_backing_on_resize_copies_old_contents_to_new() {
    use crate::backend::recording::RecordedCall;

    const WINDOW_XID: u32 = 0x0010_0001;
    const HOST_XID: u32 = 0x0040_0001;
    const OLD_BACKING: u32 = 0x0050_0001;
    const OLD_W: u16 = 100;
    const OLD_H: u16 = 50;
    const NEW_W: u16 = 100;
    const NEW_H: u16 = 75;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 32,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: OLD_W,
            height: OLD_H,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
        w.redirected_backing = Some(crate::resources::RedirectedBacking {
            host_pixmap: crate::backend::PixmapHandle::from_raw_for_test(OLD_BACKING),
            width: OLD_W,
            height: OLD_H,
            depth: 32,
        });
    }

    rotate_redirected_backing_on_resize(
        &mut state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        NEW_W,
        NEW_H,
        false,
        0,
    );

    // NEW handle is whatever the RecordingBackend's allocate
    // handed back; pull it from the resource state.
    let new_backing = state
        .resources
        .window(ResourceId(WINDOW_XID))
        .and_then(|w| w.redirected_backing)
        .expect("redirected_backing repointed after rotate");
    let new_raw = new_backing.host_pixmap.as_raw();

    let calls = backend.calls();
    // Expected overlap = min(old, new) per dimension.
    let expected_w = OLD_W.min(NEW_W);
    let expected_h = OLD_H.min(NEW_H);
    let copy = calls.iter().find(|c| {
        matches!(
            c,
            RecordedCall::CopyArea {
                src_host_xid,
                dst_host_xid,
                src_x: 0,
                src_y: 0,
                dst_x: 0,
                dst_y: 0,
                width,
                height,
            } if *src_host_xid == OLD_BACKING
                && *dst_host_xid == new_raw
                && *width == expected_w
                && *height == expected_h
        )
    });
    assert!(
        copy.is_some(),
        "expected CopyArea(OLD=0x{OLD_BACKING:x} → NEW=0x{new_raw:x}, \
             src=(0,0), dst=(0,0), {expected_w}x{expected_h}) — \
             missing the compCopyWindow analog that carries pre-resize \
             contents into the freshly-allocated backing. Calls: {calls:?}",
    );
}

// #143 (rendering half) — a SHRINK must rotate exactly like a grow.
//
// Measured under awesome+picom: switching tiling layout shrank a
// mate-terminal frame (`bw = 2`) from 1278x704 to 1276x704 and the
// render module logged NOTHING — `redirected_backing_can_fit` was a
// high-water-mark test, so the 1282x708 backing was kept and only its
// metadata was rewritten. The backing's ring stayed laid out for the
// OLD 1278-px content (2-px ring at columns 1280..1281) and nothing
// re-seeded it, leaving an alpha-0 band where content should be.
//
// Xorg reallocates on inequality in EITHER direction:
// `compReallocPixmap` (../xserver/composite/compalloc.c:698), whose
// replacement is always freshly seeded from the parent
// (`compNewPixmap`, compalloc.c:539-605).
//
// The backend predicate is where the fix lives (its own unit test is
// `redirected_backing_reuse_requires_the_exact_storage_extent`);
// what this test pins is the core half — that the realloc path
// allocates at the NEW bordered extent and carries only the CONTENT
// overlap, leaving the freshly painted ring of NEW alone.
#[test]
fn rotate_redirected_backing_on_shrink_allocates_the_new_bordered_extent() {
    use crate::backend::recording::RecordedCall;

    const BW: u16 = 2;
    // Content 1278x704 → backing 1282x708 (the pre-switch state).
    const OLD_BACKING_W: u16 = 1282;
    const OLD_BACKING_H: u16 = 708;
    // Shrink to content 1276x704 → backing 1280x708.
    const NEW_CONTENT_W: u16 = 1276;
    const NEW_CONTENT_H: u16 = 704;

    let (mut state, mut backend, old_backing) =
        redirected_window_fixture(OLD_BACKING_W, OLD_BACKING_H, BW);

    rotate_redirected_backing_on_resize(
        &mut state,
        &mut backend,
        None,
        ResourceId(ROTATE_WINDOW_XID),
        NEW_CONTENT_W,
        NEW_CONTENT_H,
        false,
        BW,
    );

    let new_backing = state
        .resources
        .window(ResourceId(ROTATE_WINDOW_XID))
        .and_then(|w| w.redirected_backing)
        .expect("redirected_backing repointed after the shrink rotate");
    assert_ne!(
        new_backing.host_pixmap.as_raw(),
        old_backing,
        "a shrink must rotate onto a FRESH backing, not keep the oversized one",
    );
    assert_eq!(
        (new_backing.width, new_backing.height),
        (1280, 708),
        "the new backing is the new BORDERED extent (1276 + 2*2, 704 + 2*2)",
    );

    let calls = backend.calls();
    assert!(
        calls.contains(&RecordedCall::AllocateRedirectedBacking {
            host_window: ROTATE_HOST_XID,
            width: 1280,
            height: 708,
            depth: 32,
        }),
        "the shrink must allocate storage at the new bordered extent \
             1280x708, not keep 1282x708. Calls: {calls:?}",
    );

    // Content-only copy: both backings hold content at `(bw, bw)`,
    // and the overlap is min(1278, 1276) x min(704, 704).
    let new_raw = new_backing.host_pixmap.as_raw();
    assert!(
        calls.iter().any(|c| matches!(
            c,
            RecordedCall::CopyArea {
                src_host_xid,
                dst_host_xid,
                src_x: 2,
                src_y: 2,
                dst_x: 2,
                dst_y: 2,
                width: 1276,
                height: 704,
            } if *src_host_xid == old_backing && *dst_host_xid == new_raw
        )),
        "the rotate copy must carry the CONTENT overlap inset by the \
             border width — a full-extent copy would repaint NEW's \
             right/bottom ring columns with OLD's interior pixels. \
             Calls: {calls:?}",
    );
}

// The over-correction guard for the test above: a bordered GROW must
// keep rotating the way it always did, and its copy is inset the same
// way (the ring of NEW is painted by `allocate_redirected_backing`;
// Xorg repaints it too, via the `compRepaintBorder` work proc queued
// from `compSetPixmap`, ../xserver/composite/compwindow.c:137-139).
#[test]
fn rotate_redirected_backing_on_bordered_grow_still_rotates_and_copies_content() {
    use crate::backend::recording::RecordedCall;

    const BW: u16 = 2;
    // Content 1276x704 → backing 1280x708, growing to content
    // 1278x704 → backing 1282x708.
    const OLD_BACKING_W: u16 = 1280;
    const OLD_BACKING_H: u16 = 708;
    const NEW_CONTENT_W: u16 = 1278;
    const NEW_CONTENT_H: u16 = 704;

    let (mut state, mut backend, old_backing) =
        redirected_window_fixture(OLD_BACKING_W, OLD_BACKING_H, BW);

    rotate_redirected_backing_on_resize(
        &mut state,
        &mut backend,
        None,
        ResourceId(ROTATE_WINDOW_XID),
        NEW_CONTENT_W,
        NEW_CONTENT_H,
        false,
        BW,
    );

    let new_backing = state
        .resources
        .window(ResourceId(ROTATE_WINDOW_XID))
        .and_then(|w| w.redirected_backing)
        .expect("redirected_backing repointed after the grow rotate");
    assert_eq!((new_backing.width, new_backing.height), (1282, 708));

    let calls = backend.calls();
    assert!(
        calls.contains(&RecordedCall::AllocateRedirectedBacking {
            host_window: ROTATE_HOST_XID,
            width: 1282,
            height: 708,
            depth: 32,
        }),
        "the grow must allocate at the new bordered extent. Calls: {calls:?}",
    );
    let new_raw = new_backing.host_pixmap.as_raw();
    assert!(
        calls.iter().any(|c| matches!(
            c,
            RecordedCall::CopyArea {
                src_host_xid,
                dst_host_xid,
                src_x: 2,
                src_y: 2,
                dst_x: 2,
                dst_y: 2,
                width: 1276,
                height: 704,
            } if *src_host_xid == old_backing && *dst_host_xid == new_raw
        )),
        "the grow copy carries the same content overlap, inset by the \
             border width. Calls: {calls:?}",
    );
}

const ROTATE_WINDOW_XID: u32 = 0x0010_0001;
const ROTATE_HOST_XID: u32 = 0x0040_0001;

/// A root child already redirected, with a backing whose recorded
/// extent is `(backing_w, backing_h)` — i.e. the post-activation
/// state, before the resize under test. Returns the OLD backing's
/// raw xid alongside the fixture.
fn redirected_window_fixture(
    backing_w: u16,
    backing_h: u16,
    border_width: u16,
) -> (ServerState, RecordingBackend, u32) {
    const OLD_BACKING: u32 = 0x0050_0001;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 32,
            window: ResourceId(ROTATE_WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: backing_w.saturating_sub(border_width.saturating_mul(2)),
            height: backing_h.saturating_sub(border_width.saturating_mul(2)),
            border_width,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(ROTATE_WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(
            ROTATE_HOST_XID,
        ));
        w.border_width = border_width;
        w.redirected_backing = Some(crate::resources::RedirectedBacking {
            host_pixmap: crate::backend::PixmapHandle::from_raw_for_test(OLD_BACKING),
            width: backing_w,
            height: backing_h,
            depth: 32,
        });
    }
    (state, backend, OLD_BACKING)
}

// Storage-alive invariant for the rotate copy. Observed in HW
// smoke (yserver-hw-mate.log 17:28:10Z) that the rotate path
// dropped tiny 1×1 CopyAreas with `copy_area dropped — src
// unknown` whenever OLD had no `NameWindowPixmap` aliases: the
// existing `release_redirected_backing` decref'd alias_registry
// to 0 → `free_pixmap` → store entry gone → `store.lookup(OLD)`
// returned None at the copy site → silent drop.
//
// Fix shape: take a rotate-scoped retain on OLD's storage
// BEFORE the release (so release's decref doesn't hit 0), drop
// it AFTER the copy (frees storage only if no other aliases
// hold it). This test pins the call ordering on
// RecordingBackend; the v2-side alias_registry incref/decref
// semantics are exercised by the v2 backend's own tests.
#[test]
fn rotate_redirected_backing_retains_old_storage_across_release_then_drops_after_copy() {
    use crate::backend::recording::RecordedCall;

    const WINDOW_XID: u32 = 0x0010_0001;
    const HOST_XID: u32 = 0x0040_0001;
    const OLD_BACKING: u32 = 0x0050_0001;
    const OLD_W: u16 = 1;
    const OLD_H: u16 = 1;
    const NEW_W: u16 = 1;
    const NEW_H: u16 = 1;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 32,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: OLD_W,
            height: OLD_H,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
        w.redirected_backing = Some(crate::resources::RedirectedBacking {
            host_pixmap: crate::backend::PixmapHandle::from_raw_for_test(OLD_BACKING),
            width: OLD_W,
            height: OLD_H,
            depth: 32,
        });
    }

    rotate_redirected_backing_on_resize(
        &mut state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        NEW_W,
        NEW_H,
        true,
        0,
    );

    let calls = backend.calls();
    let retain_idx = calls
        .iter()
        .position(|c| matches!(c, RecordedCall::RetainBackingStorage(x) if *x == OLD_BACKING));
    let release_idx = calls
        .iter()
        .position(|c| matches!(c, RecordedCall::ReleaseRedirectedBacking(x) if *x == OLD_BACKING));
    let allocate_idx = calls.iter().position(|c| {
        matches!(c, RecordedCall::AllocateRedirectedBacking { host_window, .. } if *host_window == HOST_XID)
    });
    let copy_idx = calls.iter().position(|c| {
        matches!(c, RecordedCall::CopyArea { src_host_xid, .. } if *src_host_xid == OLD_BACKING)
    });
    let drop_idx = calls
        .iter()
        .position(|c| matches!(c, RecordedCall::DropBackingStorage(x) if *x == OLD_BACKING));

    let r = retain_idx.expect(
        "rotate must retain OLD storage before releasing — otherwise the no-alias \
             case frees storage before copy_area can read it (observed as `copy_area dropped \
             — src unknown` in HW smoke)",
    );
    let rel = release_idx.expect("rotate must still release OLD's W→B map slot");
    let a = allocate_idx.expect("rotate must allocate NEW");
    let c = copy_idx.expect("rotate must copy OLD→NEW");
    let d = drop_idx.expect(
        "rotate must drop the retain after copy — leaving storage alive forever \
             would leak the backing across every resize",
    );

    assert!(
        r < rel,
        "Retain(idx={r}) must precede Release(idx={rel}) — release's decref would \
             otherwise hit refcount=0 and free OLD's storage before copy. Calls: {calls:?}",
    );
    assert!(
        rel < a,
        "Release(idx={rel}) must precede Allocate(idx={a}) — host_window_to_backing[W] \
             idempotency would otherwise return OLD instead of allocating fresh. Calls: {calls:?}",
    );
    assert!(
        a < c,
        "Allocate(idx={a}) must precede Copy(idx={c}) — copy needs NEW as destination. \
             Calls: {calls:?}",
    );
    assert!(
        c < d,
        "Copy(idx={c}) must precede Drop(idx={d}) — dropping the retain before the copy \
             defeats the purpose of taking it. Calls: {calls:?}",
    );
}

#[test]
fn rotate_redirected_backing_on_move_forces_reallocate_even_when_size_matches() {
    use crate::backend::recording::RecordedCall;

    const WINDOW_XID: u32 = 0x0010_0001;
    const HOST_XID: u32 = 0x0040_0001;
    const OLD_BACKING: u32 = 0x0050_0001;
    const W: u16 = 100;
    const H: u16 = 50;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 32,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: W,
            height: H,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
        w.redirected_backing = Some(crate::resources::RedirectedBacking {
            host_pixmap: crate::backend::PixmapHandle::from_raw_for_test(OLD_BACKING),
            width: W,
            height: H,
            depth: 32,
        });
    }

    rotate_redirected_backing_on_resize(
        &mut state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        W,
        H,
        true,
        0,
    );

    let calls = backend.calls();
    assert!(
        calls.iter().any(|c| matches!(
            c,
            RecordedCall::ReleaseRedirectedBacking(x) if *x == OLD_BACKING
        )),
        "forced move-rotate must release OLD even when size matches; got {calls:?}",
    );
    assert!(
        calls.iter().any(|c| matches!(
            c,
            RecordedCall::AllocateRedirectedBacking {
                host_window,
                width,
                height,
                depth: 32,
            } if *host_window == HOST_XID && *width == W && *height == H
        )),
        "forced move-rotate must allocate a fresh backing at the same size; got {calls:?}",
    );
    let new_backing = state
        .resources
        .window(ResourceId(WINDOW_XID))
        .and_then(|w| w.redirected_backing)
        .expect("redirected_backing repointed after forced rotate");
    assert_ne!(
        new_backing.host_pixmap.as_raw(),
        OLD_BACKING,
        "forced move-rotate must repoint to a fresh backing even at identical size",
    );
}

/// Manual-mode redirect removes W from the normal scene and keeps
/// B as an off-screen compositor source. B must not become a scene
/// participant, or the scene path can double-present redirected
/// client content behind/above the compositor's output surface.
#[test]
fn manual_redirect_keeps_window_out_of_scene() {
    use crate::backend::recording::RecordedCall;

    const WINDOW_XID: u32 = 0x0010_0001;
    const HOST_XID: u32 = 0x0040_0001;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    // Install a top-level child of root (the soon-to-be-Manual-
    // redirected window). Use real CreateWindow flow so the
    // resource record carries width/height/depth that
    // `activate_redirect_backing_for` snapshots.
    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 50,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
    }
    // Viewable: Xorg allocates a redirect backing only for a realized window.
    let _ = state.resources.map_window(ResourceId(WINDOW_XID));
    state
        .composite_redirects
        .redirect_window(
            ResourceId(WINDOW_XID),
            crate::server::RedirectRecord {
                mode: crate::server::CompositeRedirectMode::Manual,
                owner: yserver_protocol::x11::ClientId(1),
            },
        )
        .unwrap();

    activate_redirect_backing_for(
        &mut state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        crate::server::CompositeRedirectMode::Manual,
    );

    // Window participation: Manual → false (the external
    // compositor owns the window's presentation). The paired
    // assertion that B *is* scene-participating lives in
    // `manual_redirect_marks_backing_scene_participating_so_paints_emit_damage`.
    let calls = backend.calls();
    assert!(
        calls.iter().any(|c| matches!(
            c,
            RecordedCall::SetWindowSceneParticipation {
                host_window,
                participating: false,
            } if *host_window == HOST_XID
        )),
        "expected SetWindowSceneParticipation(W, false) for Manual mode; got {calls:?}",
    );
    // Positive control for the COW guard
    // (`activate_redirect_on_cow_is_never_applied`): a NORMAL window
    // DOES receive a redirect backing. This proves the COW guard is
    // overlay-window-specific, not a blanket disable of
    // `activate_redirect_backing_for`.
    assert!(
        state
            .resources
            .window(ResourceId(WINDOW_XID))
            .expect("window exists")
            .redirected_backing
            .is_some(),
        "a normal window must receive a redirect backing",
    );
}

/// Xorg `compCheckRedirect` (`composite/compwindow.c:156-170`) forces
/// `should = FALSE` for `pWin == cs->pOverlayWin`: the overlay window
/// is NEVER actually redirected, regardless of trigger. Since Phase 2
/// made the COW a real child of root, a compositor's
/// `CompositeRedirectSubwindows(root, Manual)` (mutter / cinnamon-mutter
/// all issue it) drives `activate_redirect_backing_for` once per root
/// child — including the COW. Without the guard the COW gets a Manual
/// backing + `scene_participating=false`, and the Phase 3 Manual-skip
/// drops the whole composited desktop from scanout (blank desktop,
/// observed bee/cinnamon-mutter 2026-06-09). The COW must keep its
/// `redirected_backing` empty and its scene participation untouched.
#[test]
fn activate_redirect_on_cow_is_never_applied() {
    use crate::backend::recording::RecordedCall;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    // Materialize the COW exactly as the `GetOverlayWindow` 0->1
    // claim does (host xid == COMPOSITE_OVERLAY_WINDOW.0 for the
    // RecordingBackend / v2 path, per the dispatch handler).
    let cow_host = crate::backend::WindowHandle::from_raw_panicking(COMPOSITE_OVERLAY_WINDOW.0);
    state.resources.materialize_cow_resource(cow_host);

    // This is the call `RedirectSubwindows(root, Manual)`'s child
    // loop makes for every child of root — the COW included.
    activate_redirect_backing_for(
        &mut state,
        &mut backend,
        None,
        COMPOSITE_OVERLAY_WINDOW,
        crate::server::CompositeRedirectMode::Manual,
    );

    let cow = state
        .resources
        .window(COMPOSITE_OVERLAY_WINDOW)
        .expect("COW exists");
    assert!(
        cow.redirected_backing.is_none(),
        "COW must never receive a redirect backing \
             (compCheckRedirect: should=FALSE for pOverlayWin)",
    );
    // And no scene-participation flip was recorded for the COW host —
    // the Phase 3 Manual-skip is driven off this flag.
    let calls = backend.calls();
    assert!(
        !calls.iter().any(|c| matches!(
            c,
            RecordedCall::SetWindowSceneParticipation { host_window, .. }
                if *host_window == COMPOSITE_OVERLAY_WINDOW.0
        )),
        "COW scene participation must not be flipped by redirect activation; got {calls:?}",
    );
}

/// Manual-redirected backing must have scene_participating=true so
/// the v2 scene's damage harvest sees paints into it.
///
/// Post-`6ffd370` the scene walk emits the Manual-redirected window
/// at its own coords but samples storage from the backing via
/// `redirected_target` indirection. `store.damage()` is gated on
/// the *target's* `scene_participating` — if the backing is marked
/// non-participating, every paint into it silently drops its scene
/// damage. Buffer-age clipped compose then never repaints the
/// affected region, and the BO retains whatever was in it the last
/// time it was flipped. Symptom: window content invisible except
/// where cursor damage happens to overlap the window's rect.
#[test]
fn manual_redirect_marks_backing_scene_participating_so_paints_emit_damage() {
    use crate::backend::recording::RecordedCall;

    const WINDOW_XID: u32 = 0x0010_0001;
    const HOST_XID: u32 = 0x0040_0001;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 50,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
    }
    // Viewable: Xorg allocates a redirect backing only for a realized window.
    let _ = state.resources.map_window(ResourceId(WINDOW_XID));
    state
        .composite_redirects
        .redirect_window(
            ResourceId(WINDOW_XID),
            crate::server::RedirectRecord {
                mode: crate::server::CompositeRedirectMode::Manual,
                owner: yserver_protocol::x11::ClientId(1),
            },
        )
        .unwrap();

    activate_redirect_backing_for(
        &mut state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        crate::server::CompositeRedirectMode::Manual,
    );

    let calls = backend.calls();
    assert!(
        calls.iter().any(|c| matches!(
            c,
            RecordedCall::SetBackingSceneParticipation {
                participating: true,
                ..
            }
        )),
        "expected SetBackingSceneParticipation(B, true) for Manual mode so the \
             scene's redirected_target damage-peek sees paints; got {calls:?}",
    );
}

/// Redirecting an already-mapped window must emit one initial full
/// DamageNotify wakeup so a compositor that subscribes after map
/// can pull the seeded backing into the COW immediately. Without
/// this, the backing contains the correct pixels but the COW keeps
/// showing the root/background until some unrelated later event
/// (click, move, resize) dirties the window.
#[test]
fn activate_redirect_on_mapped_window_emits_initial_damage() {
    use crate::server::{DamageObject, RedirectRecord};

    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0010_0010;
    const HOST_XID: u32 = 0x0040_0010;
    const DAMAGE_XID: u32 = 0x0010_0011;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 50,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(WINDOW_XID));
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
    }
    state
        .composite_redirects
        .redirect_window(
            ResourceId(WINDOW_XID),
            RedirectRecord {
                mode: crate::server::CompositeRedirectMode::Manual,
                owner: yserver_protocol::x11::ClientId(CLIENT_ID),
            },
        )
        .unwrap();
    state.damage_objects.insert(
        DAMAGE_XID,
        DamageObject {
            owner: ClientId(CLIENT_ID),
            drawable: ResourceId(WINDOW_XID),
            level: 3,
            rects: Vec::new(),
            pending_notify_fired: false,
            last_reported_geometry: None,
        },
    );

    activate_redirect_backing_for(
        &mut state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        crate::server::CompositeRedirectMode::Manual,
    );

    let damage = state
        .damage_objects
        .get(&DAMAGE_XID)
        .expect("damage object after redirect activation");
    assert!(
        !damage.rects.is_empty(),
        "redirect activation on an already-mapped window must emit an initial \
             full damage wakeup so compositors pull the seeded backing immediately",
    );
}

/// A compositor subscribes to DAMAGE on the `NameWindowPixmap`
/// pixmap, not the original window. That pixmap must receive the
/// same initial seed as a plain viewable window, otherwise the
/// first composite after redirect can stay blank until some later
/// client paint lands.
#[test]
fn damage_create_on_named_pixmap_alias_seeds_initial_damage() {
    use yserver_protocol::x11::damage as x11damage;

    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0010_0012;
    const HOST_WINDOW_XID: u32 = 0x0040_0012;
    const PIXMAP_XID: u32 = 0x0020_0012;
    const DAMAGE_ID: u32 = 0x0080_0012;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 50,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(
            HOST_WINDOW_XID,
        ));
        w.map_state = crate::resources::MapState::Viewable;
    }
    activate_redirect_backing_for(
        &mut state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        crate::server::CompositeRedirectMode::Manual,
    );
    let host_pixmap = state
        .resources
        .window(ResourceId(WINDOW_XID))
        .and_then(|w| w.redirected_backing.as_ref())
        .map(|b| b.host_pixmap)
        .expect("redirected backing");
    state.resources.create_pixmap(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreatePixmapRequest {
            pixmap: ResourceId(PIXMAP_XID),
            drawable: ResourceId(WINDOW_XID),
            width: 100,
            height: 50,
            depth: 24,
        },
    );
    let _ = state
        .resources
        .set_pixmap_host_xid(ResourceId(PIXMAP_XID), host_pixmap);
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.composite_named_pixmaps
            .push(crate::resources::NamedCompositePixmap {
                client_pixmap: ResourceId(PIXMAP_XID),
                host_pixmap,
                width: 100,
                height: 50,
            });
    }

    let mut body = Vec::with_capacity(12);
    body.extend_from_slice(&DAMAGE_ID.to_le_bytes());
    body.extend_from_slice(&PIXMAP_XID.to_le_bytes());
    body.push(x11damage::report_level::NON_EMPTY);
    body.extend_from_slice(&[0, 0, 0]);

    let header = RequestHeader {
        opcode: 0,
        data: x11damage::CREATE,
        length_units: 0,
    };
    handle_damage_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("damage create handled");

    let damage = state
        .damage_objects
        .get(&DAMAGE_ID)
        .expect("damage object created");
    assert!(
        !damage.rects.is_empty(),
        "creating DAMAGE on a named pixmap alias of a viewable window must seed \
             initial damage so picom sees the current backing immediately",
    );
}

/// Mapping a Manual-redirected window must not leave it visible
/// in the normal scene. The map path temporarily flips the
/// storage on, then the redirect-mode reapply must force it back
/// off.
#[test]
fn map_window_reapplies_manual_redirect_scene_participation() {
    use crate::backend::recording::RecordedCall;

    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0010_0002;
    const HOST_XID: u32 = 0x0040_0002;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 50,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
    }
    state
        .composite_redirects
        .redirect_window(
            ResourceId(WINDOW_XID),
            crate::server::RedirectRecord {
                mode: crate::server::CompositeRedirectMode::Manual,
                owner: yserver_protocol::x11::ClientId(CLIENT_ID),
            },
        )
        .unwrap();

    activate_redirect_backing_for(
        &mut state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        crate::server::CompositeRedirectMode::Manual,
    );
    let before = backend.calls().len();

    let mut body = Vec::with_capacity(4);
    body.extend_from_slice(&WINDOW_XID.to_le_bytes());
    handle_map_window(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_map_window");

    let calls = &backend.calls()[before..];
    assert!(
        calls.iter().any(|c| matches!(
            c,
            RecordedCall::SetWindowSceneParticipation {
                host_window,
                participating: false,
            } if *host_window == HOST_XID
        )),
        "mapping a Manual-redirected window must reassert scene_participating=false; got {calls:?}",
    );
    assert!(
        !calls.iter().any(|c| matches!(
            c,
            RecordedCall::SetWindowSceneParticipation {
                host_window,
                participating: true,
            } if *host_window == HOST_XID
        )),
        "mapping a Manual-redirected window must not leave it scene_participating=true; got {calls:?}",
    );
}

/// Audit #11 regression — when a window maps, server-background
/// paint fills the window's storage but no `DamageNotify` fires
/// for the affected region. Compositors that subscribe to
/// `XDamageCreate(window)` (marco-with-compositing, picom) miss
/// the first frame and the window stays invisible on COW until
/// the next paint into it. Symptom: override-redirect popup
/// menus, mate-panel system-tray icons (`nm-applet`) don't show
/// when a compositor is active and v2 routes the visible output
/// through `Present::Pixmap → COW`.
///
/// Oracle: a `DamageObject` subscribed to a freshly-created
/// window must accumulate damage rects covering the window's
/// full extent after `handle_map_window` returns.
#[test]
fn map_window_emits_damage_on_window_extent() {
    use crate::server::DamageObject;

    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0010_0010;
    const HOST_XID: u32 = 0x0040_0010;
    const DAMAGE_ID: u32 = 0x0080_0010;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 200,
            height: 80,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
    }

    // Compositor subscribes via `XDamageCreate(window)`. Pin the
    // pre-state explicitly: no rects accumulated yet.
    state.damage_objects.insert(
        DAMAGE_ID,
        DamageObject {
            owner: ClientId(CLIENT_ID),
            drawable: ResourceId(WINDOW_XID),
            level: 0,
            rects: Vec::new(),
            pending_notify_fired: false,
            last_reported_geometry: None,
        },
    );

    let mut body = Vec::with_capacity(4);
    body.extend_from_slice(&WINDOW_XID.to_le_bytes());
    handle_map_window(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_map_window");

    let damage = state
        .damage_objects
        .get(&DAMAGE_ID)
        .expect("damage_object survived map");
    assert!(
        !damage.rects.is_empty(),
        "MapWindow must fire damage on the window's extent so a \
             subscribed compositor repaints the new region into its \
             offscreen — pre-fix this is empty and the compositor \
             never sees the newly-mapped popup / tray icon / window",
    );
}

/// Per X11 protocol spec: "If the window is already mapped, this
/// request has no effect." brisk-menu (Ubuntu MATE's standalone
/// applications popup) pounds `MapWindow` at ~50 Hz on its
/// already-viewable override-redirect popup via GTK3's
/// `gtk_window_present`/`XMapRaised` loop. Pre-fix every redundant
/// MapWindow re-emitted MapNotify → Expose → full-extent damage,
/// triggering Marco to issue `COMPOSITE::NameWindowPixmap` and a
/// full recomposite of the popup ~50× per second — visible as
/// menu flicker on the COW-authoritative KMS scene path.
#[test]
fn map_window_on_already_mapped_window_is_no_op() {
    use crate::server::DamageObject;
    use std::io::Read;

    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0010_0014;
    const HOST_XID: u32 = 0x0040_0014;
    const DAMAGE_ID: u32 = 0x0080_0014;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 200,
            height: 80,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
    }

    // Marco-like subscriber: SubstructureNotify on root +
    // XDamageCreate on the new window.
    state
        .clients
        .get_mut(&CLIENT_ID)
        .unwrap()
        .event_masks
        .insert(ROOT_WINDOW, 0x0008_0000);
    state.damage_objects.insert(
        DAMAGE_ID,
        DamageObject {
            owner: ClientId(CLIENT_ID),
            drawable: ResourceId(WINDOW_XID),
            level: 0,
            rects: Vec::new(),
            pending_notify_fired: false,
            last_reported_geometry: None,
        },
    );

    let mut body = Vec::with_capacity(4);
    body.extend_from_slice(&WINDOW_XID.to_le_bytes());

    // First map: genuine transition Unmapped → Viewable. Should
    // emit MapNotify + accumulate damage.
    handle_map_window(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_map_window first");

    peer.set_nonblocking(true).unwrap();
    let mut tmp = [0u8; 1024];
    let mut first_wire = Vec::new();
    loop {
        match peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => first_wire.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    let first_map_notifies = first_wire
        .chunks_exact(32)
        .filter(|chunk| chunk[0] & 0x7f == 19)
        .count();
    assert!(
        first_map_notifies >= 1,
        "first MapWindow on an unmapped window must emit MapNotify",
    );
    let first_rect_count = state
        .damage_objects
        .get(&DAMAGE_ID)
        .expect("damage object")
        .rects
        .len();
    assert!(
        first_rect_count > 0,
        "first MapWindow must accumulate damage on the window extent",
    );

    // Second map on the now-already-Viewable window. Per spec this
    // is a no-op: no MapNotify, no extra damage rects.
    handle_map_window(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(2),
        &body,
    )
    .expect("handle_map_window second");

    let mut second_wire = Vec::new();
    loop {
        match peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => second_wire.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    let second_map_notifies = second_wire
        .chunks_exact(32)
        .filter(|chunk| chunk[0] & 0x7f == 19)
        .count();
    assert_eq!(
        second_map_notifies, 0,
        "MapWindow on an already-mapped window must NOT re-emit \
             MapNotify — repeated MapNotifies cause Marco to re-issue \
             COMPOSITE::NameWindowPixmap and full recomposite on every \
             redundant map (visible as brisk-menu flicker on KMS).",
    );
    let second_rect_count = state
        .damage_objects
        .get(&DAMAGE_ID)
        .expect("damage object")
        .rects
        .len();
    assert_eq!(
        second_rect_count, first_rect_count,
        "MapWindow on an already-mapped window must NOT accumulate \
             additional damage — full-extent damage on every redundant \
             call is what drives the recompositing flicker storm.",
    );
}

/// Per X11 protocol (Xorg `dix/window.c:2661`): `if (pWin->mapped)
/// return Success;` — `MapWindow` on an already-mapped window is a
/// no-op BEFORE any MapRequest dispatch. The root window is always
/// mapped (initialised `Viewable` at `resources.rs:204`) AND in
/// yserver root's `parent` field points to itself
/// (`resources.rs:194`), so a client calling `MapWindow(root)`
/// pre-fix matched the SubstructureRedirect-on-parent path: the
/// requester wasn't the WM, marco had SubstructureRedirect
/// (`0x0010_0000`) on root, so yserver dispatched a phantom
/// MapRequest event with `parent=root, window=root` to marco.
/// Marco's response (seen on hardware via xtrace seq `0x35e5a`
/// during a mate-screensaver activation): GrabServer →
/// ChangeWindowAttributes(root, event_mask=...) DROPPING
/// SubstructureNotify+SubstructureRedirect → UngrabServer. After
/// that marco no longer receives MapNotify for new top-levels →
/// no `COMPOSITE::NameWindowPixmap` → newly-mapped windows
/// (mate-screensaver overlay, dialogs) are invisible while the
/// cursor still moves. Match Xorg: hoist the "already mapped"
/// short-circuit above the MapRequest emission.
#[test]
fn map_window_on_root_does_not_emit_phantom_map_request() {
    use std::io::Read;

    const WM_ID: u32 = 1;
    const SAVER_ID: u32 = 2;

    let mut state = ServerState::new();
    let mut wm_peer = install_client(&mut state, WM_ID);
    let _saver_peer = install_client(&mut state, SAVER_ID);
    let mut backend = RecordingBackend::new();

    // Marco-like WM: SubstructureRedirect (0x0010_0000) on root.
    state
        .clients
        .get_mut(&WM_ID)
        .unwrap()
        .event_masks
        .insert(ROOT_WINDOW, 0x0010_0000);

    // mate-screensaver-like activation: client 2 calls
    // `MapWindow(root)`. Per X11 spec this must be a silent
    // no-op (root is always mapped).
    let mut body = Vec::with_capacity(4);
    body.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
    handle_map_window(
        &mut state,
        &mut backend,
        None,
        ClientId(SAVER_ID),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_map_window root");

    wm_peer.set_nonblocking(true).unwrap();
    let mut tmp = [0u8; 1024];
    let mut wm_wire = Vec::new();
    loop {
        match wm_peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => wm_wire.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    let map_requests = wm_wire
        .chunks_exact(32)
        .filter(|chunk| chunk[0] & 0x7f == 20)
        .count();
    assert_eq!(
        map_requests, 0,
        "MapWindow(root) must NOT generate a phantom MapRequest \
             event to the WM. Pre-fix yserver dispatched a bogus \
             MapRequest(parent=root, window=root) because root's parent \
             field points to itself; marco reacted by dropping its \
             SubstructureRedirect subscription, which broke compositing \
             of every subsequent top-level (mate-screensaver overlay \
             and dialogs went invisible while cursor still moved).",
    );
}

/// Per X11 protocol: `cursor = None` (resource id 0) on
/// ChangeWindowAttributes(CWCursor) means "clear this window's
/// cursor so the effective cursor inherits from the parent
/// chain". Pre-fix the handler short-circuited because
/// `resources.cursor_host_xid(ResourceId(0))` returns `None` and
/// the `(Some, Some)` match below dropped the call — marco
/// resets its frame's cursor via `XDefineCursor(frame, None)`
/// when the pointer moves off the resize edge into the frame
/// interior, and that reset never propagated to the backend
/// (resize cursor sprite stayed visible until the pointer left
/// the top-level frame entirely). Matches Xorg
/// `dix/window.c:1487-1491`.
#[test]
fn cwa_cursor_none_propagates_define_cursor_zero_to_backend() {
    use crate::backend::recording::RecordedCall;

    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0010_0020;
    const HOST_XID: u32 = 0x0040_0020;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 200,
            height: 80,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
    }

    // CWA body: window xid (4) + value_mask (4) + values.
    // CWCursor is bit 14 (mask = 0x4000); value = 0 means
    // X11 None.
    let mut body = Vec::with_capacity(12);
    body.extend_from_slice(&WINDOW_XID.to_le_bytes());
    body.extend_from_slice(&0x4000u32.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes());

    handle_change_window_attributes(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_change_window_attributes");

    let define_cursor_calls: Vec<_> = backend
        .calls()
        .into_iter()
        .filter(|c| matches!(c, RecordedCall::DefineCursor { .. }))
        .collect();
    assert_eq!(
        define_cursor_calls,
        vec![RecordedCall::DefineCursor {
            host_window_xid: HOST_XID,
            cursor_host_xid: 0,
        }],
        "CWA with CWCursor + value=0 must invoke \
             `backend.define_cursor(window, 0)` so the backend clears \
             its per-window cursor slot and refreshes the effective \
             cursor. Pre-fix this dropped silently, leaving stale \
             cursor state (marco's resize-frame XDefineCursor(frame, \
             None) reset on edge→interior transitions had no effect).",
    );
}

/// A `ChangeWindowAttributes` that only changes the cursor (or any
/// other non-event-mask attribute) must NOT move the input focus.
/// In X11 focus changes only via `SetInputFocus` / grabs, never CWA.
///
/// Regression (the evince / GTK4 titlebar-drag freeze): during a
/// `_NET_WM_MOVERESIZE` move, muffin sets the "fleur" move cursor on
/// its guard window via a cursor-only CWA. The handler promoted
/// keyboard focus to any "focus-wanting" (viewable + key-selecting)
/// window on *any* CWA, so focus was stolen to the guard window. The
/// app's next `SetInputFocus` to its own child was then computed from
/// that unrelated prev focus -> `FocusOut(detail=Nonlinear)` -> GTK4
/// backdrop (greyed CSD buttons) and the drag collapsed.
#[test]
fn cursor_only_cwa_does_not_steal_keyboard_focus() {
    const CLIENT_ID: u32 = 1;
    const GUARD_XID: u32 = 0x0010_0011; // muffin's guard window
    const FOCUSED_XID: u32 = 0x0010_0007; // the real focus window

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    for xid in [GUARD_XID, FOCUSED_XID] {
        state.resources.create_window(
            yserver_protocol::x11::ClientId(CLIENT_ID),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(xid),
                parent: ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: crate::resources::ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(ResourceId(xid));
    }
    // Guard window is viewable and selects key events, so
    // `window_wants_keyboard_focus` would return true for it.
    state
        .clients
        .get_mut(&CLIENT_ID)
        .expect("client")
        .event_masks
        .insert(ResourceId(GUARD_XID), 0x1); // KeyPress

    // Establish the real focus on FOCUSED_XID before the CWA.
    state.core_focus.raw = FOCUSED_XID;
    for c in state.clients.values_mut() {
        c.focused_window = ResourceId(FOCUSED_XID);
    }

    // Cursor-only CWA on the guard window: CWCursor (bit 14 =
    // 0x4000), value 0 = None. No event-mask change.
    let mut body = Vec::with_capacity(12);
    body.extend_from_slice(&GUARD_XID.to_le_bytes());
    body.extend_from_slice(&0x4000u32.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes());

    handle_change_window_attributes(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        &body,
    )
    .expect("handle_change_window_attributes");

    assert_eq!(
        state
            .clients
            .get(&CLIENT_ID)
            .expect("client")
            .focused_window,
        ResourceId(FOCUSED_XID),
        "a cursor-only ChangeWindowAttributes must not promote keyboard \
             focus to the target window; focus must stay where SetInputFocus \
             put it",
    );
}

/// GTK4 (gnome-text-editor, modern GTK apps) sets per-widget
/// cursors through XInput2's `XIChangeCursor` (opcode 42), not
/// core X11's `XDefineCursor`. Pre-fix the handler was a logging
/// no-op, so the I-beam cursor over a text widget never reached
/// the backend and the area kept showing the default arrow.
/// Treat it as `XDefineCursor` (per-device cursors aren't routed
/// yet; a single effective cursor on the window matches what
/// `AllMasterDevices`-style calls produce in practice).
#[test]
fn xi_change_cursor_propagates_define_cursor_to_backend() {
    use crate::backend::recording::RecordedCall;

    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0010_0030;
    const HOST_XID: u32 = 0x0040_0030;
    const CURSOR_XID: u32 = 0x0090_0001;
    const CURSOR_HOST_XID: u32 = 0x00a0_0001;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 200,
            height: 80,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
    }
    state
        .resources
        .create_cursor(ClientId(CLIENT_ID), ResourceId(CURSOR_XID));
    state.resources.set_cursor_host_xid(
        ResourceId(CURSOR_XID),
        crate::backend::CursorHandle::from_raw_panicking(CURSOR_HOST_XID),
    );

    // XIChangeCursor body: window(4), cursor(4), deviceid(2), pad(2).
    let mut body = Vec::with_capacity(12);
    body.extend_from_slice(&WINDOW_XID.to_le_bytes());
    body.extend_from_slice(&CURSOR_XID.to_le_bytes());
    body.extend_from_slice(&0u16.to_le_bytes());
    body.extend_from_slice(&[0u8; 2]);

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131, // doesn't matter — dispatcher is bypassed
        data: 42,    // XIChangeCursor minor
        // XIChangeCursor is Fixed(4): 4 header + window(4) + cursor(4)
        // + deviceid(2) + pad(2) = 16 bytes = 4 units. (Was 3 — pre-
        // dated the length gate, now BadLengths before the handler.)
        length_units: 4,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("handle_xi2_request");

    let define_cursor_calls: Vec<_> = backend
        .calls()
        .into_iter()
        .filter(|c| matches!(c, RecordedCall::DefineCursor { .. }))
        .collect();
    assert_eq!(
        define_cursor_calls,
        vec![RecordedCall::DefineCursor {
            host_window_xid: HOST_XID,
            cursor_host_xid: CURSOR_HOST_XID,
        }],
        "XIChangeCursor must propagate to `backend.define_cursor` \
             so GTK4's per-widget cursor (I-beam on text areas, etc.) \
             becomes effective. Pre-fix the handler was a logging \
             no-op — gnome-text-editor and other GTK4 apps kept the \
             default arrow over text widgets.",
    );

    // cursor = None (xid 0) clears the per-window cursor.
    let mut body_none = Vec::with_capacity(12);
    body_none.extend_from_slice(&WINDOW_XID.to_le_bytes());
    body_none.extend_from_slice(&0u32.to_le_bytes());
    body_none.extend_from_slice(&0u16.to_le_bytes());
    body_none.extend_from_slice(&[0u8; 2]);

    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(2),
        header,
        &body_none,
    )
    .expect("handle_xi2_request none");

    let define_cursor_calls: Vec<_> = backend
        .calls()
        .into_iter()
        .filter(|c| matches!(c, RecordedCall::DefineCursor { .. }))
        .collect();
    assert_eq!(
        define_cursor_calls,
        vec![
            RecordedCall::DefineCursor {
                host_window_xid: HOST_XID,
                cursor_host_xid: CURSOR_HOST_XID,
            },
            RecordedCall::DefineCursor {
                host_window_xid: HOST_XID,
                cursor_host_xid: 0,
            },
        ],
        "XIChangeCursor with cursor=None (xid 0) must invoke \
             `backend.define_cursor(window, 0)` — same X11 None \
             semantics as the CWA cursor path.",
    );
}

/// `XIGrabDevice` must wire into the existing core X11 grab
/// state (`state.active_pointer_grab` for
/// the master pointer, `state.active_keyboard_grab` for the
/// master keyboard) so the pointer/key fanout's
/// `active_grab_target` routing kicks in. Pre-fix the handler
/// was a no-op that just sent Success — GTK thought it owned
/// the device but events still went to whatever window the
/// pointer was over, so popups dismissed on the first stray
/// motion and `gtk_window_present` looped re-mapping at ~50 Hz.
#[test]
fn xi_grab_device_sets_active_grab_state() {
    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0010_0050;
    const CURSOR_XID: u32 = 0x0090_0050;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    // Pointer grab (deviceid=2) — XIGrabDevice body: window(4)
    // time(4) cursor(4) deviceid(2) mode(1) paired(1)
    // owner_events(1) pad(1) mask_len(2) ...
    let mut body = Vec::with_capacity(24);
    body.extend_from_slice(&WINDOW_XID.to_le_bytes()); // window
    body.extend_from_slice(&0u32.to_le_bytes()); // time
    body.extend_from_slice(&CURSOR_XID.to_le_bytes()); // cursor
    body.extend_from_slice(&2u16.to_le_bytes()); // deviceid (pointer)
    body.extend_from_slice(&[1, 1, 1, 0]); // mode async, paired async, owner_events=1, pad
    body.extend_from_slice(&0u16.to_le_bytes()); // mask_len
    body.extend_from_slice(&[0u8; 2]); // pad

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 51, // XIGrabDevice
        length_units: 7,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("XIGrabDevice pointer");

    assert_eq!(
        state
            .active_pointer_grab
            .map(|grab| (grab.owner, grab.grab_window)),
        Some((ClientId(CLIENT_ID), ResourceId(WINDOW_XID))),
        "XIGrabDevice(pointer) must set active_pointer_grab so \
             pointer_fanout's active_grab_target redirect kicks in",
    );
    assert!(state.active_pointer_grab.is_some_and(|grab| !grab.passive));
    let active = state.active_pointer_grab.expect("active_pointer_grab set");
    assert_eq!(active.owner, ClientId(CLIENT_ID));
    assert_eq!(active.grab_window, ResourceId(WINDOW_XID));
    assert_eq!(active.cursor, ResourceId(CURSOR_XID));

    // Keyboard grab (deviceid=3) — same wire format.
    let mut body_kbd = Vec::with_capacity(24);
    body_kbd.extend_from_slice(&WINDOW_XID.to_le_bytes());
    body_kbd.extend_from_slice(&0u32.to_le_bytes());
    body_kbd.extend_from_slice(&0u32.to_le_bytes());
    body_kbd.extend_from_slice(&3u16.to_le_bytes()); // keyboard
    body_kbd.extend_from_slice(&[1, 1, 1, 0]);
    body_kbd.extend_from_slice(&0u16.to_le_bytes());
    body_kbd.extend_from_slice(&[0u8; 2]);
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(2),
        header,
        &body_kbd,
    )
    .expect("XIGrabDevice keyboard");
    let kgrab = state
        .active_keyboard_grab
        .expect("active_keyboard_grab set");
    assert_eq!(kgrab.owner, ClientId(CLIENT_ID));
    assert_eq!(kgrab.grab_window, ResourceId(WINDOW_XID));

    // Ungrab both — XIUngrabDevice body: time(4) deviceid(2) pad(2).
    let ungrab_header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 52,
        // XIUngrabDevice is Fixed(3): 4 header + time(4) + deviceid(2)
        // + pad(2) = 12 bytes = 3 units. (Was 2 — pre-dated the
        // XTS-driven REQUEST_SIZE_MATCH length gate, so the malformed
        // length slipped through; master now correctly BadLengths it.)
        length_units: 3,
    };
    let mut ungrab_p = Vec::with_capacity(8);
    ungrab_p.extend_from_slice(&0u32.to_le_bytes()); // time
    ungrab_p.extend_from_slice(&2u16.to_le_bytes()); // pointer
    ungrab_p.extend_from_slice(&[0u8; 2]);
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(3),
        ungrab_header,
        &ungrab_p,
    )
    .expect("XIUngrabDevice pointer");
    assert!(state.active_pointer_grab.is_none());

    let mut ungrab_k = Vec::with_capacity(8);
    ungrab_k.extend_from_slice(&0u32.to_le_bytes());
    ungrab_k.extend_from_slice(&3u16.to_le_bytes());
    ungrab_k.extend_from_slice(&[0u8; 2]);
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(4),
        ungrab_header,
        &ungrab_k,
    )
    .expect("XIUngrabDevice keyboard");
    assert!(
        state.active_keyboard_grab.is_none(),
        "keyboard grab cleared"
    );
}

fn xi_dynamic_grab_source(
    state: &mut ServerState,
    source: u64,
    keyboard: bool,
    pointer: bool,
    name: &str,
) -> (crate::xinput::InputSourceId, u16) {
    let source_id = crate::xinput::InputSourceId(source);
    let info = crate::core_loop::DeviceInfo {
        source_id,
        enabled: true,
        resume_key: None,
        capabilities: crate::xinput::InputCapabilities {
            keyboard,
            pointer,
            touch: false,
        },
        name: name.to_owned(),
        device_node: format!("/dev/input/{name}"),
        sysname: name.to_owned(),
        vendor_id: 0,
        product_id: 0,
        is_touchpad: false,
        config: crate::core_loop::message::LibinputConfigSnapshot::default(),
    };
    let facet = if keyboard {
        crate::xinput::XiFacetKind::Keyboard
    } else {
        crate::xinput::XiFacetKind::PointerTouch
    };
    let ids = state.xi_register_source(&info);
    let device_id = ids
        .into_iter()
        .find(|id| {
            state
                .xi_devices
                .device(*id)
                .is_some_and(|device| device.facet == Some(facet))
        })
        .expect("requested physical facet was registered");
    (source_id, device_id)
}

fn process_dynamic_request(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    client_id: ClientId,
    sequence: SequenceNumber,
    opcode: u8,
    data: u8,
    body: &[u8],
) {
    let wire_bytes = body.len() + 4;
    assert_eq!(wire_bytes % 4, 0, "X11 request must be four-byte aligned");
    let length_units = u32::try_from(wire_bytes / 4).expect("request length fits CARD32");
    process_request(
        state,
        backend,
        client_id,
        sequence,
        RequestHeader {
            opcode,
            data,
            length_units,
        },
        body,
        None,
    )
    .expect("process_request dispatch");
}

fn process_xi_dynamic_request(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    client_id: ClientId,
    sequence: SequenceNumber,
    minor: u8,
    body: &[u8],
) {
    process_dynamic_request(state, backend, client_id, sequence, 137, minor, body);
}

fn xi_dynamic_wire_grab_body(
    window: u32,
    device_id: u16,
    grab_mode: u8,
    paired_device_mode: u8,
    owner_events: bool,
    mask: Option<u32>,
) -> Vec<u8> {
    let mut body = Vec::with_capacity(if mask.is_some() { 24 } else { 20 });
    body.extend_from_slice(&window.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // current time
    body.extend_from_slice(&0u32.to_le_bytes()); // no cursor
    body.extend_from_slice(&device_id.to_le_bytes());
    body.extend_from_slice(&[grab_mode, paired_device_mode, u8::from(owner_events), 0]);
    body.extend_from_slice(&u16::from(mask.is_some()).to_le_bytes()); // mask_len in 4-byte units
    if let Some(mask) = mask {
        body.extend_from_slice(&mask.to_le_bytes());
    }
    body
}

fn xi_dynamic_select_events_body(window: u32, device_id: u16, mask: u32) -> Vec<u8> {
    let mut body = Vec::with_capacity(16);
    body.extend_from_slice(&window.to_le_bytes());
    body.extend_from_slice(&1u16.to_le_bytes()); // one device mask
    body.extend_from_slice(&[0u8; 2]);
    body.extend_from_slice(&device_id.to_le_bytes());
    body.extend_from_slice(&1u16.to_le_bytes()); // one mask word
    body.extend_from_slice(&mask.to_le_bytes());
    body
}

fn xi_dynamic_pointer_event(
    origin: crate::core_loop::InputOrigin,
    kind: crate::host_x11::PointerEventKind,
    detail: u8,
    time: u32,
) -> crate::host_x11::HostPointerEvent {
    crate::host_x11::HostPointerEvent {
        origin,
        kind,
        host_xid: 0,
        detail,
        time,
        root_x: 10,
        root_y: 20,
        event_x: 10,
        event_y: 20,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    }
}

fn xi_dynamic_event_ids(bytes: &[u8]) -> Vec<(u16, u16, u16)> {
    let mut result = Vec::new();
    let mut offset = 0;
    while offset + 32 <= bytes.len() {
        assert_eq!(bytes[offset], 35, "expected GenericEvent");
        let extra = u32::from_le_bytes(bytes[offset + 4..offset + 8].try_into().unwrap());
        let evtype = u16::from_le_bytes(bytes[offset + 8..offset + 10].try_into().unwrap());
        let deviceid = u16::from_le_bytes(bytes[offset + 10..offset + 12].try_into().unwrap());
        let source_offset = if matches!(evtype, 13..=17) { 20 } else { 52 };
        let sourceid = u16::from_le_bytes(
            bytes[offset + source_offset..offset + source_offset + 2]
                .try_into()
                .unwrap(),
        );
        result.push((evtype, deviceid, sourceid));
        offset += 32 + extra as usize * 4;
    }
    assert_eq!(offset, bytes.len(), "event stream fully consumed");
    result
}

#[test]
fn xi_dynamic_grabs_xtest_release_keeps_master_passive_grab_until_master_release() {
    use crate::{
        backend::Backend, core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::PointerEventKind,
    };

    const OWNER: u32 = 1;
    const SOURCE: u64 = 91;
    let mut state = ServerState::new();
    let _owner_peer = install_client(&mut state, OWNER);
    let mut backend = RecordingBackend::new();
    let (source_id, pointer_id) =
        xi_dynamic_grab_source(&mut state, SOURCE, false, true, "passive-owner-mouse");

    // Core GrabButton: asynchronous pointer, synchronous paired keyboard.
    let mut grab_button = Vec::with_capacity(20);
    grab_button.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
    grab_button.extend_from_slice(&0x000cu16.to_le_bytes()); // ButtonPress|ButtonRelease
    grab_button.extend_from_slice(&[1, 0]); // pointer async, keyboard sync
    grab_button.extend_from_slice(&0u32.to_le_bytes()); // no confinement
    grab_button.extend_from_slice(&0u32.to_le_bytes()); // no cursor
    grab_button.extend_from_slice(&[1, 0]); // button 1, pad
    grab_button.extend_from_slice(&0u16.to_le_bytes()); // no modifiers
    process_dynamic_request(
        &mut state,
        &mut backend,
        ClientId(OWNER),
        SequenceNumber(1),
        28, // GrabButton
        0,  // owner_events=false
        &grab_button,
    );
    assert_eq!(state.button_grabs.len(), 1);

    let xid_map = backend.xid_map().clone();
    let _ = pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &xid_map,
        xi_dynamic_pointer_event(
            crate::core_loop::InputOrigin::Physical(source_id),
            PointerEventKind::ButtonPress,
            1,
            1,
        ),
        true,
        false,
    );
    assert!(state.active_pointer_grab.is_some_and(|grab| grab.passive));
    assert_eq!(state.buttons_down, 1);
    assert_eq!(state.xi_devices.device(pointer_id).unwrap().buttons_down, 1);
    assert_eq!(
        state.xi1_frozen[&crate::xinput::DEVICEID_MASTER_KEYBOARD].other,
        Some(ClientId(OWNER)),
        "the core passive grab holds its paired master keyboard"
    );

    for kind in [
        PointerEventKind::ButtonPress,
        PointerEventKind::ButtonRelease,
    ] {
        let _ = pointer_event_fanout_to_state(
            &mut state,
            &mut backend,
            &xid_map,
            xi_dynamic_pointer_event(
                crate::core_loop::InputOrigin::XTest(crate::xinput::DEVICEID_XTEST_POINTER),
                kind,
                1,
                2,
            ),
            true,
            false,
        );
    }

    assert!(
        state.active_pointer_grab.is_some_and(|grab| grab.passive),
        "the XTEST release cannot end a passive grab on the master while a physical button remains down"
    );
    assert_eq!(
        state.buttons_down, 1,
        "the master still holds physical button 1"
    );
    assert_eq!(state.xi_devices.device(pointer_id).unwrap().buttons_down, 1);
    assert_eq!(
        state
            .xi_devices
            .device(crate::xinput::DEVICEID_XTEST_POINTER)
            .unwrap()
            .buttons_down,
        0,
        "the XTEST source completed its independent click"
    );
    assert_eq!(
        state.xi1_frozen[&crate::xinput::DEVICEID_MASTER_KEYBOARD].other,
        Some(ClientId(OWNER)),
        "the paired keyboard remains held until the master grab ends"
    );
    assert!(state.sync_pending.is_empty());

    let _ = pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &xid_map,
        xi_dynamic_pointer_event(
            crate::core_loop::InputOrigin::Physical(source_id),
            PointerEventKind::ButtonRelease,
            1,
            3,
        ),
        true,
        false,
    );
    assert_eq!(state.buttons_down, 0);
    assert_eq!(state.xi_devices.device(pointer_id).unwrap().buttons_down, 0);
    assert!(state.active_pointer_grab.is_none());
    assert_eq!(
        state.xi1_frozen[&crate::xinput::DEVICEID_MASTER_KEYBOARD].other,
        None
    );
    assert!(state.sync_pending.is_empty());
}

#[test]
fn xi_dynamic_grabs_exact_slave_delivery_uses_grab_mask_without_selection() {
    use crate::{
        backend::Backend, core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::PointerEventKind,
    };

    const OWNER: u32 = 1;
    const XI_GRAB_DEVICE: u8 = 51;
    const XI_UNGRAB_DEVICE: u8 = 52;
    const GRAB_MASK: u32 = (1 << 4) | (1 << 5) | (1 << 6); // ButtonPress, ButtonRelease, Motion

    let mut state = ServerState::new();
    let mut owner_peer = install_capture_client(&mut state, OWNER);
    let mut backend = RecordingBackend::new();
    let (source_id, pointer_id) =
        xi_dynamic_grab_source(&mut state, 92, false, true, "grab-mask-mouse");
    let grab = xi_dynamic_wire_grab_body(
        ROOT_WINDOW.0,
        pointer_id,
        1, // asynchronous pointer mode
        1, // asynchronous paired-device mode
        false,
        Some(GRAB_MASK),
    );
    process_xi_dynamic_request(
        &mut state,
        &mut backend,
        ClientId(OWNER),
        SequenceNumber(1),
        XI_GRAB_DEVICE,
        &grab,
    );
    let _ = read_all_available(&mut owner_peer); // reply and grab crossings
    assert_eq!(
        state.xi_devices.device(pointer_id).unwrap().attached_master,
        None
    );

    let xid_map = backend.xid_map().clone();
    for (kind, detail, time, expected_type) in [
        (PointerEventKind::ButtonPress, 1, 2, 4),
        (PointerEventKind::MotionNotify, 0, 3, 6),
        (PointerEventKind::ButtonRelease, 1, 4, 5),
    ] {
        let _ = pointer_event_fanout_to_state(
            &mut state,
            &mut backend,
            &xid_map,
            xi_dynamic_pointer_event(
                crate::core_loop::InputOrigin::Physical(source_id),
                kind,
                detail,
                time,
            ),
            true,
            false,
        );
        assert_eq!(
            xi_dynamic_event_ids(&read_all_available(&mut owner_peer)),
            vec![(expected_type, pointer_id, pointer_id)],
            "an exact-device grab uses its XIGrabDevice mask without XISelectEvents"
        );
    }

    assert_eq!(
        state.xi2_pointer_grabs[&pointer_id].xi2_mask,
        u64::from(GRAB_MASK)
    );
    assert_eq!(state.xi_devices.device(pointer_id).unwrap().buttons_down, 0);
    assert_eq!(
        state.buttons_down, 0,
        "the floating slave never changes master held state"
    );
    assert!(state.xi2_pointer_grabs.contains_key(&pointer_id));
    assert_eq!(
        state.xi_devices.device(pointer_id).unwrap().attached_master,
        None
    );
    assert!(state.sync_pending.is_empty());
    assert!(!state.xi1_frozen[&pointer_id].frozen());

    let mut ungrab = Vec::with_capacity(8);
    ungrab.extend_from_slice(&0u32.to_le_bytes());
    ungrab.extend_from_slice(&pointer_id.to_le_bytes());
    ungrab.extend_from_slice(&[0u8; 2]);
    process_xi_dynamic_request(
        &mut state,
        &mut backend,
        ClientId(OWNER),
        SequenceNumber(2),
        XI_UNGRAB_DEVICE,
        &ungrab,
    );
    assert!(!state.xi2_pointer_grabs.contains_key(&pointer_id));
    assert_eq!(
        state.xi_devices.device(pointer_id).unwrap().attached_master,
        Some(crate::xinput::DEVICEID_MASTER_POINTER)
    );
    assert!(!state.xi2_detached_masters.contains_key(&pointer_id));
    assert!(state.sync_pending.is_empty());
}

#[test]
fn xi_dynamic_grabs_floating_slave_does_not_copy_raw_motion_to_masters() {
    use crate::{
        backend::Backend, core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::PointerEventKind,
    };

    const FACET_CLIENT: u32 = 1;
    const MASTER_CLIENT: u32 = 2;
    const ALL_MASTER_CLIENT: u32 = 3;
    const GRAB_CLIENT: u32 = 4;
    const XI_SELECT_EVENTS: u8 = 46;
    const XI_GRAB_DEVICE: u8 = 51;
    const RAW_MOTION_MASK: u32 = 1 << 17;

    let mut state = ServerState::new();
    let mut facet_peer = install_capture_client(&mut state, FACET_CLIENT);
    let mut master_peer = install_capture_client(&mut state, MASTER_CLIENT);
    let mut all_master_peer = install_capture_client(&mut state, ALL_MASTER_CLIENT);
    let mut grab_peer = install_capture_client(&mut state, GRAB_CLIENT);
    let mut backend = RecordingBackend::new();
    let (source_id, pointer_id) =
        xi_dynamic_grab_source(&mut state, 93, false, true, "floating-raw-mouse");

    for (client, selector) in [
        (FACET_CLIENT, pointer_id),
        (MASTER_CLIENT, crate::xinput::DEVICEID_MASTER_POINTER),
        (ALL_MASTER_CLIENT, 1), // XIAllMasterDevices
    ] {
        process_xi_dynamic_request(
            &mut state,
            &mut backend,
            ClientId(client),
            SequenceNumber(1),
            XI_SELECT_EVENTS,
            &xi_dynamic_select_events_body(ROOT_WINDOW.0, selector, RAW_MOTION_MASK),
        );
    }
    process_xi_dynamic_request(
        &mut state,
        &mut backend,
        ClientId(GRAB_CLIENT),
        SequenceNumber(1),
        XI_GRAB_DEVICE,
        &xi_dynamic_wire_grab_body(ROOT_WINDOW.0, pointer_id, 1, 1, false, None),
    );
    let _ = read_all_available(&mut grab_peer); // reply and grab crossings
    assert_eq!(
        state.xi_devices.device(pointer_id).unwrap().attached_master,
        None
    );

    let xid_map = backend.xid_map().clone();
    let mut motion = xi_dynamic_pointer_event(
        crate::core_loop::InputOrigin::Physical(source_id),
        PointerEventKind::MotionNotify,
        0,
        2,
    );
    motion.raw_dx = 8;
    motion.raw_dy = -3;
    let _ = pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, motion, true, false);

    assert_eq!(
        xi_dynamic_event_ids(&read_all_available(&mut facet_peer)),
        vec![(17, pointer_id, pointer_id)],
        "floating input retains its raw slave event"
    );
    assert!(
        xi_dynamic_event_ids(&read_all_available(&mut master_peer)).is_empty(),
        "a floating slave has no raw master copy"
    );
    assert!(
        xi_dynamic_event_ids(&read_all_available(&mut all_master_peer)).is_empty(),
        "XIAllMasterDevices receives no raw copy from a floating slave"
    );
    assert_eq!(
        state.xi_devices.device(pointer_id).unwrap().attached_master,
        None
    );
    assert!(state.sync_pending.is_empty());
}

#[test]
fn xi_slave_switch_device_changed_selection_on_child_window_is_delivered() {
    use crate::{core_loop::pointer_fanout::pointer_event_fanout_to_state, host_x11::HostXidMap};

    const CLIENT: u32 = 94;
    const CHILD: u32 = 0x0010_0094;
    const XI_SELECT_EVENTS: u8 = 46;
    const SOURCE: u64 = 0xB14;

    let mut state = ServerState::new();
    let mut peer = install_capture_client(&mut state, CLIENT);
    let mut backend = RecordingBackend::new();
    state.resources.create_window(
        ClientId(CLIENT),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(CHILD),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    let (source_id, pointer_id) =
        xi_dynamic_grab_source(&mut state, SOURCE, false, true, "child-switch-mouse");
    process_xi_dynamic_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT),
        SequenceNumber(1),
        XI_SELECT_EVENTS,
        &xi_dynamic_select_events_body(
            CHILD,
            crate::xinput::DEVICEID_MASTER_POINTER,
            crate::xinput::XI2_DEVICE_CHANGED_MASK,
        ),
    );
    assert!(
        read_all_available(&mut peer).is_empty(),
        "a child selection does not receive the root-only bootstrap"
    );
    process_xi_dynamic_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT),
        SequenceNumber(2),
        XI_SELECT_EVENTS,
        &xi_dynamic_select_events_body(
            ROOT_WINDOW.0,
            crate::xinput::DEVICEID_MASTER_POINTER,
            crate::xinput::XI2_DEVICE_CHANGED_MASK,
        ),
    );
    let _root_bootstrap = read_all_available(&mut peer);

    let dropped = pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &HostXidMap::new(),
        xi_dynamic_pointer_event(
            crate::core_loop::InputOrigin::Physical(source_id),
            crate::host_x11::PointerEventKind::MotionNotify,
            0,
            1,
        ),
        true,
        false,
    );
    assert!(dropped.is_empty());

    let events = read_all_available(&mut peer);
    let mut delivered = Vec::new();
    let mut offset = 0;
    while offset < events.len() {
        assert_eq!(events[offset], 35, "GenericEvent");
        let units = usize::try_from(u32::from_le_bytes(
            events[offset + 4..offset + 8].try_into().unwrap(),
        ))
        .unwrap();
        let event_len = 32 + 4 * units;
        assert!(
            offset + event_len <= events.len(),
            "complete DeviceChanged event"
        );
        assert_eq!(
            u16::from_le_bytes([events[offset + 8], events[offset + 9]]),
            1,
            "XI_DeviceChanged SlaveSwitch"
        );
        assert_eq!(
            u16::from_le_bytes([events[offset + 10], events[offset + 11]]),
            crate::xinput::DEVICEID_MASTER_POINTER
        );
        assert_eq!(
            u16::from_le_bytes([events[offset + 18], events[offset + 19]]),
            pointer_id,
            "sourceid is the newly active physical slave"
        );
        delivered.push((
            u16::from_le_bytes([events[offset + 10], events[offset + 11]]),
            u16::from_le_bytes([events[offset + 18], events[offset + 19]]),
        ));
        offset += event_len;
    }
    assert_eq!(
        delivered,
        [(crate::xinput::DEVICEID_MASTER_POINTER, pointer_id); 2],
        "Xorg emits one DeviceChanged for root and one for the selected child"
    );
    assert_eq!(
        state.xi_devices.device(pointer_id).unwrap().attached_master,
        Some(crate::xinput::DEVICEID_MASTER_POINTER)
    );
    assert!(state.xi2_pointer_grabs.is_empty());
    assert!(state.active_pointer_grab.is_none());
    assert_eq!(state.buttons_down, 0);
    assert!(state.unpublished_pointer_buttons_down.is_empty());
    assert!(state.sync_pending.is_empty());
    assert!(state.xi1_frozen.values().all(|freeze| {
        freeze.state == crate::server::Xi1SyncState::Thawed
            && freeze.other.is_none()
            && freeze.stored.is_none()
    }));
    assert!(state.clients[&CLIENT].outbound.is_empty());
}

fn xi_dynamic_grab_body(window: u32, device_id: u16, mode: u8) -> Vec<u8> {
    let mut body = Vec::with_capacity(24);
    body.extend_from_slice(&window.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // current time
    body.extend_from_slice(&0u32.to_le_bytes()); // no cursor
    body.extend_from_slice(&device_id.to_le_bytes());
    body.extend_from_slice(&[mode, 1, 0, 0]); // mode, paired async, owner_events, pad
    body.extend_from_slice(&0u16.to_le_bytes()); // no event-mask words
    body.extend_from_slice(&[0u8; 2]);
    body
}

fn xi_dynamic_passive_grab_body(
    window: u32,
    detail: u32,
    device_id: u16,
    grab_type: u8,
    grab_mode: u8,
    paired_device_mode: u8,
) -> Vec<u8> {
    let mut body = Vec::with_capacity(32);
    body.extend_from_slice(&0u32.to_le_bytes()); // current time
    body.extend_from_slice(&window.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // no cursor
    body.extend_from_slice(&detail.to_le_bytes());
    body.extend_from_slice(&device_id.to_le_bytes());
    body.extend_from_slice(&1u16.to_le_bytes()); // one modifier tuple
    body.extend_from_slice(&0u16.to_le_bytes()); // no XI2 event-mask words
    body.extend_from_slice(&[grab_type, grab_mode, paired_device_mode, 0, 0, 0]);
    body.extend_from_slice(&0u32.to_le_bytes()); // no modifiers
    body
}

fn xi_dynamic_allow_replay_body(device_id: u16) -> Vec<u8> {
    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&0u32.to_le_bytes()); // current time
    body.extend_from_slice(&device_id.to_le_bytes());
    body.extend_from_slice(&[2, 0]); // XIReplayDevice, pad
    body
}

#[test]
fn xi_dynamic_grabs_classify_keyboard_and_keep_slave_grabs_independent() {
    const KEY_CLIENT: u32 = 1;
    const POINTER_CLIENT_A: u32 = 2;
    const POINTER_CLIENT_B: u32 = 3;
    const WINDOW: u32 = 0x0010_0057;

    let mut state = ServerState::new();
    let _key_peer = install_client(&mut state, KEY_CLIENT);
    let _pointer_peer_a = install_client(&mut state, POINTER_CLIENT_A);
    let _pointer_peer_b = install_client(&mut state, POINTER_CLIENT_B);
    let mut backend = RecordingBackend::new();
    let (_, keyboard_id) = xi_dynamic_grab_source(&mut state, 11, true, false, "kbd-a");
    let (_, pointer_id_a) = xi_dynamic_grab_source(&mut state, 12, false, true, "ptr-a");
    let (_, pointer_id_b) = xi_dynamic_grab_source(&mut state, 13, false, true, "ptr-b");
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 51,
        length_units: 7,
    };

    for (client, device_id) in [
        (KEY_CLIENT, keyboard_id),
        (POINTER_CLIENT_A, pointer_id_a),
        (POINTER_CLIENT_B, pointer_id_b),
    ] {
        handle_xi2_request(
            &mut state,
            &mut backend,
            None,
            ClientId(client),
            SequenceNumber(1),
            header,
            &xi_dynamic_grab_body(WINDOW, device_id, 1),
        )
        .expect("XIGrabDevice for physical facet");
    }

    assert!(
        state.active_pointer_grab.is_none(),
        "a pointer-slave grab must not occupy the core master-pointer slot"
    );
    assert!(
        state.active_keyboard_grab.is_none(),
        "a keyboard-slave grab must not occupy the core master-keyboard slot"
    );
    assert_eq!(
        state.xi2_keyboard_grabs.get(&keyboard_id).unwrap().owner,
        ClientId(KEY_CLIENT)
    );
    assert_eq!(
        state.xi2_pointer_grabs.get(&pointer_id_a).unwrap().owner,
        ClientId(POINTER_CLIENT_A)
    );
    assert_eq!(
        state.xi2_pointer_grabs.get(&pointer_id_b).unwrap().owner,
        ClientId(POINTER_CLIENT_B)
    );
    assert_eq!(state.xi2_keyboard_grabs.len(), 1);
    assert_eq!(state.xi2_pointer_grabs.len(), 2);
    assert_eq!(
        state.xi2_detached_masters.get(&keyboard_id),
        Some(&crate::xinput::DEVICEID_MASTER_KEYBOARD)
    );
    assert_eq!(
        state.xi2_detached_masters.get(&pointer_id_a),
        Some(&crate::xinput::DEVICEID_MASTER_POINTER)
    );
    assert_eq!(
        state.xi2_detached_masters.get(&pointer_id_b),
        Some(&crate::xinput::DEVICEID_MASTER_POINTER)
    );
    assert_eq!(
        state
            .xi_devices
            .device(keyboard_id)
            .unwrap()
            .attached_master,
        None
    );
    assert_eq!(
        state
            .xi_devices
            .device(pointer_id_a)
            .unwrap()
            .attached_master,
        None
    );
    assert_eq!(
        state
            .xi_devices
            .device(pointer_id_b)
            .unwrap()
            .attached_master,
        None
    );
}

#[test]
fn xi_dynamic_grabs_slave_pointer_replay_reattaches_and_replays_to_natural_target() {
    use crate::{
        backend::Backend,
        core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
    };

    const GRAB_CLIENT: u32 = 1;
    const TARGET_CLIENT: u32 = 2;
    const TARGET_WINDOW: u32 = 0x0010_005A;
    const HOST_XID: u32 = 0xCAFE_005A;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT);
    let mut target_peer = install_client(&mut state, TARGET_CLIENT);
    let mut backend = RecordingBackend::new();
    let (source_id, pointer_id) =
        xi_dynamic_grab_source(&mut state, 41, false, true, "replay-pointer");
    assert!(pointer_id > 5, "test must use a dynamic physical slave ID");
    assert_eq!(
        state.xi_devices.role(pointer_id),
        Some(crate::xinput::XiDeviceRole::SlavePointer)
    );
    state.resources.create_window(
        ClientId(TARGET_CLIENT),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(TARGET_WINDOW),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(TARGET_WINDOW));
    state
        .clients
        .get_mut(&TARGET_CLIENT)
        .expect("target client")
        .event_masks
        .insert(ResourceId(TARGET_WINDOW), 0x0004); // ButtonPressMask
    Backend::register_top_level(&mut backend, None, ResourceId(TARGET_WINDOW), HOST_XID)
        .expect("register physical input target");

    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT),
        SequenceNumber(1),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 54,
            length_units: 9,
        },
        &xi_dynamic_passive_grab_body(
            ROOT_WINDOW.0,
            1,
            pointer_id,
            0, // Button
            0, // synchronous pointer mode
            1, // asynchronous paired-device mode
        ),
    )
    .expect("XIPassiveGrabDevice button");
    let _ = read_all_available(&mut grab_peer); // XIPassiveGrabDevice reply

    let xid_map = backend.xid_map().clone();
    let press = HostPointerEvent {
        origin: crate::core_loop::InputOrigin::Physical(source_id),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_XID,
        detail: 1,
        time: 0x1234,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let _ = pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, press, true, false);

    assert!(state.xi2_pointer_grabs.contains_key(&pointer_id));
    assert_eq!(
        state.xi_devices.device(pointer_id).unwrap().attached_master,
        None,
        "activating a synchronous physical-slave button grab detaches that slave"
    );
    assert!(
        state.active_pointer_grab.is_none(),
        "a physical-slave XI2 grab must not occupy the core master slot"
    );
    assert!(matches!(
        state
            .xi1_frozen
            .get(&pointer_id)
            .and_then(|freeze| freeze.stored.as_ref()),
        Some(crate::server::QueuedInputEvent::HostPointer(_))
    ));
    assert!(
        read_all_available(&mut target_peer).is_empty(),
        "the natural target waits for XIReplayDevice"
    );

    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT),
        SequenceNumber(2),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 53,
            length_units: 3,
        },
        &xi_dynamic_allow_replay_body(pointer_id),
    )
    .expect("XIAllowEvents ReplayDevice");

    assert!(!state.xi2_pointer_grabs.contains_key(&pointer_id));
    assert!(state.active_pointer_grab.is_some_and(|grab| {
        grab.implicit
            && grab.owner == ClientId(TARGET_CLIENT)
            && grab.grab_window == ResourceId(TARGET_WINDOW)
    }));
    assert_eq!(
        state.xi_devices.device(pointer_id).unwrap().attached_master,
        Some(crate::xinput::DEVICEID_MASTER_POINTER),
        "ReplayDevice restores the physical slave's original master"
    );
    assert!(!state.xi2_detached_masters.contains_key(&pointer_id));
    assert!(!state.xi1_frozen[&pointer_id].frozen());
    assert!(state.xi1_frozen[&pointer_id].stored.is_none());

    let replay = read_all_or_buffered(&mut state, TARGET_CLIENT, &mut target_peer);
    assert!(
        replay.len() >= 32,
        "expected replayed ButtonPress, got {} bytes",
        replay.len()
    );
    assert_eq!(
        replay[0] & 0x7f,
        4,
        "replay reaches the target as ButtonPress"
    );
    assert_eq!(
        &replay[12..16],
        &TARGET_WINDOW.to_le_bytes(),
        "XIReplayDevice delivers to the natural target after the passive grab"
    );

    let _ = pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &xid_map,
        HostPointerEvent {
            kind: PointerEventKind::ButtonRelease,
            time: 0x1235,
            state: 0x0100,
            ..press
        },
        true,
        false,
    );
    assert!(state.xi2_pointer_grabs.is_empty());
    assert!(state.active_pointer_grab.is_none());
}

#[test]
fn xi_dynamic_grabs_slave_keyboard_replay_reattaches_and_replays_to_focus() {
    use crate::{
        core_loop::key_fanout::key_event_fanout_to_state, host_x11::HostKeyEvent,
        resources::ROOT_VISUAL,
    };

    const GRAB_CLIENT: u32 = 1;
    const TARGET_CLIENT: u32 = 2;
    const TARGET_WINDOW: u32 = 0x0010_005B;
    const KEYCODE: u32 = 38;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT);
    let mut target_peer = install_client(&mut state, TARGET_CLIENT);
    let mut backend = RecordingBackend::new();
    let (source_id, keyboard_id) =
        xi_dynamic_grab_source(&mut state, 42, true, false, "replay-keyboard");
    assert!(keyboard_id > 5, "test must use a dynamic physical slave ID");
    assert_eq!(
        state.xi_devices.role(keyboard_id),
        Some(crate::xinput::XiDeviceRole::SlaveKeyboard)
    );
    state.resources.create_window(
        ClientId(TARGET_CLIENT),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(TARGET_WINDOW),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(TARGET_WINDOW));
    state.core_focus.raw = TARGET_WINDOW;
    state
        .clients
        .get_mut(&TARGET_CLIENT)
        .expect("target client")
        .event_masks
        .insert(ResourceId(TARGET_WINDOW), 0x0001); // KeyPressMask

    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT),
        SequenceNumber(1),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 54,
            length_units: 9,
        },
        &xi_dynamic_passive_grab_body(
            ROOT_WINDOW.0,
            KEYCODE,
            keyboard_id,
            1, // Keycode
            0, // synchronous keyboard mode
            1, // asynchronous paired-device mode
        ),
    )
    .expect("XIPassiveGrabDevice keycode");
    let _ = read_all_available(&mut grab_peer); // XIPassiveGrabDevice reply

    let press = HostKeyEvent {
        origin: crate::core_loop::InputOrigin::Physical(source_id),
        pressed: true,
        keycode: KEYCODE as u8,
        time: 0x1234,
        root_x: 10,
        root_y: 20,
        event_x: 10,
        event_y: 20,
        state: 0,
    };
    let _ = key_event_fanout_to_state(&mut state, &mut backend, press);

    assert!(state.xi2_keyboard_grabs.contains_key(&keyboard_id));
    assert_eq!(
        state
            .xi_devices
            .device(keyboard_id)
            .unwrap()
            .attached_master,
        None,
        "activating a synchronous physical-slave key grab detaches that slave"
    );
    assert!(matches!(
        state
            .xi1_frozen
            .get(&keyboard_id)
            .and_then(|freeze| freeze.stored.as_ref()),
        Some(
            crate::server::QueuedInputEvent::HostKey(_)
                | crate::server::QueuedInputEvent::HostKeyTransition(_, _)
        )
    ));
    assert!(
        read_all_available(&mut target_peer).is_empty(),
        "the focus window waits for XIReplayDevice"
    );

    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT),
        SequenceNumber(2),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 53,
            length_units: 3,
        },
        &xi_dynamic_allow_replay_body(keyboard_id),
    )
    .expect("XIAllowEvents ReplayDevice");

    assert!(!state.xi2_keyboard_grabs.contains_key(&keyboard_id));
    assert!(state.active_keyboard_grab.is_none());
    assert_eq!(
        state
            .xi_devices
            .device(keyboard_id)
            .unwrap()
            .attached_master,
        Some(crate::xinput::DEVICEID_MASTER_KEYBOARD),
        "ReplayDevice restores the physical slave's original master"
    );
    assert!(!state.xi2_detached_masters.contains_key(&keyboard_id));
    assert!(!state.xi1_frozen[&keyboard_id].frozen());
    assert!(state.xi1_frozen[&keyboard_id].stored.is_none());

    let replay = read_all_available(&mut target_peer);
    assert!(
        replay.len() >= 32,
        "expected replayed KeyPress, got {} bytes",
        replay.len()
    );
    assert_eq!(replay[0] & 0x7f, 2, "replay reaches focus as KeyPress");
    assert_eq!(
        &replay[12..16],
        &TARGET_WINDOW.to_le_bytes(),
        "XIReplayDevice delivers to the current focus window"
    );
}

#[test]
fn xi_dynamic_grabs_slave_keyboard_release_reattaches_for_next_key() {
    use crate::{
        core_loop::key_fanout::key_event_fanout_to_state, host_x11::HostKeyEvent,
        resources::ROOT_VISUAL,
    };

    const GRAB_CLIENT: u32 = 1;
    const TARGET_CLIENT: u32 = 2;
    const TARGET_WINDOW: u32 = 0x0010_005C;
    const GRABBED_KEYCODE: u32 = 38;
    const NEXT_KEYCODE: u8 = 39;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT);
    let mut target_peer = install_client(&mut state, TARGET_CLIENT);
    let mut backend = RecordingBackend::new();
    let (source_id, keyboard_id) =
        xi_dynamic_grab_source(&mut state, 43, true, false, "release-keyboard");
    assert!(keyboard_id > 5, "test must use a dynamic physical slave ID");
    assert_eq!(
        state.xi_devices.role(keyboard_id),
        Some(crate::xinput::XiDeviceRole::SlaveKeyboard)
    );
    state.resources.create_window(
        ClientId(TARGET_CLIENT),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(TARGET_WINDOW),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(TARGET_WINDOW));
    state.core_focus.raw = TARGET_WINDOW;
    state
        .clients
        .get_mut(&TARGET_CLIENT)
        .expect("target client")
        .event_masks
        .insert(ResourceId(TARGET_WINDOW), 0x0001); // KeyPressMask

    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT),
        SequenceNumber(1),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 54,
            length_units: 9,
        },
        &xi_dynamic_passive_grab_body(
            ROOT_WINDOW.0,
            GRABBED_KEYCODE,
            keyboard_id,
            1, // Keycode
            1, // asynchronous keyboard mode; release is not frozen
            1, // asynchronous paired-device mode
        ),
    )
    .expect("XIPassiveGrabDevice keycode");
    let _ = read_all_available(&mut grab_peer); // XIPassiveGrabDevice reply

    let input = |pressed, keycode| HostKeyEvent {
        origin: crate::core_loop::InputOrigin::Physical(source_id),
        pressed,
        keycode,
        time: 0x1234,
        root_x: 10,
        root_y: 20,
        event_x: 10,
        event_y: 20,
        state: 0,
    };
    let _ = key_event_fanout_to_state(&mut state, &mut backend, input(true, GRABBED_KEYCODE as u8));
    assert!(state.xi2_keyboard_grabs.contains_key(&keyboard_id));
    assert_eq!(
        state
            .xi_devices
            .device(keyboard_id)
            .unwrap()
            .attached_master,
        None,
        "the matching passive grab floats the physical keyboard"
    );

    let _ = key_event_fanout_to_state(
        &mut state,
        &mut backend,
        input(false, GRABBED_KEYCODE as u8),
    );
    assert!(
        !state.xi2_keyboard_grabs.contains_key(&keyboard_id),
        "the matching key release auto-deactivates the slave passive grab"
    );
    assert_eq!(
        state
            .xi_devices
            .device(keyboard_id)
            .unwrap()
            .attached_master,
        Some(crate::xinput::DEVICEID_MASTER_KEYBOARD),
        "matching key release restores the physical slave's original master"
    );
    assert!(!state.xi2_detached_masters.contains_key(&keyboard_id));

    let _ = key_event_fanout_to_state(&mut state, &mut backend, input(true, NEXT_KEYCODE));
    let delivered = read_all_available(&mut target_peer);
    assert!(
        delivered.len() >= 32,
        "expected next core KeyPress, got {} bytes",
        delivered.len()
    );
    assert_eq!(
        delivered[0] & 0x7f,
        2,
        "next key returns to core KeyPress delivery"
    );
    assert_eq!(
        &delivered[12..16],
        &TARGET_WINDOW.to_le_bytes(),
        "next key from the reattached slave reaches the focused window"
    );
    assert_ne!(
        state.keys_down[usize::from(NEXT_KEYCODE / 8)] & (1 << (NEXT_KEYCODE % 8)),
        0,
        "the reattached key also updates master keyboard state"
    );
}

#[test]
fn xi_dynamic_grabs_passive_button_is_scoped_to_its_device() {
    use crate::{
        backend::Backend,
        core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
    };

    const GRAB_CLIENT: u32 = 1;
    const WINDOW: u32 = 0x0010_0058;
    const HOST_XID: u32 = 0xCAFE_0058;
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, GRAB_CLIENT);
    let mut backend = RecordingBackend::new();
    let (_, razer_id) = xi_dynamic_grab_source(&mut state, 21, false, true, "razer");
    let (hyperx_source, hyperx_id) = xi_dynamic_grab_source(&mut state, 22, false, true, "hyperx");
    state.resources.create_window(
        ClientId(GRAB_CLIENT),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(WINDOW));

    // XIPassiveGrabDevice: one AnyModifier button grab, tied to the Razer
    // pointer facet. The button mask is intentionally empty; the passive
    // grab still activates and its owner receives the protocol event.
    let mut body = Vec::with_capacity(32);
    body.extend_from_slice(&0u32.to_le_bytes());
    body.extend_from_slice(&WINDOW.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // cursor
    body.extend_from_slice(&1u32.to_le_bytes()); // button 1
    body.extend_from_slice(&razer_id.to_le_bytes());
    body.extend_from_slice(&1u16.to_le_bytes()); // one modifier tuple
    body.extend_from_slice(&0u16.to_le_bytes()); // no event-mask words
    body.extend_from_slice(&[0, 0, 1, 0, 0, 0]); // button, sync, async, owner=false, pad
    body.extend_from_slice(&0u32.to_le_bytes()); // AnyModifier is encoded as zero here
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT),
        SequenceNumber(1),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 54,
            length_units: 9,
        },
        &body,
    )
    .expect("XIPassiveGrabDevice");

    Backend::register_top_level(&mut backend, None, ResourceId(WINDOW), HOST_XID)
        .expect("register host window");
    let event = |source, kind, root_x, root_y, state_mask| HostPointerEvent {
        origin: crate::core_loop::InputOrigin::Physical(source),
        kind,
        host_xid: HOST_XID,
        detail: 1,
        time: 0x1234,
        root_x,
        root_y,
        event_x: root_x,
        event_y: root_y,
        state: state_mask,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let xid_map = backend.xid_map().clone();
    for kind in [
        PointerEventKind::ButtonPress,
        PointerEventKind::ButtonRelease,
    ] {
        let _ = pointer_event_fanout_to_state(
            &mut state,
            &mut backend,
            &xid_map,
            event(
                hyperx_source,
                kind,
                10,
                10,
                if kind == PointerEventKind::ButtonRelease {
                    0x0100
                } else {
                    0
                },
            ),
            true,
            false,
        );
    }

    assert!(
        !state.xi2_pointer_grabs.contains_key(&razer_id),
        "HyperX press/release must not activate Razer's exact-device passive grab",
    );
    assert!(
        state.active_pointer_grab.is_none(),
        "Razer's exact-device passive grab must not intercept HyperX"
    );
    assert_eq!(
        state.xi_devices.device(hyperx_id).unwrap().buttons_down,
        0,
        "HyperX press/release transitions remain balanced on HyperX"
    );
    assert_eq!(
        state.xi_devices.device(razer_id).unwrap().buttons_down,
        0,
        "Razer's held set is untouched"
    );

    let _ = pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &xid_map,
        event(hyperx_source, PointerEventKind::ButtonPress, 10, 10, 0),
        true,
        false,
    );
    let _ = pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &xid_map,
        event(
            crate::xinput::InputSourceId(21),
            PointerEventKind::ButtonPress,
            10,
            10,
            0,
        ),
        true,
        false,
    );
    assert_eq!(
        state
            .xi2_pointer_grabs
            .get(&razer_id)
            .map(|grab| grab.owner),
        Some(ClientId(GRAB_CLIENT)),
        "Razer's exact XI2 passive grab activates for Razer"
    );
    assert_eq!(
        state.xi_devices.device(razer_id).unwrap().attached_master,
        None,
        "the passive grab floats only its exact physical slave"
    );
    assert!(state.active_pointer_grab.is_none());

    // The activating press arrived while attached. A later, separate
    // button transition arrives while the Razer facet is floating and
    // must change only its per-slave hold state.
    let master_buttons = state.buttons_down;
    let master_position = state.pointer_root;
    let second_press = HostPointerEvent {
        detail: 2,
        state: 0x0100,
        ..event(
            crate::xinput::InputSourceId(21),
            PointerEventKind::ButtonPress,
            10,
            10,
            0x0100,
        )
    };
    let _ = pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &xid_map,
        second_press,
        true,
        false,
    );
    assert_eq!(state.buttons_down, master_buttons);
    assert_eq!(state.pointer_root, master_position);
    assert_eq!(state.xi_devices.device(razer_id).unwrap().buttons_down, 3);
    let second_release = HostPointerEvent {
        kind: PointerEventKind::ButtonRelease,
        state: 0x0300,
        ..second_press
    };
    let _ = pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &xid_map,
        second_release,
        true,
        false,
    );
    assert_eq!(state.buttons_down, master_buttons);
    assert_eq!(state.xi_devices.device(razer_id).unwrap().buttons_down, 1);

    for kind in [
        PointerEventKind::ButtonPress,
        PointerEventKind::ButtonRelease,
    ] {
        let _ = pointer_event_fanout_to_state(
            &mut state,
            &mut backend,
            &xid_map,
            event(
                hyperx_source,
                kind,
                10,
                10,
                if kind == PointerEventKind::ButtonRelease {
                    0x0100
                } else {
                    0
                },
            ),
            true,
            false,
        );
    }
    assert!(state.xi2_pointer_grabs.contains_key(&razer_id));
    assert_eq!(state.xi_devices.device(hyperx_id).unwrap().buttons_down, 0);

    let master_position = state.pointer_root;
    let _ = pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &xid_map,
        event(
            crate::xinput::InputSourceId(21),
            PointerEventKind::MotionNotify,
            30,
            40,
            0x0100,
        ),
        true,
        false,
    );
    assert_eq!(
        state.pointer_root, master_position,
        "floating motion leaves the master sprite alone"
    );
    assert_eq!(
        state.floating_pointer_positions.get(&razer_id),
        Some(&(30.0, 40.0))
    );

    let _ = pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &xid_map,
        event(
            crate::xinput::InputSourceId(21),
            PointerEventKind::ButtonRelease,
            30,
            40,
            0x0100,
        ),
        true,
        false,
    );
    assert!(state.xi2_pointer_grabs.contains_key(&razer_id));
    assert_eq!(
        state.xi_devices.device(razer_id).unwrap().attached_master,
        None,
        "a synchronous activating press stays grabbed until replay"
    );
    assert!(!state.sync_pending.is_empty());

    let mut allow_body = Vec::with_capacity(8);
    allow_body.extend_from_slice(&0u32.to_le_bytes());
    allow_body.extend_from_slice(&razer_id.to_le_bytes());
    allow_body.extend_from_slice(&[2, 0]); // XIReplayDevice
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT),
        SequenceNumber(2),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 53,
            length_units: 3,
        },
        &allow_body,
    )
    .expect("XIAllowEvents ReplayDevice");
    assert!(
        state.xi2_pointer_grabs.is_empty(),
        "passive release ends the exact-device grab"
    );
    assert_eq!(
        state.xi_devices.device(razer_id).unwrap().attached_master,
        Some(crate::xinput::DEVICEID_MASTER_POINTER),
        "passive release restores the original master"
    );
    assert_eq!(state.xi_devices.device(razer_id).unwrap().buttons_down, 0);
    assert_eq!(state.xi_devices.device(hyperx_id).unwrap().buttons_down, 0);
    assert_eq!(
        state.buttons_down, 0,
        "replay drains the attached master hold"
    );
    assert!(!state.xi2_detached_masters.contains_key(&razer_id));
    assert!(!state.floating_pointer_positions.contains_key(&razer_id));
    assert!(!state.xi1_frozen[&razer_id].frozen());
    assert!(state.sync_pending.is_empty());
}

#[test]
fn xi_dynamic_grabs_detach_and_reattach_slave_without_pair_freeze() {
    const CLIENT: u32 = 1;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT);
    let mut backend = RecordingBackend::new();
    let (source_id, pointer_id) =
        xi_dynamic_grab_source(&mut state, 31, false, true, "floating-razer");
    let grab_body = xi_dynamic_wire_grab_body(
        ROOT_WINDOW.0,
        pointer_id,
        1, // asynchronous pointer mode
        0, // requested synchronous paired-device mode; Xorg forces Async for slaves
        false,
        None,
    );
    process_xi_dynamic_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT),
        SequenceNumber(1),
        51,
        &grab_body,
    );
    let _ = read_all_available(&mut peer); // XIGrabDevice reply and crossings

    assert_eq!(
        state.xi_devices.device(pointer_id).unwrap().attached_master,
        None,
        "an explicit XI2 physical-slave grab detaches the slave"
    );
    assert!(
        state.xi_devices.source(source_id).unwrap().enabled,
        "detaching a live slave does not disable its source"
    );
    assert_eq!(
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_KEYBOARD)
            .and_then(|freeze| freeze.other),
        None,
        "a slave grab forces its paired mode to Async and leaves the master keyboard unfrozen",
    );
    assert!(
        !state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_KEYBOARD)
            .is_some_and(crate::server::Xi1Freeze::frozen)
    );

    // XIAsyncPairedDevice remains a no-op after Xorg coerces the paired
    // mode to Async during XIGrabDevice.
    let mut allow_body = Vec::with_capacity(8);
    allow_body.extend_from_slice(&0u32.to_le_bytes());
    allow_body.extend_from_slice(&pointer_id.to_le_bytes());
    allow_body.extend_from_slice(&[3, 0]); // XIAsyncPairedDevice
    process_xi_dynamic_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT),
        SequenceNumber(2),
        53,
        &allow_body,
    );
    assert_eq!(
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_KEYBOARD)
            .and_then(|freeze| freeze.other),
        None,
        "XIAllowEvents does not find a paired master hold to release",
    );
    assert!(state.xi2_pointer_grabs.contains_key(&pointer_id));
    assert_eq!(
        state.xi_devices.device(pointer_id).unwrap().attached_master,
        None,
        "allowing the paired device leaves the requested slave grab intact",
    );

    let mut ungrab_body = Vec::with_capacity(8);
    ungrab_body.extend_from_slice(&0u32.to_le_bytes());
    ungrab_body.extend_from_slice(&pointer_id.to_le_bytes());
    ungrab_body.extend_from_slice(&[0u8; 2]);
    process_xi_dynamic_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT),
        SequenceNumber(3),
        52,
        &ungrab_body,
    );
    assert_eq!(
        state.xi_devices.device(pointer_id).unwrap().attached_master,
        Some(crate::xinput::DEVICEID_MASTER_POINTER),
        "ungrab restores the original master attachment"
    );
    assert!(!state.xi2_pointer_grabs.contains_key(&pointer_id));
    assert!(!state.xi2_detached_masters.contains_key(&pointer_id));
    assert!(!state.floating_pointer_positions.contains_key(&pointer_id));
    assert!(!state.xi1_frozen[&pointer_id].frozen());
    assert!(state.sync_pending.is_empty());
}

#[test]
fn xi_dynamic_grabs_disconnect_reattaches_only_the_owners_slave() {
    use crate::{
        backend::Backend,
        core_loop::{message::InputOrigin, pointer_fanout::pointer_event_fanout_to_state},
        host_x11::{HostPointerEvent, PointerEventKind},
    };

    const OWNER: u32 = 1;
    const OTHER_OWNER: u32 = 2;
    let mut state = ServerState::new();
    let _owner_peer = install_client(&mut state, OWNER);
    let _other_peer = install_client(&mut state, OTHER_OWNER);
    let mut backend = RecordingBackend::new();
    let (owner_source, owner_device) =
        xi_dynamic_grab_source(&mut state, 41, false, true, "disconnect-pointer");
    let (_other_source, other_device) =
        xi_dynamic_grab_source(&mut state, 42, false, true, "unrelated-pointer");
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 51,
        length_units: 7,
    };

    for (client, device, mode) in [(OWNER, owner_device, 0), (OTHER_OWNER, other_device, 1)] {
        handle_xi2_request(
            &mut state,
            &mut backend,
            None,
            ClientId(client),
            SequenceNumber(1),
            header,
            &xi_dynamic_grab_body(ROOT_WINDOW.0, device, mode),
        )
        .expect("XIGrabDevice before disconnect");
    }

    assert!(state.xi1_frozen[&owner_device].frozen());
    let xid_map = backend.xid_map().clone();
    let _ = pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &xid_map,
        HostPointerEvent {
            origin: InputOrigin::Physical(owner_source),
            kind: PointerEventKind::ButtonPress,
            host_xid: 0,
            detail: 1,
            time: 0x2233,
            root_x: 12,
            root_y: 13,
            event_x: 12,
            event_y: 13,
            state: 0,
            crossing_mode: 0,
            child: 0,
            raw_dx: 0,
            raw_dy: 0,
            tree_change: false,
        },
        true,
        false,
    );
    assert_eq!(state.sync_pending.len(), 1, "sync-grab event is queued");
    assert_eq!(
        state.xi_devices.device(owner_device).unwrap().buttons_down,
        1
    );

    crate::core_loop::process_disconnect::process_disconnect(
        &mut state,
        &mut backend,
        ClientId(OWNER),
    );

    assert!(!state.xi2_pointer_grabs.contains_key(&owner_device));
    assert_eq!(
        state
            .xi2_pointer_grabs
            .get(&other_device)
            .map(|grab| grab.owner),
        Some(ClientId(OTHER_OWNER)),
        "disconnect leaves the other client's independent grab intact"
    );
    assert_eq!(
        state
            .xi_devices
            .device(owner_device)
            .unwrap()
            .attached_master,
        Some(crate::xinput::DEVICEID_MASTER_POINTER)
    );
    assert_eq!(
        state
            .xi_devices
            .device(other_device)
            .unwrap()
            .attached_master,
        None,
        "the unrelated grabbed slave remains floating"
    );
    assert!(!state.xi2_detached_masters.contains_key(&owner_device));
    assert!(!state.floating_pointer_positions.contains_key(&owner_device));
    assert!(state.xi2_detached_masters.contains_key(&other_device));
    assert!(!state.xi1_frozen[&owner_device].frozen());
    assert!(state.xi1_frozen[&owner_device].stored.is_none());
    assert!(state.sync_pending.is_empty());
    assert_eq!(
        state.xi_devices.device(owner_device).unwrap().buttons_down,
        1,
        "disconnect releases the grab and queue, while the still-held physical button remains tracked"
    );
    assert!(state.active_pointer_grab.is_none());
}

/// On `XIGrabDevice` activation, Xorg synthesises an XI2 crossing
/// event (`XI_Enter`(7) for pointer / `XI_FocusIn`(9) for keyboard)
/// with `mode=NotifyGrab`(1) and `detail=NotifyNonlinear`(3) and
/// delivers it to the grab requester. Without these events, GTK3
/// popup state machines never engage their hover/click tracking —
/// the menu is visible but items don't highlight or activate.
/// Captured in `mate-xorg.xtrace` (Xi/exevents.c::ActivatePointer
/// Grab / ActivateKeyboardGrab). On `XIUngrabDevice` the symmetric
/// `mode=NotifyUngrab`(2) crossings fire.
#[test]
fn xi_grab_device_emits_grab_activation_crossings() {
    use std::io::Read;

    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0010_0060;
    const HOST_XID: u32 = 0x0040_0060;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: ROOT_WINDOW,
            x: 100,
            y: 200,
            width: 300,
            height: 200,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(WINDOW_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
    }
    let _ = state.resources.map_window(ResourceId(WINDOW_XID));

    // XIGrabDevice pointer.
    let mut body = Vec::with_capacity(24);
    body.extend_from_slice(&WINDOW_XID.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // time
    body.extend_from_slice(&0u32.to_le_bytes()); // cursor
    body.extend_from_slice(&2u16.to_le_bytes()); // deviceid
    body.extend_from_slice(&[1, 1, 1, 0]);
    body.extend_from_slice(&0u16.to_le_bytes()); // mask_len
    body.extend_from_slice(&[0u8; 2]);
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 51,
        length_units: 7,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("XIGrabDevice");

    // Drain wire and look for the synthesised XI2 Enter event:
    //   byte 0: 35 (GenericEvent)
    //   byte 1: 137 (XInputExtension major)
    //   bytes 8-9: evtype = 7 (XI_Enter)
    //   byte 18: mode = 1 (NotifyGrab)
    //   byte 19: detail = 0 (NotifyAncestor — sprite is the ancestor)
    peer.set_nonblocking(true).unwrap();
    let mut wire = Vec::new();
    let mut tmp = [0u8; 4096];
    loop {
        match peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => wire.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    // Wire contains both the 32-byte XIGrabDevice reply and the
    // synthesised XI2 GenericEvent (76 bytes). Order may vary —
    // scan for the GenericEvent signature: type=35, major=137,
    // evtype=7 (XI_Enter).
    let crossing_offset = (0..wire.len().saturating_sub(76))
        .find(|&i| {
            wire[i] == 35
                && wire[i + 1] == 137
                && u16::from_le_bytes([wire[i + 8], wire[i + 9]]) == 7
        })
        .unwrap_or_else(|| {
            panic!(
                "no XI_Enter GenericEvent found in {} wire bytes: {:?}",
                wire.len(),
                &wire[..wire.len().min(140)],
            )
        });
    let crossing = &wire[crossing_offset..crossing_offset + 76];
    // Crossing event byte layout (from encode_xi2_crossing_event):
    //   0:type=35, 1:major, 2..4:seq, 4..8:length, 8..10:evtype,
    //   10..12:deviceid, 12..16:time, 16..18:sourceid, 18:mode,
    //   19:detail, 20..24:root, 24..28:event, ...
    assert_eq!(crossing[18], 1, "mode = NotifyGrab");
    // The sprite (pointer at (0,0)) is in root, an ancestor of the
    // grab window — Xorg's `DeviceEnterLeaveEvents` IsParent(from,to)
    // branch emits `XI_Enter(NotifyAncestor)` on the grab window
    // (preceded by `XI_Leave(NotifyInferior)` on root). NotifyAncestor
    // = 0. (Pre-fix this was a hardcoded NotifyNonlinear = 3.)
    assert_eq!(crossing[19], 0, "detail = NotifyAncestor");
    let event_window = u32::from_le_bytes([crossing[24], crossing[25], crossing[26], crossing[27]]);
    assert_eq!(event_window, WINDOW_XID);

    // The activation chain also leaves the ancestor (root) the
    // sprite was in: an `XI_Leave(NotifyInferior)` precedes the Enter.
    let leave = (0..wire.len().saturating_sub(28)).find(|&i| {
        wire[i] == 35 && wire[i + 1] == 137 && u16::from_le_bytes([wire[i + 8], wire[i + 9]]) == 8
    });
    let leave = leave.expect("XI_Leave on the ancestor (root) must precede the Enter");
    let leave = &wire[leave..leave + 28];
    assert_eq!(leave[19], 2, "Leave detail = NotifyInferior");
    let leave_window = u32::from_le_bytes([leave[24], leave[25], leave[26], leave[27]]);
    assert_eq!(leave_window, ROOT_WINDOW.0, "Leave is on the root ancestor");
}

/// XIGrabDevice whose `grab_window` is the very window the pointer
/// already sits in must emit NO pointer crossing — Xorg's
/// `DoEnterLeaveEvents` early-returns when `fromWin == toWin`
/// (dix/enterleave.c). mutter/muffin grabs its own full-screen
/// clutter stage on every button press; the pre-fix code emitted an
/// unconditional `XI_Enter(NotifyGrab)` on the grab window, which
/// desynced cinnamon's XEmbed-systray click-forward state machine —
/// pamac's tray icon became unclickable (HW trace 2026-06-22). The
/// sprite is resolved from the live pointer position, matching the
/// production handler.
#[test]
fn xi_grab_device_self_grab_emits_no_crossing() {
    use std::io::Read;

    const CLIENT_ID: u32 = 1;
    // Window covering the pointer position (RecordingBackend's
    // query_pointer reports (0,0)), so it is the sprite window AND
    // the grab window.
    const STAGE_XID: u32 = 0x0010_0070;
    const HOST_XID: u32 = 0x0040_0070;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(STAGE_XID),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 2560,
            height: 1440,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(STAGE_XID))
            .expect("window installed");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));
    }
    let _ = state.resources.map_window(ResourceId(STAGE_XID));
    // Precondition: the pointer (0,0) really does resolve to the
    // grab window, otherwise the test would pass trivially.
    assert_eq!(
        state.root_pointer_target_at(0, 0).map(|h| h.0),
        Some(ResourceId(STAGE_XID)),
        "sprite must be the grab window for this fixture"
    );

    // XIGrabDevice pointer (device 2) on the stage window.
    let mut body = Vec::with_capacity(24);
    body.extend_from_slice(&STAGE_XID.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // time
    body.extend_from_slice(&0u32.to_le_bytes()); // cursor
    body.extend_from_slice(&2u16.to_le_bytes()); // deviceid
    body.extend_from_slice(&[1, 1, 1, 0]); // mode, paired, owner_events, pad
    body.extend_from_slice(&0u16.to_le_bytes()); // mask_len
    body.extend_from_slice(&[0u8; 2]);
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 51,
        length_units: 7,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("XIGrabDevice");

    peer.set_nonblocking(true).unwrap();
    let mut wire = Vec::new();
    let mut tmp = [0u8; 4096];
    loop {
        match peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => wire.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    // Scan for any XI2 GenericEvent that is an Enter (evtype 7) or
    // Leave (evtype 8) from the XInput extension (major 137). There
    // must be none — a self-grab is a no-op transition.
    let crossing = (0..wire.len().saturating_sub(10)).find(|&i| {
        wire[i] == 35
            && wire[i + 1] == 137
            && matches!(u16::from_le_bytes([wire[i + 8], wire[i + 9]]), 7 | 8)
    });
    assert!(
        crossing.is_none(),
        "self-grab must emit no XI_Enter/XI_Leave crossing; got {} wire bytes: {:?}",
        wire.len(),
        &wire[..wire.len().min(140)],
    );
}

/// A `SendEvent` with an empty `event_mask` is addressed to the
/// client that *created* the destination window (X11 SendEvent
/// semantics). That is the XEmbed input-forwarding contract: a
/// systray manager (cinnamon) forwards the synthetic core
/// ButtonPress of a user click on the tray icon to the embedded
/// client, which also holds an XI2 selection on the window; dropping
/// it left pamac's tray icon unclickable (HW air 2026-06-22).
#[test]
fn send_event_empty_mask_delivers_synthetic_button_to_owner_despite_xi2_selection() {
    use std::io::Read;

    const SENDER: u32 = 1; // cinnamon
    const OWNER: u32 = 2; // pamac
    const WIN: u32 = 0x0020_0001; // pamac's embedded icon window

    let mut state = ServerState::new();
    let _sender_peer = install_client(&mut state, SENDER);
    let mut owner_peer = install_client(&mut state, OWNER);

    // Window created by (owned by) the pamac client.
    state.resources.create_window(
        yserver_protocol::x11::ClientId(OWNER),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 24,
            height: 24,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    // pamac (GTK3) selects XI2 ButtonPress (bit 4) on its own window —
    // exactly what makes the guard fire.
    state
        .clients
        .get_mut(&OWNER)
        .unwrap()
        .xi2_masks
        .insert((ResourceId(WIN), 1), 1 << 4);

    // SendEvent: destination=WIN, event_mask=0, template = core
    // ButtonPress (type 4).
    let mut body = Vec::with_capacity(40);
    body.extend_from_slice(&WIN.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // empty event-mask
    let mut tmpl = [0u8; 32];
    tmpl[0] = 4; // ButtonPress
    body.extend_from_slice(&tmpl);
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 25,
        data: 0, // propagate = false
        length_units: 11,
    };
    handle_send_event(
        &mut state,
        ClientId(SENDER),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("SendEvent");

    owner_peer.set_nonblocking(true).unwrap();
    let mut wire = Vec::new();
    let mut tmp = [0u8; 256];
    loop {
        match owner_peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => wire.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    // The owner must receive the synthetic ButtonPress (type 4 with
    // the sent-event bit 0x80 set → 0x84).
    assert!(
        !wire.is_empty() && wire[0] == 0x84,
        "owner must receive the XEmbed-forwarded ButtonPress; got {} bytes: {:?}",
        wire.len(),
        &wire[..wire.len().min(40)],
    );
}

/// Windows for the `SendEvent` tests: W (owned by `owner`, child of the
/// root) and its child C, neither mapped, so the pointer sprite is the
/// root.
fn send_event_tree(state: &mut ServerState, owner: u32, w: u32, c: u32) {
    for (id, parent) in [(w, ROOT_WINDOW.0), (c, w)] {
        state.resources.create_window(
            yserver_protocol::x11::ClientId(owner),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(id),
                parent: ResourceId(parent),
                width: 100,
                height: 100,
                class: 1,
                visual: crate::resources::ROOT_VISUAL,
                ..Default::default()
            },
        );
    }
}

fn send_event_body(destination: u32, mask: u32, event_type: u8) -> Vec<u8> {
    let mut body = Vec::with_capacity(40);
    body.extend_from_slice(&destination.to_le_bytes());
    body.extend_from_slice(&mask.to_le_bytes());
    let mut tmpl = [0u8; 32];
    tmpl[0] = event_type;
    body.extend_from_slice(&tmpl);
    body
}

fn run_send_event(state: &mut ServerState, sender: u32, propagate: u8, body: &[u8]) {
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 25,
        data: propagate,
        length_units: 11,
    };
    handle_send_event(state, ClientId(sender), SequenceNumber(1), header, body).expect("SendEvent");
}

fn drain_wire(peer: &mut UnixStream) -> Vec<u8> {
    use std::io::Read;
    peer.set_nonblocking(true).unwrap();
    let mut wire = Vec::new();
    let mut tmp = [0u8; 256];
    while let Ok(n) = peer.read(&mut tmp) {
        if n == 0 {
            break;
        }
        wire.extend_from_slice(&tmp[..n]);
    }
    wire
}

/// The first byte of each 32-byte packet on the wire.
fn wire_types(wire: &[u8]) -> Vec<u8> {
    wire.chunks(32).map(|p| p[0]).collect()
}

/// #212: a synthetic core Motion/Press/Release reaches the client whose
/// CORE mask matches even when it also selected the XI2 form of the
/// event on the window (master or all-devices) and on the root. Xorg
/// `GetClientsForDelivery` (`dix/events.c:2241`) takes the core
/// `OtherClients` for a core type; XI2 masks never enter. Measured:
/// goldens/sendevent-xi2.txt, the "XI2 AllMasterDevices" steps.
#[test]
fn send_event_core_mask_delivers_despite_xi2_selection() {
    const SENDER: u32 = 1;
    const OWNER: u32 = 2;
    const W: u32 = 0x0020_0001;
    const C: u32 = 0x0020_0002;
    let mut state = ServerState::new();
    let mut sender_peer = install_client(&mut state, SENDER);
    let mut owner_peer = install_client(&mut state, OWNER);
    send_event_tree(&mut state, OWNER, W, C);
    let owner = state.clients.get_mut(&OWNER).unwrap();
    owner.event_masks.insert(ResourceId(W), 0x4C); // ButtonPress|Release|PointerMotion
    owner.xi2_masks.insert((ResourceId(W), 1), 0x70); // XI_ButtonPress|Release|Motion
    owner.xi2_masks.insert((ROOT_WINDOW, 0), 0x70);
    for (event_type, mask) in [(6u8, 0x40u32), (4, 0x0C), (5, 0x0C)] {
        run_send_event(&mut state, SENDER, 0, &send_event_body(W, mask, event_type));
    }
    assert_eq!(
        wire_types(&drain_wire(&mut owner_peer)),
        vec![0x86, 0x84, 0x85]
    );
    assert!(drain_wire(&mut sender_peer).is_empty());
}

/// Propagation (Xorg `ProcSendEvent`, `dix/events.c:5622-5636`): no
/// selector on C, so propagate=True carries the event to W; False stops
/// at C; C's do-not-propagate mask strips its bits, and an empty
/// remainder ends the walk. Measured: goldens/sendevent-xi2.txt.
#[test]
fn send_event_propagates_by_core_masks_and_do_not_propagate() {
    const SENDER: u32 = 1;
    const OWNER: u32 = 2;
    const W: u32 = 0x0020_0001;
    const C: u32 = 0x0020_0002;
    let mut state = ServerState::new();
    let _sender_peer = install_client(&mut state, SENDER);
    let mut owner_peer = install_client(&mut state, OWNER);
    send_event_tree(&mut state, OWNER, W, C);
    let owner = state.clients.get_mut(&OWNER).unwrap();
    owner.event_masks.insert(ResourceId(W), 0x0C); // ButtonPress|ButtonRelease
    owner.xi2_masks.insert((ResourceId(W), 1), 0x70);

    run_send_event(&mut state, SENDER, 0, &send_event_body(C, 0x04, 4));
    assert!(
        drain_wire(&mut owner_peer).is_empty(),
        "propagate False stops at C"
    );

    run_send_event(&mut state, SENDER, 1, &send_event_body(C, 0x04, 4));
    assert_eq!(wire_types(&drain_wire(&mut owner_peer)), vec![0x84]);

    state
        .resources
        .window_mut(ResourceId(C))
        .unwrap()
        .do_not_propagate_mask = 0x04;
    run_send_event(&mut state, SENDER, 1, &send_event_body(C, 0x04, 4));
    assert!(
        drain_wire(&mut owner_peer).is_empty(),
        "DNP strips the only bit"
    );
    // ButtonPress|ButtonRelease minus DNP ButtonPress still matches W.
    run_send_event(&mut state, SENDER, 1, &send_event_body(C, 0x0C, 4));
    assert_eq!(wire_types(&drain_wire(&mut owner_peer)), vec![0x84]);
}

/// InputFocus (`dix/events.c:5594-5611`): with the pointer outside the
/// focus window the walk starts AND ends at the focus window, so W's
/// selection is never reached from focus C; focus W gets it. Focus None
/// delivers nothing and raises no error. Measured:
/// goldens/sendevent-xi2.txt, the "focus" steps.
#[test]
fn send_event_input_focus_stops_at_the_focus_window() {
    const SENDER: u32 = 1;
    const OWNER: u32 = 2;
    const W: u32 = 0x0020_0001;
    const C: u32 = 0x0020_0002;
    let mut state = ServerState::new();
    let mut sender_peer = install_client(&mut state, SENDER);
    let mut owner_peer = install_client(&mut state, OWNER);
    send_event_tree(&mut state, OWNER, W, C);
    state
        .clients
        .get_mut(&OWNER)
        .unwrap()
        .event_masks
        .insert(ResourceId(W), 0x01); // KeyPress

    state.core_focus.raw = C;
    run_send_event(&mut state, SENDER, 1, &send_event_body(1, 0x01, 2));
    assert!(
        drain_wire(&mut owner_peer).is_empty(),
        "walk ends at focus C"
    );

    state.core_focus.raw = W;
    run_send_event(&mut state, SENDER, 1, &send_event_body(1, 0x01, 2));
    assert_eq!(wire_types(&drain_wire(&mut owner_peer)), vec![0x82]);

    state.core_focus.raw = 0;
    run_send_event(&mut state, SENDER, 1, &send_event_body(1, 0x01, 2));
    assert!(drain_wire(&mut owner_peer).is_empty());
    assert!(
        drain_wire(&mut sender_peer).is_empty(),
        "focus None is not an error"
    );
}

/// `ProcSendEvent` errors (`dix/events.c:5563-5619`), each measured on
/// Xorg (goldens/sendevent-xi2.txt): an unknown destination is
/// BadWindow; event types outside 2..=34 and 64.. (GenericEvent too),
/// a ClientMessage format other than 8/16/32, and mask bits above
/// `AllEventMasks` are BadValue carrying the offending value.
#[test]
fn send_event_rejects_like_xorg() {
    const SENDER: u32 = 1;
    const OWNER: u32 = 2;
    const W: u32 = 0x0020_0001;
    const C: u32 = 0x0020_0002;
    let mut state = ServerState::new();
    let mut sender_peer = install_client(&mut state, SENDER);
    let mut owner_peer = install_client(&mut state, OWNER);
    send_event_tree(&mut state, OWNER, W, C);
    let mut client_message = send_event_body(W, 0, 33);
    client_message[9] = 7;
    let cases: [(Vec<u8>, u8, u32); 6] = [
        (send_event_body(0x7fff_fff0, 0, 4), 3, 0x7fff_fff0),
        (send_event_body(W, 0x0200_0000, 4), 2, 0x0200_0000),
        (send_event_body(W, 0, 1), 2, 1),
        (send_event_body(W, 0, 35), 2, 35),
        (send_event_body(W, 0, 40), 2, 40),
        (client_message, 2, 7),
    ];
    for (body, code, value) in cases {
        run_send_event(&mut state, SENDER, 0, &body);
        let wire = drain_wire(&mut sender_peer);
        assert_eq!(wire.len(), 32, "one error for {body:?}");
        assert_eq!((wire[0], wire[1]), (0, code));
        assert_eq!(
            u32::from_le_bytes([wire[4], wire[5], wire[6], wire[7]]),
            value
        );
    }
    assert!(drain_wire(&mut owner_peer).is_empty());
}

/// `XIPassiveGrabDevice` with grab_type=Button(0) installs entries
/// in `state.button_grabs`; grab_type=Keycode(1) installs entries
/// in `state.key_grabs`. One entry per modifier (or one entry with
/// modifiers=0 when num_modifiers=0). `XIPassiveUngrabDevice`
/// removes matching entries.
#[test]
fn xi_passive_grab_device_pushes_button_and_key_grabs() {
    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0010_0051;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    // Helper to build XIPassiveGrabDevice body per
    // `xXIPassiveGrabDeviceReq` in X11/extensions/XI2proto.h:
    // time, grab_window, cursor, detail, deviceid, num_modifiers,
    // mask_len, grab_type, grab_mode, paired_device_mode,
    // owner_events, pad1, mask, modifiers.
    fn build_body(
        window: u32,
        detail: u32,
        device_id: u16,
        grab_type: u8,
        modifiers: &[u32],
    ) -> Vec<u8> {
        #[allow(clippy::cast_possible_truncation)]
        let num_modifiers = modifiers.len() as u16;
        let mut b = Vec::with_capacity(28 + modifiers.len() * 4);
        b.extend_from_slice(&0u32.to_le_bytes()); // time
        b.extend_from_slice(&window.to_le_bytes());
        b.extend_from_slice(&0u32.to_le_bytes()); // cursor
        b.extend_from_slice(&detail.to_le_bytes());
        b.extend_from_slice(&device_id.to_le_bytes());
        b.extend_from_slice(&num_modifiers.to_le_bytes());
        b.extend_from_slice(&0u16.to_le_bytes()); // mask_len
        b.push(grab_type);
        b.push(1); // grab_mode async
        b.push(1); // paired async
        b.push(0); // owner_events
        b.extend_from_slice(&0u16.to_le_bytes()); // pad1
        for m in modifiers {
            b.extend_from_slice(&m.to_le_bytes());
        }
        b
    }
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 54,
        // XIPassiveGrabDevice is AtLeast(8) and has no exact-length
        // gate (modifier count is read from the body's num_modifiers
        // field, not derived from the request length). 8 is the spec
        // minimum; was 6, which pre-dated the REQUEST_SIZE_MATCH gate
        // and now BadLengths before the handler runs.
        length_units: 8,
    };

    // Button grab on button 3 with modifiers [0, ControlMask(4)].
    let body = build_body(
        WINDOW_XID,
        3,
        crate::xinput::DEVICEID_MASTER_POINTER,
        0,
        &[0, 4],
    );
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("button grab");
    assert_eq!(state.button_grabs.len(), 2, "one grab per modifier");
    assert!(
        state
            .button_grabs
            .iter()
            .any(|g| g.button == 3 && g.modifiers == 0)
    );
    assert!(
        state
            .button_grabs
            .iter()
            .any(|g| g.button == 3 && g.modifiers == 4)
    );

    // Key grab on keycode 67 (F1) with no modifiers → single entry
    // with modifier-mask 0.
    let body = build_body(
        WINDOW_XID,
        67,
        crate::xinput::DEVICEID_MASTER_KEYBOARD,
        1,
        &[],
    );
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(2),
        header,
        &body,
    )
    .expect("key grab");
    assert_eq!(state.key_grabs.len(), 1);
    assert_eq!(state.key_grabs[0].keycode, 67);
    assert_eq!(state.key_grabs[0].modifiers, 0);

    // XI2 "Any" modifier (bit 31) → core X11 AnyModifier (0x8000).
    let body = build_body(
        WINDOW_XID,
        1,
        crate::xinput::DEVICEID_MASTER_POINTER,
        0,
        &[0x8000_0000],
    );
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(3),
        header,
        &body,
    )
    .expect("any-modifier grab");
    assert!(
        state
            .button_grabs
            .iter()
            .any(|g| g.button == 1 && g.modifiers == 0x8000),
        "XI2 Any (bit 31) maps to core X11 AnyModifier 0x8000",
    );

    // XIPassiveUngrabDevice — body: window(4) detail(4) deviceid(2)
    // num_modifiers(2) grab_type(1) pad(3) modifiers.
    fn build_ungrab_body(
        window: u32,
        detail: u32,
        device_id: u16,
        grab_type: u8,
        modifiers: &[u32],
    ) -> Vec<u8> {
        #[allow(clippy::cast_possible_truncation)]
        let num_modifiers = modifiers.len() as u16;
        let mut b = Vec::with_capacity(16 + modifiers.len() * 4);
        b.extend_from_slice(&window.to_le_bytes());
        b.extend_from_slice(&detail.to_le_bytes());
        b.extend_from_slice(&device_id.to_le_bytes());
        b.extend_from_slice(&num_modifiers.to_le_bytes());
        b.push(grab_type);
        b.extend_from_slice(&[0u8; 3]);
        for m in modifiers {
            b.extend_from_slice(&m.to_le_bytes());
        }
        b
    }
    let ungrab_header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 55,
        // XIPassiveUngrabDevice is AtLeast(5), no exact gate. 5 is the
        // spec minimum; was 4 (pre-gate placeholder → BadLength now).
        length_units: 5,
    };
    let body = build_ungrab_body(
        WINDOW_XID,
        3,
        crate::xinput::DEVICEID_MASTER_POINTER,
        0,
        &[0, 4],
    );
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(4),
        ungrab_header,
        &body,
    )
    .expect("button ungrab");
    assert!(
        !state
            .button_grabs
            .iter()
            .any(|g| g.button == 3 && (g.modifiers == 0 || g.modifiers == 4)),
        "ungrab removes the matching button+modifier entries",
    );
    // AnyModifier grab still present (we didn't ungrab it).
    assert!(
        state
            .button_grabs
            .iter()
            .any(|g| g.button == 1 && g.modifiers == 0x8000)
    );
}

/// Regression test for the XIPassiveGrabDevice field-offset bug.
/// `mask_len` and `grab_type` were swapped: a real client (muffin,
/// xfwm4) sending mask_len=2 + grab_type=Keycode(1) was mis-parsed
/// as grab_type=Enter(2), silently dropping every keyboard
/// accelerator. The body here matches `xXIPassiveGrabDeviceReq`
/// in `X11/extensions/XI2proto.h` byte-for-byte with mask_len=2,
/// which is what real WM clients send.
#[test]
fn xi_passive_grab_device_keycode_with_xi2_mask() {
    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0010_0051;
    const KEYCODE: u32 = 116;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    // Spec-shaped body with mask_len=2 (two 4-byte mask words,
    // matching what muffin emits for XI device-event masks).
    let mut body = Vec::with_capacity(28 + 8 + 4);
    body.extend_from_slice(&0u32.to_le_bytes()); // time
    body.extend_from_slice(&WINDOW_XID.to_le_bytes()); // grab_window
    body.extend_from_slice(&0u32.to_le_bytes()); // cursor
    body.extend_from_slice(&KEYCODE.to_le_bytes()); // detail
    body.extend_from_slice(&3u16.to_le_bytes()); // deviceid (keyboard)
    body.extend_from_slice(&1u16.to_le_bytes()); // num_modifiers
    body.extend_from_slice(&2u16.to_le_bytes()); // mask_len = 2
    body.push(1); // grab_type = Keycode
    body.push(1); // grab_mode async
    body.push(1); // paired async
    body.push(0); // owner_events
    body.extend_from_slice(&0u16.to_le_bytes()); // pad1
    body.extend_from_slice(&[0u8; 8]); // mask (2 words)
    body.extend_from_slice(&0u32.to_le_bytes()); // modifier 0

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 54,
        length_units: 10,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("keycode grab with mask");

    assert_eq!(
        state.key_grabs.len(),
        1,
        "Keycode grab must be recorded — bug was misclassifying \
             as grab_type=Enter due to swapped mask_len/grab_type"
    );
    #[allow(clippy::cast_possible_truncation)]
    let expected_kc = KEYCODE as u8;
    assert_eq!(state.key_grabs[0].keycode, expected_kc);
    assert_eq!(state.key_grabs[0].modifiers, 0);
    assert!(state.button_grabs.is_empty());
}

/// `XIAllowEvents` with `mode=AsyncDevice(0)` releases the
/// passive grab on the calling client's device, matching what
/// mutter/cinnamon shell call after their click-to-focus button
/// grab activates. Before this handler shipped, the call was a
/// debug-logged stub so `state.pointer_grab` stayed pinned until
/// the next ButtonRelease, leaking the grab across intermediate
/// motion events.
#[test]
fn xi_allow_events_async_device_releases_passive_pointer_grab() {
    const CLIENT_ID: u32 = 1;
    const GRAB_WIN: u32 = 0x0010_0051;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    // Seed a SYNC passive grab that has activated: the grab is held,
    // the device frozen, and the activating press stored — exactly the
    // state the pointer-fanout Step-3 path leaves after a matched click.
    set_test_pointer_grab(&mut state, CLIENT_ID, GRAB_WIN, true, false);
    state.xi1_frozen.insert(
        crate::xinput::DEVICEID_MASTER_POINTER,
        crate::server::Xi1Freeze {
            state: crate::server::Xi1SyncState::FrozenNoEvent,
            ..Default::default()
        },
    );

    // Body per `xXIAllowEventsReq`: time(4) + deviceid(2) +
    // mode(1) + pad(1). deviceid=2 (master pointer), mode=0
    // (AsyncDevice).
    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&0u32.to_le_bytes()); // time
    body.extend_from_slice(&2u16.to_le_bytes()); // deviceid
    body.push(0); // mode = AsyncDevice
    body.push(0); // pad

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 53,
        length_units: 3,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("allow events");

    // AsyncDevice thaws the frozen pointer so events flow again (Xorg
    // AsyncPointer). Per Xorg the passive grab itself persists until the
    // button is released — what matters is the device is no longer
    // frozen (the freeze gate would otherwise queue every later event).
    assert!(
        !state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_POINTER)
            .is_some_and(crate::server::Xi1Freeze::frozen),
        "AsyncDevice must thaw the frozen pointer device"
    );
}

#[test]
fn xi_allow_events_replay_device_replays_frozen_button_press_to_target() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
    };

    const GRAB_CLIENT_ID: u32 = 1;
    const TARGET_CLIENT_ID: u32 = 2;
    const GRAB_WIN: u32 = 0x0010_0051;
    const TARGET_WIN: u32 = 0x0020_0052;
    const HOST_XID: u32 = 0xCAFE_0001;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut target_peer = install_client(&mut state, TARGET_CLIENT_ID);
    let mut backend = RecordingBackend::new();
    grab_peer
        .set_nonblocking(true)
        .expect("grab peer nonblocking");
    target_peer
        .set_nonblocking(true)
        .expect("target peer nonblocking");

    state.resources.create_window(
        ClientId(GRAB_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(GRAB_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    state.resources.create_window(
        ClientId(TARGET_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(TARGET_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(GRAB_WIN));
    let _ = state.resources.map_window(ResourceId(TARGET_WIN));
    state
        .clients
        .get_mut(&TARGET_CLIENT_ID)
        .expect("target client")
        .event_masks
        .insert(ResourceId(TARGET_WIN), 0x0000_0004);

    set_test_pointer_grab(&mut state, GRAB_CLIENT_ID, GRAB_WIN, true, false);
    {
        let f = state
            .xi1_frozen
            .entry(crate::xinput::DEVICEID_MASTER_POINTER)
            .or_default();
        f.state = crate::server::Xi1SyncState::FrozenWithEvent;
        f.stored = Some(crate::server::QueuedInputEvent::HostPointer(
            HostPointerEvent {
                origin: crate::core_loop::message::InputOrigin::XTest(4),
                kind: PointerEventKind::ButtonPress,
                host_xid: HOST_XID,
                detail: 1,
                time: 0,
                root_x: 10,
                root_y: 10,
                event_x: 10,
                event_y: 10,
                state: 0,
                crossing_mode: 0,
                child: 0,
                raw_dx: 0,
                raw_dy: 0,
                tree_change: false,
            },
        ));
    }
    Backend::register_top_level(&mut backend, None, ResourceId(TARGET_WIN), HOST_XID)
        .expect("register host xid");

    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&0u32.to_le_bytes()); // time
    body.extend_from_slice(&2u16.to_le_bytes()); // deviceid
    body.push(2); // mode = ReplayDevice
    body.push(0); // pad

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 53,
        length_units: 3,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("allow events");

    assert_eq!(
        state
            .active_pointer_grab
            .map(|grab| (grab.owner, grab.grab_window)),
        Some((ClientId(TARGET_CLIENT_ID), ResourceId(TARGET_WIN))),
        "the replayed press must install the implicit grab on the natural \
             recipient (#94 — Xorg ActivateImplicitGrab on the replayed delivery)"
    );
    assert!(
        state
            .active_pointer_grab
            .is_some_and(|g| g.implicit && !g.via_xi2),
        "replayed core press installs a core-form implicit grab"
    );
    assert!(
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_POINTER)
            .and_then(|f| f.stored.as_ref())
            .is_none()
    );

    let mut buf = [0u8; 32];
    let grab_read = grab_peer.read(&mut buf);
    assert!(
        matches!(grab_read, Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock),
        "grab owner must not receive replayed ButtonPress; got {grab_read:?}",
    );
    let target_read = target_peer.read(&mut buf);
    assert!(
        matches!(target_read, Ok(32)),
        "target window subscriber should receive replayed ButtonPress; got {target_read:?}",
    );
    assert_eq!(buf[0], 4, "event type should be ButtonPress");
    assert_eq!(&buf[12..16], &TARGET_WIN.to_le_bytes());
}

/// Regression for the MATE submenu-hover bug. mate-panel holds an
/// active XI2 grab on its main panel window with `owner_events=true`;
/// menu items it pops up are top-level override-redirect windows
/// OWNED BY mate-panel (siblings of the grab window, not
/// descendants). Pre-fix the active-grab-redirect check used pure
/// topology (`target == grab_window || is_descendant_of`),
/// which redirected motion on the menu items to the grab window
/// with grab-relative coords — GTK couldn't track which menu item
/// the cursor was over, hover-delay never fired the submenu.
/// The fix adds an ownership-aware path: window owned by the grab
/// client qualifies for natural delivery alongside descendants.
/// Note: this is a heuristic — the fully spec-correct rule is "the
/// event would normally be reported to the grab client" (a mask-
/// subscription check). Ownership is a close proxy: clients almost
/// always select events on windows they own.
#[test]
fn active_grab_owner_events_natural_delivery_to_sibling_window_owned_by_grab_client() {
    use crate::{
        backend::Backend,
        core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
        server::ActivePointerGrab,
    };

    const GRAB_CLIENT_ID: u32 = 1;
    const GRAB_WIN: u32 = 0x0010_0070;
    const SIBLING_WIN: u32 = 0x0010_0071; // top-level, owned by same client, not descendant of grab window
    const HOST_GRAB_XID: u32 = 0xCAFE_0070;
    const HOST_SIBLING_XID: u32 = 0xCAFE_0071;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut backend = RecordingBackend::new();
    peer.set_nonblocking(true).expect("nonblocking");

    // Create two top-level windows under root, both owned by the
    // grab client. They are siblings (both children of root), not
    // in an ancestor relationship — the exact topology for
    // mate-panel + popup-menu.
    for (xid, host_xid) in [(GRAB_WIN, HOST_GRAB_XID), (SIBLING_WIN, HOST_SIBLING_XID)] {
        state.resources.create_window(
            ClientId(GRAB_CLIENT_ID),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(xid),
                parent: ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(ResourceId(xid));
        Backend::register_top_level(&mut backend, None, ResourceId(xid), host_xid)
            .expect("register host xid");
    }
    // XI2 mask selecting motion on the sibling window (the menu
    // item the cursor will move over). XI_Motion evtype = 6 →
    // mask bit 1<<6 = 0x40.
    state
        .clients
        .get_mut(&GRAB_CLIENT_ID)
        .expect("client")
        .xi2_masks
        .insert((ResourceId(SIBLING_WIN), 2), 0x40);

    // Install active grab on GRAB_WIN with owner_events=true.
    state.active_pointer_grab = Some(ActivePointerGrab {
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ResourceId(GRAB_WIN),
        event_mask: 0,
        cursor: ResourceId(0),
        time: 0,
        owner_events: true,
        via_xi2: true,
        implicit: false,
        passive: false,
        xi2_mask: u64::MAX,
    });
    // Sanity: sibling is NOT a descendant of grab window.
    assert!(
        !state
            .resources
            .is_descendant_of(ResourceId(SIBLING_WIN), ResourceId(GRAB_WIN))
    );
    // And IS owned by the grab client.
    assert_eq!(
        state.resources.window_owner(ResourceId(SIBLING_WIN)),
        Some(ClientId(GRAB_CLIENT_ID)),
    );

    // Cursor at root_x=50, root_y=50 — landing on SIBLING_WIN.
    // host_xid = SIBLING's host xid so the v2-style hit-test lands
    // on the sibling window naturally.
    let motion = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::MotionNotify,
        host_xid: HOST_SIBLING_XID,
        detail: 0,
        time: 0x1000,
        root_x: 50,
        root_y: 50,
        event_x: 50,
        event_y: 50,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let xid_map = backend.xid_map().clone();
    let _ = pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, motion, true, false);

    // Read whatever landed on the wire. With the ownership-aware
    // natural-delivery check, the XI2 motion must report against
    // the sibling window (event=SIBLING_WIN) with sensible coords
    // (event_x ≈ 50), NOT redirected to the grab window with
    // grab-relative coords. Pre-fix the event would be on
    // GRAB_WIN with grab-clamped coords — for this layout
    // (sibling at the same root origin) the difference might be
    // subtle in coords but the `event` window XID is the
    // smoking-gun: GRAB vs SIBLING.
    let mut buf = [0u8; 256];
    let n = peer.read(&mut buf).expect("client got at least one event");
    assert!(n >= 32, "expected at least one event, got {n} bytes");
    // Scan for a Generic XI2 event (type=35, second byte=major opcode of XInputExtension).
    // We just need to find the `event` window XID in the body.
    let mut found_sibling = false;
    let mut found_grab = false;
    let mut i = 0;
    while i + 32 <= n {
        // Generic event byte 0 is type. XI2 Motion event window
        // sits at a known offset; rather than parsing the full
        // event structure, scan for either window XID in the
        // first 64 bytes of the body. Cheap+robust.
        let slice = &buf[i..(i + 64).min(n)];
        if slice.windows(4).any(|w| w == SIBLING_WIN.to_le_bytes()) {
            found_sibling = true;
        }
        if slice.windows(4).any(|w| w == GRAB_WIN.to_le_bytes()) {
            found_grab = true;
        }
        i += 32;
    }
    assert!(
        found_sibling,
        "XI2 motion must address the sibling window (owner=grab client) under owner_events=true; got buf bytes {:?}",
        &buf[..n.min(64)],
    );
    // The grab window XID may also appear (e.g., in root/sourceid
    // fields by coincidence) so we don't assert !found_grab — the
    // load-bearing assertion is that the natural target window
    // shows up in the body.
    let _ = found_grab;
}

/// Regression for the MATE menu-click bug: when a release was
/// queued during a sync passive grab freeze (because the WM hadn't
/// yet called AllowEvents), the replay path MUST drain both the
/// frozen press AND the queued release to the natural target — in
/// that order. Pre-fix the release leaked through during freeze
/// and the press was never replayed (frozen state cleared by the
/// rogue release path), so the app saw release-then-nothing.
#[test]
fn xi_allow_events_replay_device_drains_queued_release_after_press() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
    };

    const GRAB_CLIENT_ID: u32 = 1;
    const TARGET_CLIENT_ID: u32 = 2;
    const GRAB_WIN: u32 = 0x0010_0061;
    const TARGET_WIN: u32 = 0x0020_0062;
    const HOST_XID: u32 = 0xCAFE_0010;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut target_peer = install_client(&mut state, TARGET_CLIENT_ID);
    let mut backend = RecordingBackend::new();
    grab_peer
        .set_nonblocking(true)
        .expect("grab peer nonblocking");
    target_peer
        .set_nonblocking(true)
        .expect("target peer nonblocking");

    state.resources.create_window(
        ClientId(GRAB_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(GRAB_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    state.resources.create_window(
        ClientId(TARGET_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(TARGET_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(GRAB_WIN));
    let _ = state.resources.map_window(ResourceId(TARGET_WIN));
    // Target client selects ButtonPress | ButtonRelease.
    state
        .clients
        .get_mut(&TARGET_CLIENT_ID)
        .expect("target client")
        .event_masks
        .insert(ResourceId(TARGET_WIN), 0x0000_000c);

    set_test_pointer_grab(&mut state, GRAB_CLIENT_ID, GRAB_WIN, true, false);
    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_XID,
        detail: 1,
        time: 0x1c33,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    {
        let f = state
            .xi1_frozen
            .entry(crate::xinput::DEVICEID_MASTER_POINTER)
            .or_default();
        f.state = crate::server::Xi1SyncState::FrozenWithEvent;
        f.stored = Some(crate::server::QueuedInputEvent::HostPointer(press));
    }
    // Queue a release that arrived while frozen.
    let release = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonRelease,
        time: 0x1c89,
        ..press
    };
    state
        .sync_pending
        .push_back(crate::server::PendingSyncEvent {
            device: crate::xinput::DEVICEID_MASTER_POINTER,
            event: crate::server::QueuedInputEvent::HostPointer(release),
        });
    Backend::register_top_level(&mut backend, None, ResourceId(TARGET_WIN), HOST_XID)
        .expect("register host xid");

    // XIAllowEvents ReplayDevice on master pointer (deviceid=2).
    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&0u32.to_le_bytes());
    body.extend_from_slice(&2u16.to_le_bytes());
    body.push(2); // mode = ReplayDevice
    body.push(0); // pad
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 53,
        length_units: 3,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("allow events");

    // Both frozen slots cleared after drain.
    assert!(
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_POINTER)
            .and_then(|f| f.stored.as_ref())
            .is_none()
    );
    assert!(
        !state
            .sync_pending
            .iter()
            .any(|p| p.device == crate::xinput::DEVICEID_MASTER_POINTER)
    );
    assert!(state.active_pointer_grab.is_none());
    assert_eq!(
        state.buttons_down, 0,
        "replayed press and queued release leave the master clear"
    );
    assert_eq!(
        state.xi_devices.device(4).unwrap().buttons_down,
        0,
        "replayed press and queued release leave XTEST 4 clear"
    );

    // Grab owner must not receive the replayed events (they go to
    // the natural target).
    let mut buf = [0u8; 32];
    let grab_read = grab_peer.read(&mut buf);
    assert!(
        matches!(grab_read, Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock),
        "grab owner must not receive replay; got {grab_read:?}",
    );

    // Target must receive BOTH events in order. Read a sequence of
    // 32-byte core events, expecting Press(type=4) then
    // Release(type=5). The XI2 fanout would also fire (each event
    // shipping a GenericEvent), so we read until we've seen one
    // press and one release.
    let mut saw_press = false;
    let mut saw_release = false;
    let mut press_offset = usize::MAX;
    let mut release_offset = usize::MAX;
    let mut total_read = 0usize;
    // Slurp whatever the wire has — bound the read loop to avoid
    // hanging if something goes wrong.
    for iter in 0..8 {
        let mut chunk = [0u8; 256];
        match target_peer.read(&mut chunk) {
            Ok(0) => break,
            Ok(n) => {
                // Scan 32-byte boundaries for core ButtonPress(4)
                // / ButtonRelease(5). GenericEvents (XI2) are
                // type=35 and longer; their first byte still
                // shows up at a 32-byte offset.
                let mut i = 0;
                while i + 32 <= n {
                    let evt_type = chunk[i] & 0x7F;
                    if evt_type == 4 && !saw_press {
                        saw_press = true;
                        press_offset = total_read + i;
                    } else if evt_type == 5 && !saw_release {
                        saw_release = true;
                        release_offset = total_read + i;
                    }
                    // GenericEvent is variable-length; advance by 32 conservatively.
                    i += 32;
                }
                total_read += n;
                if saw_press && saw_release {
                    break;
                }
            }
            Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(e) => panic!("target read failed at iter {iter}: {e}"),
        }
    }
    assert!(saw_press, "target must receive replayed ButtonPress");
    assert!(saw_release, "target must receive queued ButtonRelease");
    assert!(
        press_offset < release_offset,
        "Press must arrive BEFORE Release at the target (got press@{press_offset}, release@{release_offset})",
    );
}

/// Regression: XI2 `XIAllowEvents(AsyncDevice)` must thaw the unified
/// per-device freeze AND replay the events withheld during the freeze.
/// muffin (Cinnamon) installs XI2 sync passive button grabs; activating
/// one engages `xi1_frozen[POINTER]` via `xi1_check_grab_for_syncs`,
/// after which the unified-freeze gate queues every core pointer event.
/// The XI2 AllowEvents handler historically never touched `xi1_frozen`,
/// so `AsyncDevice` left the pointer frozen forever and dropped the
/// withheld queue — the Cinnamon desktop never saw the drag's
/// ButtonRelease, leaving the selection rubber-band stuck. (Core grabs
/// — marco/xfwm4 — thaw via the core AllowEvents path, so MATE/XFCE
/// were unaffected.)
#[test]
fn xi_allow_events_async_device_thaws_freeze_and_replays_queue() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
        server::{Xi1Freeze, Xi1SyncState},
    };

    const GRAB_CLIENT_ID: u32 = 1;
    const TARGET_CLIENT_ID: u32 = 2;
    const GRAB_WIN: u32 = 0x0010_0061;
    const TARGET_WIN: u32 = 0x0020_0062;
    const HOST_XID: u32 = 0xCAFE_0005;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut target_peer = install_client(&mut state, TARGET_CLIENT_ID);
    let mut backend = RecordingBackend::new();
    grab_peer
        .set_nonblocking(true)
        .expect("grab peer nonblocking");
    target_peer
        .set_nonblocking(true)
        .expect("target peer nonblocking");

    for (client, win) in [(GRAB_CLIENT_ID, GRAB_WIN), (TARGET_CLIENT_ID, TARGET_WIN)] {
        state.resources.create_window(
            ClientId(client),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(win),
                parent: ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(ResourceId(win));
    }
    // Target selects ButtonPress | ButtonRelease.
    state
        .clients
        .get_mut(&TARGET_CLIENT_ID)
        .expect("target client")
        .event_masks
        .insert(ResourceId(TARGET_WIN), 0x0000_000c);

    // muffin's sync passive grab has activated: grab held, the
    // activating press already delivered to the owner, the pointer
    // device frozen, and a release queued during the freeze.
    set_test_pointer_grab(&mut state, GRAB_CLIENT_ID, GRAB_WIN, true, false);
    // The activated passive grab's defining record (present for any
    // real activation) — its mask is what the drain-path redirect
    // reports to the grab owner.
    state.button_grabs.push(crate::server::PassiveButtonGrab {
        device_id: 0,
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ResourceId(GRAB_WIN),
        button: 1,
        modifiers: 0x8000,
        owner_events: false,
        event_mask: 0x0000_000c, // press|release
        pointer_mode: 0,         // sync
        keyboard_mode: 1,
        confine_to: ResourceId(0),
        via_xi2: false,
    });
    state.xi1_frozen.insert(
        crate::xinput::DEVICEID_MASTER_POINTER,
        Xi1Freeze {
            state: Xi1SyncState::FrozenNoEvent,
            ..Default::default()
        },
    );
    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_XID,
        detail: 1,
        time: 0x2a00,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    {
        let f = state
            .xi1_frozen
            .entry(crate::xinput::DEVICEID_MASTER_POINTER)
            .or_default();
        f.state = crate::server::Xi1SyncState::FrozenWithEvent;
        f.stored = Some(crate::server::QueuedInputEvent::HostPointer(press));
    }
    state
        .sync_pending
        .push_back(crate::server::PendingSyncEvent {
            device: crate::xinput::DEVICEID_MASTER_POINTER,
            event: crate::server::QueuedInputEvent::HostPointer(HostPointerEvent {
                origin: crate::core_loop::message::InputOrigin::XTest(4),
                kind: PointerEventKind::ButtonRelease,
                time: 0x2a50,
                ..press
            }),
        });
    Backend::register_top_level(&mut backend, None, ResourceId(TARGET_WIN), HOST_XID)
        .expect("register host xid");

    // XIAllowEvents AsyncDevice on master pointer (deviceid=2).
    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&0u32.to_le_bytes()); // time
    body.extend_from_slice(&2u16.to_le_bytes()); // deviceid
    body.push(0); // mode = AsyncDevice
    body.push(0); // pad
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 53,
        length_units: 3,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("allow events");

    // The unified pointer freeze must be thawed — otherwise every
    // later core pointer event is queued-then-dropped (dead pointer).
    assert!(
        !state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_POINTER)
            .is_some_and(crate::server::Xi1Freeze::frozen),
        "AsyncDevice must thaw the unified per-device pointer freeze"
    );
    assert!(
        state.active_pointer_grab.is_none(),
        "passive grab ended by the terminating (replayed) release, not by AsyncDevice"
    );
    assert!(
        !state
            .sync_pending
            .iter()
            .any(|p| p.device == crate::xinput::DEVICEID_MASTER_POINTER),
        "withheld queue must be replayed, not left pending"
    );

    // AsyncDevice thaws WITHOUT deactivating the grab (Xorg AllowSome
    // THAWED, dix/events.c:1857 — DeactivateGrab is the NOT_GRABBED
    // /Replay case only). So the withheld release replays THROUGH the
    // grab (ComputeFreezes → PlayReleasedEvents → DeliverGrabbedEvent):
    // it is reported to the GRAB OWNER on the grab window, then the
    // terminating release ends the passive grab. It must NOT leak to
    // the foreign natural target (pre-implicit-grab #94 bug).
    assert!(
        peer_saw_event(&mut grab_peer, 5, None),
        "withheld ButtonRelease must replay THROUGH the grab to its owner \
             on AsyncDevice thaw"
    );
    assert!(
        !peer_saw_event(&mut target_peer, 5, None),
        "the grab intercepts the release — it must not leak to the foreign \
             natural target (#94)"
    );
}

/// Helper: drain a nonblocking peer and return true if any 32-byte core
/// event with `type & 0x7f == want_type` (and, if `want_detail` is Some,
/// matching `detail` byte) was delivered.
fn peer_saw_event(peer: &mut UnixStream, want_type: u8, want_detail: Option<u8>) -> bool {
    for _ in 0..8 {
        let mut chunk = [0u8; 512];
        match peer.read(&mut chunk) {
            Ok(0) => return false,
            Ok(n) => {
                let mut i = 0;
                while i + 32 <= n {
                    if chunk[i] & 0x7F == want_type && want_detail.is_none_or(|d| chunk[i + 1] == d)
                    {
                        return true;
                    }
                    i += 32;
                }
            }
            Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => return false,
            Err(e) => panic!("peer read failed: {e}"),
        }
    }
    false
}

/// ISSUE 1 (known-issues.md 2026-07-15): `AllowEvents` admission keys ONLY
/// on the unified per-device sync state (Xorg `AllowSome`,
/// dix/events.c:1851). When the device is thawed in unified state, a
/// `ReplayDevice` from the grabbing client is a no-op — nothing is
/// replayed — regardless of any residual/legacy activating event.
#[test]
fn xi_allow_events_replay_no_op_when_unified_thawed() {
    use crate::{
        resources::ROOT_VISUAL,
        server::{Xi1Freeze, Xi1SyncState},
    };
    const GRAB_CLIENT_ID: u32 = 1;
    const GRAB_WIN: u32 = 0x0010_0101;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    grab_peer.set_nonblocking(true).expect("nonblocking");
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        ClientId(GRAB_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(GRAB_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(GRAB_WIN));
    state
        .clients
        .get_mut(&GRAB_CLIENT_ID)
        .expect("grab client")
        .event_masks
        .insert(ResourceId(GRAB_WIN), 0x0000_000c); // ButtonPress|ButtonRelease

    set_test_pointer_grab(&mut state, GRAB_CLIENT_ID, GRAB_WIN, true, false);
    // Unified state THAWED — the sole admission authority says "not frozen".
    state.xi1_frozen.insert(
        crate::xinput::DEVICEID_XTEST_POINTER,
        Xi1Freeze {
            state: Xi1SyncState::Thawed,
            ..Default::default()
        },
    );

    // XIAllowEvents XIReplayDevice (mode 2) on master pointer (deviceid=2).
    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&0u32.to_le_bytes()); // CurrentTime
    body.extend_from_slice(&2u16.to_le_bytes()); // deviceid
    body.push(2); // XIReplayDevice
    body.push(0);
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 53,
        length_units: 3,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("allow events");

    assert!(
        !peer_saw_event(&mut grab_peer, 4, None) && !peer_saw_event(&mut grab_peer, 5, None),
        "ReplayDevice on a unified-thawed device must be a no-op (no stale replay)"
    );
}

/// ISSUE 2 (known-issues.md 2026-07-15): a thaw via a path OTHER than
/// AllowEvents must still replay the withheld queue (Xorg ComputeFreezes ->
/// PlayReleasedEvents, dix/events.c:1368-1372), not drop it. Drives the
/// production representation (`sync_pending`) that the freeze gate fills.
#[test]
fn out_of_band_pointer_thaw_replays_withheld_release() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
        server::{PendingSyncEvent, QueuedInputEvent, Xi1Freeze, Xi1SyncState},
    };
    const GRAB_CLIENT_ID: u32 = 1;
    const GRAB_WIN: u32 = 0x0010_0111;
    const HOST_XID: u32 = 0xCAFE_0011;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    grab_peer.set_nonblocking(true).expect("nonblocking");
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        ClientId(GRAB_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(GRAB_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(GRAB_WIN));
    state
        .clients
        .get_mut(&GRAB_CLIENT_ID)
        .expect("grab client")
        .event_masks
        .insert(ResourceId(GRAB_WIN), 0x0000_000c);
    Backend::register_top_level(&mut backend, None, ResourceId(GRAB_WIN), HOST_XID)
        .expect("register host xid");

    set_test_pointer_grab(&mut state, GRAB_CLIENT_ID, GRAB_WIN, true, false);
    // A real activated passive grab always has its defining
    // `button_grabs` record present; the drain-path redirect reads its
    // `event_mask` to know what to report to the grab owner (Xorg
    // DeliverGrabbedEvent consults the grab's own mask). Without it the
    // grab captures the release but reports nothing.
    state.button_grabs.push(crate::server::PassiveButtonGrab {
        device_id: 0,
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ResourceId(GRAB_WIN),
        button: 1,
        modifiers: 0x8000,
        owner_events: false,
        event_mask: 0x0000_000c, // press|release
        pointer_mode: 0,         // sync
        keyboard_mode: 1,
        confine_to: ResourceId(0),
        via_xi2: false,
    });
    state.xi1_frozen.insert(
        crate::xinput::DEVICEID_XTEST_POINTER,
        Xi1Freeze {
            state: Xi1SyncState::FrozenNoEvent,
            ..Default::default()
        },
    );
    // A release withheld during the freeze, in the global queue (what the
    // production QUEUE-WHILE-FROZEN gate pushes).
    state.sync_pending.push_back(PendingSyncEvent {
        device: crate::xinput::DEVICEID_XTEST_POINTER,
        event: QueuedInputEvent::HostPointer(HostPointerEvent {
            origin: crate::core_loop::message::InputOrigin::XTest(4),
            kind: PointerEventKind::ButtonRelease,
            host_xid: HOST_XID,
            detail: 1,
            time: 0x2a50,
            root_x: 10,
            root_y: 10,
            event_x: 10,
            event_y: 10,
            state: 0,
            crossing_mode: 0,
            child: 0,
            raw_dx: 0,
            raw_dy: 0,
            tree_change: false,
        }),
    });

    // OUT-OF-BAND thaw (NOT AllowEvents).
    let xid_map = backend.xid_map().clone();
    crate::core_loop::pointer_fanout::xi1_thaw_device(
        &mut state,
        &mut backend,
        &xid_map,
        crate::xinput::DEVICEID_XTEST_POINTER,
    );

    assert!(
        peer_saw_event(&mut grab_peer, 5, None),
        "withheld ButtonRelease must be replayed on an out-of-band thaw, not dropped"
    );
    assert!(
        state.sync_pending.is_empty(),
        "the global queue must be drained on thaw"
    );
}

/// Global-queue replay preserves arrival order ACROSS devices (Xorg
/// PlayReleasedEvents over the single `syncEvents.pending`,
/// dix/events.c:1233-1291): a keyboard event queued before a pointer event
/// is replayed first when both thaw in a single `xi1_compute_freezes` pass.
#[test]
fn compute_freezes_replays_global_queue_in_arrival_order() {
    use crate::{
        backend::Backend,
        host_x11::{HostKeyEvent, HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
        server::{CoreFocus, PendingSyncEvent, QueuedInputEvent, Xi1Freeze, Xi1SyncState},
    };
    const CLIENT_ID: u32 = 1;
    const WIN: u32 = 0x0010_0121;
    const HOST_XID: u32 = 0xCAFE_0021;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    peer.set_nonblocking(true).expect("nonblocking");
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(WIN));
    Backend::register_top_level(&mut backend, None, ResourceId(WIN), HOST_XID)
        .expect("register host xid");
    // KeyPress|KeyRelease|ButtonPress|ButtonRelease.
    state
        .clients
        .get_mut(&CLIENT_ID)
        .expect("client")
        .event_masks
        .insert(ResourceId(WIN), 0x0000_000f);
    // Key delivery routes to the core focus window.
    state.core_focus = CoreFocus {
        raw: WIN,
        revert_to: 0,
        time: 0,
    };

    for dev in [
        crate::xinput::DEVICEID_XTEST_KEYBOARD,
        crate::xinput::DEVICEID_XTEST_POINTER,
    ] {
        state.xi1_frozen.insert(
            dev,
            Xi1Freeze {
                state: Xi1SyncState::FrozenNoEvent,
                ..Default::default()
            },
        );
    }
    // Enqueue KEY (release) THEN POINTER (release), in that global order.
    state.sync_pending.push_back(PendingSyncEvent {
        device: crate::xinput::DEVICEID_XTEST_KEYBOARD,
        event: QueuedInputEvent::HostKey(HostKeyEvent {
            origin: crate::core_loop::InputOrigin::NestedHost,
            pressed: false,
            keycode: 38,
            time: 0x1000,
            root_x: 5,
            root_y: 5,
            event_x: 5,
            event_y: 5,
            state: 0,
        }),
    });
    state.sync_pending.push_back(PendingSyncEvent {
        device: crate::xinput::DEVICEID_XTEST_POINTER,
        event: QueuedInputEvent::HostPointer(HostPointerEvent {
            origin: crate::core_loop::message::InputOrigin::XTest(4),
            kind: PointerEventKind::ButtonRelease,
            host_xid: HOST_XID,
            detail: 1,
            time: 0x2000,
            root_x: 5,
            root_y: 5,
            event_x: 5,
            event_y: 5,
            state: 0,
            crossing_mode: 0,
            child: 0,
            raw_dx: 0,
            raw_dy: 0,
            tree_change: false,
        }),
    });

    // Thaw BOTH, then ONE replay pass.
    for dev in [
        crate::xinput::DEVICEID_XTEST_KEYBOARD,
        crate::xinput::DEVICEID_XTEST_POINTER,
    ] {
        state.xi1_frozen.get_mut(&dev).unwrap().state = Xi1SyncState::Thawed;
    }
    let xid_map = backend.xid_map().clone();
    crate::core_loop::pointer_fanout::xi1_compute_freezes(&mut state, &mut backend, &xid_map);

    // Read the full wire once and compare offsets: KeyRelease (3) precedes
    // ButtonRelease (5).
    let mut buf = [0u8; 8192];
    let n = peer.read(&mut buf).expect("read wire");
    assert!(
        n >= 64,
        "expected both replayed events on the wire (got {n} bytes)"
    );
    let mut key_pos = None;
    let mut btn_pos = None;
    let mut i = 0;
    while i + 32 <= n {
        let ty = buf[i] & 0x7F;
        if ty == 3 && key_pos.is_none() {
            key_pos = Some(i);
        }
        if ty == 5 && btn_pos.is_none() {
            btn_pos = Some(i);
        }
        i += 32;
    }
    assert!(
        key_pos.is_some() && btn_pos.is_some(),
        "both the keyboard and pointer events must be delivered (key={key_pos:?} btn={btn_pos:?})"
    );
    assert!(
        key_pos < btn_pos,
        "keyboard event (queued first) must replay before the pointer event"
    );
    assert!(state.sync_pending.is_empty(), "queue fully drained");
}

/// Regression for the double-button-map hazard: the freeze gate stores the
/// PHYSICAL detail, and replay re-enters button mapping exactly once. With
/// a non-identity `pointer_mapping_override` (physical 1 -> logical 3), the
/// replayed release must carry logical button 3 (mapped once), not a
/// twice-mapped value.
#[test]
fn frozen_pointer_replay_maps_button_exactly_once() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
        server::{Xi1Freeze, Xi1SyncState},
    };
    const CLIENT_ID: u32 = 1;
    const WIN: u32 = 0x0010_0131;
    const HOST_XID: u32 = 0xCAFE_0031;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    peer.set_nonblocking(true).expect("nonblocking");
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(WIN));
    Backend::register_top_level(&mut backend, None, ResourceId(WIN), HOST_XID)
        .expect("register host xid");
    state
        .clients
        .get_mut(&CLIENT_ID)
        .expect("client")
        .event_masks
        .insert(ResourceId(WIN), 0x0000_000c);

    // Physical button 1 -> logical 3 (identity for 2/3).
    state.pointer_mapping_override = Some(vec![3, 2, 1]);
    // Pointer frozen so the release is withheld at the gate.
    state.xi1_frozen.insert(
        crate::xinput::DEVICEID_XTEST_POINTER,
        Xi1Freeze {
            state: Xi1SyncState::FrozenNoEvent,
            ..Default::default()
        },
    );

    let xid_map = backend.xid_map().clone();
    // Drive a PHYSICAL button-1 release through the real fanout: the gate
    // withholds it into sync_pending with the physical detail preserved.
    let release = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonRelease,
        host_xid: HOST_XID,
        detail: 1,
        time: 0x2a50,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let _ = crate::core_loop::pointer_fanout::pointer_event_fanout_to_state(
        &mut state,
        &mut backend,
        &xid_map,
        release,
        true,
        false,
    );
    assert_eq!(
        state.sync_pending.len(),
        1,
        "release must be withheld while frozen"
    );

    // Thaw and replay.
    crate::core_loop::pointer_fanout::xi1_thaw_device(
        &mut state,
        &mut backend,
        &xid_map,
        crate::xinput::DEVICEID_XTEST_POINTER,
    );

    // The delivered ButtonRelease must carry LOGICAL button 3 (mapped once).
    assert!(
        peer_saw_event(&mut peer, 5, Some(3)),
        "replayed release must map physical 1 -> logical 3 exactly once (not double-mapped)"
    );
}

/// XI2 mode → core AllowSome mode mapping ([`xi2_allow_mode_to_core`]).
#[test]
fn xi2_allow_mode_to_core_maps_all_modes() {
    // Pointer: Async/Sync/Replay → Pointer variants.
    assert_eq!(xi2_allow_mode_to_core(0, false), Some(0)); // AsyncDevice → AsyncPointer
    assert_eq!(xi2_allow_mode_to_core(1, false), Some(1)); // SyncDevice → SyncPointer
    assert_eq!(xi2_allow_mode_to_core(2, false), Some(2)); // ReplayDevice → ReplayPointer
    // Keyboard: → Keyboard variants.
    assert_eq!(xi2_allow_mode_to_core(0, true), Some(3)); // → AsyncKeyboard
    assert_eq!(xi2_allow_mode_to_core(1, true), Some(4)); // → SyncKeyboard
    assert_eq!(xi2_allow_mode_to_core(2, true), Some(5)); // → ReplayKeyboard
    // paired: AsyncPairedDevice acts on the OTHER device.
    assert_eq!(xi2_allow_mode_to_core(3, false), Some(3)); // ptr grab → async keyboard
    assert_eq!(xi2_allow_mode_to_core(3, true), Some(0)); // kbd grab → async pointer
    assert_eq!(xi2_allow_mode_to_core(4, false), Some(6)); // AsyncPair → AsyncBoth
    assert_eq!(xi2_allow_mode_to_core(5, false), Some(7)); // SyncPair  → SyncBoth
    // touch / unknown → unsupported.
    assert_eq!(xi2_allow_mode_to_core(6, false), None); // XIAcceptTouch
    assert_eq!(xi2_allow_mode_to_core(7, false), None); // XIRejectTouch
}

/// Regression: XI2 `XIAllowEvents(XISyncDevice)` (mode 1) must thaw the
/// frozen device and replay the withheld queue. It used to be a no-op
/// ("we're always-async"), so muffin's click-to-focus SYNC path (mutter
/// `events.c` `maybe_unfreeze_pointer_events(EVENTS_UNFREEZE_SYNC)`)
/// could not clear the freeze → `QUEUE-WHILE-FROZEN` piled up → the
/// Cinnamon clicks-and-typing-dead freeze. Now routed through the shared
/// `apply_allow_events` (core SyncPointer).
#[test]
fn xi_allow_events_sync_device_thaws_and_drains_queue() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
    };
    const GRAB_CLIENT_ID: u32 = 1;
    const TARGET_CLIENT_ID: u32 = 2;
    const GRAB_WIN: u32 = 0x0010_0071;
    const TARGET_WIN: u32 = 0x0020_0072;
    const HOST_XID: u32 = 0xCAFE_0007;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut target_peer = install_client(&mut state, TARGET_CLIENT_ID);
    let mut backend = RecordingBackend::new();
    grab_peer.set_nonblocking(true).expect("nonblocking");
    target_peer.set_nonblocking(true).expect("nonblocking");

    for (client, win) in [(GRAB_CLIENT_ID, GRAB_WIN), (TARGET_CLIENT_ID, TARGET_WIN)] {
        state.resources.create_window(
            ClientId(client),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(win),
                parent: ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(ResourceId(win));
    }
    state
        .clients
        .get_mut(&TARGET_CLIENT_ID)
        .expect("target")
        .event_masks
        .insert(ResourceId(TARGET_WIN), 0x0000_000c);

    // Activated SYNC passive grab: held, frozen, activating press stored,
    // a release withheld during the freeze.
    set_test_pointer_grab(&mut state, GRAB_CLIENT_ID, GRAB_WIN, true, false);
    // The activated passive grab's defining record (its mask is what
    // the drain-path redirect reports to the grab owner).
    state.button_grabs.push(crate::server::PassiveButtonGrab {
        device_id: 0,
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ResourceId(GRAB_WIN),
        button: 1,
        modifiers: 0x8000,
        owner_events: false,
        event_mask: 0x0000_000c, // press|release
        pointer_mode: 0,         // sync
        keyboard_mode: 1,
        confine_to: ResourceId(0),
        via_xi2: false,
    });
    state.xi1_frozen.insert(
        crate::xinput::DEVICEID_MASTER_POINTER,
        crate::server::Xi1Freeze {
            state: crate::server::Xi1SyncState::FrozenNoEvent,
            ..Default::default()
        },
    );
    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_XID,
        detail: 1,
        time: 0x10,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    {
        let f = state
            .xi1_frozen
            .entry(crate::xinput::DEVICEID_MASTER_POINTER)
            .or_default();
        f.state = crate::server::Xi1SyncState::FrozenWithEvent;
        f.stored = Some(crate::server::QueuedInputEvent::HostPointer(press));
    }
    state
        .sync_pending
        .push_back(crate::server::PendingSyncEvent {
            device: crate::xinput::DEVICEID_MASTER_POINTER,
            event: crate::server::QueuedInputEvent::HostPointer(HostPointerEvent {
                origin: crate::core_loop::message::InputOrigin::XTest(4),
                kind: PointerEventKind::ButtonRelease,
                time: 0x20,
                ..press
            }),
        });
    Backend::register_top_level(&mut backend, None, ResourceId(TARGET_WIN), HOST_XID)
        .expect("register host xid");

    // XIAllowEvents XISyncDevice (mode 1) on master pointer (deviceid 2).
    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&0u32.to_le_bytes()); // time
    body.extend_from_slice(&2u16.to_le_bytes()); // deviceid
    body.push(1); // mode = XISyncDevice
    body.push(0); // pad
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 53,
        length_units: 3,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("allow events");

    assert!(
        !state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_POINTER)
            .is_some_and(crate::server::Xi1Freeze::frozen),
        "XISyncDevice must thaw the frozen pointer (was a no-op → Cinnamon freeze)"
    );
    assert!(
        !state
            .sync_pending
            .iter()
            .any(|p| p.device == crate::xinput::DEVICEID_MASTER_POINTER),
        "withheld queue must be drained on XISyncDevice"
    );

    // XISyncDevice (FREEZE_NEXT_EVENT) thaws WITHOUT deactivating the
    // grab (Xorg AllowSome, dix/events.c:1864 — only NOT_GRABBED
    // /Replay deactivates). The withheld release replays THROUGH the
    // grab (DeliverGrabbedEvent) to the grab owner, then the
    // terminating release ends the passive grab; it must NOT leak to
    // the foreign natural target (#94).
    assert!(
        peer_saw_event(&mut grab_peer, 5, None),
        "withheld ButtonRelease must replay THROUGH the grab to its owner \
             on XISyncDevice"
    );
    assert!(
        !peer_saw_event(&mut target_peer, 5, None),
        "the grab intercepts the release — it must not leak to the foreign \
             natural target (#94)"
    );
}

#[test]
fn xi_allow_events_replay_device_releases_active_pointer_grab() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
        server::ActivePointerGrab,
    };

    const GRAB_CLIENT_ID: u32 = 1;
    const TARGET_WIN: u32 = 0x0020_0052;
    const HOST_XID: u32 = 0xCAFE_0003;

    let mut state = ServerState::new();
    let _grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        ClientId(GRAB_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(TARGET_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(TARGET_WIN));
    state.active_pointer_grab = Some(ActivePointerGrab {
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ResourceId(TARGET_WIN),
        event_mask: 0xFFFF,
        cursor: ResourceId(0),
        time: 0,
        owner_events: false,
        via_xi2: true,
        implicit: false,
        passive: false,
        xi2_mask: u64::MAX,
    });
    // ReplayDevice only acts on a FROZEN device with a stored event to
    // replay (Xorg AllowSome) — engage the sync freeze + activating press.
    state.xi1_frozen.insert(
        crate::xinput::DEVICEID_MASTER_POINTER,
        crate::server::Xi1Freeze {
            state: crate::server::Xi1SyncState::FrozenNoEvent,
            ..Default::default()
        },
    );
    {
        let f = state
            .xi1_frozen
            .entry(crate::xinput::DEVICEID_MASTER_POINTER)
            .or_default();
        f.state = crate::server::Xi1SyncState::FrozenWithEvent;
        f.stored = Some(crate::server::QueuedInputEvent::HostPointer(
            HostPointerEvent {
                origin: crate::core_loop::message::InputOrigin::XTest(4),
                kind: PointerEventKind::ButtonPress,
                host_xid: HOST_XID,
                detail: 1,
                time: 0,
                root_x: 10,
                root_y: 10,
                event_x: 10,
                event_y: 10,
                state: 0,
                crossing_mode: 0,
                child: 0,
                raw_dx: 0,
                raw_dy: 0,
                tree_change: false,
            },
        ));
    }
    Backend::register_top_level(&mut backend, None, ResourceId(TARGET_WIN), HOST_XID)
        .expect("register host xid");

    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&0u32.to_le_bytes()); // time
    body.extend_from_slice(&2u16.to_le_bytes()); // deviceid
    body.push(2); // mode = ReplayDevice
    body.push(0); // pad

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 53,
        length_units: 3,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("allow events replay pointer");

    assert!(state.active_pointer_grab.is_none());
}

#[test]
fn xi_sync_passive_grab_replays_xi2_press_to_target_only_after_allow_events() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
        server::PassiveButtonGrab,
    };

    const GRAB_CLIENT_ID: u32 = 1;
    const TARGET_CLIENT_ID: u32 = 2;
    const TARGET_WIN: u32 = 0x0020_0052;
    const HOST_XID: u32 = 0xCAFE_0002;
    const XI2_BUTTON_PRESS_BIT: u32 = 1 << 4;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut target_peer = install_client(&mut state, TARGET_CLIENT_ID);
    let mut backend = RecordingBackend::new();
    grab_peer
        .set_nonblocking(true)
        .expect("grab peer nonblocking");
    target_peer
        .set_nonblocking(true)
        .expect("target peer nonblocking");

    state.resources.create_window(
        ClientId(TARGET_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(TARGET_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(TARGET_WIN));
    state
        .clients
        .get_mut(&GRAB_CLIENT_ID)
        .expect("grab client")
        .xi2_masks
        .insert((ResourceId(TARGET_WIN), 1), u64::from(XI2_BUTTON_PRESS_BIT));
    state
        .clients
        .get_mut(&TARGET_CLIENT_ID)
        .expect("target client")
        .xi2_masks
        .insert((ResourceId(TARGET_WIN), 1), u64::from(XI2_BUTTON_PRESS_BIT));
    state.button_grabs.push(PassiveButtonGrab {
        device_id: 0,
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ResourceId(TARGET_WIN),
        button: 1,
        modifiers: 0,
        owner_events: false,
        event_mask: 0xFFFF_FFFF,
        pointer_mode: 0,
        keyboard_mode: 1,
        confine_to: ResourceId(0),
        via_xi2: true,
    });
    Backend::register_top_level(&mut backend, None, ResourceId(TARGET_WIN), HOST_XID)
        .expect("register host xid");

    let event = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_XID,
        detail: 1,
        time: 0x1234,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let xid_map = backend.xid_map().clone();
    let _dropped =
        pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, event, true, false);

    assert!(state.active_pointer_grab.is_some_and(|grab| grab.passive));
    assert!(
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_POINTER)
            .and_then(|f| f.stored.as_ref())
            .is_some()
    );

    let mut buf = [0u8; 128];
    let target_read = target_peer.read(&mut buf);
    assert!(
        matches!(target_read, Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock),
        "sync passive XI2 grab must withhold the initial XI2 press from the target; got {target_read:?}",
    );
    let grab_read = grab_peer.read(&mut buf);
    assert!(
        matches!(grab_read, Ok(n) if n > 0),
        "grab owner should receive the grabbed press stream; got {grab_read:?}",
    );

    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&0x1234u32.to_le_bytes()); // time
    body.extend_from_slice(&2u16.to_le_bytes()); // deviceid
    body.push(2); // mode = ReplayDevice
    body.push(0); // pad

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 53,
        length_units: 3,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(GRAB_CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("allow events");

    let target_read = target_peer.read(&mut buf);
    assert!(
        matches!(target_read, Ok(n) if n >= 32 && buf[0] == 35),
        "ReplayDevice must redeliver the XI2 press to the natural target; got {target_read:?}",
    );
}

#[test]
fn xi_sync_passive_grab_release_during_freeze_queues_for_replay() {
    // Regression: in a sync passive grab, a ButtonRelease arriving
    // BEFORE the grab owner sends AllowEvents must NOT clear the
    // grab nor leak to the natural target — it must queue alongside
    // the activating press for replay. Pre-fix, the release cleared
    // `frozen_pointer_event` + `pointer_grab_is_passive`, so when
    // AllowEvents(ReplayPointer/ReplayDevice) finally arrived there
    // was nothing to replay. Visible symptom on MATE: marco's slow
    // ~10 round-trip grab handler vs a fast click → app never sees
    // the press → menu/titlebar clicks dead.
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
        server::PassiveButtonGrab,
    };

    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0020_0053;
    const HOST_XID: u32 = 0xCAFE_0004;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(WINDOW_XID));
    state.button_grabs.push(PassiveButtonGrab {
        device_id: 0,
        owner: ClientId(CLIENT_ID),
        grab_window: ResourceId(WINDOW_XID),
        button: 1,
        modifiers: 0,
        owner_events: true,
        event_mask: 0xFFFF_FFFF,
        pointer_mode: 0, // Synchronous → triggers freeze
        keyboard_mode: 1,
        confine_to: ResourceId(0),
        via_xi2: true,
    });
    Backend::register_top_level(&mut backend, None, ResourceId(WINDOW_XID), HOST_XID)
        .expect("register host xid");

    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_XID,
        detail: 1,
        time: 0x1234,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let xid_map = backend.xid_map().clone();
    let _dropped =
        pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, press, true, false);
    assert!(state.active_pointer_grab.is_some_and(|grab| grab.passive));
    assert!(
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_POINTER)
            .and_then(|f| f.stored.as_ref())
            .is_some()
    );
    // No ButtonRelease is withheld yet — it hasn't arrived. (The unified
    // queue may already hold the activating press's XI1 form; that is
    // expected — Xorg stores the activating event too. We assert on the
    // RELEASE specifically, which is what this test is about.)
    assert!(
        !state
            .sync_pending
            .iter()
            .any(|p| p.device == crate::xinput::DEVICEID_MASTER_POINTER
                && matches!(
                    &p.event,
                    crate::server::QueuedInputEvent::HostPointer(e)
                        if e.kind == PointerEventKind::ButtonRelease
                )),
        "no ButtonRelease must be queued before the release arrives"
    );

    // Release arrives BEFORE AllowEvents (the load-bearing case).
    let release = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonRelease,
        time: 0x1280,
        ..press
    };
    let xid_map = backend.xid_map().clone();
    let _dropped =
        pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, release, true, false);

    // Grab MUST still be active (waiting for AllowEvents). Press
    // is still frozen. Release is in the queue.
    assert!(
        state.active_pointer_grab.is_some(),
        "grab must remain active while frozen — release waits for AllowEvents",
    );
    assert!(state.active_pointer_grab.is_some_and(|grab| grab.passive));
    assert!(
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_POINTER)
            .and_then(|f| f.stored.as_ref())
            .is_some()
    );
    // The withheld release must sit in the global replay queue as a core
    // HostPointer event (Xorg syncEvents.pending), not be delivered to the
    // natural target.
    assert!(
        state
            .sync_pending
            .iter()
            .any(|p| p.device == crate::xinput::DEVICEID_MASTER_POINTER
                && matches!(
                    &p.event,
                    crate::server::QueuedInputEvent::HostPointer(e)
                        if e.kind == PointerEventKind::ButtonRelease
                )),
        "release must be queued for replay, not delivered to natural target",
    );
}

/// Xorg semantics (`DeliverGrabbedEvent`, dix/events.c:4361): the
/// `owner_events=true` natural walk is filtered to the GRAB
/// CLIENT — `TryClientEvents` (dix/events.c:2069) returns -1 for
/// any other client ("not delivered due to grab"), aborting
/// propagation; the press then falls back to the grab window.
///
/// This test previously pinned the OPPOSITE ("delivers descendant
/// window regardless of owner", from the 2b2680e cinnamon wip) —
/// that leak is what wedged wmaker on HW 2026-06-04: the sync
/// grab froze the queue while the press went to the app client,
/// so the WM never called AllowEvents and clicks died.
#[test]
fn xi_passive_grab_owner_events_redirects_foreign_descendant_press_to_grab_client() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
        server::PassiveButtonGrab,
    };

    const GRAB_CLIENT_ID: u32 = 1;
    const CHILD_CLIENT_ID: u32 = 2;
    const GRAB_WIN: u32 = 0x0020_0062;
    const CHILD_WIN: u32 = 0x0020_0063;
    const HOST_XID: u32 = 0xCAFE_0005;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut child_peer = install_client(&mut state, CHILD_CLIENT_ID);
    let mut backend = RecordingBackend::new();
    grab_peer
        .set_nonblocking(true)
        .expect("grab peer nonblocking");
    child_peer
        .set_nonblocking(true)
        .expect("child peer nonblocking");

    state.resources.create_window(
        ClientId(GRAB_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(GRAB_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    state.resources.create_window(
        ClientId(CHILD_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(CHILD_WIN),
            parent: ResourceId(GRAB_WIN),
            x: 10,
            y: 10,
            width: 40,
            height: 40,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(GRAB_WIN));
    let _ = state.resources.map_window(ResourceId(CHILD_WIN));
    state
        .clients
        .get_mut(&CHILD_CLIENT_ID)
        .expect("child client")
        .event_masks
        .insert(ResourceId(CHILD_WIN), 0x0000_0004);
    state.button_grabs.push(PassiveButtonGrab {
        device_id: 0,
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ResourceId(GRAB_WIN),
        button: 1,
        modifiers: 0,
        owner_events: true,
        event_mask: 0xFFFF_FFFF,
        pointer_mode: 0,
        keyboard_mode: 1,
        confine_to: ResourceId(0),
        via_xi2: true,
    });
    Backend::register_top_level(&mut backend, None, ResourceId(GRAB_WIN), HOST_XID)
        .expect("register host xid");

    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_XID,
        detail: 1,
        time: 0x1234,
        root_x: 20,
        root_y: 20,
        event_x: 20,
        event_y: 20,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let xid_map = backend.xid_map().clone();
    let _dropped =
        pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, press, true, false);

    let mut buf = [0u8; 128];
    let grab_read = grab_peer.read(&mut buf);
    assert!(
        matches!(grab_read, Ok(n) if n >= 32),
        "press on a foreign-owned descendant must fall back to grab-window \
             delivery to the GRAB client (Xorg dix/events.c:2069 aborts the \
             natural walk on a foreign subscriber); got {grab_read:?}",
    );
    assert_eq!(buf[0], 4, "core ButtonPress to the grab client");
    assert_eq!(
        &buf[12..16],
        &GRAB_WIN.to_le_bytes(),
        "press reported on the grab window",
    );
    let child_read = child_peer.read(&mut buf);
    let child_got_core_press =
        matches!(child_read, Ok(n) if buf[..n.min(128)].chunks(32).any(|c| c[0] == 4));
    assert!(
        !child_got_core_press,
        "the foreign descendant's owner must NOT see the core press while \
             the grab holds; got {child_read:?}",
    );
    assert!(
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_POINTER)
            .and_then(|f| f.stored.as_ref())
            .is_some(),
        "GrabModeSync activation with a delivery must freeze the queue",
    );
}

/// During a window move, muffin holds an *active* `XIGrabDevice` on
/// the master pointer. Every master-pointer XI2 event — including the
/// final `XI_ButtonRelease` — must be funnelled to the grab owner,
/// even after the drag has pulled the pointer over another client's
/// window. Regression: the XI2 fanout routed purely by window
/// mask-selection and ignored the active grab, so the release was
/// delivered to the window under the cursor (nemo-desktop) instead of
/// the grab owner (muffin) — leaving muffin stuck in its move loop
/// with the button apparently still held.
#[test]
fn xi_active_device_grab_funnels_button_release_to_grab_owner_not_window_under_cursor() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
        server::ActivePointerGrab,
    };

    const GRAB_CLIENT_ID: u32 = 1; // muffin
    const OTHER_CLIENT_ID: u32 = 2; // nemo-desktop
    const GRAB_WIN: u32 = 0x0010_0011; // muffin's grab window
    const OTHER_WIN: u32 = 0x0025_0003; // nemo-desktop fullscreen window
    const OTHER_HOST_XID: u32 = 0xCAFE_0006;
    const XI2_BUTTON_RELEASE_BIT: u32 = 1 << 5;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut other_peer = install_client(&mut state, OTHER_CLIENT_ID);
    let mut backend = RecordingBackend::new();
    grab_peer.set_nonblocking(true).unwrap();
    other_peer.set_nonblocking(true).unwrap();

    // muffin's grab window — small, off in the corner. The drag pulls
    // the pointer away from it onto the desktop.
    state.resources.create_window(
        ClientId(GRAB_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(GRAB_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 50,
            height: 50,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    // nemo-desktop's window — covers where the pointer ends up.
    state.resources.create_window(
        ClientId(OTHER_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(OTHER_WIN),
            parent: ROOT_WINDOW,
            x: 200,
            y: 200,
            width: 400,
            height: 400,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(GRAB_WIN));
    let _ = state.resources.map_window(ResourceId(OTHER_WIN));

    // nemo selects XI2 ButtonRelease on its own window (XIAllDevices=1).
    state
        .clients
        .get_mut(&OTHER_CLIENT_ID)
        .expect("other client")
        .xi2_masks
        .insert(
            (ResourceId(OTHER_WIN), 1),
            u64::from(XI2_BUTTON_RELEASE_BIT),
        );

    // muffin holds an active master-pointer grab (XIGrabDevice).
    // owner_events=false → every event funnels to the grab owner.
    state.active_pointer_grab = Some(ActivePointerGrab {
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ResourceId(GRAB_WIN),
        event_mask: 0xFFFF,
        cursor: ResourceId(0),
        time: 0,
        owner_events: false,
        via_xi2: true,
        implicit: false,
        passive: false,
        xi2_mask: u64::MAX,
    });

    Backend::register_top_level(&mut backend, None, ResourceId(OTHER_WIN), OTHER_HOST_XID)
        .expect("register host xid");

    // Pointer has dragged onto nemo-desktop (200,200..600,600); button 1
    // still held. event_x/y are relative to OTHER_WIN's origin.
    let release = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonRelease,
        host_xid: OTHER_HOST_XID,
        detail: 1,
        time: 0x2000,
        root_x: 300,
        root_y: 300,
        event_x: 100,
        event_y: 100,
        state: 0x100, // button 1 down
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let xid_map = backend.xid_map().clone();
    let press = HostPointerEvent {
        kind: PointerEventKind::ButtonPress,
        state: 0,
        ..release
    };
    let _dropped =
        pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, press, true, false);
    let _ = read_all_available(&mut grab_peer);
    let _ = read_all_available(&mut other_peer);
    grab_peer
        .set_nonblocking(true)
        .expect("restore grab peer mode");
    other_peer
        .set_nonblocking(true)
        .expect("restore other peer mode");

    let _dropped =
        pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, release, true, false);

    let mut buf = [0u8; 256];

    // The window under the cursor must NOT get the XI2 release — the
    // active grab owns the device.
    let other_read = other_peer.read(&mut buf);
    assert!(
        matches!(other_read, Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock),
        "active device grab must withhold the XI2 ButtonRelease from the window under the cursor; got {other_read:?}",
    );

    // The grab owner must receive the XI2 ButtonRelease. The grab owner
    // also gets the parallel core ButtonRelease (32 bytes) from the
    // core redirect, so scan event boundaries for the XI2 GenericEvent.
    let n = match grab_peer.read(&mut buf) {
        Ok(n) => n,
        Err(e) => panic!("grab owner must receive the grabbed XI2 release; got {e:?}"),
    };
    let off = (0..n)
        .step_by(32)
        .find(|&off| off + 10 <= n && buf[off] == 35)
        .expect("grab owner must receive an XI2 GenericEvent (got core-only stream)");
    assert_eq!(
        u16::from_le_bytes([buf[off + 8], buf[off + 9]]),
        5,
        "the grabbed XI2 event must be a ButtonRelease (evtype 5)",
    );
}

/// A *core* `XGrabPointer` grab must NOT funnel XI2 XGE events to
/// the grab owner — the owner asked for core delivery only (Xorg's
/// `DeliverGrabbedEvent` consults the grab's own xi2mask, which is
/// empty for core grabs). Regression: the XI2 active-grab redirect
/// pushed the grab client unconditionally; a plain-Xlib client that
/// linked libXi without calling XIQueryVersion (every xts5 Xlib11
/// TCM) NULL-derefs inside libXi's wire handler on the XGE event,
/// and TET's longjmp out of the SIGSEGV poisons the display mutex —
/// the rest of the test case hangs forever (Xlib11/ButtonPress
/// scenario 890-0 on eiger HW, 2026-06-04).
#[test]
fn core_pointer_grab_does_not_send_xi2_to_grab_owner() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
        server::ActivePointerGrab,
    };

    const GRAB_CLIENT_ID: u32 = 1;
    const GRAB_WIN: u32 = 0x0010_0021;
    const HOST_XID: u32 = 0xCAFE_0016;

    let mut state = ServerState::new();
    let mut grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut backend = RecordingBackend::new();
    grab_peer.set_nonblocking(true).unwrap();

    state.resources.create_window(
        ClientId(GRAB_CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(GRAB_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 50,
            height: 50,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(GRAB_WIN));
    // Select core ButtonPress on the grab window so the core
    // redirect has a delivery target.
    state
        .clients
        .get_mut(&GRAB_CLIENT_ID)
        .expect("grab client")
        .event_masks
        .insert(ResourceId(GRAB_WIN), 0x0000_0004);

    // Core XGrabPointer, owner_events=false — the xts5 TP10 shape.
    state.active_pointer_grab = Some(ActivePointerGrab {
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ResourceId(GRAB_WIN),
        event_mask: 0xFFFF,
        cursor: ResourceId(0),
        time: 0,
        owner_events: false,
        via_xi2: false,
        implicit: false,
        passive: false,
        xi2_mask: 0,
    });

    Backend::register_top_level(&mut backend, None, ResourceId(GRAB_WIN), HOST_XID)
        .expect("register host xid");

    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_XID,
        detail: 1,
        time: 0x3000,
        root_x: 25,
        root_y: 25,
        event_x: 25,
        event_y: 25,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let xid_map = backend.xid_map().clone();
    let _dropped =
        pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, press, true, false);

    // The grab owner gets the core ButtonPress (type 4) and nothing
    // else — scan every 32-byte event for an XI2 GenericEvent (35).
    let mut buf = [0u8; 512];
    let n = match grab_peer.read(&mut buf) {
        Ok(n) => n,
        Err(e) => panic!("grab owner must receive the core press; got {e:?}"),
    };
    let mut saw_core_press = false;
    for off in (0..n).step_by(32) {
        assert_ne!(
            buf[off], 35,
            "core grab owner must not receive XI2 GenericEvents",
        );
        if buf[off] == 4 {
            saw_core_press = true;
        }
    }
    assert!(saw_core_press, "core ButtonPress must reach the grab owner");
}

/// `XIQueryPointer` must report currently-held pointer buttons in
/// the XI2 `buttons` bitmask, not only in the legacy KeyButMask
/// `effective_mods`. A GTK4 CSD window move goes through
/// `_NET_WM_MOVERESIZE`: the app sends the request and muffin — which
/// never saw the ButtonPress — queries the pointer to learn whether
/// the initiating button is still held. With an empty `buttons` mask
/// muffin concluded the button was released and aborted the move
/// grab immediately (the window "didn't budge"). Button N maps to
/// bit N (button 1 -> bit 1).
#[test]
fn xi_query_pointer_reports_held_button_in_xi2_button_mask() {
    use crate::{backend::Backend, resources::ROOT_VISUAL};
    use yserver_protocol::x11::ClientByteOrder;

    const CLIENT_ID: u32 = 1;
    const WINDOW_XID: u32 = 0x0020_0070;
    const HOST_XID: u32 = 0xCAFE_0007;

    // Run for both client byte orders. The XI2 button mask is a raw
    // byte array indexed by `XIMaskIsSet` (X11/extensions/XI2.h), so it
    // must NOT be byte-swapped per client order — a big-endian client
    // must still read button 1 in mask byte 0.
    for order in [ClientByteOrder::LittleEndian, ClientByteOrder::BigEndian] {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, CLIENT_ID);
        peer.set_nonblocking(true).unwrap();
        state.clients.get_mut(&CLIENT_ID).unwrap().byte_order = order;
        let mut backend = RecordingBackend::new();
        // Model button 1 held (KeyButMask Button1Mask = 0x0100).
        backend.query_pointer_mask = 0x0100;

        state.resources.create_window(
            yserver_protocol::x11::ClientId(CLIENT_ID),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(WINDOW_XID),
                parent: ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(ResourceId(WINDOW_XID));
        Backend::register_top_level(&mut backend, None, ResourceId(WINDOW_XID), HOST_XID)
            .expect("register host xid");

        // XIQueryPointer body: window(4) + deviceid(2) + pad(2).
        let mut body = Vec::with_capacity(8);
        body.extend_from_slice(&WINDOW_XID.to_le_bytes());
        body.extend_from_slice(&2u16.to_le_bytes()); // master pointer
        body.extend_from_slice(&0u16.to_le_bytes()); // pad

        let header = yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 40, // XIQueryPointer
            length_units: 3,
        };
        handle_xi2_request(
            &mut state,
            &mut backend,
            None,
            ClientId(CLIENT_ID),
            SequenceNumber(1),
            header,
            &body,
        )
        .expect("xi query pointer");

        let mut buf = [0u8; 128];
        let n = peer.read(&mut buf).expect("reply");
        // Reply: 8-byte header + 24 coord bytes; same_screen@32, pad@33,
        // buttons_len@34-35, mods@36-51, group@52-55, button mask@56+.
        assert!(
            n >= 60,
            "{order:?}: XIQueryPointer reply must carry a 1-unit button bitmask (got {n})",
        );
        let buttons_len = match order {
            ClientByteOrder::LittleEndian => u16::from_le_bytes([buf[34], buf[35]]),
            ClientByteOrder::BigEndian => u16::from_be_bytes([buf[34], buf[35]]),
        };
        assert_eq!(
            buttons_len, 1,
            "{order:?}: buttons_len must be 1 so clients can read button state",
        );
        // Byte-indexed exactly as `XIMaskIsSet(mask, 1) = mask[1>>3] &
        // (1 << (1 & 7)) = mask[0] & 0x02` (the way muffin reads it),
        // which is byte-order independent.
        assert_ne!(
            buf[56] & (1 << 1),
            0,
            "{order:?}: button 1 must be held in XI2 button mask byte 0 \
                 (raw byte array, not byte-swapped); muffin's \
                 _NET_WM_MOVERESIZE move aborts on an empty mask",
        );
    }
}

/// Cinnamon alt-tab regression #2 (2026-06-10): `XIQueryPointer`
/// must report the keyboard modifier state in `ModifierInfo` —
/// Xorg `Xi/xiquerypointer.c:120,139` fills `rep.mods` from the
/// paired MASTER_KEYBOARD's XKB state. The backend mask is a core
/// KeyButMask (modifiers in the low byte, buttons at 0x100+);
/// `base_mods` must carry the modifier bits WITHOUT the button
/// bits. Pre-fix `base_mods` was hardcoded 0 — cinnamon's
/// `global.get_pointer()` (GDK → XIQueryPointer) saw "Alt not
/// held" mid-alt-tab and the switcher took the modifier-already-
/// released branch: `_activateSelected()` + destroy, so the popup
/// never appeared (trace: instant raise+SetInputFocus between the
/// modal grab and ungrab, same server timestamp).
#[test]
fn xi_query_pointer_reports_keyboard_mods_in_modifier_info() {
    use yserver_protocol::x11::ClientByteOrder;

    const CLIENT_ID: u32 = 1;
    for order in [ClientByteOrder::LittleEndian, ClientByteOrder::BigEndian] {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, CLIENT_ID);
        peer.set_nonblocking(true).unwrap();
        state.clients.get_mut(&CLIENT_ID).unwrap().byte_order = order;
        let mut backend = RecordingBackend::new();
        // Alt (Mod1Mask = 0x8) held + button 1 held (Button1Mask =
        // 0x100): the reply must separate them.
        backend.query_pointer_mask = 0x0108;

        // XIQueryPointer body: window(4) + deviceid(2) + pad(2).
        let mut body = Vec::with_capacity(8);
        body.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
        body.extend_from_slice(&2u16.to_le_bytes()); // master pointer
        body.extend_from_slice(&0u16.to_le_bytes()); // pad
        let header = yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 40, // XIQueryPointer
            length_units: 3,
        };
        handle_xi2_request(
            &mut state,
            &mut backend,
            None,
            ClientId(CLIENT_ID),
            SequenceNumber(1),
            header,
            &body,
        )
        .expect("xi query pointer");

        let mut buf = [0u8; 128];
        let n = peer.read(&mut buf).expect("reply");
        assert!(n >= 56, "{order:?}: short XIQueryPointer reply ({n})");
        // ModifierInfo at bytes 36..52: base / latched / locked /
        // effective (each CARD32, client byte order).
        let read_u32 = |b: &[u8]| match order {
            ClientByteOrder::LittleEndian => u32::from_le_bytes([b[0], b[1], b[2], b[3]]),
            ClientByteOrder::BigEndian => u32::from_be_bytes([b[0], b[1], b[2], b[3]]),
        };
        let base_mods = read_u32(&buf[36..40]);
        let effective_mods = read_u32(&buf[48..52]);
        assert_eq!(
            base_mods, 0x8,
            "{order:?}: base_mods must carry the held Mod1 (Alt) and \
                 not the button bits (Xorg fills it from the paired \
                 keyboard's XKB state)",
        );
        assert_ne!(
            effective_mods & 0x8,
            0,
            "{order:?}: effective_mods must include the held Mod1 — \
                 GDK reads the effective field for global.get_pointer()",
        );
    }
}

/// Cinnamon alt-tab regression #1 (2026-06-10): a SYNC passive key
/// grab (the muffin keybinding) activates on Alt+Tab and freezes
/// the keyboard; muffin then takes an ASYNC active `XIGrabDevice`
/// (pushModal) and later `XIUngrabDevice`s (popModal). Per Xorg the
/// async activation THAWS the frozen device — `ActivateKeyboardGrab`
/// → `CheckGrabForSyncs` (dix/events.c:1424: async → THAWED) — and
/// deactivation runs `ComputeFreezes` (`DeactivateKeyboardGrab`:
/// sync.state = NOT_GRABBED). The XIAllowEvents muffin sends after
/// the ungrab is then a no-op on an already-thawed device. Pre-fix
/// yserver's XI2 grab/ungrab never touched the sync state, so the
/// freeze outlived the whole modal cycle and EVERY later key event
/// was withheld — one alt-tab permanently killed keyboard input
/// (server log: "AllowEvents no-op ... state=FrozenNoEvent";
/// trace: zero key events after the alt-tab cluster).
#[test]
fn async_xi2_grab_and_ungrab_thaw_sync_passive_key_freeze() {
    use crate::{
        core_loop::key_fanout::key_event_fanout_to_state, host_x11::HostKeyEvent, server::KeyGrab,
        xinput::DEVICEID_MASTER_KEYBOARD,
    };

    const APP_WIN: u32 = 0x0030_0001;
    const APP: u32 = 9;
    const WM: u32 = 7;
    let key_event = |pressed: bool, keycode: u8| HostKeyEvent {
        origin: crate::core_loop::InputOrigin::NestedHost,
        pressed,
        keycode,
        time: 1,
        root_x: 10,
        root_y: 20,
        event_x: 10,
        event_y: 20,
        state: 0,
    };

    let mut state = ServerState::new();
    let mut app = install_client(&mut state, APP);
    app.set_nonblocking(true).unwrap();
    let _wm = install_client(&mut state, WM);
    let mut backend = RecordingBackend::new();

    // Focused app window with a core KeyPress selection.
    state.resources.create_window(
        yserver_protocol::x11::ClientId(APP),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(APP_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(APP_WIN));
    state
        .clients
        .get_mut(&APP)
        .unwrap()
        .event_masks
        .insert(ResourceId(APP_WIN), 0x1); // KeyPressMask
    state.core_focus.raw = APP_WIN;

    // muffin keybinding: SYNC passive key grab on Tab (keycode 23).
    state.key_grabs.push(KeyGrab {
        device_id: 0,
        owner: ClientId(WM),
        grab_window: ROOT_WINDOW,
        keycode: 23,
        modifiers: 0,
        owner_events: false,
        pointer_mode: 1,
        keyboard_mode: 0, // synchronous → freeze
        via_xi2: true,
        xi2_mask: 0,
    });

    // 1. Alt+Tab press: passive grab activates + keyboard freezes.
    let _ = key_event_fanout_to_state(&mut state, &mut backend, key_event(true, 23));
    assert!(
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_KEYBOARD)
            .and_then(|f| f.stored.as_ref())
            .is_some(),
        "sync passive grab must freeze the activating press",
    );

    // 2. pushModal: ASYNC XIGrabDevice on the keyboard. Body per
    //    xXIGrabDeviceReq: window(4) time(4) cursor(4) deviceid(2)
    //    mode(1) paired(1) owner_events(1) pad(1) mask_len(2).
    let mut grab_body = Vec::with_capacity(18);
    grab_body.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
    grab_body.extend_from_slice(&0u32.to_le_bytes()); // time = CurrentTime
    grab_body.extend_from_slice(&0u32.to_le_bytes()); // cursor = None
    grab_body.extend_from_slice(&3u16.to_le_bytes()); // master keyboard
    grab_body.push(1); // grab_mode = XIGrabModeAsync
    grab_body.push(1); // paired_device_mode = Async
    grab_body.push(0); // owner_events = false
    grab_body.push(0); // pad
    grab_body.extend_from_slice(&0u16.to_le_bytes()); // mask_len = 0
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(WM),
        SequenceNumber(2),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 51, // XIGrabDevice
            length_units: 6,
        },
        &grab_body,
    )
    .expect("xi grab device");
    assert!(
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_KEYBOARD)
            .and_then(|f| f.stored.as_ref())
            .is_none(),
        "CheckGrabForSyncs: an ASYNC active grab must thaw the \
             sync-passive-grab freeze (Xorg dix/events.c:1431)",
    );
    assert!(
        !state
            .xi1_frozen
            .get(&DEVICEID_MASTER_KEYBOARD)
            .is_some_and(crate::server::Xi1Freeze::frozen),
        "keyboard sync state must be THAWED after the async grab",
    );

    // 3. popModal: XIUngrabDevice. Body: time(4) deviceid(2) pad(2).
    let mut ungrab_body = Vec::with_capacity(8);
    ungrab_body.extend_from_slice(&0u32.to_le_bytes());
    ungrab_body.extend_from_slice(&3u16.to_le_bytes());
    ungrab_body.extend_from_slice(&0u16.to_le_bytes());
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(WM),
        SequenceNumber(3),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 52, // XIUngrabDevice
            length_units: 3,
        },
        &ungrab_body,
    )
    .expect("xi ungrab device");

    // 4. The keyboard must still deliver: a fresh key press reaches
    //    the focused window's client.
    let mut drain = [0u8; 512];
    while app.read(&mut drain).is_ok_and(|n| n > 0) {}
    let _ = key_event_fanout_to_state(&mut state, &mut backend, key_event(true, 38));
    let mut buf = [0u8; 64];
    let n = app.read(&mut buf).unwrap_or(0);
    assert!(
        n >= 32,
        "keyboard must keep delivering after the modal grab cycle \
             (got {n} bytes) — a leaked freeze kills all key input",
    );
    assert_eq!(buf[0] & 0x7f, 2, "must be a core KeyPress");
}

/// `XIGetClientPointer` reply must place `deviceid` at bytes 10-11.
/// Per `xXIGetClientPointerReply` (X11/extensions/XI2proto.h):
/// `set` at byte 8, `pad0` at byte 9, `deviceid` (u16) at bytes
/// 10-11. Regression: the encoder wrote 3 pad bytes after `set`,
/// pushing deviceid to bytes 12-13, so clients read deviceid=0.
/// nemo's desktop rubber-band asks `XIGetClientPointer` for its
/// pointer device, got 0, and queried that for the band anchor —
/// anchoring it at (0,0). caja never calls it, so it was immune.
#[test]
fn xi_get_client_pointer_reply_deviceid_offset() {
    const CLIENT_ID: u32 = 1;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    peer.set_nonblocking(true).unwrap();
    let mut backend = RecordingBackend::new();

    // XIGetClientPointer body: window(4).
    let body = 0u32.to_le_bytes().to_vec();
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 45, // XIGetClientPointer
        length_units: 2,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("xi get client pointer");

    let mut buf = [0u8; 64];
    let n = peer.read(&mut buf).expect("reply");
    assert_eq!(n, 32, "reply must be 32 bytes");
    assert_eq!(buf[8], 1, "byte 8: set = True");
    assert_eq!(
        u16::from_le_bytes([buf[10], buf[11]]),
        2,
        "deviceid (bytes 10-11 per xXIGetClientPointerReply) must be the \
             master pointer (2); a wrong offset reads as 0 and breaks nemo's \
             pointer-device lookup for the rubber-band anchor",
    );
}

/// XI2 `FocusIn`/`FocusOut` events share the `xXIEnterEvent` layout
/// and must carry the current pointer position (Xorg populates
/// root_x/root_y/event_x/event_y from it). yserver emits focus events
/// from request handlers that have no backend handle, so it reads the
/// cached `state.pointer_root`. Regression target: focus events
/// shipped at (0,0).
#[test]
fn xi_focus_in_carries_cached_pointer_position() {
    use crate::resources::ROOT_VISUAL;

    const CLIENT_ID: u32 = 1;
    const FOCUS_WIN: u32 = 0x0010_0007;
    const PREV_WIN: u32 = 0x0010_0008;
    const XI_FOCUS_IN: u16 = 9;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    peer.set_nonblocking(true).unwrap();

    for xid in [FOCUS_WIN, PREV_WIN] {
        state.resources.create_window(
            yserver_protocol::x11::ClientId(CLIENT_ID),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(xid),
                parent: ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(ResourceId(xid));
    }
    // Client selects XI_FocusIn on FOCUS_WIN (keyboard device 3).
    state
        .clients
        .get_mut(&CLIENT_ID)
        .unwrap()
        .xi2_masks
        .insert((ResourceId(FOCUS_WIN), 3), 1 << XI_FOCUS_IN);

    // Cache the pointer position; prior focus is on an unrelated window
    // so a Focus crossing actually fires onto FOCUS_WIN.
    state.pointer_root = (631, 641);
    state.core_focus = crate::server::CoreFocus {
        raw: PREV_WIN,
        revert_to: 0,
        time: 0,
    };

    emit_core_focus_transition(&mut state, PREV_WIN, FOCUS_WIN, 0);
    state.core_focus.raw = FOCUS_WIN;

    let mut buf = [0u8; 128];
    let n = peer.read(&mut buf).expect("focus event");
    assert!(n >= 36, "expected an XI2 focus event (got {n} bytes)");
    assert_eq!(buf[0], 35, "must be an XI2 GenericEvent");
    assert_eq!(
        u16::from_le_bytes([buf[8], buf[9]]),
        XI_FOCUS_IN,
        "evtype must be FocusIn",
    );
    // root_x is FP1616 at bytes 32-35 (after the 32-byte boundary).
    let root_x_fp = u32::from_le_bytes([buf[32], buf[33], buf[34], buf[35]]);
    assert_eq!(
        root_x_fp,
        (631i32 << 16) as u32,
        "FocusIn must carry the current pointer X (631), not 0; Xorg \
             populates focus-event coords from the pointer position",
    );
}

/// A sync passive button grab that also froze the keyboard (dtwm's
/// front panel: GrabModeSync for both) and is let go by
/// `AllowEvents(ReplayPointer)`: Xorg DeactivatePointerGrab clears the
/// keyboard's hold with the grab, so typing works again (measured:
/// tools/vng-scenarios/goldens/passive-grab.txt, last line).
#[test]
fn replay_pointer_of_passive_grab_thaws_keyboard_it_froze() {
    const GRAB_CLIENT_ID: u32 = 1;
    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();
    let _grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    state.set_pointer_grab(crate::server::ActivePointerGrab {
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ROOT_WINDOW,
        event_mask: 0x0008,
        cursor: ResourceId(0),
        time: 0,
        owner_events: false,
        via_xi2: false,
        implicit: false,
        passive: true,
        xi2_mask: 0,
    });
    crate::core_loop::pointer_fanout::xi1_check_grab_for_syncs(
        &mut state,
        crate::xinput::DEVICEID_MASTER_POINTER,
        ClientId(GRAB_CLIENT_ID),
        true,
        true,
    );
    state
        .xi1_frozen
        .entry(crate::xinput::DEVICEID_MASTER_POINTER)
        .or_default()
        .state = crate::server::Xi1SyncState::FrozenWithEvent;
    let kbd_frozen = |state: &ServerState| {
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_KEYBOARD)
            .is_some_and(crate::server::Xi1Freeze::frozen)
    };
    assert!(
        kbd_frozen(&state),
        "the grab's sync keyboard mode holds the keyboard"
    );

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 35,
        data: 2, // ReplayPointer
        length_units: 2,
    };
    handle_allow_events(
        &mut state,
        &mut backend,
        ClientId(GRAB_CLIENT_ID),
        SequenceNumber(1),
        header,
        &[0u8; 4],
    )
    .expect("allow events replay pointer");

    assert!(state.active_pointer_grab.is_none());
    assert!(!kbd_frozen(&state), "the keyboard thaws with the grab");
}

/// Core `AllowEvents(ReplayKeyboard)` (mode 5 — what muffin/mutter
/// calls for a declined key) releases the passive keyboard grab and
/// replays the frozen key to the focused window. This is the
/// dead-`p`-in-wezterm fix end-to-end: a sync passive key grab held
/// `p`, the WM declined it, and ReplayKeyboard hands it to the
/// focused client.
#[test]
fn core_replay_keyboard_releases_grab_and_replays_to_focus() {
    use crate::{
        host_x11::HostKeyEvent,
        server::{ActiveKeyboardGrab, ActiveKeyboardGrabSource},
    };

    const GRAB_CLIENT_ID: u32 = 1;
    const FOCUS_CLIENT_ID: u32 = 2;
    const FOCUS_WIN: u32 = 0x0020_0061;
    const KEY_PRESS_MASK: u32 = 0x0000_0001;

    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();
    let _grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut focus_peer = install_client(&mut state, FOCUS_CLIENT_ID);
    focus_peer.set_nonblocking(true).unwrap();

    // Focused client selects core KeyPress on its window.
    {
        let c = state.clients.get_mut(&FOCUS_CLIENT_ID).unwrap();
        c.focused_window = ResourceId(FOCUS_WIN);
        c.event_masks.insert(ResourceId(FOCUS_WIN), KEY_PRESS_MASK);
    }
    state.core_focus.raw = FOCUS_WIN;

    // A sync passive key grab held by the WM is active, with a
    // frozen press waiting.
    state.active_keyboard_grab = Some(ActiveKeyboardGrab {
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ROOT_WINDOW,
        owner_events: false,
        source: ActiveKeyboardGrabSource::PassiveKey { keycode: 33 },
        via_xi2: true,
        xi2_mask: 0,
    });
    {
        let f = state
            .xi1_frozen
            .entry(crate::xinput::DEVICEID_MASTER_KEYBOARD)
            .or_default();
        f.state = crate::server::Xi1SyncState::FrozenWithEvent;
        f.stored = Some(crate::server::QueuedInputEvent::HostKey(HostKeyEvent {
            origin: crate::core_loop::InputOrigin::NestedHost,
            pressed: true,
            keycode: 33,
            time: 0x1234,
            root_x: 10,
            root_y: 20,
            event_x: 10,
            event_y: 20,
            state: 0,
        }));
    }

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 35,
        data: 5, // ReplayKeyboard
        length_units: 2,
    };
    handle_allow_events(
        &mut state,
        &mut backend,
        ClientId(GRAB_CLIENT_ID),
        SequenceNumber(1),
        header,
        &[0u8; 4],
    )
    .expect("allow events replay keyboard");

    assert!(
        state.active_keyboard_grab.is_none(),
        "ReplayKeyboard must release the passive keyboard grab"
    );
    assert!(
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_KEYBOARD)
            .and_then(|f| f.stored.as_ref())
            .is_none(),
        "the frozen key must be consumed by the replay"
    );
    let mut buf = [0u8; 64];
    let n = focus_peer.read(&mut buf).unwrap_or(0);
    assert!(
        n >= 32 && buf[0] == 2,
        "replayed KeyPress (event type 2) must reach the focused client; got n={n} type={}",
        buf[0]
    );
}

/// GH #59 regression (bspwm/sxhkd dead keyboard). sxhkd holds a
/// SYNCHRONOUS core passive key grab; after the activating chord
/// press freezes the keyboard it issues exactly ONE
/// AllowEvents(SyncKeyboard) and waits. The terminating key release
/// must reach `key_route` (device still FreezeNextEvent, NOT
/// re-frozen), deactivate the passive grab, and thaw — so typing
/// reaches the focused window. Pre-fix the SyncKeyboard
/// `FreezeNextEvent` allowance was consumed by replaying the grab's
/// OWN already-delivered activating press (double-booked in the XI1
/// queue), re-freezing to FrozenWithEvent; the release was then
/// withheld, the grab never deactivated, and the keyboard was dead.
/// Xorg's `ComputeFreezes` only replays the stored event for
/// `Replay*`, not `Sync*` (dix/events.c:1320-1370).
#[test]
fn sync_passive_kbd_grab_synckeyboard_release_thaws() {
    use crate::{
        core_loop::key_fanout::key_event_fanout_to_state,
        host_x11::HostKeyEvent,
        server::{KeyGrab, Xi1SyncState},
    };

    const GRAB_CLIENT_ID: u32 = 1; // sxhkd
    const FOCUS_CLIENT_ID: u32 = 2; // kitty
    const FOCUS_WIN: u32 = 0x0020_0091;
    const KEY_PRESS_MASK: u32 = 0x0000_0001;
    const RETURN_KC: u8 = 36;

    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();
    let _grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    let mut focus_peer = install_client(&mut state, FOCUS_CLIENT_ID);
    focus_peer.set_nonblocking(true).unwrap();
    {
        let c = state.clients.get_mut(&FOCUS_CLIENT_ID).unwrap();
        c.focused_window = ResourceId(FOCUS_WIN);
        c.event_masks.insert(ResourceId(FOCUS_WIN), KEY_PRESS_MASK);
    }
    state.core_focus.raw = FOCUS_WIN;

    // sxhkd's synchronous core passive grab on the chord key.
    state.key_grabs.push(KeyGrab {
        device_id: 0,
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ROOT_WINDOW,
        keycode: RETURN_KC,
        modifiers: 0,
        owner_events: true,
        pointer_mode: 1,
        keyboard_mode: 0, // synchronous → freeze
        via_xi2: false,
        xi2_mask: 0,
    });

    let key = |pressed, keycode| HostKeyEvent {
        origin: crate::core_loop::InputOrigin::NestedHost,
        pressed,
        keycode,
        time: 1,
        root_x: 0,
        root_y: 0,
        event_x: 0,
        event_y: 0,
        state: 0,
    };

    // 1) chord press activates the grab and freezes the device.
    let _ = key_event_fanout_to_state(&mut state, &mut backend, key(true, RETURN_KC));
    assert!(
        state.active_keyboard_grab.is_some(),
        "synchronous passive grab must activate on the chord press"
    );

    // 2) sxhkd issues a single AllowEvents(SyncKeyboard) (mode 4).
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 35,
        data: 4, // SyncKeyboard
        length_units: 2,
    };
    handle_allow_events(
        &mut state,
        &mut backend,
        ClientId(GRAB_CLIENT_ID),
        SequenceNumber(1),
        header,
        &[0u8; 4],
    )
    .expect("allow events sync keyboard");

    // 3) the terminating release must deactivate the grab and thaw.
    let _ = key_event_fanout_to_state(&mut state, &mut backend, key(false, RETURN_KC));
    assert!(
        state.active_keyboard_grab.is_none(),
        "the matching key release must deactivate the passive grab"
    );
    let frozen = state
        .xi1_frozen
        .get(&crate::xinput::DEVICEID_XTEST_KEYBOARD)
        .map_or(Xi1SyncState::Thawed, |f| f.state);
    assert_eq!(
        frozen,
        Xi1SyncState::Thawed,
        "the terminating release must thaw the keyboard (not leave it FrozenWithEvent)"
    );

    // 4) typing (an ungrabbed key) must now reach the focused window.
    let _ = key_event_fanout_to_state(&mut state, &mut backend, key(true, 38));
    let mut buf = [0u8; 64];
    let n = focus_peer.read(&mut buf).unwrap_or(0);
    assert!(
        n >= 32 && buf[0] == 2,
        "after the grab releases, typing must reach the focused window; got n={n} type={}",
        buf[0]
    );
}

/// Regression (codex review): ReplayKeyboard must release an
/// EXPLICIT GrabKeyboard(GrabModeSync), not just a passive key
/// grab — Xorg NOT_GRABBED calls DeactivateGrab regardless of
/// grab kind (dix/events.c:1898). Pre-fix the grab stayed active
/// after the replay → stuck keyboard.
#[test]
fn core_replay_keyboard_releases_explicit_sync_grab() {
    use crate::{
        host_x11::HostKeyEvent,
        server::{ActiveKeyboardGrab, ActiveKeyboardGrabSource},
    };

    const GRAB_CLIENT_ID: u32 = 1;
    const FOCUS_WIN: u32 = 0x0020_0071;

    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();
    let _grab_peer = install_client(&mut state, GRAB_CLIENT_ID);
    state.core_focus.raw = FOCUS_WIN;

    // Explicit GrabKeyboard(GrabModeSync): active grab + the
    // device frozen-no-event, with a key withheld in the freeze
    // queue (the "with event" condition for replay).
    state.active_keyboard_grab = Some(ActiveKeyboardGrab {
        owner: ClientId(GRAB_CLIENT_ID),
        grab_window: ROOT_WINDOW,
        owner_events: false,
        source: ActiveKeyboardGrabSource::Explicit,
        via_xi2: false,
        xi2_mask: 0,
    });
    {
        let f = state
            .xi1_frozen
            .entry(crate::xinput::DEVICEID_MASTER_KEYBOARD)
            .or_default();
        f.state = crate::server::Xi1SyncState::FrozenNoEvent;
        state
            .sync_pending
            .push_back(crate::server::PendingSyncEvent {
                device: crate::xinput::DEVICEID_MASTER_KEYBOARD,
                event: crate::server::QueuedInputEvent::HostKey(HostKeyEvent {
                    origin: crate::core_loop::InputOrigin::NestedHost,
                    pressed: true,
                    keycode: 38,
                    time: 0x2222,
                    root_x: 1,
                    root_y: 2,
                    event_x: 1,
                    event_y: 2,
                    state: 0,
                }),
            });
    }

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 35,
        data: 5, // ReplayKeyboard
        length_units: 2,
    };
    handle_allow_events(
        &mut state,
        &mut backend,
        ClientId(GRAB_CLIENT_ID),
        SequenceNumber(1),
        header,
        &[0u8; 4],
    )
    .expect("allow events replay keyboard");

    assert!(
        state.active_keyboard_grab.is_none(),
        "ReplayKeyboard must deactivate the explicit sync keyboard grab",
    );
}

/// XFixes `SetCursorName(cursor, "name")` interns the name as an
/// atom and stores it on the cursor; the subsequent
/// `GetCursorName(cursor)` returns the same atom + name bytes.
/// A cursor that was never named reports atom=0 (None) + empty
/// name, matching Xorg `xfixes/cursor.c:ProcXFixesGetCursorName`'s
/// `pCursor->name == 0` branch.
#[test]
fn xfixes_cursor_name_round_trip() {
    use std::io::Read;

    const CLIENT_ID: u32 = 1;
    const CURSOR_XID: u32 = 0x0090_0042;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();
    state
        .resources
        .create_cursor(ClientId(CLIENT_ID), ResourceId(CURSOR_XID));

    let name = b"xterm";
    // SetCursorName body: cursor(4) + nbytes(2) + pad(2) + name + pad.
    let mut set_body = Vec::with_capacity(16);
    set_body.extend_from_slice(&CURSOR_XID.to_le_bytes());
    #[allow(clippy::cast_possible_truncation)]
    set_body.extend_from_slice(&(name.len() as u16).to_le_bytes());
    set_body.extend_from_slice(&[0u8; 2]);
    set_body.extend_from_slice(name);
    while !set_body.len().is_multiple_of(4) {
        set_body.push(0);
    }

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 140, // XFIXES major (dispatcher reads minor from header.data)
        data: 23,    // SET_CURSOR_NAME
        length_units: 3,
    };
    handle_xfixes_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &set_body,
    )
    .expect("SetCursorName");

    // The atom must be stored on the cursor and resolve back to
    // the original name.
    let stored = state
        .resources
        .cursor_name_atom(ResourceId(CURSOR_XID))
        .expect("name atom present after SetCursorName");
    assert!(stored.0 != 0, "non-None atom expected for non-empty name");
    assert_eq!(
        state.atoms.name(stored).map(str::as_bytes),
        Some(name.as_ref()),
        "interned atom must reverse-resolve to the original name",
    );

    // GetCursorName body: cursor(4).
    let get_body = CURSOR_XID.to_le_bytes().to_vec();
    let get_header = yserver_protocol::x11::RequestHeader {
        opcode: 140,
        data: 24, // GET_CURSOR_NAME
        length_units: 2,
    };
    handle_xfixes_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(2),
        get_header,
        &get_body,
    )
    .expect("GetCursorName");

    peer.set_nonblocking(true).unwrap();
    let mut wire = Vec::new();
    let mut tmp = [0u8; 1024];
    loop {
        match peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => wire.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    // Reply layout: type(1) + pad(1) + sequence(2) + length(4) +
    // atom(4) + nbytes(2) + pad(18) + name(n) + pad-to-4.
    assert_eq!(wire[0], 1, "X_Reply type byte");
    let reply_atom = u32::from_le_bytes(wire[8..12].try_into().unwrap());
    let reply_nbytes = u16::from_le_bytes(wire[12..14].try_into().unwrap()) as usize;
    assert_eq!(reply_atom, stored.0, "reply atom matches stored atom");
    assert_eq!(reply_nbytes, name.len());
    assert_eq!(
        &wire[32..32 + name.len()],
        name,
        "reply name bytes match the original",
    );

    // GetCursorName on an unnamed cursor → atom=0, nbytes=0.
    const UNNAMED_XID: u32 = 0x0090_0099;
    state
        .resources
        .create_cursor(ClientId(CLIENT_ID), ResourceId(UNNAMED_XID));
    let get_body = UNNAMED_XID.to_le_bytes().to_vec();
    handle_xfixes_request(
        &mut state,
        &mut backend,
        None,
        ClientId(CLIENT_ID),
        SequenceNumber(3),
        get_header,
        &get_body,
    )
    .expect("GetCursorName unnamed");
    let mut wire2 = Vec::new();
    loop {
        match peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => wire2.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    let reply_atom = u32::from_le_bytes(wire2[8..12].try_into().unwrap());
    let reply_nbytes = u16::from_le_bytes(wire2[12..14].try_into().unwrap()) as usize;
    assert_eq!(reply_atom, 0, "unnamed cursor reports atom=0 (None)");
    assert_eq!(reply_nbytes, 0, "unnamed cursor reports empty name");
}

/// One XFIXES request through the real dispatcher (version gate
/// included), little-endian body.
fn xfixes_req(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    client: u32,
    minor: u8,
    body: &[u8],
) {
    process_request(
        state,
        backend,
        ClientId(client),
        SequenceNumber(1),
        RequestHeader {
            opcode: XFIXES_MAJOR_OPCODE,
            data: minor,
            length_units: u32::try_from(1 + body.len().div_ceil(4)).unwrap(),
        },
        body,
        None,
    )
    .expect("xfixes request");
}

fn xfixes_u32s(values: &[u32]) -> Vec<u8> {
    values.iter().flat_map(|v| v.to_le_bytes()).collect()
}

/// Split queued 32-byte packets (errors, events, fixed replies).
fn wire_packets(peer: &mut UnixStream) -> Vec<[u8; 32]> {
    read_all_available(peer)
        .chunks_exact(32)
        .map(|c| <[u8; 32]>::try_from(c).unwrap())
        .collect()
}

fn le_u32(p: &[u8], at: usize) -> u32 {
    u32::from_le_bytes(p[at..at + 4].try_into().unwrap())
}

/// Error packet → (code, bad value, minor, major).
fn error_fields(p: &[u8; 32]) -> (u8, u32, u16, u8) {
    assert_eq!(p[0], 0, "expected an error packet, got type {}", p[0]);
    (p[1], le_u32(p, 4), u16::from_le_bytes([p[8], p[9]]), p[10])
}

/// QueryVersion follows Xorg's rule and gates requests on the
/// negotiated major. Ground truth: Xorg 21.1.24 Xvfb, raw xcb probe —
/// HideCursor before QueryVersion is BadRequest (major 138 there,
/// minor 29, value 0); 4.0 → 4.0; then 2.0 → 2.0 while HideCursor
/// still succeeds and DeletePointerBarrier (a 5.0 request) is
/// BadRequest; 7.0 is capped at the server version.
#[test]
fn xfixes_query_version_negotiates_and_gates_requests() {
    use yserver_protocol::x11::xfixes as x11xfixes;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let root = ROOT_WINDOW.0;

    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::HIDE_CURSOR,
        &xfixes_u32s(&[root]),
    );
    let packets = wire_packets(&mut peer);
    assert_eq!(packets.len(), 1);
    assert_eq!(
        error_fields(&packets[0]),
        (x11::error::BAD_REQUEST, 0, 29, XFIXES_MAJOR_OPCODE)
    );
    assert!(state.xfixes_cursor_hide_counts.is_empty());

    let query = |state: &mut ServerState,
                 backend: &mut RecordingBackend,
                 peer: &mut UnixStream,
                 major: u32,
                 minor: u32| {
        xfixes_req(
            state,
            backend,
            1,
            x11xfixes::QUERY_VERSION,
            &xfixes_u32s(&[major, minor]),
        );
        let packets = wire_packets(peer);
        assert_eq!(packets.len(), 1);
        assert_eq!(packets[0][0], 1, "reply");
        (le_u32(&packets[0], 8), le_u32(&packets[0], 12))
    };
    assert_eq!(query(&mut state, &mut backend, &mut peer, 4, 0), (4, 0));
    assert_eq!(query(&mut state, &mut backend, &mut peer, 2, 0), (2, 0));

    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::HIDE_CURSOR,
        &xfixes_u32s(&[root]),
    );
    assert!(wire_packets(&mut peer).is_empty(), "4.0 request set kept");
    assert_eq!(state.xfixes_cursor_hide_counts.get(&1), Some(&1));

    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::DELETE_POINTER_BARRIER,
        &xfixes_u32s(&[0x1234]),
    );
    let packets = wire_packets(&mut peer);
    assert_eq!(
        error_fields(&packets[0]),
        (x11::error::BAD_REQUEST, 0, 32, XFIXES_MAJOR_OPCODE)
    );

    assert_eq!(query(&mut state, &mut backend, &mut peer, 7, 0), (5, 0));
    assert_eq!(query(&mut state, &mut backend, &mut peer, 3, 7), (3, 7));
}

/// Hide/Show counting, captured on Xvfb: bad window → BadWindow (value
/// = window) for both; ShowCursor without a hide → BadMatch (value =
/// window); two hides need two shows and a third show is BadMatch.
/// Across clients the sprite hides on the first hide anywhere and
/// comes back when the last hider shows or disconnects.
#[test]
fn xfixes_hide_show_cursor_counts_per_client() {
    use yserver_protocol::x11::xfixes as x11xfixes;
    let mut state = ServerState::new();
    let mut peer1 = install_client(&mut state, 1);
    let _peer2 = install_client(&mut state, 2);
    state.xfixes_client_major.insert(1, 5);
    state.xfixes_client_major.insert(2, 5);
    let mut backend = RecordingBackend::new();
    let root = ROOT_WINDOW.0;
    let hidden_calls = |backend: &RecordingBackend| -> Vec<bool> {
        backend
            .calls
            .lock()
            .unwrap()
            .iter()
            .filter_map(|c| match c {
                RecordedCall::SetCursorHidden(h) => Some(*h),
                _ => None,
            })
            .collect()
    };

    for minor in [x11xfixes::HIDE_CURSOR, x11xfixes::SHOW_CURSOR] {
        xfixes_req(
            &mut state,
            &mut backend,
            1,
            minor,
            &xfixes_u32s(&[0x0bad_bad0]),
        );
        let packets = wire_packets(&mut peer1);
        assert_eq!(
            error_fields(&packets[0]),
            (
                x11::error::BAD_WINDOW,
                0x0bad_bad0,
                u16::from(minor),
                XFIXES_MAJOR_OPCODE
            )
        );
    }
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::SHOW_CURSOR,
        &xfixes_u32s(&[root]),
    );
    let packets = wire_packets(&mut peer1);
    assert_eq!(
        error_fields(&packets[0]),
        (x11::error::BAD_MATCH, root, 30, XFIXES_MAJOR_OPCODE)
    );
    assert!(hidden_calls(&backend).is_empty());

    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::HIDE_CURSOR,
        &xfixes_u32s(&[root]),
    );
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::HIDE_CURSOR,
        &xfixes_u32s(&[root]),
    );
    xfixes_req(
        &mut state,
        &mut backend,
        2,
        x11xfixes::HIDE_CURSOR,
        &xfixes_u32s(&[root]),
    );
    assert_eq!(
        hidden_calls(&backend),
        vec![true],
        "one edge for three hides"
    );

    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::SHOW_CURSOR,
        &xfixes_u32s(&[root]),
    );
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::SHOW_CURSOR,
        &xfixes_u32s(&[root]),
    );
    assert!(wire_packets(&mut peer1).is_empty());
    assert_eq!(hidden_calls(&backend), vec![true], "client 2 still hides");
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::SHOW_CURSOR,
        &xfixes_u32s(&[root]),
    );
    let packets = wire_packets(&mut peer1);
    assert_eq!(
        error_fields(&packets[0]),
        (x11::error::BAD_MATCH, root, 30, XFIXES_MAJOR_OPCODE)
    );

    crate::core_loop::process_disconnect::process_disconnect(&mut state, &mut backend, ClientId(2));
    assert_eq!(
        hidden_calls(&backend),
        vec![true, false],
        "disconnect shows"
    );
    assert!(state.xfixes_cursor_hide_counts.is_empty());
    assert!(!state.xfixes_client_major.contains_key(&2));
}

/// CursorNotify fan-out, per the Xvfb capture: one event per
/// (client, window) selection carrying that window, the cursor serial
/// and its name atom; a destroyed window's selection is gone; bad mask
/// → BadValue, bad window → BadWindow.
#[test]
fn xfixes_cursor_notify_goes_to_each_selection() {
    use yserver_protocol::x11::xfixes as x11xfixes;
    const CHILD: u32 = 0x0040_0001;
    const CURSOR: u32 = 0x0040_0010;
    const HOST: u32 = 0x0001_0077;
    let mut state = ServerState::new();
    let mut peer1 = install_client(&mut state, 1);
    let mut peer2 = install_client(&mut state, 2);
    state.xfixes_client_major.insert(1, 5);
    state.xfixes_client_major.insert(2, 5);
    let mut backend = RecordingBackend::new();
    let root = ROOT_WINDOW.0;
    create_present_test_window(&mut state, CHILD, 0, 0, 10, 10);
    state
        .resources
        .create_cursor(ClientId(1), ResourceId(CURSOR));
    state.resources.set_cursor_host_xid(
        ResourceId(CURSOR),
        crate::backend::CursorHandle::from_raw(HOST).unwrap(),
    );
    let name = state.atoms.intern("bname", false);
    state
        .resources
        .set_cursor_name_atom(ResourceId(CURSOR), name);

    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::SELECT_CURSOR_INPUT,
        &xfixes_u32s(&[root, 2]),
    );
    assert_eq!(
        error_fields(&wire_packets(&mut peer1)[0]),
        (x11::error::BAD_VALUE, 2, 3, XFIXES_MAJOR_OPCODE)
    );
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::SELECT_CURSOR_INPUT,
        &xfixes_u32s(&[0x0bad_bad0, 1]),
    );
    assert_eq!(
        error_fields(&wire_packets(&mut peer1)[0]),
        (x11::error::BAD_WINDOW, 0x0bad_bad0, 3, XFIXES_MAJOR_OPCODE)
    );
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::SELECT_CURSOR_INPUT,
        &xfixes_u32s(&[root, 1]),
    );
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::SELECT_CURSOR_INPUT,
        &xfixes_u32s(&[CHILD, 1]),
    );
    assert!(wire_packets(&mut peer1).is_empty());

    backend.displayed_cursor_change = Some(crate::backend::DisplayedCursor {
        host_xid: HOST,
        serial: 3,
    });
    emit_xfixes_cursor_notify(&mut state, &mut backend);
    let events = wire_packets(&mut peer1);
    assert_eq!(events.len(), 2, "one per selection");
    let mut windows = Vec::new();
    for e in &events {
        assert_eq!(e[0], crate::nested::XFIXES_FIRST_EVENT + 1);
        assert_eq!(e[1], x11xfixes::DISPLAY_CURSOR_NOTIFY);
        windows.push(le_u32(e, 4));
        assert_eq!(le_u32(e, 8), 3, "serial");
        assert_eq!(le_u32(e, 16), name.0, "name atom");
    }
    windows.sort_unstable();
    assert_eq!(windows, vec![root, CHILD]);
    assert!(
        wire_packets(&mut peer2).is_empty(),
        "client 2 never selected"
    );
    emit_xfixes_cursor_notify(&mut state, &mut backend);
    assert!(
        wire_packets(&mut peer1).is_empty(),
        "the report is consumed"
    );

    // Destroying the child drops its selection (Xorg CursorFreeWindow).
    destroy_window_subtree(&mut state, &mut backend, None, ResourceId(CHILD));
    backend.displayed_cursor_change = Some(crate::backend::DisplayedCursor {
        host_xid: 0x0001_0099,
        serial: 1,
    });
    emit_xfixes_cursor_notify(&mut state, &mut backend);
    let events = wire_packets(&mut peer1);
    assert_eq!(events.len(), 1);
    assert_eq!(le_u32(&events[0], 4), root);
    assert_eq!(le_u32(&events[0], 16), 0, "unnamed cursor");
}

/// ChangeCursor: every XID of the destination cursor now names the
/// source cursor, and the backend replaces its displayed uses. Xvfb:
/// bad source / bad destination → BadCursor naming it.
#[test]
fn xfixes_change_cursor_retargets_cursor_and_backend() {
    use yserver_protocol::x11::xfixes as x11xfixes;
    const A: u32 = 0x0040_0020;
    const D: u32 = 0x0040_0021;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    state.xfixes_client_major.insert(1, 5);
    let mut backend = RecordingBackend::new();
    for (xid, host) in [(A, 0x0001_0010), (D, 0x0001_0020)] {
        state.resources.create_cursor(ClientId(1), ResourceId(xid));
        state.resources.set_cursor_host_xid(
            ResourceId(xid),
            crate::backend::CursorHandle::from_raw(host).unwrap(),
        );
    }

    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::CHANGE_CURSOR,
        &xfixes_u32s(&[0x0bad_bad0, A]),
    );
    assert_eq!(
        error_fields(&wire_packets(&mut peer)[0]),
        (x11::error::BAD_CURSOR, 0x0bad_bad0, 26, XFIXES_MAJOR_OPCODE)
    );
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::CHANGE_CURSOR,
        &xfixes_u32s(&[D, 0x0bad_bad0]),
    );
    assert_eq!(
        error_fields(&wire_packets(&mut peer)[0]),
        (x11::error::BAD_CURSOR, 0x0bad_bad0, 26, XFIXES_MAJOR_OPCODE)
    );

    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::CHANGE_CURSOR,
        &xfixes_u32s(&[D, A]),
    );
    assert!(wire_packets(&mut peer).is_empty());
    assert_eq!(
        state.resources.cursor_host_xid(ResourceId(A)),
        Some(0x0001_0020)
    );
    let calls = backend.calls.lock().unwrap().clone();
    assert!(calls.contains(&RecordedCall::ReplaceCursor {
        old_host_xid: 0x0001_0010,
        new_host_xid: 0x0001_0020,
    }));
    // A and D now share one host cursor: freeing one XID must not free it.
    assert_eq!(state.resources.free_cursor(ResourceId(A)), None);
    assert_eq!(
        state.resources.free_cursor(ResourceId(D)),
        Some(0x0001_0020)
    );
}

/// ChangeCursorByName matches the cursor object's name even after the
/// client freed its XID (the window still shows it); a name nobody
/// interned matches nothing and is not an error (Xvfb: OK).
#[test]
fn xfixes_change_cursor_by_name_replaces_named_cursors() {
    use yserver_protocol::x11::xfixes as x11xfixes;
    const A: u32 = 0x0040_0030;
    const B: u32 = 0x0040_0031;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    state.xfixes_client_major.insert(1, 5);
    let mut backend = RecordingBackend::new();
    for (xid, host) in [(A, 0x0001_0030), (B, 0x0001_0031)] {
        state.resources.create_cursor(ClientId(1), ResourceId(xid));
        state.resources.set_cursor_host_xid(
            ResourceId(xid),
            crate::backend::CursorHandle::from_raw(host).unwrap(),
        );
    }
    let name = state.atoms.intern("bname", false);
    state.resources.set_cursor_name_atom(ResourceId(B), name);
    let _ = state.resources.free_cursor(ResourceId(B));

    let by_name = |name: &[u8]| {
        let mut body = Vec::new();
        body.extend_from_slice(&A.to_le_bytes());
        body.extend_from_slice(&u16::try_from(name.len()).unwrap().to_le_bytes());
        body.extend_from_slice(&[0, 0]);
        body.extend_from_slice(name);
        body.resize(body.len().div_ceil(4) * 4, 0);
        body
    };
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::CHANGE_CURSOR_BY_NAME,
        &by_name(b"zzznoname"),
    );
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::CHANGE_CURSOR_BY_NAME,
        &by_name(b"bname"),
    );
    assert!(wire_packets(&mut peer).is_empty());
    let replaces: Vec<RecordedCall> = backend
        .calls
        .lock()
        .unwrap()
        .iter()
        .filter(|c| matches!(c, RecordedCall::ReplaceCursor { .. }))
        .cloned()
        .collect();
    assert_eq!(
        replaces,
        vec![RecordedCall::ReplaceCursor {
            old_host_xid: 0x0001_0031,
            new_host_xid: 0x0001_0030,
        }]
    );
    assert_eq!(state.resources.cursor_name_for_host(0x0001_0031), None);
}

/// ExpandRegion against Xvfb: {(10,10 5x5),(30,30 5x5)} expanded by
/// l1 r2 t3 b4 → {(9,7 8x12),(29,27 8x12)}; by l20 r20 → the
/// overlapping boxes are unioned into {(-10,10 45x5),(10,30 45x5)}; an
/// empty source leaves the destination as it was; bad source or
/// destination → XFixes BadRegion (error base + 0) naming it.
#[test]
fn xfixes_expand_region_matches_xvfb() {
    use yserver_protocol::x11::xfixes::{self as x11xfixes, RegionRect};
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    state.xfixes_client_major.insert(1, 5);
    let mut backend = RecordingBackend::new();
    let rect = |x, y, width, height| RegionRect {
        x,
        y,
        width,
        height,
    };
    let region = |rects| crate::server::XFixesRegion {
        owner: ClientId(1),
        rects,
    };
    state
        .xfixes_regions
        .insert(0x10, region(vec![rect(10, 10, 5, 5), rect(30, 30, 5, 5)]));
    state
        .xfixes_regions
        .insert(0x11, region(vec![rect(100, 100, 7, 7)]));
    state.xfixes_regions.insert(0x12, region(Vec::new()));
    let expand = |src: u32, dst: u32, l: u16, r: u16, t: u16, b: u16| {
        let mut body = xfixes_u32s(&[src, dst]);
        for v in [l, r, t, b] {
            body.extend_from_slice(&v.to_le_bytes());
        }
        body
    };

    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::EXPAND_REGION,
        &expand(0x10, 0x11, 1, 2, 3, 4),
    );
    assert_eq!(
        state.xfixes_regions[&0x11].rects,
        vec![rect(9, 7, 8, 12), rect(29, 27, 8, 12)]
    );
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::EXPAND_REGION,
        &expand(0x10, 0x11, 20, 20, 0, 0),
    );
    assert_eq!(
        state.xfixes_regions[&0x11].rects,
        vec![rect(-10, 10, 45, 5), rect(10, 30, 45, 5)]
    );
    xfixes_req(
        &mut state,
        &mut backend,
        1,
        x11xfixes::EXPAND_REGION,
        &expand(0x12, 0x11, 1, 1, 1, 1),
    );
    assert_eq!(
        state.xfixes_regions[&0x11].rects,
        vec![rect(-10, 10, 45, 5), rect(10, 30, 45, 5)]
    );
    assert!(wire_packets(&mut peer).is_empty());

    for (src, dst) in [(0x0bad_bad0, 0x11), (0x10, 0x0bad_bad0)] {
        xfixes_req(
            &mut state,
            &mut backend,
            1,
            x11xfixes::EXPAND_REGION,
            &expand(src, dst, 1, 1, 1, 1),
        );
        assert_eq!(
            error_fields(&wire_packets(&mut peer)[0]),
            (
                crate::nested::XFIXES_FIRST_ERROR,
                0x0bad_bad0,
                28,
                XFIXES_MAJOR_OPCODE
            )
        );
    }
}

// ── SYNC Await / AwaitFence ─────────────────────────────────────
// Ground truth for every expectation below: Xorg 21.1.24 Xvfb driven
// by a two-connection xcb probe (client A changes counters and fences,
// client B awaits and then sends GetInputFocus; "suspended" means B's
// reply had not arrived after A's round trip).

fn sync_req(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    client: u32,
    minor: u8,
    body: &[u8],
) {
    process_request(
        state,
        backend,
        ClientId(client),
        SequenceNumber(1),
        RequestHeader {
            opcode: 142,
            data: minor,
            length_units: u32::try_from(1 + body.len().div_ceil(4)).unwrap(),
        },
        body,
        None,
    )
    .expect("sync request");
}

fn sync_i64(v: i64) -> [u8; 8] {
    let mut out = [0u8; 8];
    #[allow(clippy::cast_possible_truncation)]
    out[..4].copy_from_slice(&((v >> 32) as i32).to_le_bytes());
    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
    out[4..].copy_from_slice(&(v as u32).to_le_bytes());
    out
}

fn sync_counter_body(counter: u32, value: i64) -> Vec<u8> {
    let mut body = counter.to_le_bytes().to_vec();
    body.extend_from_slice(&sync_i64(value));
    body
}

/// One `WAITCONDITION`: counter, value type, wait value, test type,
/// event threshold.
fn sync_wait(counter: u32, value_type: u32, wait: i64, test_type: u32, threshold: i64) -> Vec<u8> {
    let mut body = counter.to_le_bytes().to_vec();
    body.extend_from_slice(&value_type.to_le_bytes());
    body.extend_from_slice(&sync_i64(wait));
    body.extend_from_slice(&test_type.to_le_bytes());
    body.extend_from_slice(&sync_i64(threshold));
    body
}

/// CounterNotify → (counter, wait value, counter value, count, destroyed).
fn counter_notify_fields(p: &[u8; 32]) -> (u32, i64, i64, u16, bool) {
    assert_eq!(p[0], crate::nested::SYNC_FIRST_EVENT, "CounterNotify type");
    assert_eq!(p[1], 0, "kind CounterNotify");
    let i64_at = |at: usize| {
        #[allow(clippy::cast_possible_wrap)]
        let hi = le_u32(p, at) as i32;
        (i64::from(hi) << 32) | i64::from(le_u32(p, at + 4))
    };
    (
        le_u32(p, 4),
        i64_at(8),
        i64_at(16),
        u16::from_le_bytes([p[28], p[29]]),
        p[30] != 0,
    )
}

struct SyncFixture {
    state: ServerState,
    backend: RecordingBackend,
    _peer_a: UnixStream,
    peer_b: UnixStream,
}

const SYNC_A: u32 = 1;
const SYNC_B: u32 = 2;
const SYNC_C1: u32 = 0x0010_0001;
const SYNC_C2: u32 = 0x0010_0002;

fn sync_fixture() -> SyncFixture {
    let mut state = ServerState::new();
    let peer_a = install_client(&mut state, SYNC_A);
    let peer_b = install_client(&mut state, SYNC_B);
    SyncFixture {
        state,
        backend: RecordingBackend::new(),
        _peer_a: peer_a,
        peer_b,
    }
}

impl SyncFixture {
    fn a(&mut self, minor: u8, body: &[u8]) {
        sync_req(&mut self.state, &mut self.backend, SYNC_A, minor, body);
    }
    fn b(&mut self, minor: u8, body: &[u8]) {
        sync_req(&mut self.state, &mut self.backend, SYNC_B, minor, body);
    }
    fn suspended(&self) -> bool {
        crate::core_loop::sync_await::client_is_suspended(&self.state, ClientId(SYNC_B))
    }
    fn b_packets(&mut self) -> Vec<[u8; 32]> {
        wire_packets(&mut self.peer_b)
    }
    fn a_packets(&mut self) -> Vec<[u8; 32]> {
        wire_packets(&mut self._peer_a)
    }
}

/// Xvfb: B awaits c1 >= 5 (PositiveComparison); A sets 3 → B stays
/// suspended; A sets 7 → B resumes with CounterNotify(c1, wait 5,
/// value 7, count 0, not destroyed).
#[test]
fn sync_await_suspends_until_the_counter_condition_holds() {
    use yserver_protocol::x11::sync as s;
    let mut f = sync_fixture();
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 0));
    f.b(
        s::AWAIT,
        &sync_wait(
            SYNC_C1,
            s::VALUE_TYPE_ABSOLUTE,
            5,
            s::TEST_POSITIVE_COMPARISON,
            0,
        ),
    );
    assert!(f.suspended());
    assert!(f.b_packets().is_empty());
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 3));
    assert!(f.suspended(), "3 < 5");
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 7));
    assert!(!f.suspended());
    let events = f.b_packets();
    assert_eq!(events.len(), 1);
    assert_eq!(counter_notify_fields(&events[0]), (SYNC_C1, 5, 7, 0, false));

    // Already satisfied at request time: no suspension, the event
    // still goes out (Xvfb: reply arrives with CounterNotify wait 5
    // value 7).
    f.b(
        s::AWAIT,
        &sync_wait(
            SYNC_C1,
            s::VALUE_TYPE_ABSOLUTE,
            5,
            s::TEST_POSITIVE_COMPARISON,
            0,
        ),
    );
    assert!(!f.suspended());
    assert_eq!(
        counter_notify_fields(&f.b_packets()[0]),
        (SYNC_C1, 5, 7, 0, false)
    );
}

/// Transitions need a crossing and events respect the threshold, per
/// Xvfb: PositiveTransition 10 thr 2 from 7 → set 9 (no), set 12 →
/// event value 12; from 12, PositiveTransition 10 → set 1 does not
/// fire (no upward crossing); from 1, PositiveTransition 10 → 5 (no),
/// 11 → event; PositiveTransition 0 thr 5 from -5 → set 1 resumes the
/// client without an event (diff 1 < 5).
#[test]
fn sync_await_transitions_and_event_threshold() {
    use yserver_protocol::x11::sync as s;
    let mut f = sync_fixture();
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 7));
    f.b(
        s::AWAIT,
        &sync_wait(
            SYNC_C1,
            s::VALUE_TYPE_ABSOLUTE,
            10,
            s::TEST_POSITIVE_TRANSITION,
            2,
        ),
    );
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 9));
    assert!(f.suspended());
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 12));
    assert!(!f.suspended());
    assert_eq!(
        counter_notify_fields(&f.b_packets()[0]),
        (SYNC_C1, 10, 12, 0, false)
    );

    f.b(
        s::AWAIT,
        &sync_wait(
            SYNC_C1,
            s::VALUE_TYPE_ABSOLUTE,
            10,
            s::TEST_POSITIVE_TRANSITION,
            100,
        ),
    );
    assert!(f.suspended(), "12 >= 10 but no transition yet");
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 1));
    assert!(f.suspended());
    f.state.sync_awaits.remove(&SYNC_B);

    f.b(
        s::AWAIT,
        &sync_wait(
            SYNC_C1,
            s::VALUE_TYPE_ABSOLUTE,
            10,
            s::TEST_POSITIVE_TRANSITION,
            0,
        ),
    );
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 5));
    assert!(f.suspended());
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 11));
    assert!(!f.suspended());
    assert_eq!(
        counter_notify_fields(&f.b_packets()[0]),
        (SYNC_C1, 10, 11, 0, false)
    );

    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, -5));
    f.b(
        s::AWAIT,
        &sync_wait(
            SYNC_C1,
            s::VALUE_TYPE_ABSOLUTE,
            0,
            s::TEST_POSITIVE_TRANSITION,
            5,
        ),
    );
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 1));
    assert!(!f.suspended());
    assert!(f.b_packets().is_empty(), "diff below threshold: no event");
}

/// Xvfb: c1=11, c2=100; B awaits [c1 >= 1000 thr -2000, c2 <= 45 thr
/// 0]; A sets c2 50 (suspended) then 40 → both conditions report, in
/// order, count 1 then 0. Relative waits add to the counter (c1=11,
/// +3 → wait 14); NegativeTransition -3 fires on the way down.
#[test]
fn sync_await_multi_condition_relative_and_negative() {
    use yserver_protocol::x11::sync as s;
    let mut f = sync_fixture();
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 11));
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C2, 100));
    let mut body = sync_wait(
        SYNC_C1,
        s::VALUE_TYPE_ABSOLUTE,
        1000,
        s::TEST_POSITIVE_COMPARISON,
        -2000,
    );
    body.extend(sync_wait(
        SYNC_C2,
        s::VALUE_TYPE_ABSOLUTE,
        45,
        s::TEST_NEGATIVE_COMPARISON,
        0,
    ));
    f.b(s::AWAIT, &body);
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C2, 50));
    assert!(f.suspended());
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C2, 40));
    assert!(!f.suspended());
    let events = f.b_packets();
    assert_eq!(events.len(), 2);
    assert_eq!(
        counter_notify_fields(&events[0]),
        (SYNC_C1, 1000, 11, 1, false)
    );
    assert_eq!(
        counter_notify_fields(&events[1]),
        (SYNC_C2, 45, 40, 0, false)
    );

    f.b(
        s::AWAIT,
        &sync_wait(
            SYNC_C1,
            s::VALUE_TYPE_RELATIVE,
            3,
            s::TEST_POSITIVE_COMPARISON,
            0,
        ),
    );
    f.a(s::CHANGE_COUNTER, &sync_counter_body(SYNC_C1, 2));
    assert!(f.suspended());
    f.a(s::CHANGE_COUNTER, &sync_counter_body(SYNC_C1, 1));
    assert!(!f.suspended());
    assert_eq!(
        counter_notify_fields(&f.b_packets()[0]),
        (SYNC_C1, 14, 14, 0, false)
    );

    f.b(
        s::AWAIT,
        &sync_wait(
            SYNC_C1,
            s::VALUE_TYPE_ABSOLUTE,
            -3,
            s::TEST_NEGATIVE_TRANSITION,
            0,
        ),
    );
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, -5));
    assert!(!f.suspended());
    assert_eq!(
        counter_notify_fields(&f.b_packets()[0]),
        (SYNC_C1, -3, -5, 0, false)
    );
}

/// Xvfb: destroying an awaited counter resumes the client with a
/// destroyed event carrying its last value, plus threshold events for
/// the other conditions; an alarm on it goes Inactive with an
/// AlarmNotify. A counter owner disconnecting does the same (value 0).
#[test]
fn sync_await_fires_destroyed_when_the_counter_goes_away() {
    use yserver_protocol::x11::sync as s;
    let mut f = sync_fixture();
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, -5));
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C2, 40));
    let mut body = sync_wait(
        SYNC_C1,
        s::VALUE_TYPE_ABSOLUTE,
        1000,
        s::TEST_POSITIVE_COMPARISON,
        0,
    );
    body.extend(sync_wait(
        SYNC_C2,
        s::VALUE_TYPE_ABSOLUTE,
        1000,
        s::TEST_POSITIVE_COMPARISON,
        -2000,
    ));
    f.b(s::AWAIT, &body);
    f.state.sync_alarms.insert(
        0x0020_0009,
        crate::server::SyncAlarm {
            owner: ClientId(SYNC_B),
            counter: SYNC_C1,
            wait_value: 1000,
            delta: 1,
            test_type: s::TEST_POSITIVE_COMPARISON,
            events: true,
            state: s::ALARM_STATE_ACTIVE,
            event_clients: Vec::new(),
            value_type: 0,
            raw_wait: 1000,
            check_type: s::TEST_POSITIVE_COMPARISON,
        },
    );
    f.a(s::DESTROY_COUNTER, &SYNC_C1.to_le_bytes());
    assert!(!f.suspended());
    let packets = f.b_packets();
    let notifies: Vec<_> = packets
        .iter()
        .filter(|p| p[0] == crate::nested::SYNC_FIRST_EVENT)
        .map(counter_notify_fields)
        .collect();
    assert_eq!(
        notifies,
        vec![(SYNC_C1, 1000, -5, 1, true), (SYNC_C2, 1000, 40, 0, false)]
    );
    let alarm = packets
        .iter()
        .find(|p| p[0] == crate::nested::SYNC_FIRST_EVENT + 1)
        .expect("AlarmNotify for the alarm on the destroyed counter");
    assert_eq!(alarm[28], s::ALARM_STATE_INACTIVE);
    assert_eq!(
        f.state.sync_alarms[&0x0020_0009].state,
        s::ALARM_STATE_INACTIVE
    );
    assert_eq!(f.state.sync_alarms[&0x0020_0009].counter, 0);

    // Owner disconnect: Xvfb sends destroyed, wait 10, value 0.
    const C3: u32 = 0x0030_0001;
    let _peer_c = install_client(&mut f.state, 3);
    sync_req(
        &mut f.state,
        &mut f.backend,
        3,
        s::CREATE_COUNTER,
        &sync_counter_body(C3, 0),
    );
    f.b(
        s::AWAIT,
        &sync_wait(
            C3,
            s::VALUE_TYPE_ABSOLUTE,
            10,
            s::TEST_POSITIVE_COMPARISON,
            0,
        ),
    );
    assert!(f.suspended());
    crate::core_loop::process_disconnect::process_disconnect(
        &mut f.state,
        &mut f.backend,
        ClientId(3),
    );
    assert!(!f.suspended());
    assert_eq!(
        counter_notify_fields(&f.b_packets()[0]),
        (C3, 10, 0, 0, true)
    );
}

/// Xvfb: Initialize with client 3.1 / 3.0 / 2.0 / 4.0 always replies 3.1.
#[test]
fn sync_initialize_always_answers_the_server_version() {
    use yserver_protocol::x11::sync as s;
    let mut f = sync_fixture();
    for (major, minor) in [(3u8, 1u8), (3, 0), (2, 0), (4, 0)] {
        f.b(s::INITIALIZE, &[major, minor, 0, 0]);
        let reply = f.b_packets();
        assert_eq!(reply[0][0], 1);
        assert_eq!((reply[0][8], reply[0][9]), (3, 1), "client {major}.{minor}");
    }
}

/// Xvfb error table for Await and the counter requests.
#[test]
fn sync_await_and_counter_errors_match_xvfb() {
    use yserver_protocol::x11::sync as s;
    let mut f = sync_fixture();
    let bad_counter = crate::nested::SYNC_FIRST_ERROR + s::BAD_COUNTER;
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C2, 100));
    let cases: [(Vec<u8>, u8, u32); 6] = [
        (Vec::new(), x11::error::BAD_VALUE, 0),
        (sync_wait(0, 0, 1, 2, 0), bad_counter, 0),
        (sync_wait(0x0bad_bad0, 0, 1, 2, 0), bad_counter, 0x0bad_bad0),
        (sync_wait(SYNC_C2, 7, 1, 2, 0), x11::error::BAD_VALUE, 7),
        (sync_wait(SYNC_C2, 0, 1, 9, 0), x11::error::BAD_VALUE, 9),
        (
            sync_wait(SYNC_C2, 1, i64::MAX, 2, 0),
            x11::error::BAD_VALUE,
            0x7fff_ffff,
        ),
    ];
    for (body, code, value) in cases {
        f.b(s::AWAIT, &body);
        assert!(!f.suspended(), "an erroring Await never suspends");
        assert_eq!(
            error_fields(&f.b_packets()[0]),
            (code, value, u16::from(s::AWAIT), 142)
        );
    }
    let mut peer_a = std::mem::replace(&mut f._peer_a, UnixStream::pair().unwrap().0);
    let st = s::SERVERTIME_COUNTER;
    let a_cases: [(u8, Vec<u8>, u8, u32); 5] = [
        (
            s::SET_COUNTER,
            sync_counter_body(st, 1),
            x11::error::BAD_ACCESS,
            st,
        ),
        (
            s::SET_COUNTER,
            sync_counter_body(0x0bad_bad0, 1),
            bad_counter,
            0x0bad_bad0,
        ),
        (
            s::CHANGE_COUNTER,
            sync_counter_body(SYNC_C2, i64::MAX),
            x11::error::BAD_VALUE,
            0x7fff_ffff,
        ),
        (
            s::DESTROY_COUNTER,
            st.to_le_bytes().to_vec(),
            x11::error::BAD_ACCESS,
            st,
        ),
        (
            s::DESTROY_COUNTER,
            0x0bad_bad0u32.to_le_bytes().to_vec(),
            bad_counter,
            0x0bad_bad0,
        ),
    ];
    for (minor, body, code, value) in a_cases {
        f.a(minor, &body);
        assert_eq!(
            error_fields(&wire_packets(&mut peer_a)[0]),
            (code, value, u16::from(minor), 142)
        );
    }
    assert_eq!(
        f.state.sync_counters[&SYNC_C2].value, 100,
        "overflow left it alone"
    );
}

/// Xvfb: AwaitFence on an untriggered fence suspends until TriggerFence
/// (no events); on a triggered fence it returns at once; destroying the
/// fence resumes with CounterNotify(counter = fence, 0, 0, destroyed).
/// Errors: empty → BadValue, None / unknown → BadFence; ResetFence of an
/// untriggered fence → BadMatch naming it.
#[test]
fn sync_await_fence_suspends_until_triggered() {
    use yserver_protocol::x11::sync as s;
    const F1: u32 = 0x0010_0010;
    const F2: u32 = 0x0010_0011;
    let mut f = sync_fixture();
    let fence_body = |fence: u32, triggered: bool| {
        let mut body = ROOT_WINDOW.0.to_le_bytes().to_vec();
        body.extend_from_slice(&fence.to_le_bytes());
        body.extend_from_slice(&[u8::from(triggered), 0, 0, 0]);
        body
    };
    f.a(s::CREATE_FENCE, &fence_body(F1, false));
    f.a(s::CREATE_FENCE, &fence_body(F2, true));

    f.b(s::AWAIT_FENCE, &F1.to_le_bytes());
    assert!(f.suspended());
    f.a(s::TRIGGER_FENCE, &F1.to_le_bytes());
    assert!(!f.suspended());
    assert!(
        f.b_packets().is_empty(),
        "fences send no events when triggered"
    );

    f.b(s::AWAIT_FENCE, &F2.to_le_bytes());
    assert!(!f.suspended(), "already triggered");

    f.a(s::RESET_FENCE, &F1.to_le_bytes());
    f.b(s::AWAIT_FENCE, &F1.to_le_bytes());
    assert!(f.suspended());
    f.a(s::DESTROY_FENCE, &F1.to_le_bytes());
    assert!(!f.suspended());
    assert_eq!(
        counter_notify_fields(&f.b_packets()[0]),
        (F1, 0, 0, 0, true)
    );

    let bad_fence = crate::nested::SYNC_FIRST_ERROR + s::BAD_FENCE;
    for (body, code, value) in [
        (Vec::new(), x11::error::BAD_VALUE, 0),
        (0u32.to_le_bytes().to_vec(), bad_fence, 0),
        (
            0x0bad_bad0u32.to_le_bytes().to_vec(),
            bad_fence,
            0x0bad_bad0,
        ),
    ] {
        f.b(s::AWAIT_FENCE, &body);
        assert!(!f.suspended());
        assert_eq!(
            error_fields(&f.b_packets()[0]),
            (code, value, u16::from(s::AWAIT_FENCE), 142)
        );
    }
    f.b(s::RESET_FENCE, &F2.to_le_bytes());
    f.b(s::RESET_FENCE, &F2.to_le_bytes());
    assert_eq!(
        error_fields(&f.b_packets()[0]),
        (x11::error::BAD_MATCH, F2, u16::from(s::RESET_FENCE), 142)
    );
}

/// A Present idle fence triggered by the server wakes an AwaitFence on
/// it. A deliberate difference from Xorg: `present_fence_set_triggered`
/// only calls the fence's `SetTriggered`, not `miSyncTriggerFence`, so
/// on Xorg such an await is only re-checked by a TriggerFence request
/// or the fence's destruction and would otherwise stay suspended.
#[test]
fn sync_await_fence_wakes_on_server_side_trigger() {
    use yserver_protocol::x11::sync as s;
    const F1: u32 = 0x0010_0020;
    let mut f = sync_fixture();
    f.state.sync_fences.insert(
        F1,
        crate::server::SyncFence {
            owner: ClientId(SYNC_A),
            triggered: false,
        },
    );
    f.b(s::AWAIT_FENCE, &F1.to_le_bytes());
    assert!(f.suspended());
    crate::core_loop::sync_await::fence_triggered(&mut f.state, F1);
    assert!(!f.suspended());
    assert!(f.state.sync_fences[&F1].triggered);
}

/// A ChangeAlarm body: alarm, value mask, value list.
fn sync_alarm_body(alarm: u32, mask: u32, values: &[u32]) -> Vec<u8> {
    let mut body = alarm.to_le_bytes().to_vec();
    body.extend_from_slice(&mask.to_le_bytes());
    for v in values {
        body.extend_from_slice(&v.to_le_bytes());
    }
    body
}

/// Xvfb: ChangeAlarm / QueryAlarm / DestroyAlarm on an alarm that
/// does not exist (unknown, None, or destroyed) answer BadAlarm (SYNC
/// error base + 1) naming it. Xorg's order: QueryAlarm and DestroyAlarm
/// check the exact request size first (BadLength), ChangeAlarm checks
/// the minimum size, then looks the alarm up, and only then matches the
/// value list against the mask (BadLength naming the alarm).
#[test]
fn sync_alarm_requests_on_a_missing_alarm_answer_bad_alarm() {
    use yserver_protocol::x11::sync as s;
    const ALARM: u32 = 0x0010_0030;
    const GONE: u32 = 0x0010_0031;
    const UNKNOWN: u32 = 0x0bad_bad0;
    let bad_alarm = crate::nested::SYNC_FIRST_ERROR + s::BAD_ALARM;
    let bad_length = x11::error::BAD_LENGTH;
    let mut f = sync_fixture();
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 0));
    f.a(
        s::CREATE_ALARM,
        &sync_alarm_body(ALARM, s::CA_COUNTER, &[SYNC_C1]),
    );
    f.a(
        s::CREATE_ALARM,
        &sync_alarm_body(GONE, s::CA_COUNTER, &[SYNC_C1]),
    );
    f.a(s::DESTROY_ALARM, &GONE.to_le_bytes());
    let _ = f.b_packets();
    let long = sync_alarm_body(UNKNOWN, s::CA_EVENTS, &[]);
    let cases: Vec<(u8, Vec<u8>, u8, u32)> = vec![
        (
            s::QUERY_ALARM,
            UNKNOWN.to_le_bytes().to_vec(),
            bad_alarm,
            UNKNOWN,
        ),
        (s::QUERY_ALARM, 0u32.to_le_bytes().to_vec(), bad_alarm, 0),
        (s::QUERY_ALARM, GONE.to_le_bytes().to_vec(), bad_alarm, GONE),
        (
            s::CHANGE_ALARM,
            sync_alarm_body(UNKNOWN, 0, &[]),
            bad_alarm,
            UNKNOWN,
        ),
        (
            s::CHANGE_ALARM,
            sync_alarm_body(GONE, 0, &[]),
            bad_alarm,
            GONE,
        ),
        (s::CHANGE_ALARM, long.clone(), bad_alarm, UNKNOWN),
        (
            s::DESTROY_ALARM,
            UNKNOWN.to_le_bytes().to_vec(),
            bad_alarm,
            UNKNOWN,
        ),
        (
            s::DESTROY_ALARM,
            GONE.to_le_bytes().to_vec(),
            bad_alarm,
            GONE,
        ),
        (s::QUERY_ALARM, long.clone(), bad_length, 0),
        (s::DESTROY_ALARM, long, bad_length, 0),
        (
            s::CHANGE_ALARM,
            UNKNOWN.to_le_bytes().to_vec(),
            bad_length,
            0,
        ),
        (
            s::CHANGE_ALARM,
            sync_alarm_body(ALARM, s::CA_EVENTS, &[]),
            bad_length,
            ALARM,
        ),
        (
            s::CHANGE_ALARM,
            sync_alarm_body(ALARM, s::CA_VALUE, &[0]),
            bad_length,
            ALARM,
        ),
    ];
    for (minor, body, code, value) in cases {
        f.b(minor, &body);
        let packets = f.b_packets();
        assert!(
            !packets.is_empty(),
            "minor {minor} body {body:x?}: no error"
        );
        assert_eq!(
            error_fields(&packets[0]),
            (code, value, u16::from(minor), 142),
            "minor {minor} body {body:x?}"
        );
    }
    assert!(f.state.sync_alarms.contains_key(&ALARM));
}

/// QueryAlarm → (counter, value type, wait value, test type, delta,
/// events, state), per `xSyncQueryAlarmReply`.
fn query_alarm_fields(f: &mut SyncFixture, alarm: u32) -> (u32, u32, i64, u32, i64, u8, u8) {
    use yserver_protocol::x11::sync as s;
    f.b(s::QUERY_ALARM, &alarm.to_le_bytes());
    let r = read_all_available(&mut f.peer_b);
    assert_eq!((r.len(), r[0]), (40, 1), "QueryAlarm reply");
    let i64_at = |at: usize| {
        #[allow(clippy::cast_possible_wrap)]
        let hi = le_u32(&r, at) as i32;
        (i64::from(hi) << 32) | i64::from(le_u32(&r, at + 4))
    };
    (
        le_u32(&r, 8),
        le_u32(&r, 12),
        i64_at(16),
        le_u32(&r, 24),
        i64_at(28),
        r[36],
        r[37],
    )
}

/// Xvfb: QueryAlarm reports the alarm's test type (a fresh alarm's
/// default is PositiveComparison, 2) and, as Xorg's
/// `ProcSyncQueryAlarm`, always value type Absolute with the resolved
/// wait value.
#[test]
fn sync_query_alarm_reports_the_test_type() {
    use yserver_protocol::x11::sync as s;
    const AL: u32 = 0x0010_0080;
    const AN: u32 = 0x0010_0081;
    let mut f = sync_fixture();
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 0));
    f.a(
        s::CREATE_ALARM,
        &sync_alarm_body(AL, s::CA_COUNTER | s::CA_VALUE, &[SYNC_C1, 0, 10]),
    );
    assert_eq!(
        query_alarm_fields(&mut f, AL),
        (
            SYNC_C1,
            s::VALUE_TYPE_ABSOLUTE,
            10,
            s::TEST_POSITIVE_COMPARISON,
            1,
            1,
            s::ALARM_STATE_ACTIVE
        )
    );
    f.a(s::CREATE_ALARM, &sync_alarm_body(AN, s::CA_VALUE, &[0, 5]));
    assert_eq!(
        query_alarm_fields(&mut f, AN),
        (
            0,
            s::VALUE_TYPE_ABSOLUTE,
            5,
            s::TEST_POSITIVE_COMPARISON,
            1,
            1,
            s::ALARM_STATE_INACTIVE
        )
    );
}

/// Xvfb ("CreateAlarm attribute errors"): Xorg's checks, in its order —
/// the value list in mask-bit order (`events` not True/False, unknown
/// bits naming the bits above), the delta sign against the test type
/// (the default delta 1 counts), then the trigger: unknown counter,
/// value type, Relative without a counter, INT64 overflow (naming the
/// value's high word), test type. BadMatch names the alarm. A failing
/// CreateAlarm creates nothing.
#[test]
fn sync_create_alarm_attribute_errors_match_xvfb() {
    use yserver_protocol::x11::sync as s;
    let mut f = sync_fixture();
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 14));
    let bad_counter = crate::nested::SYNC_FIRST_ERROR + s::BAD_COUNTER;
    let (value, matchh) = (x11::error::BAD_VALUE, x11::error::BAD_MATCH);
    let c = SYNC_C1;
    let unknown = 0x0bad_bad0;
    // (mask, values, expected error (code, value; None = the alarm id)).
    type Case = (u32, Vec<u32>, Option<(u8, Option<u32>)>);
    let cases: Vec<Case> = vec![
        (
            s::CA_COUNTER | s::CA_TEST_TYPE,
            vec![c, 9],
            Some((value, Some(9))),
        ),
        (
            s::CA_COUNTER | s::CA_VALUE_TYPE,
            vec![c, 7],
            Some((value, Some(7))),
        ),
        (
            s::CA_COUNTER | s::CA_EVENTS,
            vec![c, 2],
            Some((value, Some(2))),
        ),
        (
            s::CA_COUNTER,
            vec![unknown],
            Some((bad_counter, Some(unknown))),
        ),
        (
            s::CA_VALUE_TYPE,
            vec![s::VALUE_TYPE_RELATIVE],
            Some((matchh, None)),
        ),
        (
            s::CA_COUNTER | s::CA_TEST_TYPE | s::CA_DELTA,
            vec![c, s::TEST_POSITIVE_COMPARISON, u32::MAX, u32::MAX],
            Some((matchh, None)),
        ),
        (
            s::CA_COUNTER | s::CA_TEST_TYPE,
            vec![c, s::TEST_NEGATIVE_COMPARISON],
            Some((matchh, None)),
        ),
        (
            s::CA_COUNTER | s::CA_TEST_TYPE | s::CA_DELTA,
            vec![c, s::TEST_NEGATIVE_COMPARISON, 0, 0],
            None,
        ),
        (
            s::CA_COUNTER | s::CA_VALUE_TYPE | s::CA_VALUE,
            vec![c, s::VALUE_TYPE_RELATIVE, 0x7fff_ffff, u32::MAX],
            Some((value, Some(0x7fff_ffff))),
        ),
        (
            s::CA_COUNTER | s::CA_TEST_TYPE,
            vec![unknown, 9],
            Some((bad_counter, Some(unknown))),
        ),
        (
            s::CA_VALUE_TYPE | s::CA_TEST_TYPE,
            vec![7, 9],
            Some((value, Some(7))),
        ),
        (1 << 6, vec![0], Some((value, Some(0)))),
        (s::CA_EVENTS | 1 << 6, vec![2, 0], Some((value, Some(2)))),
    ];
    for (index, (mask, values, expect)) in cases.into_iter().enumerate() {
        let alarm = 0x0020_0100 + u32::try_from(index).unwrap();
        f.b(s::CREATE_ALARM, &sync_alarm_body(alarm, mask, &values));
        let packets = f.b_packets();
        match expect {
            Some((code, bad)) => {
                assert_eq!(
                    error_fields(&packets[0]),
                    (code, bad.unwrap_or(alarm), u16::from(s::CREATE_ALARM), 142),
                    "case {index}"
                );
                assert!(!f.state.sync_alarms.contains_key(&alarm), "case {index}");
            }
            None => {
                assert!(packets.is_empty(), "case {index}");
                assert!(f.state.sync_alarms.contains_key(&alarm), "case {index}");
            }
        }
    }
}

/// Xvfb ("ChangeAlarm attribute errors: what sticks"): a failing
/// ChangeAlarm keeps what Xorg's `SyncChangeAlarmAttributes` stored
/// before `SyncInitTrigger` failed — delta, value type, value and the
/// test type — while the counter, the resolved wait value (except an
/// overflowing Relative sum, which is stored wrapped), the test the
/// trigger runs and the state stay. A stored bad value type makes a
/// later value-only change Relative; a stored bad test type is what
/// QueryAlarm reports, passes the delta-sign check, and the alarm keeps
/// firing on its old PositiveComparison.
#[test]
fn sync_change_alarm_failures_keep_what_xorg_keeps() {
    use yserver_protocol::x11::sync as s;
    const X: u32 = 0x0010_0090;
    let mut f = sync_fixture();
    let bad_counter = crate::nested::SYNC_FIRST_ERROR + s::BAD_COUNTER;
    let (value, matchh) = (x11::error::BAD_VALUE, x11::error::BAD_MATCH);
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 20));
    f.a(
        s::CREATE_ALARM,
        &sync_alarm_body(
            X,
            s::CA_COUNTER | s::CA_VALUE_TYPE | s::CA_VALUE | s::CA_TEST_TYPE | s::CA_DELTA,
            &[SYNC_C1, 0, 0, 30, s::TEST_POSITIVE_COMPARISON, 0, 1],
        ),
    );
    let q = |f: &mut SyncFixture| query_alarm_fields(f, X);
    let pc = s::TEST_POSITIVE_COMPARISON;
    assert_eq!(q(&mut f), (SYNC_C1, 0, 30, pc, 1, 1, 0));
    let change = |f: &mut SyncFixture, mask: u32, values: &[u32]| {
        f.a(s::CHANGE_ALARM, &sync_alarm_body(X, mask, values));
        f.a_packets()
            .first()
            .map(error_fields)
            .map(|(code, bad, minor, _)| {
                assert_eq!(minor, u16::from(s::CHANGE_ALARM));
                (code, bad)
            })
    };
    let m = u32::MAX;
    assert_eq!(
        change(&mut f, s::CA_VALUE_TYPE | s::CA_VALUE, &[7, 0, 50]),
        Some((value, 7))
    );
    assert_eq!(q(&mut f), (SYNC_C1, 0, 30, pc, 1, 1, 0));
    assert_eq!(change(&mut f, s::CA_VALUE, &[0, 5]), None);
    assert_eq!(
        q(&mut f),
        (SYNC_C1, 0, 25, pc, 1, 1, 0),
        "stored type 7 acts Relative"
    );
    assert_eq!(
        change(
            &mut f,
            s::CA_COUNTER | s::CA_VALUE | s::CA_DELTA,
            &[0x0bad_bad0, 0, 70, 0, 3]
        ),
        Some((bad_counter, 0x0bad_bad0))
    );
    assert_eq!(q(&mut f), (SYNC_C1, 0, 25, pc, 3, 1, 0), "delta sticks");
    assert_eq!(change(&mut f, s::CA_DELTA, &[m, m]), Some((matchh, X)));
    assert_eq!(
        change(
            &mut f,
            s::CA_VALUE_TYPE | s::CA_VALUE | s::CA_TEST_TYPE,
            &[0, 0, 100, s::TEST_NEGATIVE_TRANSITION]
        ),
        Some((matchh, X))
    );
    assert_eq!(q(&mut f), (SYNC_C1, 0, 25, pc, 3, 1, 0));
    assert_eq!(change(&mut f, s::CA_TEST_TYPE, &[9]), Some((value, 9)));
    assert_eq!(q(&mut f), (SYNC_C1, 0, 25, 9, 3, 1, 0));
    assert_eq!(
        change(&mut f, s::CA_DELTA, &[m, m]),
        None,
        "no sign for test type 9"
    );
    assert_eq!(q(&mut f), (SYNC_C1, 0, 25, 9, -1, 1, 0));
    assert_eq!(change(&mut f, s::CA_DELTA, &[0, 1]), None);
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 25));
    assert_eq!(
        alarm_notifies(&f.a_packets()),
        vec![(X, 25, 25, s::ALARM_STATE_ACTIVE)]
    );
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 21));
    assert!(f.a_packets().is_empty());
    assert_eq!(q(&mut f), (SYNC_C1, 0, 26, 9, 1, 1, 0));
    f.a(s::CHANGE_ALARM, &sync_alarm_body(X, s::CA_COUNTER, &[0]));
    assert_eq!(
        alarm_notifies(&f.a_packets()),
        vec![(X, 0, 26, s::ALARM_STATE_INACTIVE)]
    );
    assert_eq!(
        change(&mut f, s::CA_VALUE_TYPE, &[s::VALUE_TYPE_RELATIVE]),
        Some((matchh, X))
    );
    assert_eq!(q(&mut f), (0, 0, 26, 9, 1, 1, s::ALARM_STATE_INACTIVE));
    assert_eq!(
        change(
            &mut f,
            s::CA_COUNTER | s::CA_VALUE_TYPE | s::CA_VALUE,
            &[SYNC_C1, s::VALUE_TYPE_RELATIVE, 0x7fff_ffff, m]
        ),
        Some((value, 0x7fff_ffff))
    );
    let wrapped = 21i64.wrapping_add(i64::MAX);
    assert_eq!(q(&mut f), (0, 0, wrapped, 9, 1, 1, s::ALARM_STATE_INACTIVE));
    assert_eq!(change(&mut f, 1 << 6, &[0]), Some((value, 0)));
    f.a(s::DESTROY_ALARM, &X.to_le_bytes());
    assert_eq!(
        alarm_notifies(&f.a_packets()),
        vec![(X, 0, wrapped, s::ALARM_STATE_DESTROYED)]
    );
}

/// Xvfb (the "bad test type" line of "AlarmNotify selection"): B's
/// ChangeAlarm {test type 9, events True} on A's alarm is BadValue(9),
/// yet B is selected (the selection precedes the check) and the alarm,
/// still running PositiveComparison, notifies B when the counter
/// reaches it; QueryAlarm reports test type 9.
#[test]
fn sync_alarm_bad_test_type_still_selects_and_fires() {
    use yserver_protocol::x11::sync as s;
    const AL: u32 = 0x0010_00a0;
    let mut f = sync_fixture();
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 13));
    f.a(
        s::CREATE_ALARM,
        &sync_alarm_body(
            AL,
            s::CA_COUNTER | s::CA_VALUE | s::CA_EVENTS,
            &[SYNC_C1, 0, 14, 0],
        ),
    );
    f.b(
        s::CHANGE_ALARM,
        &sync_alarm_body(AL, s::CA_TEST_TYPE | s::CA_EVENTS, &[9, 1]),
    );
    assert_eq!(
        error_fields(&f.b_packets()[0]),
        (x11::error::BAD_VALUE, 9, u16::from(s::CHANGE_ALARM), 142)
    );
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 14));
    assert_eq!(
        alarm_notifies(&f.b_packets()),
        vec![(AL, 14, 14, s::ALARM_STATE_ACTIVE)]
    );
    assert!(f.a_packets().is_empty());
    assert_eq!(query_alarm_fields(&mut f, AL), (SYNC_C1, 0, 15, 9, 1, 0, 0));
}

/// Every AlarmNotify in `packets` → (alarm, counter value, alarm
/// value, state).
fn alarm_notifies(packets: &[[u8; 32]]) -> Vec<(u32, i64, i64, u8)> {
    let i64_at = |p: &[u8; 32], at: usize| {
        #[allow(clippy::cast_possible_wrap)]
        let hi = le_u32(p, at) as i32;
        (i64::from(hi) << 32) | i64::from(le_u32(p, at + 4))
    };
    packets
        .iter()
        .filter(|p| p[0] == crate::nested::SYNC_FIRST_EVENT + 1)
        .map(|p| {
            assert_eq!(p[1], 1, "kind AlarmNotify");
            (le_u32(p, 4), i64_at(p, 8), i64_at(p, 16), p[28])
        })
        .collect()
}

fn sync_events_body(alarm: u32, on: u32) -> Vec<u8> {
    use yserver_protocol::x11::sync as s;
    sync_alarm_body(alarm, s::CA_EVENTS, &[on])
}

/// Xvfb (tools/sync-await-probe.c, "AlarmNotify selection"): an alarm
/// owned by A (c >= 10, delta 1, events). B and D select AlarmNotify
/// with ChangeAlarm(events=True) — any client may — and every firing
/// reaches the owner (while its own flag is set) and each selecting
/// client once. events=False by B removes B; by A clears only the
/// owner's flag (what QueryAlarm reports). A selecting client that
/// disconnects drops off the list. A non-owner may change other
/// attributes too. DestroyAlarm sends a Destroyed notify to the
/// selecting clients. An `events` value other than True/False is
/// BadValue naming it and selects nothing.
#[test]
fn sync_alarm_notify_reaches_every_client_that_selected_it() {
    use yserver_protocol::x11::sync as s;
    const AL: u32 = 0x0010_0040;
    const D: u32 = 3;
    let mut f = sync_fixture();
    let mut peer_d = install_client(&mut f.state, D);
    let d_req = |f: &mut SyncFixture, minor: u8, body: &[u8]| {
        sync_req(&mut f.state, &mut f.backend, D, minor, body);
    };
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 0));
    let mut create = AL.to_le_bytes().to_vec();
    create.extend_from_slice(
        &(s::CA_COUNTER
            | s::CA_VALUE_TYPE
            | s::CA_VALUE
            | s::CA_TEST_TYPE
            | s::CA_DELTA
            | s::CA_EVENTS)
            .to_le_bytes(),
    );
    for v in [
        SYNC_C1,
        s::VALUE_TYPE_ABSOLUTE,
        0,
        10,
        s::TEST_POSITIVE_COMPARISON,
        0,
        1,
        1,
    ] {
        create.extend_from_slice(&v.to_le_bytes());
    }
    f.a(s::CREATE_ALARM, &create);
    f.b(s::CHANGE_ALARM, &sync_events_body(AL, 1));
    d_req(&mut f, s::CHANGE_ALARM, &sync_events_body(AL, 1));
    f.b(s::CHANGE_ALARM, &sync_events_body(AL, 1));
    assert!(f.b_packets().is_empty(), "selecting sends nothing");
    assert!(f.state.sync_alarms[&AL].events, "owner flag untouched");
    assert!(f.a_packets().is_empty());

    let set = |f: &mut SyncFixture, v: i64| f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, v));
    set(&mut f, 10);
    let fired = |v: i64| vec![(AL, v, v, s::ALARM_STATE_ACTIVE)];
    assert_eq!(alarm_notifies(&f.a_packets()), fired(10));
    assert_eq!(alarm_notifies(&f.b_packets()), fired(10), "B once");
    assert_eq!(alarm_notifies(&wire_packets(&mut peer_d)), fired(10));

    f.b(s::CHANGE_ALARM, &sync_events_body(AL, 0));
    set(&mut f, 11);
    assert_eq!(alarm_notifies(&f.a_packets()), fired(11));
    assert!(f.b_packets().is_empty(), "B deselected");
    assert_eq!(alarm_notifies(&wire_packets(&mut peer_d)), fired(11));

    f.a(s::CHANGE_ALARM, &sync_events_body(AL, 0));
    set(&mut f, 12);
    assert!(f.a_packets().is_empty(), "owner flag off");
    assert!(!f.state.sync_alarms[&AL].events);
    assert_eq!(alarm_notifies(&wire_packets(&mut peer_d)), fired(12));

    crate::core_loop::process_disconnect::process_disconnect(
        &mut f.state,
        &mut f.backend,
        ClientId(D),
    );
    assert!(f.state.sync_alarms[&AL].event_clients.is_empty());
    set(&mut f, 13);
    assert!(f.a_packets().is_empty() && f.b_packets().is_empty());

    f.b(s::CHANGE_ALARM, &sync_events_body(AL, 9));
    assert_eq!(
        error_fields(&f.b_packets()[0]),
        (x11::error::BAD_VALUE, 9, u16::from(s::CHANGE_ALARM), 142)
    );
    assert!(f.state.sync_alarms[&AL].event_clients.is_empty());

    f.b(s::CHANGE_ALARM, &sync_events_body(AL, 1));
    set(&mut f, 14);
    assert_eq!(alarm_notifies(&f.b_packets()), fired(14));
    f.b(
        s::CHANGE_ALARM,
        &sync_alarm_body(AL, s::CA_VALUE, &[0, 100]),
    );
    assert!(f.b_packets().is_empty(), "a non-owner may change the value");
    assert_eq!(f.state.sync_alarms[&AL].wait_value, 100);

    f.a(s::DESTROY_ALARM, &AL.to_le_bytes());
    assert!(f.a_packets().is_empty());
    assert_eq!(
        alarm_notifies(&f.b_packets()),
        vec![(AL, 14, 100, s::ALARM_STATE_DESTROYED)]
    );
}

/// Xvfb: a non-owner may DestroyAlarm (owner and selecting clients get
/// the Destroyed notify); the owner's disconnect destroys its alarms,
/// and the clients that selected them get the Destroyed notify with
/// the counter's value. A destroyed counter deactivates the alarm with
/// an Inactive notify to them as well.
#[test]
fn sync_alarm_destruction_notifies_every_selecting_client() {
    use yserver_protocol::x11::sync as s;
    const E: u32 = 3;
    const CE: u32 = 0x0030_0001;
    const AE1: u32 = 0x0030_0002;
    const AE2: u32 = 0x0030_0003;
    const A2: u32 = 0x0010_0050;
    let mut f = sync_fixture();
    let mut peer_e = install_client(&mut f.state, E);
    let e_req = |f: &mut SyncFixture, minor: u8, body: &[u8]| {
        sync_req(&mut f.state, &mut f.backend, E, minor, body);
    };
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 14));
    e_req(&mut f, s::CREATE_COUNTER, &sync_counter_body(CE, 0));
    e_req(
        &mut f,
        s::CREATE_ALARM,
        &sync_alarm_body(AE1, s::CA_COUNTER | s::CA_VALUE, &[CE, 0, 50]),
    );
    e_req(
        &mut f,
        s::CREATE_ALARM,
        &sync_alarm_body(AE2, s::CA_COUNTER | s::CA_VALUE, &[SYNC_C1, 0, 50]),
    );
    f.b(s::CHANGE_ALARM, &sync_events_body(AE1, 1));
    f.b(s::CHANGE_ALARM, &sync_events_body(AE2, 1));
    f.b(s::DESTROY_ALARM, &AE1.to_le_bytes());
    let destroyed = vec![(AE1, 0, 50, s::ALARM_STATE_DESTROYED)];
    assert_eq!(alarm_notifies(&wire_packets(&mut peer_e)), destroyed);
    assert_eq!(alarm_notifies(&f.b_packets()), destroyed);
    assert!(!f.state.sync_alarms.contains_key(&AE1));

    crate::core_loop::process_disconnect::process_disconnect(
        &mut f.state,
        &mut f.backend,
        ClientId(E),
    );
    assert_eq!(
        alarm_notifies(&f.b_packets()),
        vec![(AE2, 14, 50, s::ALARM_STATE_DESTROYED)]
    );
    assert!(!f.state.sync_alarms.contains_key(&AE2));

    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C2, 3));
    f.a(
        s::CREATE_ALARM,
        &sync_alarm_body(A2, s::CA_COUNTER | s::CA_VALUE, &[SYNC_C2, 0, 50]),
    );
    f.b(s::CHANGE_ALARM, &sync_events_body(A2, 1));
    f.a(s::DESTROY_COUNTER, &SYNC_C2.to_le_bytes());
    let inactive = vec![(A2, 3, 50, s::ALARM_STATE_INACTIVE)];
    assert_eq!(alarm_notifies(&f.a_packets()), inactive);
    assert_eq!(alarm_notifies(&f.b_packets()), inactive);
    f.a(s::DESTROY_ALARM, &A2.to_le_bytes());
    let destroyed = vec![(A2, 0, 50, s::ALARM_STATE_DESTROYED)];
    assert_eq!(alarm_notifies(&f.a_packets()), destroyed);
    assert_eq!(alarm_notifies(&f.b_packets()), destroyed);
}

/// Xvfb: CreateAlarm defaults are Xorg's (PositiveComparison, value 0,
/// delta 1, events): on a counter at 0 it fires at once and re-arms to
/// a wait value of 1. Without a counter the alarm starts Inactive and
/// silent; a ChangeAlarm on it then fires Inactive with counter value
/// 0 ("NULL counter WILL trigger in ChangeAlarm").
#[test]
fn sync_alarm_defaults_and_counterless_alarms_match_xvfb() {
    use yserver_protocol::x11::sync as s;
    const GONE: u32 = 0x0010_0060;
    const AN: u32 = 0x0020_0060;
    let mut f = sync_fixture();
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 0));
    f.a(
        s::CREATE_ALARM,
        &sync_alarm_body(GONE, s::CA_COUNTER, &[SYNC_C1]),
    );
    assert_eq!(
        alarm_notifies(&f.a_packets()),
        vec![(GONE, 0, 0, s::ALARM_STATE_ACTIVE)]
    );
    f.a(s::DESTROY_ALARM, &GONE.to_le_bytes());
    assert_eq!(
        alarm_notifies(&f.a_packets()),
        vec![(GONE, 0, 1, s::ALARM_STATE_DESTROYED)]
    );

    f.b(s::CREATE_ALARM, &sync_alarm_body(AN, s::CA_VALUE, &[0, 5]));
    assert!(f.b_packets().is_empty());
    assert_eq!(f.state.sync_alarms[&AN].state, s::ALARM_STATE_INACTIVE);
    f.b(s::CHANGE_ALARM, &sync_events_body(AN, 1));
    assert_eq!(
        alarm_notifies(&f.b_packets()),
        vec![(AN, 0, 5, s::ALARM_STATE_INACTIVE)]
    );
    f.b(s::DESTROY_ALARM, &AN.to_le_bytes());
    assert_eq!(
        alarm_notifies(&f.b_packets()),
        vec![(AN, 0, 5, s::ALARM_STATE_DESTROYED)]
    );
}

/// A DRI3 FenceFromFD xshmfence keeps its state in memory the client
/// can trigger and reset itself (`xshmfence_trigger` /
/// `xshmfence_reset`). Xorg's shm fence (`misyncshm.c`) answers every
/// `CheckTriggered` from that memory — QueryFence, the AwaitFence
/// epilogue, ResetFence's BadMatch test, and `miSyncTriggerFence`'s
/// re-check — and never from the server's own bit; ResetFence resets
/// the memory and DestroyFence triggers it before unmapping. Nothing in
/// Xorg watches the memory, so an AwaitFence already suspended stays
/// suspended when the client triggers it in memory, until a
/// TriggerFence request or the fence's destruction. Xvfb has no DRI3,
/// so this follows the source (`miSyncShmFenceCheckTriggered`,
/// `miSyncShmFenceReset`, `miSyncShmScreenDestroyFence`,
/// `SyncAwaitEpilogue`, `miSyncTriggerFence`).
#[test]
fn sync_shm_fence_state_is_read_from_shared_memory() {
    use yserver_protocol::x11::sync as s;
    const F: u32 = 0x0010_0070;
    const G: u32 = 0x0010_0071;
    let mut f = sync_fixture();
    for fence in [F, G] {
        f.state.sync_fences.insert(
            fence,
            crate::server::SyncFence {
                owner: ClientId(SYNC_A),
                triggered: false,
            },
        );
        f.backend.shm_fences.insert(fence, false);
    }
    let query = |f: &mut SyncFixture| {
        f.b(s::QUERY_FENCE, &F.to_le_bytes());
        let reply = f.b_packets();
        assert_eq!(reply[0][0], 1, "QueryFence reply");
        reply[0][8] != 0
    };

    // The client triggers it in memory: QueryFence sees it and an
    // AwaitFence returns at once.
    f.backend.shm_fences.insert(F, true);
    assert!(query(&mut f));
    f.b(s::AWAIT_FENCE, &F.to_le_bytes());
    assert!(!f.suspended());

    // The client resets it in memory after the server triggered it:
    // the memory wins over the server's bit.
    f.a(s::TRIGGER_FENCE, &F.to_le_bytes());
    assert!(f.state.sync_fences[&F].triggered);
    f.backend.shm_fences.insert(F, false);
    assert!(!query(&mut f));
    f.b(s::RESET_FENCE, &F.to_le_bytes());
    assert_eq!(
        error_fields(&f.b_packets()[0]),
        (x11::error::BAD_MATCH, F, u16::from(s::RESET_FENCE), 142),
        "untriggered in memory"
    );
    f.b(s::AWAIT_FENCE, &F.to_le_bytes());
    assert!(f.suspended(), "untriggered in memory");

    // A trigger in memory alone wakes nothing (Xorg never looks);
    // a TriggerFence request does.
    f.backend.shm_fences.insert(F, true);
    assert!(f.suspended());
    f.a(s::TRIGGER_FENCE, &F.to_le_bytes());
    assert!(!f.suspended());

    // ResetFence of a fence triggered in memory resets the memory.
    f.b(s::RESET_FENCE, &F.to_le_bytes());
    assert!(f.b_packets().is_empty());
    assert_eq!(f.backend.shm_fences.get(&F), Some(&false));
    assert!(!query(&mut f));

    // DestroyFence triggers the memory (releasing client waiters) and
    // unmaps it; so does the owner's disconnect.
    f.a(s::DESTROY_FENCE, &F.to_le_bytes());
    assert_eq!(f.backend.destroyed_shm_fences, vec![(F, true)]);
    assert!(!f.backend.shm_fences.contains_key(&F));
    crate::core_loop::process_disconnect::process_disconnect(
        &mut f.state,
        &mut f.backend,
        ClientId(SYNC_A),
    );
    assert_eq!(f.backend.destroyed_shm_fences, vec![(F, true), (G, true)]);
    assert!(f.backend.shm_fences.is_empty());
}

/// SERVERTIME awaits wake when the clock reaches the value (Xvfb: an
/// absolute now+300 PositiveComparison blocked ~300 ms and reported
/// wait == value), and the loop gets a deadline for it.
#[test]
fn sync_await_on_servertime_fires_when_the_clock_gets_there() {
    use yserver_protocol::x11::sync as s;
    let mut f = sync_fixture();
    let now = i64::from(f.state.timestamp_now());
    f.b(
        s::AWAIT,
        &sync_wait(
            s::SERVERTIME_COUNTER,
            s::VALUE_TYPE_ABSOLUTE,
            now + 300,
            s::TEST_POSITIVE_COMPARISON,
            0,
        ),
    );
    assert!(f.suspended());
    let deadline = crate::core_loop::sync_await::system_counter_deadline(&f.state)
        .expect("a SERVERTIME deadline");
    let wait = deadline.saturating_duration_since(std::time::Instant::now());
    assert!(
        wait > std::time::Duration::from_millis(200)
            && wait <= std::time::Duration::from_millis(300),
        "deadline ~300 ms out, got {wait:?}"
    );
    crate::core_loop::sync_await::evaluate_servertime(&mut f.state);
    assert!(f.suspended(), "not there yet");
    // Let 400 ms of server time pass. Until the loop evaluates it, the
    // passed value must read as due now — never as "no deadline", or
    // an idle loop would block past it.
    f.state.start_instant -= std::time::Duration::from_millis(400);
    let due = crate::core_loop::sync_await::system_counter_deadline(&f.state)
        .expect("still pending until evaluated");
    assert!(due <= std::time::Instant::now());
    crate::core_loop::sync_await::evaluate_servertime(&mut f.state);
    assert!(!f.suspended());
    let (counter, wait_value, value, count, destroyed) = counter_notify_fields(&f.b_packets()[0]);
    assert_eq!(
        (counter, wait_value, count, destroyed),
        (s::SERVERTIME_COUNTER, now + 300, 0, false)
    );
    assert!(value >= now + 300);
    assert!(crate::core_loop::sync_await::system_counter_deadline(&f.state).is_none());
}

/// SERVERTIME alarms fire too (Xvfb: an absolute now+200
/// PositiveComparison alarm with delta 0 sent AlarmNotify after ~200 ms
/// with state Inactive and counter >= alarm value).
#[test]
fn sync_alarm_on_servertime_fires_when_the_clock_gets_there() {
    use yserver_protocol::x11::sync as s;
    const ALARM: u32 = 0x0010_0030;
    let mut f = sync_fixture();
    let now = i64::from(f.state.timestamp_now());
    let mut body = ALARM.to_le_bytes().to_vec();
    let mask = s::CA_COUNTER | s::CA_VALUE_TYPE | s::CA_VALUE | s::CA_TEST_TYPE | s::CA_DELTA;
    body.extend_from_slice(&mask.to_le_bytes());
    body.extend_from_slice(&s::SERVERTIME_COUNTER.to_le_bytes());
    body.extend_from_slice(&s::VALUE_TYPE_ABSOLUTE.to_le_bytes());
    body.extend_from_slice(&sync_i64(now + 200));
    body.extend_from_slice(&s::TEST_POSITIVE_COMPARISON.to_le_bytes());
    body.extend_from_slice(&sync_i64(0));
    f.b(s::CREATE_ALARM, &body);
    assert!(f.b_packets().is_empty(), "not due yet");
    assert!(crate::core_loop::sync_await::system_counter_deadline(&f.state).is_some());
    f.state.start_instant -= std::time::Duration::from_millis(300);
    crate::core_loop::sync_await::evaluate_servertime(&mut f.state);
    let packets = f.b_packets();
    assert_eq!(packets.len(), 1);
    assert_eq!(
        packets[0][0],
        crate::nested::SYNC_FIRST_EVENT + 1,
        "AlarmNotify"
    );
    assert_eq!(packets[0][28], s::ALARM_STATE_INACTIVE);
    assert_eq!(f.state.sync_alarms[&ALARM].state, s::ALARM_STATE_INACTIVE);
}

/// IDLETIME awaits: a positive test wakes when idle time reaches it; a
/// negative transition wakes on input (idle drops to 0).
#[test]
fn sync_await_on_idletime_fires_on_idle_and_on_input() {
    use yserver_protocol::x11::sync as s;
    let mut f = sync_fixture();
    f.state.dpms.last_activity = std::time::Instant::now();
    f.b(
        s::AWAIT,
        &sync_wait(
            s::IDLETIME_COUNTER,
            s::VALUE_TYPE_ABSOLUTE,
            5_000,
            s::TEST_POSITIVE_TRANSITION,
            0,
        ),
    );
    assert!(f.suspended());
    assert!(crate::core_loop::sync_await::system_counter_deadline(&f.state).is_some());
    f.state.dpms.last_activity -= std::time::Duration::from_secs(6);
    crate::core_loop::run::evaluate_idletime_alarms_post_poll(&mut f.state, &mut f.backend);
    assert!(!f.suspended());
    let (counter, wait_value, _, _, _) = counter_notify_fields(&f.b_packets()[0]);
    assert_eq!((counter, wait_value), (s::IDLETIME_COUNTER, 5_000));

    f.b(
        s::AWAIT,
        &sync_wait(
            s::IDLETIME_COUNTER,
            s::VALUE_TYPE_ABSOLUTE,
            1_000,
            s::TEST_NEGATIVE_TRANSITION,
            0,
        ),
    );
    assert!(f.suspended(), "idle is ~6 s, no downward crossing yet");
    evaluate_idletime_negative_alarms_on_input_wake(&mut f.state, 2, 6_000, 6_000);
    assert!(!f.suspended());
}

/// The awaiting client's own disconnect drops its await.
#[test]
fn sync_await_dies_with_its_client() {
    use yserver_protocol::x11::sync as s;
    let mut f = sync_fixture();
    f.a(s::CREATE_COUNTER, &sync_counter_body(SYNC_C1, 0));
    f.b(
        s::AWAIT,
        &sync_wait(
            SYNC_C1,
            s::VALUE_TYPE_ABSOLUTE,
            5,
            s::TEST_POSITIVE_COMPARISON,
            0,
        ),
    );
    assert!(f.suspended());
    crate::core_loop::process_disconnect::process_disconnect(
        &mut f.state,
        &mut f.backend,
        ClientId(SYNC_B),
    );
    assert!(f.state.sync_awaits.is_empty());
    f.a(s::SET_COUNTER, &sync_counter_body(SYNC_C1, 9));
    assert!(f.state.sync_counters.contains_key(&SYNC_C1));
}

fn xfixes_create_barrier(
    state: &mut ServerState,
    client: ClientId,
    barrier: u32,
    window: u32,
    x1: i16,
    y1: i16,
    x2: i16,
    y2: i16,
    directions: u32,
    devices: &[u16],
) -> io::Result<RequestOutcome> {
    use yserver_protocol::x11::xfixes as x11xfixes;

    let mut body = Vec::new();
    body.extend_from_slice(&barrier.to_le_bytes());
    body.extend_from_slice(&window.to_le_bytes());
    body.extend_from_slice(&x1.to_le_bytes());
    body.extend_from_slice(&y1.to_le_bytes());
    body.extend_from_slice(&x2.to_le_bytes());
    body.extend_from_slice(&y2.to_le_bytes());
    body.extend_from_slice(&directions.to_le_bytes());
    body.extend_from_slice(&0u16.to_le_bytes());
    body.extend_from_slice(&(devices.len() as u16).to_le_bytes());
    for &device in devices {
        body.extend_from_slice(&device.to_le_bytes());
    }

    let header = RequestHeader {
        opcode: 140,
        data: x11xfixes::CREATE_POINTER_BARRIER,
        length_units: u32::try_from(1 + body.len() / 4).unwrap(),
    };
    handle_xfixes_request(
        state,
        &mut RecordingBackend::new(),
        None,
        client,
        SequenceNumber(1),
        header,
        &body,
    )
}

fn xfixes_delete_barrier(
    state: &mut ServerState,
    client: ClientId,
    barrier: u32,
) -> io::Result<RequestOutcome> {
    use yserver_protocol::x11::xfixes as x11xfixes;
    let body = barrier.to_le_bytes();
    let header = RequestHeader {
        opcode: 140,
        data: x11xfixes::DELETE_POINTER_BARRIER,
        length_units: 2,
    };
    handle_xfixes_request(
        state,
        &mut RecordingBackend::new(),
        None,
        client,
        SequenceNumber(1),
        header,
        &body,
    )
}

fn xi2_barrier_release(
    state: &mut ServerState,
    client: ClientId,
    entries: &[(u16, u32, u32)],
) -> io::Result<RequestOutcome> {
    let mut body = Vec::new();
    body.extend_from_slice(&(entries.len() as u32).to_le_bytes());
    for &(deviceid, barrier, eventid) in entries {
        body.extend_from_slice(&deviceid.to_le_bytes());
        body.extend_from_slice(&0u16.to_le_bytes());
        body.extend_from_slice(&barrier.to_le_bytes());
        body.extend_from_slice(&eventid.to_le_bytes());
    }
    handle_xi2_request(
        state,
        &mut RecordingBackend::new(),
        None,
        client,
        SequenceNumber(1),
        xi2_header_for_body(61, &body),
        &body,
    )
}

