    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let bid = 0x0040_0001u32;

    xfixes_create_barrier(
        &mut state,
        ClientId(1),
        bid,
        ROOT_WINDOW.0,
        100,
        0,
        100,
        200,
        0,
        &[],
    )
    .expect("create barrier");

