#[test]
fn delete_while_hit_emits_released_leave() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    if let Some(client) = state.clients.get_mut(&1) {
        client.xi2_masks.insert((ROOT_WINDOW, 2), 1 << 26);
    }
    let bid = 0x0040_0003u32;

    xfixes_create_barrier(
        &mut state,
        ClientId(1),
        bid,
        ROOT_WINDOW.0,
        100,
        0,
        100,
        200,
        0,
        &[],
    )
    .expect("create barrier");
    {
        let barrier = state.pointer_barriers.get_mut(&bid).expect("barrier");
        barrier.hit = true;
        barrier.event_id = 1;
        barrier.last_timestamp = 10;
    }
    // Sprite resting on the barrier. The released leave must carry the
    // CURRENT position (not 0,0 — the pre-fix bug).
    state.pointer_root = (100, 50);

    xfixes_delete_barrier(&mut state, ClientId(1), bid).expect("owner delete handled");
    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes.len(), 68);
    assert_eq!(bytes[0], 35, "GenericEvent");
    assert_eq!(bytes[1], XI2_MAJOR_OPCODE, "XI2 major opcode");
    assert_eq!(&bytes[8..10], &26u16.to_le_bytes(), "BarrierLeave");
    assert_eq!(
        &bytes[36..40],
        &1u32.to_le_bytes(),
        "XIBarrierPointerReleased"
    );
    assert_eq!(&bytes[40..42], &0u16.to_le_bytes(), "sourceid = 0");
    // root_x/root_y carry the current sprite position as FP1616 (v<<16),
    // not the pre-fix 0,0.
    assert_eq!(
        &bytes[44..48],
        &(100i32 << 16).to_le_bytes(),
        "root_x = 100"
    );
    assert_eq!(&bytes[48..52], &(50i32 << 16).to_le_bytes(), "root_y = 50");
    assert!(!state.pointer_barriers.contains_key(&bid));
}

#[test]
fn shape_input_change_emits_shape_notify_to_selectors() {
    // A client that ShapeSelectInput'd a window must receive a
    // ShapeNotify when that window's input region changes. Regression
    // for the cinnamon "nemo rises" bug: nautilus grows its input shape
    // from a tiny startup rect to full size; without ShapeNotify the
    // compositing WM keeps the stale tiny region, treats the window as
    // click-through over most of its area, and focuses/raises the
    // window below on a click.
    use yserver_protocol::x11::{shape as x11shape, xfixes::RegionRect};
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let win = ResourceId(0x1b00004);
    seed_window(&mut state, win, ROOT_WINDOW, 800, 600);

    // WM selected ShapeNotify on the window.
    state.shape_select_masks.insert((1, win), true);

    // Window sets its (grown) input shape, then we notify.
    crate::nested::set_shape_rects(
        &mut state,
        win,
        x11shape::KIND_INPUT,
        vec![RegionRect {
            x: 13,
            y: 13,
            width: 1482,
            height: 1024,
        }],
    );
    emit_shape_notify(&mut state, win, x11shape::KIND_INPUT);

    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes.len(), 32, "one 32-byte ShapeNotify");
    assert_eq!(
        bytes[0],
        crate::nested::SHAPE_FIRST_EVENT,
        "ShapeNotify type"
    );
    assert_eq!(bytes[1], x11shape::KIND_INPUT, "kind = Input");
    assert_eq!(&bytes[4..8], &win.0.to_le_bytes(), "affected window");
    assert_eq!(bytes[20], 1, "shaped = true");

    // A client that did NOT select gets nothing.
    let mut peer2 = install_client(&mut state, 2);
    emit_shape_notify(&mut state, win, x11shape::KIND_INPUT);
    assert!(
        read_all_available(&mut peer2).is_empty(),
        "non-selecting client must not receive ShapeNotify"
    );
}

/// A `ShapeMask(kind=Input, src=None)` that clears an already-unset
/// input shape is a no-op and must NOT generate a ShapeNotify —
/// matching Xorg. xfwm4 re-asserts exactly this on its panel frames
/// repeatedly; a spurious notify each time made it re-derive the
/// frame's input shape from a stale geometry-default rect, so XFCE
/// bottom-panel buttons fell through to xfdesktop (HW xfce
/// 2026-06-22). Drives the real `handle_shape_request` MASK path.
#[test]
fn shape_mask_none_clearing_unset_input_emits_no_shape_notify() {
    use yserver_protocol::x11::shape as x11shape;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let win = ResourceId(0x1b00004);
    seed_window(&mut state, win, ROOT_WINDOW, 25, 49);
    // WM (xfwm4-like) selected ShapeNotify on the window.
    state.shape_select_masks.insert((1, win), true);

    // MASK body: op(1) dest_kind(1) pad(2) dest(4) x_off(2) y_off(2) src(4).
    let mut body = vec![0u8; 16];
    body[0] = x11shape::OP_SET;
    body[1] = x11shape::KIND_INPUT;
    body[4..8].copy_from_slice(&win.0.to_le_bytes());
    // src stays 0 == None → clear the (already-unset) input shape.
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 129, // SHAPE major (unused by handle_shape_request)
        data: 2,     // SHAPE minor: Mask
        length_units: 5,
    };
    handle_shape_request(
        &mut state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("ShapeMask");

    assert!(
        read_all_available(&mut peer).is_empty(),
        "no-op input clear must emit no ShapeNotify",
    );
}

/// `RRSetCrtcConfig` real handler — validates mode/output/rotation and
/// calls `apply_crtc_config`. Replaces the old no-op-accept test.
///
/// Cases:
/// The fixture has two outputs with the same connector name. Requests
/// target the second by `(crtc=5, output=4)` so routing cannot fall back
/// to a globally-ambiguous name.
///
/// 1. valid enable (mode=3, crtc=5, outputs=[4], rotation=RR_Rotate_0)
///    → reply status=0 (Success).
/// 2. disable (mode=0, crtc=2, no outputs)
///    → reply status=0.
/// 3. bad mode (555 not in output's mode_ids)
///    → X11 error BadMatch (type byte = 0).
/// 4. bad rotation (0x41: a bit outside the CRTC's `rotations` 0x3f)
///    → X11 error BadMatch (type byte = 0).
#[test]
fn randr_set_crtc_config_validates_mode_id() {
    use crate::randr::{RandrMode, RandrOutput, RandrState};

    const CLIENT_ID: u32 = 1;
    let mode_table = vec![RandrMode {
        mode_id: 3,
        width: 1920,
        height: 1080,
        vrefresh: 60,
        timing: None,
    }];
    let outputs = vec![
        RandrOutput {
            name: "test-0".to_string(),
            output_id: 1,
            crtc_id: 2,
            mode_id: 3,
            connected: true,
            x: 0,
            y: 0,
            width: 1920,
            height: 1080,
            vrefresh: 60,
            timing: None,
            mm_width: 0,
            mm_height: 0,
            mode_ids: vec![3],
            num_preferred: 1,
            pending_transform: Default::default(),
            current_transform: Default::default(),
            rotation: crate::randr::RR_ROTATE_0,
        },
        // Equal connector names are legal across different DRM devices.
        // Address this second row by CRTC/XID to prove the core never
        // re-resolves the request through the ambiguous display name.
        RandrOutput {
            name: "test-0".to_string(),
            output_id: 4,
            crtc_id: 5,
            mode_id: 3,
            connected: true,
            x: 1920,
            y: 0,
            width: 1920,
            height: 1080,
            vrefresh: 60,
            timing: None,
            mm_width: 0,
            mm_height: 0,
            mode_ids: vec![3],
            num_preferred: 1,
            pending_transform: Default::default(),
            current_transform: Default::default(),
            rotation: crate::randr::RR_ROTATE_0,
        },
    ];
    let mut state = ServerState::new();
    state.randr = RandrState::from_outputs_with_modes(1, outputs, mode_table);
    let mut backend = RecordingBackend::new();
    let mut peer = install_client(&mut state, CLIENT_ID);

    // Body layout: crtc(4) ts(4) cts(4) x(2) y(2) mode(4) rotation(2)
    // pad(2) outputs(4*N).
    fn build_body(mode: u32, rotation: u16, output_ids: &[u32]) -> Vec<u8> {
        let mut b = Vec::with_capacity(24 + output_ids.len() * 4);
        b.extend_from_slice(&5u32.to_le_bytes()); // target the second same-name CRTC
        b.extend_from_slice(&0u32.to_le_bytes()); // timestamp
        b.extend_from_slice(&0u32.to_le_bytes()); // config_timestamp
        b.extend_from_slice(&0i16.to_le_bytes()); // x
        b.extend_from_slice(&0i16.to_le_bytes()); // y
        b.extend_from_slice(&mode.to_le_bytes()); // mode
        b.extend_from_slice(&rotation.to_le_bytes()); // rotation
        b.extend_from_slice(&[0u8; 2]); // pad
        for &oid in output_ids {
            b.extend_from_slice(&oid.to_le_bytes());
        }
        b
    }
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 140,
        data: 21, // RR_SET_CRTC_CONFIG
        length_units: 7,
    };

    // (1) Valid enable: mode=3, rotation=RR_Rotate_0(1), outputs=[4] → Success reply.
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &build_body(3, 1, &[4]),
    )
    .expect("valid enable");

    // (2) Disable: mode=0, no outputs → Success reply.
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(2),
        header,
        &build_body(0, 1, &[]),
    )
    .expect("disable");

    // (3) Bad mode: mode=555 not in output's mode_ids → BadMatch error.
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(3),
        header,
        &build_body(555, 1, &[4]),
    )
    .expect("bad mode → error");

    // (4) Bad rotation: RR_Rotate_0 plus bit 6, which no CRTC
    // advertises. validate_set_crtc_config succeeds (mode 3 known), then
    // `(~crtc->rotations) & rotation` fires BadMatch (rrcrtc.c:1403).
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(4),
        header,
        &build_body(3, 0x41, &[4]),
    )
    .expect("bad rotation → error");

    use std::io::Read;
    peer.set_nonblocking(true).unwrap();
    let mut wire = Vec::new();
    let mut tmp = [0u8; 1024];
    loop {
        match peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => wire.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    // All 4 responses are 32 bytes. type byte at offset 0:
    // 1 = reply, 0 = error.
    assert_eq!(wire.len(), 128, "4 × 32-byte packets");
    let type_bytes: Vec<u8> = wire.chunks_exact(32).map(|c| c[0]).collect();
    assert_eq!(type_bytes[0], 1, "valid enable → reply");
    let status_enable = wire[1]; // data byte of first reply
    assert_eq!(status_enable, 0, "valid enable → status=0 (Success)");
    assert_eq!(type_bytes[1], 1, "disable → reply");
    let status_disable = wire[32 + 1];
    assert_eq!(status_disable, 0, "disable → status=0");
    assert_eq!(type_bytes[2], 0, "bad mode → X11 error (type=0)");
    assert_eq!(type_bytes[3], 0, "bad rotation → X11 error (type=0)");

    let crtc_calls: Vec<_> = backend
        .calls()
        .into_iter()
        .filter(|call| matches!(call, RecordedCall::ApplyCrtcConfig { .. }))
        .collect();
    assert_eq!(
        crtc_calls,
        vec![
            RecordedCall::ApplyCrtcConfig {
                output_id: 4,
                connector: "test-0".to_string(),
                mode: Some(ModeSpec {
                    width: 1920,
                    height: 1080,
                    vrefresh: 60,
                }),
                x: 0,
                y: 0,
            },
            RecordedCall::ApplyCrtcConfig {
                output_id: 4,
                connector: "test-0".to_string(),
                mode: None,
                x: 0,
                y: 0,
            },
        ],
        "the second same-name output XID must be carried into backend routing",
    );

    // An asynchronous backend returns a continuation token without
    // sending a premature reply. The core loop owns parking and later
    // invokes `complete_crtc_config` with the finished result.
    let token = CrtcConfigToken(0x1234);
    backend.pending_crtc_config = Some(token);
    let outcome = handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(5),
        header,
        &build_body(3, 1, &[4]),
    )
    .expect("asynchronous enable begins");
    let RequestOutcome::PendingCrtcConfig(pending) = outcome else {
        panic!("asynchronous backend must return a pending continuation");
    };
    assert_eq!(pending.token, token);
    assert_eq!(pending.completion.output_id, 4);
    assert!(
        read_all_available(&mut peer).is_empty(),
        "pending request must not receive a reply before completion"
    );
}

#[test]
fn randr_get_crtc_gamma_size_uses_backend_and_invalid_crtc_is_bad_crtc() {
    use crate::randr::{RandrOutput, RandrState};
    use yserver_protocol::x11::randr as x11randr;

    const CLIENT_ID: u32 = 1;
    let outputs = vec![RandrOutput {
        name: "DP-1".to_string(),
        output_id: 1,
        crtc_id: 2,
        mode_id: 3,
        connected: true,
        x: 0,
        y: 0,
        width: 1920,
        height: 1080,
        vrefresh: 60,
        timing: None,
        mm_width: 0,
        mm_height: 0,
        mode_ids: vec![3],
        num_preferred: 1,
        pending_transform: Default::default(),
        current_transform: Default::default(),
        rotation: crate::randr::RR_ROTATE_0,
    }];
    let mut state = ServerState::new();
    state.randr = RandrState::from_outputs(1, outputs);
    let mut backend = RecordingBackend::new();
    let mut peer = install_client(&mut state, CLIENT_ID);

    let header = RequestHeader {
        opcode: 128,
        data: x11randr::RR_GET_CRTC_GAMMA_SIZE,
        length_units: 2,
    };
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &2u32.to_le_bytes(),
    )
    .expect("valid get gamma size");
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(2),
        header,
        &999u32.to_le_bytes(),
    )
    .expect("invalid get gamma size");

    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes.len(), 64, "reply + error");
    assert_eq!(bytes[0], 1, "valid query replies");
    assert_eq!(&bytes[8..10], &256u16.to_le_bytes(), "gamma size");
    assert_eq!(bytes[32], 0, "invalid crtc emits error packet");
    assert_eq!(bytes[33], RANDR_BAD_CRTC);
}

