/// Audit #7 (code-review follow-up): Xorg's
/// `ProcXFixesCreateRegionFromWindow` (`xfixes/region.c:158-163`)
/// returns BadWindow when `dixLookupResourceByType` on the
/// window xid fails, with `client->error_value = stuff->window`.
/// Pre-fix yserver passed any xid (including 0) through to
/// `shape_rects_for` and silently inserted a default/empty
/// region.
#[test]
fn create_region_from_window_with_unknown_window_returns_bad_window() {
    use std::io::Read;
    use yserver_protocol::x11::xfixes as x11xfixes;
    const APP: u32 = 82;
    const REGION_XID: u32 = 0x0082_0001;
    const UNKNOWN_WIN: u32 = 0x0082_ffff;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, APP);
    let mut backend = RecordingBackend::new();

    // body: region(4) + window(4) + kind(1) + pad(3)
    let mut body = Vec::with_capacity(12);
    body.extend_from_slice(&REGION_XID.to_le_bytes());
    body.extend_from_slice(&UNKNOWN_WIN.to_le_bytes());
    body.push(0); // kind = Bounding (valid)
    body.extend_from_slice(&[0u8; 3]);
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body fits");
    // The client negotiated XFIXES (Xorg gates requests on QueryVersion).
    state.xfixes_client_major.insert(APP, 5);
    process_request(
        &mut state,
        &mut backend,
        ClientId(APP),
        SequenceNumber(1),
        RequestHeader {
            opcode: XFIXES_MAJOR_OPCODE,
            data: x11xfixes::CREATE_REGION_FROM_WINDOW,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request");

    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf).expect("error reply delivered");
    assert_eq!(
        buf[1],
        yserver_protocol::x11::error::BAD_WINDOW,
        "expected BadWindow (3) for unknown window xid; got {}",
        buf[1],
    );
    assert_eq!(
        u32::from_le_bytes([buf[4], buf[5], buf[6], buf[7]]),
        UNKNOWN_WIN,
        "error.bad_value must carry the offending window xid",
    );
    assert!(
        !state.xfixes_regions.contains_key(&REGION_XID),
        "no region must be inserted on BadWindow",
    );
}

/// Audit #7 (code-review follow-up): Xorg's
/// `ProcXFixesCreateRegionFromWindow` (`xfixes/region.c:164-181`)
/// accepts only `WindowRegionBounding` (0) and `WindowRegionClip`
/// (1); any other `kind` returns BadValue with
/// `client->error_value = stuff->kind`. The SHAPE-shaped value 2
/// (Input) is rejected per X11 XFIXES spec.
#[test]
fn create_region_from_window_with_invalid_kind_returns_bad_value() {
    use std::io::Read;
    use yserver_protocol::x11::{CreateWindowRequest, xfixes as x11xfixes};
    const APP: u32 = 83;
    const REGION_XID: u32 = 0x0083_0001;
    const WIN_XID: u32 = 0x0083_0002;
    const INVALID_KIND: u8 = 2;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, APP);
    let mut backend = RecordingBackend::new();
    // Window must exist so the BadWindow gate doesn't fire
    // first — we want to isolate the BadValue(kind) path.
    state.resources.create_window(
        ClientId(APP),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(WIN_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );

    let mut body = Vec::with_capacity(12);
    body.extend_from_slice(&REGION_XID.to_le_bytes());
    body.extend_from_slice(&WIN_XID.to_le_bytes());
    body.push(INVALID_KIND);
    body.extend_from_slice(&[0u8; 3]);
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body fits");
    // The client negotiated XFIXES (Xorg gates requests on QueryVersion).
    state.xfixes_client_major.insert(APP, 5);
    process_request(
        &mut state,
        &mut backend,
        ClientId(APP),
        SequenceNumber(1),
        RequestHeader {
            opcode: XFIXES_MAJOR_OPCODE,
            data: x11xfixes::CREATE_REGION_FROM_WINDOW,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request");

    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf).expect("error reply delivered");
    assert_eq!(
        buf[1],
        yserver_protocol::x11::error::BAD_VALUE,
        "expected BadValue (2) for kind={INVALID_KIND}; got {}",
        buf[1],
    );
    assert_eq!(
        u32::from_le_bytes([buf[4], buf[5], buf[6], buf[7]]),
        u32::from(INVALID_KIND),
        "error.bad_value must carry the offending kind",
    );
    assert!(
        !state.xfixes_regions.contains_key(&REGION_XID),
        "no region must be inserted on BadValue",
    );
}

/// Audit #7 (code-review follow-up): every XFIXES
/// `CreateRegion*` opcode begins with
/// `LEGAL_NEW_RESOURCE(stuff->region, client)` in Xorg
/// (`xfixes/region.c:78,114,157,213,…`). Reusing an existing
/// region XID must surface BadIDChoice. Pre-fix yserver silently
/// overwrote `state.xfixes_regions[region]` via `.insert(…)`,
/// matching the colormap/window/etc. bug class that the
/// codebase already gates elsewhere.
#[test]
fn create_region_with_in_use_xid_returns_bad_id_choice() {
    use std::io::Read;
    use yserver_protocol::x11::xfixes as x11xfixes;
    const APP: u32 = 80;
    const REGION_XID: u32 = 0x0080_0001;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, APP);
    let mut backend = RecordingBackend::new();

    // Pre-populate the region xid so the new request is a
    // duplicate.
    state.xfixes_regions.insert(
        REGION_XID,
        crate::server::XFixesRegion {
            owner: ClientId(APP),
            rects: Vec::new(),
        },
    );

    // CreateRegion body: region(4) + N×8 (rects). Zero rects =
    // empty region; the duplicate-xid check must fire BEFORE
    // any rect parsing.
    let mut body = Vec::with_capacity(4);
    body.extend_from_slice(&REGION_XID.to_le_bytes());
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body fits");
    // The client negotiated XFIXES (Xorg gates requests on QueryVersion).
    state.xfixes_client_major.insert(APP, 5);
    process_request(
        &mut state,
        &mut backend,
        ClientId(APP),
        SequenceNumber(1),
        RequestHeader {
            opcode: XFIXES_MAJOR_OPCODE,
            data: x11xfixes::CREATE_REGION,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request");

    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf).expect("error reply delivered");
    assert_eq!(buf[0], 0, "first byte = error class");
    assert_eq!(
        buf[1],
        yserver_protocol::x11::error::BAD_ID_CHOICE,
        "expected BadIDChoice (14) when reusing an existing region xid; got {}",
        buf[1],
    );
    // The duplicate must not be overwritten — the pre-existing
    // entry's marker (empty rects placeholder) survives intact.
    let r = state
        .xfixes_regions
        .get(&REGION_XID)
        .expect("pre-existing region must remain");
    assert!(
        r.rects.is_empty(),
        "pre-existing region must not be overwritten on BadIDChoice; \
             got rects={:?}",
        r.rects,
    );
}

/// Audit #7 (code-review follow-up): the duplicate-xid gate
/// also applies to `CREATE_REGION_FROM_GC` (and all other
/// CreateRegion variants). The GC path is the audit-#7 patch
/// site — confirm the new gate is wired in front of the raw
/// clip-copy too.
#[test]
fn create_region_from_gc_with_in_use_xid_returns_bad_id_choice() {
    use std::io::Read;
    use yserver_protocol::x11::{
        ClipRectangles, CreateGcRequest, CreateWindowRequest, SetClipRectanglesRequest,
        xfixes as x11xfixes,
    };
    const APP: u32 = 81;
    const WIN_XID: u32 = 0x0081_0001;
    const GC_XID: u32 = 0x0081_0002;
    const REGION_XID: u32 = 0x0081_0003;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, APP);
    let mut backend = RecordingBackend::new();
    state.resources.create_window(
        ClientId(APP),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(WIN_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    state.resources.create_gc(
        ClientId(APP),
        CreateGcRequest {
            gc: ResourceId(GC_XID),
            drawable: ResourceId(WIN_XID),
            function: None,
            plane_mask: None,
            foreground: None,
            background: None,
            line_width: None,
            line_style: None,
            cap_style: None,
            join_style: None,
            fill_style: None,
            fill_rule: None,
            tile: None,
            stipple: None,
            tile_x_origin: None,
            tile_y_origin: None,
            font: None,
            subwindow_mode: None,
            graphics_exposures: None,
            clip_x_origin: None,
            clip_y_origin: None,
            clip_mask: None,
            dash_offset: None,
            dashes: None,
            arc_mode: None,
        },
    );
    // Single-rect clip so the GC's `clientClip` exists.
    let mut rect_bytes = Vec::with_capacity(8);
    rect_bytes.extend_from_slice(&0i16.to_le_bytes());
    rect_bytes.extend_from_slice(&0i16.to_le_bytes());
    rect_bytes.extend_from_slice(&5u16.to_le_bytes());
    rect_bytes.extend_from_slice(&5u16.to_le_bytes());
    state.resources.set_clip_rectangles(
        yserver_protocol::x11::ClientId(1),
        SetClipRectanglesRequest {
            gc: ResourceId(GC_XID),
            clip: ClipRectangles {
                ordering: 0,
                x_origin: 0,
                y_origin: 0,
                rectangles: rect_bytes,
            },
        },
    );

    // Pre-occupy REGION_XID.
    state.xfixes_regions.insert(
        REGION_XID,
        crate::server::XFixesRegion {
            owner: ClientId(APP),
            rects: Vec::new(),
        },
    );

    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&REGION_XID.to_le_bytes());
    body.extend_from_slice(&GC_XID.to_le_bytes());
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body fits");
    // The client negotiated XFIXES (Xorg gates requests on QueryVersion).
    state.xfixes_client_major.insert(APP, 5);
    process_request(
        &mut state,
        &mut backend,
        ClientId(APP),
        SequenceNumber(1),
        RequestHeader {
            opcode: XFIXES_MAJOR_OPCODE,
            data: x11xfixes::CREATE_REGION_FROM_GC,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request");

    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf).expect("error reply delivered");
    assert_eq!(
        buf[1],
        yserver_protocol::x11::error::BAD_ID_CHOICE,
        "CreateRegionFromGC must gate on LEGAL_NEW_RESOURCE before \
             copying the GC's clip; got error code {}",
        buf[1],
    );
}

/// Audit #7 (`docs/protocol-audit-2026-05-19.md`):
/// `CreateRegionFromGC` must return the GC's clip rectangles in
/// their RAW clip-coordinate space — Xorg's
/// `ProcXFixesCreateRegionFromGC` (`xfixes/region.c:219-226`)
/// just `XFixesRegionCopy(pGC->clientClip)` with NO origin
/// translation applied. yserver was offsetting by
/// `(clip.x_origin, clip.y_origin)` at insert time. When a WM
/// later re-installs the resulting region as a GC's clip via
/// `SetGcClipRegion(gc, region, x_origin, y_origin)`, the
/// GC-side origin is applied a SECOND time → double-translation
/// → wrong area shadowed/repainted.
#[test]
fn create_region_from_gc_copies_clip_rects_without_origin_translation() {
    use yserver_protocol::x11::{
        ClipRectangles, CreateGcRequest, CreateWindowRequest, SetClipRectanglesRequest,
        xfixes as x11xfixes,
    };
    const APP: u32 = 70;
    const WIN_XID: u32 = 0x0070_0001;
    const GC_XID: u32 = 0x0070_0002;
    const REGION_XID: u32 = 0x0070_0003;
    const X_ORIGIN: i16 = 100;
    const Y_ORIGIN: i16 = 200;
    const RECT_X: i16 = 10;
    const RECT_Y: i16 = 20;
    const RECT_W: u16 = 5;
    const RECT_H: u16 = 5;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, APP);
    let mut backend = RecordingBackend::new();

    // Drawable to attach the GC to.
    state.resources.create_window(
        ClientId(APP),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(WIN_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    state.resources.create_gc(
        ClientId(APP),
        CreateGcRequest {
            gc: ResourceId(GC_XID),
            drawable: ResourceId(WIN_XID),
            function: None,
            plane_mask: None,
            foreground: None,
            background: None,
            line_width: None,
            line_style: None,
            cap_style: None,
            join_style: None,
            fill_style: None,
            fill_rule: None,
            tile: None,
            stipple: None,
            tile_x_origin: None,
            tile_y_origin: None,
            font: None,
            subwindow_mode: None,
            graphics_exposures: None,
            clip_x_origin: None,
            clip_y_origin: None,
            clip_mask: None,
            dash_offset: None,
            dashes: None,
            arc_mode: None,
        },
    );

    // Set the GC's clip: single rect at (10, 20, 5×5) in
    // clip-coordinate space, with origin (100, 200). The wire
    // format is (x i16, y i16, w u16, h u16) per rect.
    let mut rect_bytes = Vec::with_capacity(8);
    rect_bytes.extend_from_slice(&RECT_X.to_le_bytes());
    rect_bytes.extend_from_slice(&RECT_Y.to_le_bytes());
    rect_bytes.extend_from_slice(&RECT_W.to_le_bytes());
    rect_bytes.extend_from_slice(&RECT_H.to_le_bytes());
    state.resources.set_clip_rectangles(
        yserver_protocol::x11::ClientId(1),
        SetClipRectanglesRequest {
            gc: ResourceId(GC_XID),
            clip: ClipRectangles {
                ordering: 0,
                x_origin: X_ORIGIN,
                y_origin: Y_ORIGIN,
                rectangles: rect_bytes,
            },
        },
    );

    // CREATE_REGION_FROM_GC body: region(4) + gc(4).
    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&REGION_XID.to_le_bytes());
    body.extend_from_slice(&GC_XID.to_le_bytes());
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body fits");
    // The client negotiated XFIXES (Xorg gates requests on QueryVersion).
    state.xfixes_client_major.insert(APP, 5);
    process_request(
        &mut state,
        &mut backend,
        ClientId(APP),
        SequenceNumber(1),
        RequestHeader {
            opcode: XFIXES_MAJOR_OPCODE,
            data: x11xfixes::CREATE_REGION_FROM_GC,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request");

    let region = state
        .xfixes_regions
        .get(&REGION_XID)
        .expect("CreateRegionFromGC inserted region");
    assert_eq!(
        region.rects.len(),
        1,
        "expected exactly one rect from the GC's single-rect clip; got {:?}",
        region.rects,
    );
    let r = &region.rects[0];
    assert_eq!(
        (r.x, r.y, r.width, r.height),
        (RECT_X, RECT_Y, RECT_W, RECT_H),
        "rect must be in raw clip-coord space (NOT translated by \
             clip_origin=({X_ORIGIN},{Y_ORIGIN})); the symptom of \
             over-translation is x={}, y={} (= raw + clip_origin).",
        r.x,
        r.y,
    );
}

/// Audit #9 (code-review follow-up): Xorg's
/// `ProcXFixesSelectSelectionInput` (`xfixes/select.c:189-192`)
/// runs `dixLookupWindow` first and propagates its return code
/// (`BadWindow` for an unknown xid). Before the fix yserver
/// silently stored the subscription, accepting illegal records.
#[test]
fn select_selection_input_with_invalid_window_returns_bad_window() {
    use std::io::Read;
    use yserver_protocol::x11::xfixes as x11xfixes;

    const CLIENT: u32 = 21;
    const UNKNOWN_WIN: u32 = 0x00ff_eeee;
    const PRIMARY: u32 = 1;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT);
    let mut backend = RecordingBackend::new();

    let mut body = Vec::with_capacity(12);
    body.extend_from_slice(&UNKNOWN_WIN.to_le_bytes());
    body.extend_from_slice(&PRIMARY.to_le_bytes());
    body.extend_from_slice(&x11xfixes::SELECTION_MASK_SET_OWNER.to_le_bytes());
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body fits");
    // The client negotiated XFIXES (Xorg gates requests on QueryVersion).
    state.xfixes_client_major.insert(CLIENT, 5);
    process_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT),
        SequenceNumber(1),
        RequestHeader {
            opcode: XFIXES_MAJOR_OPCODE,
            data: x11xfixes::SELECT_SELECTION_INPUT,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request");

    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf).expect("error reply delivered");
    assert_eq!(buf[0], 0, "first byte = error class");
    assert_eq!(
        buf[1],
        yserver_protocol::x11::error::BAD_WINDOW,
        "expected BadWindow (3) for unknown window xid; got {}",
        buf[1],
    );
    assert!(
        state.xfixes_selection_masks.is_empty(),
        "the subscription must NOT be recorded on BadWindow; got {:?}",
        state.xfixes_selection_masks,
    );
}

/// Audit #9 (code-review follow-up): Xorg's
/// `ProcXFixesSelectSelectionInput` (`xfixes/select.c:193-196`)
/// returns BadValue when `eventMask & ~SelectionAllEvents` is
/// non-zero. Before the fix yserver stored arbitrary mask bits.
#[test]
fn select_selection_input_with_mask_outside_known_bits_returns_bad_value() {
    use std::io::Read;
    use yserver_protocol::x11::{CreateWindowRequest, xfixes as x11xfixes};

    const CLIENT: u32 = 22;
    const WIN: u32 = 0x0150_0001;
    const PRIMARY: u32 = 1;
    const ILLEGAL_MASK: u32 = 1 << 8; // outside SelectionAllEvents

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT);
    let mut backend = RecordingBackend::new();
    // Window must exist for the window-validation step to pass,
    // so we cleanly isolate the mask-validation path.
    state.resources.create_window(
        ClientId(CLIENT),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(WIN),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 50,
            height: 50,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );

    let mut body = Vec::with_capacity(12);
    body.extend_from_slice(&WIN.to_le_bytes());
    body.extend_from_slice(&PRIMARY.to_le_bytes());
    body.extend_from_slice(&ILLEGAL_MASK.to_le_bytes());
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body fits");
    // The client negotiated XFIXES (Xorg gates requests on QueryVersion).
    state.xfixes_client_major.insert(CLIENT, 5);
    process_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT),
        SequenceNumber(1),
        RequestHeader {
            opcode: XFIXES_MAJOR_OPCODE,
            data: x11xfixes::SELECT_SELECTION_INPUT,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request");

    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf).expect("error reply delivered");
    assert_eq!(buf[0], 0, "first byte = error class");
    assert_eq!(
        buf[1],
        yserver_protocol::x11::error::BAD_VALUE,
        "expected BadValue (2) for mask with bits outside \
             SelectionAllEvents (0b111); got {}",
        buf[1],
    );
    assert!(
        state.xfixes_selection_masks.is_empty(),
        "the subscription must NOT be recorded on BadValue; got {:?}",
        state.xfixes_selection_masks,
    );
}

/// Audit #9 (code-review follow-up): the destroy/close path
/// must emit the notify BEFORE clearing the selection (matching
/// Xorg's `DeleteWindowFromAnySelections` order at
/// `dix/selection.c:131-138`) so the wire payload carries the
/// stored `selection_timestamp` — `selection->lastTimeChanged`
/// in Xorg's `xfixes/select.c:89`. yserver tracks
/// `lastTimeChanged` as the second element of the
/// `state.selections` tuple, stamped by SetSelectionOwner with
/// the request's `time` arg.
#[test]
fn destroy_window_owning_selection_carries_prior_last_time_changed_in_selection_timestamp() {
    use std::io::Read;
    use yserver_protocol::x11::{CreateWindowRequest, xfixes as x11xfixes};
    const SUBSCRIBER_ID: u32 = 15;
    const OWNER_ID: u32 = 16;
    const SUBSCRIBER_WIN: u32 = 0x00f0_0001;
    const OWNER_WIN: u32 = 0x0100_0001;
    const PRIMARY: u32 = 1;
    const SET_OWNER_TIME: u32 = 0x0a0b_0c0d;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, SUBSCRIBER_ID);
    let _ = install_client(&mut state, OWNER_ID);

    state.resources.create_window(
        ClientId(OWNER_ID),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(OWNER_WIN),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    state.xfixes_selection_masks.insert(
        (SUBSCRIBER_ID, ResourceId(SUBSCRIBER_WIN), AtomId(PRIMARY)),
        x11xfixes::SELECTION_MASK_WINDOW_DESTROY,
    );

    // Seed ownership directly with a known `lastTimeChanged`.
    // This decouples the destroy-path assertion from
    // `handle_set_selection_owner`'s time-resolution logic
    // (future/stale checks, ClientTime → ServerTime conversion);
    // we only care here that whatever value is in the second
    // tuple slot flows through to the notify wire payload.
    state
        .selections
        .insert(AtomId(PRIMARY), (ResourceId(OWNER_WIN), SET_OWNER_TIME));

    let mut destroy_body = Vec::with_capacity(4);
    destroy_body.extend_from_slice(&OWNER_WIN.to_le_bytes());
    let mut backend = RecordingBackend::new();
    handle_destroy_window(
        &mut state,
        &mut backend,
        None,
        ClientId(OWNER_ID),
        SequenceNumber(2),
        &destroy_body,
    )
    .expect("handle_destroy_window");
    peer.set_nonblocking(true).unwrap();

    let mut all = Vec::new();
    let mut chunk = [0u8; 4096];
    loop {
        match peer.read(&mut chunk) {
            Ok(0) => break,
            Ok(n) => all.extend_from_slice(&chunk[..n]),
            Err(_) => break,
        }
    }
    let evt: [u8; 32] = all
        .chunks_exact(32)
        .find(|e| {
            e[0] == crate::nested::XFIXES_FIRST_EVENT
                && e[1] == x11xfixes::SELECTION_NOTIFY_WINDOW_DESTROY
        })
        .map(|s| {
            let mut a = [0u8; 32];
            a.copy_from_slice(s);
            a
        })
        .expect("WindowDestroy notify in stream");

    assert_eq!(
        u32::from_le_bytes([evt[20], evt[21], evt[22], evt[23]]),
        SET_OWNER_TIME,
        "selection_timestamp must carry the prior SetSelectionOwner \
             time arg (Xorg `selection->lastTimeChanged`); pre-fix the \
             payload was zeroed",
    );
    // The `timestamp` field is `state.timestamp_now()` (Xorg's
    // `currentTime.milliseconds` equivalent); not asserted here
    // because in a sub-millisecond test it's legitimately 0 — which
    // matches Xorg behavior (`UpdateCurrentTimeIf` snapshots
    // `GetTimeInMillis()` with no floor). The
    // `selection_timestamp` assertion above is the load-bearing
    // spec-compliance check.
}

/// Audit #9 (code-review follow-up): Xorg's
/// `XFixesSelectionCallback` (`xfixes/select.c:79-91`) walks
/// every matching subscription record and emits one event per
/// `(client, window, selection)` tuple. A single client that
/// has two windows subscribed to the same selection must
/// receive TWO events whose `window` fields are the two
/// distinct subscriber windows — not one collapsed event nor
/// two events with the same window field.
///
/// `fanout_event_to_clients` deduplicates by ClientId *within
/// one call* via a freshly-allocated `seen` set, so calling it
/// once per subscription with a single-element slice is the
/// correct shape; the closure captures the per-iteration
/// subscriber window. This test pins that invariant against
/// future refactors.
#[test]
fn set_selection_owner_emits_one_event_per_subscription_when_client_has_two_windows() {
    use std::io::Read;
    use yserver_protocol::x11::xfixes as x11xfixes;
    const SUBSCRIBER: u32 = 13;
    const APP: u32 = 14;
    const WIN_A: u32 = 0x00d0_0001;
    const WIN_B: u32 = 0x00d0_0002;
    const OWNER_WIN: u32 = 0x00e0_0001;
    const PRIMARY: u32 = 1;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, SUBSCRIBER);
    let _ = install_client(&mut state, APP);

    // OWNER_WIN must exist for SetSelectionOwner's window
    // validation gate.
    state.resources.create_window(
        ClientId(APP),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(OWNER_WIN),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 50,
            height: 50,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );

    // Same client, two subscription records on the same selection.
    state.xfixes_selection_masks.insert(
        (SUBSCRIBER, ResourceId(WIN_A), AtomId(PRIMARY)),
        x11xfixes::SELECTION_MASK_SET_OWNER,
    );
    state.xfixes_selection_masks.insert(
        (SUBSCRIBER, ResourceId(WIN_B), AtomId(PRIMARY)),
        x11xfixes::SELECTION_MASK_SET_OWNER,
    );

    let mut body = Vec::with_capacity(12);
    body.extend_from_slice(&OWNER_WIN.to_le_bytes());
    body.extend_from_slice(&PRIMARY.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes());
    handle_set_selection_owner(&mut state, ClientId(APP), SequenceNumber(1), &body)
        .expect("handle_set_selection_owner");

    peer.set_nonblocking(true).unwrap();
    let mut all = Vec::new();
    let mut chunk = [0u8; 4096];
    loop {
        match peer.read(&mut chunk) {
            Ok(0) => break,
            Ok(n) => all.extend_from_slice(&chunk[..n]),
            Err(_) => break,
        }
    }
    let mut subscriber_windows: Vec<u32> = all
        .chunks_exact(32)
        .filter(|e| {
            e[0] == crate::nested::XFIXES_FIRST_EVENT
                && e[1] == x11xfixes::SELECTION_NOTIFY_SET_OWNER
        })
        .map(|e| u32::from_le_bytes([e[4], e[5], e[6], e[7]]))
        .collect();
    subscriber_windows.sort_unstable();
    assert_eq!(
        subscriber_windows,
        vec![WIN_A, WIN_B],
        "must get one event per (client, window, selection) subscription \
             record with distinct `window` fields; got {} bytes total: {:02x?}",
        all.len(),
        all,
    );
}

/// Audit #9: subscribing with mask=0 then re-subscribing with the
/// set-owner bit, the FIRST owner-change must still emit (verifies
/// the mask-bit gate, not the presence of the subscription key).
#[test]
fn set_selection_owner_skips_subscribers_whose_mask_excludes_set_owner() {
    use std::io::Read;
    use yserver_protocol::x11::xfixes as x11xfixes;

    const SUBSCRIBER: u32 = 5;
    const APP: u32 = 6;
    const SUBSCRIBER_WIN: u32 = 0x0050_0001;
    const PRIMARY: u32 = 1;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, SUBSCRIBER);
    let _ = install_client(&mut state, APP);

    // Subscribe with a mask that does NOT include SET_OWNER —
    // only WINDOW_DESTROY. SetSelectionOwner must NOT fire for
    // this subscription.
    state.xfixes_selection_masks.insert(
        (SUBSCRIBER, ResourceId(SUBSCRIBER_WIN), AtomId(PRIMARY)),
        x11xfixes::SELECTION_MASK_WINDOW_DESTROY,
    );

    let mut body = Vec::with_capacity(12);
    body.extend_from_slice(&0x0090_0001u32.to_le_bytes()); // owner window
    body.extend_from_slice(&PRIMARY.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // time
    handle_set_selection_owner(&mut state, ClientId(APP), SequenceNumber(1), &body)
        .expect("handle_set_selection_owner");

    peer.set_nonblocking(true).unwrap();
    let mut all = Vec::new();
    let mut chunk = [0u8; 4096];
    loop {
        match peer.read(&mut chunk) {
            Ok(0) => break,
            Ok(n) => all.extend_from_slice(&chunk[..n]),
            Err(_) => break,
        }
    }
    assert!(
        !all.chunks_exact(32)
            .any(|evt| evt[0] == crate::nested::XFIXES_FIRST_EVENT),
        "no XFixesSelectionNotify expected when subscriber's mask excludes \
             SET_OWNER; got {} bytes: {:02x?}",
        all.len(),
        all,
    );
}

/// X11 §CopyArea source-availability split: requested source
/// rect vs source drawable bounds → (clamped copy, missing
/// dst-coord rects for GraphicsExpose).
#[test]
fn copy_area_source_split_right_half_missing() {
    let mut state = ServerState::new();
    // 100×100 pixmap as the source.
    state.resources.create_pixmap(
        ClientId(1),
        yserver_protocol::x11::CreatePixmapRequest {
            depth: 24,
            pixmap: ResourceId(0x700),
            drawable: crate::resources::ROOT_WINDOW,
            width: 100,
            height: 100,
        },
    );
    // Copy 100 wide from x=50 → right 50 missing.
    let (avail, missing) = copy_area_source_split(&state, ResourceId(0x700), 50, 0, 0, 0, 100, 100);
    assert_eq!(avail, Some((50, 0, 0, 0, 50, 100)), "clamped copy");
    assert_eq!(
        missing,
        vec![(50, 0, 50, 100)],
        "missing right half in DST coords (xts XCopyArea-4 expects x=50 w=50)"
    );
    // Fully in-bounds → NoExposure (empty missing list).
    let (avail, missing) = copy_area_source_split(&state, ResourceId(0x700), 0, 0, 10, 10, 80, 80);
    assert_eq!(avail, Some((0, 0, 10, 10, 80, 80)));
    assert!(missing.is_empty(), "fully available → NoExposure");
    // Fully out of bounds → no copy, whole rect exposed.
    let (avail, missing) = copy_area_source_split(&state, ResourceId(0x700), 200, 0, 5, 5, 30, 30);
    assert!(avail.is_none());
    assert_eq!(missing, vec![(5, 5, 30, 30)]);
}

/// Stage 4d follow-up (codex review 2026-05-18): when ClipByChildren
/// (or any other clipping) fully covers the destination so no pixels
/// are actually copied, the X11 spec still requires the server to
/// emit a GraphicsExpose / NoExposure event for clients with
/// `graphics-exposures=True`. Pre-fix the early-return-on-empty
/// path silently swallowed this event; clients waiting on it
/// (xterm, gtk2 backing-store users) would hang.
#[test]
fn copy_area_fully_clipped_still_emits_graphics_expose_event() {
    use std::io::Read;
    use yserver_protocol::x11::{CreateGcRequest, CreateWindowRequest};

    const FRAME_XID: u32 = 0x0010_0001;
    const FRAME_HOST: u32 = 0x0040_0001;
    const FRAME_BACKING_HOST: u32 = 0x0050_0001;
    const CHILD_XID: u32 = 0x0010_0002;
    const CHILD_HOST: u32 = 0x0040_0002;
    const SRC_PIXMAP_XID: u32 = 0x0010_0010;
    const SRC_PIXMAP_HOST: u32 = 0x0040_0010;
    const GC_XID: u32 = 0x0010_0020;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    // Make the peer-read non-blocking so an absent event doesn't
    // hang the test.
    peer.set_nonblocking(true).expect("nonblocking");
    let mut backend = RecordingBackend::new();

    // Frame 100×100 entirely covered by child window 100×100 at
    // (0, 0). Any CopyArea(dst=frame, 0,0 100x100) gets fully
    // clipped by the child.
    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(FRAME_XID),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(FRAME_XID))
            .expect("frame");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(FRAME_HOST));
        w.redirected_backing = Some(crate::resources::RedirectedBacking {
            host_pixmap: crate::backend::PixmapHandle::from_raw_for_test(FRAME_BACKING_HOST),
            width: 100,
            height: 100,
            depth: 24,
        });
        w.map_state = crate::resources::MapState::Viewable;
    }
    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(CHILD_XID),
            parent: ResourceId(FRAME_XID),
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(CHILD_XID))
            .expect("child");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(CHILD_HOST));
        w.map_state = crate::resources::MapState::Viewable;
    }
    state.resources.create_pixmap(
        ClientId(1),
        yserver_protocol::x11::CreatePixmapRequest {
            pixmap: ResourceId(SRC_PIXMAP_XID),
            drawable: ROOT_WINDOW,
            width: 100,
            height: 100,
            depth: 24,
        },
    );
    let _ = state.resources.set_pixmap_host_xid(
        ResourceId(SRC_PIXMAP_XID),
        crate::backend::PixmapHandle::from_raw_for_test(SRC_PIXMAP_HOST),
    );
    // GC with graphics_exposures = True (the spec default; without
    // explicit override the GC inherits that default).
    state.resources.create_gc(
        ClientId(1),
        CreateGcRequest {
            gc: ResourceId(GC_XID),
            drawable: ResourceId(FRAME_XID),
            function: None,
            plane_mask: None,
            foreground: None,
            background: None,
            line_width: None,
            line_style: None,
            cap_style: None,
            join_style: None,
            fill_style: None,
            fill_rule: None,
            tile: None,
            stipple: None,
            tile_x_origin: None,
            tile_y_origin: None,
            font: None,
            subwindow_mode: None,
            graphics_exposures: Some(true),
            clip_x_origin: None,
            clip_y_origin: None,
            clip_mask: None,
            dash_offset: None,
            dashes: None,
            arc_mode: None,
        },
    );

    let mut body = Vec::with_capacity(24);
    body.extend_from_slice(&SRC_PIXMAP_XID.to_le_bytes());
    body.extend_from_slice(&FRAME_XID.to_le_bytes());
    body.extend_from_slice(&GC_XID.to_le_bytes());
    body.extend_from_slice(&0_i16.to_le_bytes());
    body.extend_from_slice(&0_i16.to_le_bytes());
    body.extend_from_slice(&0_i16.to_le_bytes());
    body.extend_from_slice(&0_i16.to_le_bytes());
    body.extend_from_slice(&100_u16.to_le_bytes());
    body.extend_from_slice(&100_u16.to_le_bytes());

    process_request(
        &mut state,
        &mut backend,
        ClientId(1),
        SequenceNumber(1),
        RequestHeader {
            opcode: 62,
            data: 0,
            length_units: 7,
        },
        &body,
        None,
    )
    .expect("dispatch CopyArea");

    // No backend.copy_area should have fired (fully clipped).
    let copy_calls = backend
        .calls()
        .into_iter()
        .filter(|c| matches!(c, crate::backend::recording::RecordedCall::CopyArea { .. }))
        .count();
    assert_eq!(
        copy_calls, 0,
        "fully-clipped CopyArea must NOT call backend.copy_area",
    );

    // The graphics-exposures contract still fires for a fully
    // dst-clipped copy — but as NoExposure: the SOURCE was fully
    // available (GraphicsExpose only describes missing source
    // regions; dst-side child clipping doesn't expose anything).
    let mut buf = [0u8; 64];
    let n = peer.read(&mut buf).unwrap_or(0);
    assert!(
        n >= 32,
        "expected a 32-byte NoExposure event even for a \
             fully-clipped CopyArea (codex review 2026-05-18); got \
             {n} bytes",
    );
    assert_eq!(
        buf[0], 14,
        "first byte must be NoExposure (event type 14) — source \
             fully available",
    );
}

// ---- Unviewable CopyArea/CopyPlane sources (Xorg micopy.c / miexpose.c) ----

const UV_FRAME: u32 = 0x0010_0101;
const UV_CHILD: u32 = 0x0010_0102;
const UV_LONE: u32 = 0x0010_0103;
const UV_SHOWN: u32 = 0x0010_0104;
const UV_PIXMAP: u32 = 0x0010_0110;
const UV_DST_PIXMAP: u32 = 0x0010_0111;
const UV_GC: u32 = 0x0010_0120;
const UV_GC_NOEXP: u32 = 0x0010_0121;

fn uv_gc_request(gc: u32, graphics_exposures: bool) -> yserver_protocol::x11::CreateGcRequest {
    yserver_protocol::x11::CreateGcRequest {
        gc: ResourceId(gc),
        drawable: ROOT_WINDOW,
        function: None,
        plane_mask: None,
        foreground: None,
        background: None,
        line_width: None,
        line_style: None,
        cap_style: None,
        join_style: None,
        fill_style: None,
        fill_rule: None,
        tile: None,
        stipple: None,
        tile_x_origin: None,
        tile_y_origin: None,
        font: None,
        subwindow_mode: None,
        graphics_exposures: Some(graphics_exposures),
        clip_x_origin: None,
        clip_y_origin: None,
        clip_mask: None,
        dash_offset: None,
        dashes: None,
        arc_mode: None,
    }
}

fn uv_window(
    state: &mut ServerState,
    xid: u32,
    parent: ResourceId,
    map_state: crate::resources::MapState,
) {
    state.resources.create_window(
        ClientId(1),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(xid),
            parent,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    let w = state.resources.window_mut(ResourceId(xid)).expect("window");
    w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(
        xid | 0x0040_0000,
    ));
    w.map_state = map_state;
}

fn uv_pixmap(state: &mut ServerState, xid: u32) {
    state.resources.create_pixmap(
        ClientId(1),
        yserver_protocol::x11::CreatePixmapRequest {
            pixmap: ResourceId(xid),
            drawable: ROOT_WINDOW,
            width: 100,
            height: 100,
            depth: 24,
        },
    );
    let _ = state.resources.set_pixmap_host_xid(
        ResourceId(xid),
        crate::backend::PixmapHandle::from_raw_for_test(xid | 0x0040_0000),
    );
}

/// Unmapped frame with a mapped (so Unviewable) child, a lone unmapped
/// window, a viewable window, two pixmaps and GCs with exposures on/off.
fn uv_fixture() -> (ServerState, UnixStream) {
    use crate::resources::MapState;
    let mut state = ServerState::new();
    let peer = install_client(&mut state, 1);
    uv_window(&mut state, UV_FRAME, ROOT_WINDOW, MapState::Unmapped);
    uv_window(
        &mut state,
        UV_CHILD,
        ResourceId(UV_FRAME),
        MapState::Unviewable,
    );
    uv_window(&mut state, UV_LONE, ROOT_WINDOW, MapState::Unmapped);
    uv_window(&mut state, UV_SHOWN, ROOT_WINDOW, MapState::Viewable);
    uv_pixmap(&mut state, UV_PIXMAP);
    uv_pixmap(&mut state, UV_DST_PIXMAP);
    state
        .resources
        .create_gc(ClientId(1), uv_gc_request(UV_GC, true));
    state
        .resources
        .create_gc(ClientId(1), uv_gc_request(UV_GC_NOEXP, false));
    (state, peer)
}

#[allow(clippy::too_many_arguments)]
fn uv_copy(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    opcode: u8,
    src: u32,
    dst: u32,
    gc: u32,
    src_xy: (i16, i16),
    dst_xy: (i16, i16),
    size: (u16, u16),
) {
    let mut body = Vec::with_capacity(28);
    body.extend_from_slice(&src.to_le_bytes());
    body.extend_from_slice(&dst.to_le_bytes());
    body.extend_from_slice(&gc.to_le_bytes());
    body.extend_from_slice(&src_xy.0.to_le_bytes());
    body.extend_from_slice(&src_xy.1.to_le_bytes());
    body.extend_from_slice(&dst_xy.0.to_le_bytes());
    body.extend_from_slice(&dst_xy.1.to_le_bytes());
    body.extend_from_slice(&size.0.to_le_bytes());
    body.extend_from_slice(&size.1.to_le_bytes());
    if opcode == 63 {
        body.extend_from_slice(&1u32.to_le_bytes());
    }
    process_request(
        state,
        backend,
        ClientId(1),
        SequenceNumber(1),
        RequestHeader {
            opcode,
            data: 0,
            length_units: u32::try_from(1 + body.len() / 4).unwrap(),
        },
        &body,
        None,
    )
    .expect("dispatch copy");
}

fn uv_copy_calls(backend: &RecordingBackend) -> usize {
    use crate::backend::recording::RecordedCall;
    backend
        .calls()
        .into_iter()
        .filter(|c| {
            matches!(
                c,
                RecordedCall::CopyArea { .. } | RecordedCall::CopyPlane { .. }
            )
        })
        .count()
}

/// Decoded (type, drawable, x, y, w, h, count, major) per 32-byte event.
type UvEvent = (u8, u32, u16, u16, u16, u16, u16, u8);

fn uv_events(bytes: &[u8]) -> Vec<UvEvent> {
    bytes
        .chunks_exact(32)
        .map(|e| {
            let u16_at = |i: usize| u16::from_le_bytes([e[i], e[i + 1]]);
            let drawable = u32::from_le_bytes([e[4], e[5], e[6], e[7]]);
            if e[0] == 13 {
                (
                    13,
                    drawable,
                    u16_at(8),
                    u16_at(10),
                    u16_at(12),
                    u16_at(14),
                    u16_at(18),
                    e[20],
                )
            } else {
                (e[0], drawable, 0, 0, 0, 0, 0, e[10])
            }
        })
        .collect()
}

/// `miHandleExposures` (`mi/miexpose.c:120-305`) as measured by
/// tools/vng-scenarios/expose-probe.c: a client window C (190x100)
/// with a child V (100,10 80x120). A scroll whose source runs past
/// C's bottom lands its missing rows outside C: NoExpose. A source
/// under V is hidden under ClipByChildren, not under IncludeInferiors.
#[test]
fn copy_area_exposes_what_the_source_hides_inside_the_destination_clip() {
    use crate::resources::MapState;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let (c, v) = (0x0010_0130u32, 0x0010_0131u32);
    uv_window(&mut state, c, ROOT_WINDOW, MapState::Viewable);
    uv_window(&mut state, v, ResourceId(c), MapState::Viewable);
    for (id, x, y, w, h) in [(c, 5, 20, 190, 100), (v, 100, 10, 80, 120)] {
        let win = state.resources.window_mut(ResourceId(id)).unwrap();
        (win.x, win.y, win.width, win.height) = (x, y, w, h);
    }
    state
        .resources
        .create_gc(ClientId(1), uv_gc_request(UV_GC, true));
    let mut inferiors = uv_gc_request(UV_GC_NOEXP, true);
    inferiors.subwindow_mode = Some(1);
    state.resources.create_gc(ClientId(1), inferiors);
    let mut copy = |state: &mut ServerState, gc, src: (i16, i16), dst: (i16, i16), size| {
        uv_copy(state, &mut backend, 62, c, c, gc, src, dst, size);
        uv_events(&read_all_available(&mut peer))
    };
    assert_eq!(
        copy(&mut state, UV_GC, (0, 0), (0, 40), (100, 200)),
        vec![(14, c, 0, 0, 0, 0, 0, 62)],
        "NoExpose"
    );
    assert_eq!(
        copy(&mut state, UV_GC, (90, 20), (10, 20), (40, 40)),
        vec![(13, c, 20, 20, 30, 40, 0, 62)]
    );
    assert_eq!(
        copy(&mut state, UV_GC_NOEXP, (90, 20), (10, 20), (40, 40)),
        vec![(14, c, 0, 0, 0, 0, 0, 62)],
        "IncludeInferiors: V's pixels are the source's"
    );
}

/// Xorg: an unrealized source window has an empty clipList
/// (mivaltree.c:691-696, miwindow.c:741-744, window.c:892), so miDoCopy
/// copies nothing and miHandleExposures exposes the whole rect.
#[test]
fn copy_area_from_unviewable_window_exposes_whole_dest_rect() {
    for (opcode, src) in [
        (62u8, UV_LONE),
        (62, UV_CHILD),
        (63, UV_LONE),
        (63, UV_CHILD),
    ] {
        let (mut state, mut peer) = uv_fixture();
        let mut backend = RecordingBackend::new();
        uv_copy(
            &mut state,
            &mut backend,
            opcode,
            src,
            UV_DST_PIXMAP,
            UV_GC,
            (10, 20),
            (5, 7),
            (30, 40),
        );
        assert_eq!(
            uv_copy_calls(&backend),
            0,
            "op {opcode} src 0x{src:x}: nothing copied"
        );
        assert_eq!(
            uv_events(&read_all_available(&mut peer)),
            vec![(13, UV_DST_PIXMAP, 5, 7, 30, 40, 0, opcode)],
            "op {opcode} src 0x{src:x}: one GraphicsExpose for the dest rect, no NoExpose",
        );
    }
}

#[test]
fn copy_area_from_unviewable_window_without_exposures_sends_nothing() {
    for opcode in [62u8, 63] {
        let (mut state, mut peer) = uv_fixture();
        let mut backend = RecordingBackend::new();
        uv_copy(
            &mut state,
            &mut backend,
            opcode,
            UV_CHILD,
            UV_DST_PIXMAP,
            UV_GC_NOEXP,
            (0, 0),
            (0, 0),
            (30, 40),
        );
        assert_eq!(uv_copy_calls(&backend), 0);
        assert!(
            read_all_available(&mut peer).is_empty(),
            "op {opcode}: no events"
        );
    }
}

/// A pixmap or viewable window source is unchanged: copied, NoExpose.
#[test]
fn copy_area_from_pixmap_or_viewable_window_still_copies_with_no_expose() {
    for opcode in [62u8, 63] {
        for src in [UV_PIXMAP, UV_SHOWN] {
            let (mut state, mut peer) = uv_fixture();
            let mut backend = RecordingBackend::new();
            uv_copy(
                &mut state,
                &mut backend,
                opcode,
                src,
                UV_DST_PIXMAP,
                UV_GC,
                (10, 20),
                (5, 7),
                (30, 40),
            );
            assert_eq!(uv_copy_calls(&backend), 1, "op {opcode} src 0x{src:x}");
            assert_eq!(
                uv_events(&read_all_available(&mut peer)),
                vec![(14, UV_DST_PIXMAP, 0, 0, 0, 0, 0, opcode)],
                "op {opcode} src 0x{src:x}: NoExpose",
            );
        }
    }
}

/// Xorg miDoCopy returns NULL for an unrealized destination before any
/// copy or exposure (micopy.c:157-160), so the requestor gets NoExpose
/// even when the source is unavailable.
#[test]
fn copy_area_to_unviewable_window_copies_nothing_and_sends_no_expose() {
    for opcode in [62u8, 63] {
        for (src, src_xy) in [(UV_PIXMAP, (0, 0)), (UV_PIXMAP, (90, 0)), (UV_LONE, (0, 0))] {
            let (mut state, mut peer) = uv_fixture();
            let mut backend = RecordingBackend::new();
            uv_copy(
                &mut state,
                &mut backend,
                opcode,
                src,
                UV_CHILD,
                UV_GC,
                src_xy,
                (0, 0),
                (30, 40),
            );
            assert_eq!(uv_copy_calls(&backend), 0, "op {opcode} src 0x{src:x}");
            assert!(
                !backend.calls().iter().any(|c| matches!(
                    c,
                    crate::backend::recording::RecordedCall::PaintWindowBackgroundRect { .. }
                )),
                "op {opcode} src 0x{src:x}: no background paint",
            );
            assert_eq!(
                uv_events(&read_all_available(&mut peer)),
                vec![(14, UV_CHILD, 0, 0, 0, 0, 0, opcode)],
                "op {opcode} src 0x{src:x} at {src_xy:?}: NoExpose",
            );
        }
    }
}

/// Drawing to an unmapped window records no damage (Xorg damage.c:197).
#[test]
fn poly_fill_on_unmapped_window_records_no_damage() {
    use crate::server::DamageObject;
    const DAMAGE_XID: u32 = 0x0010_0130;
    for (window, expect_damage) in [(UV_LONE, false), (UV_CHILD, false), (UV_SHOWN, true)] {
        let (mut state, _peer) = uv_fixture();
        let mut backend = RecordingBackend::new();
        state.damage_objects.insert(
            DAMAGE_XID,
            DamageObject {
                owner: ClientId(1),
                drawable: ResourceId(window),
                level: 3,
                rects: Vec::new(),
                pending_notify_fired: false,
                last_reported_geometry: None,
            },
        );
        let body = poly_fill_rectangle_body(window, UV_GC);
        process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(1),
            RequestHeader {
                opcode: 70,
                data: 0,
                length_units: u32::try_from(1 + body.len() / 4).unwrap(),
            },
            &body,
            None,
        )
        .expect("PolyFillRectangle");
        let dmg = state
            .damage_objects
            .get(&DAMAGE_XID)
            .expect("damage object");
        assert_eq!(
            !dmg.rects.is_empty() || dmg.pending_notify_fired,
            expect_damage,
            "window 0x{window:x}: rects={:?} fired={}",
            dmg.rects,
            dmg.pending_notify_fired,
        );
    }
}

/// Stage 4d Manual-redirect CopyArea ClipByChildren fix.
///
/// Scenario (matches marco's failing #6886 / #7450 CopyArea on
/// the MATE Control Center frame):
/// - Frame window 997×652 at root, mapped, with a redirected
///   backing pixmap allocated.
/// - CC client window 975×600 reparented under the frame at
///   (11, 41), mapped.
/// - X11 CopyArea(src=decoration_pixmap, dst=frame_window,
///   gc=default) 997×652.
///
/// Pre-fix: dispatch resolves `dst` to the backing pixmap and
/// hands the backend a single full-extent copy, which clobbers
/// the area where CC's content lives in the backing.
///
/// Spec-correct (Xorg `mi/midispcur.c` + the X11 GC
/// `subwindow-mode` default): under `ClipByChildren`, subtract
/// every mapped child's geometry before copying. Result is the
/// four border strips (top/bottom/left/right of CC).
#[test]
fn copy_area_into_window_with_mapped_child_excludes_child_area() {
    use crate::backend::recording::RecordedCall;
    use yserver_protocol::x11::{CreateGcRequest, CreateWindowRequest};

    const FRAME_XID: u32 = 0x0010_0001;
    const FRAME_HOST: u32 = 0x0040_0001;
    const FRAME_BACKING_HOST: u32 = 0x0050_0001;
    const CHILD_XID: u32 = 0x0010_0002;
    const CHILD_HOST: u32 = 0x0040_0002;
    const SRC_PIXMAP_XID: u32 = 0x0010_0010;
    const SRC_PIXMAP_HOST: u32 = 0x0040_0010;
    const GC_XID: u32 = 0x0010_0020;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    // Frame: top-level under root, viewable, redirected (backing
    // present). Mirrors the post-Reparent + post-Map + post-
    // activate_redirect_backing state.
    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(FRAME_XID),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 997,
            height: 652,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(FRAME_XID))
            .expect("frame");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(FRAME_HOST));
        w.redirected_backing = Some(crate::resources::RedirectedBacking {
            host_pixmap: crate::backend::PixmapHandle::from_raw_for_test(FRAME_BACKING_HOST),
            width: 997,
            height: 652,
            depth: 24,
        });
        w.map_state = crate::resources::MapState::Viewable;
    }
    // CC: child of frame, viewable, at (11, 41) sized 975×600.
    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(CHILD_XID),
            parent: ResourceId(FRAME_XID),
            x: 11,
            y: 41,
            width: 975,
            height: 600,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let w = state
            .resources
            .window_mut(ResourceId(CHILD_XID))
            .expect("child");
        w.host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(CHILD_HOST));
        w.map_state = crate::resources::MapState::Viewable;
    }
    // Source pixmap (depth-24, same depth as frame).
    state.resources.create_pixmap(
        ClientId(1),
        yserver_protocol::x11::CreatePixmapRequest {
            pixmap: ResourceId(SRC_PIXMAP_XID),
            drawable: ROOT_WINDOW,
            width: 997,
            height: 652,
            depth: 24,
        },
    );
    let _ = state.resources.set_pixmap_host_xid(
        ResourceId(SRC_PIXMAP_XID),
        crate::backend::PixmapHandle::from_raw_for_test(SRC_PIXMAP_HOST),
    );
    // GC for client 1. Every value-mask field is None → defaults
    // apply, including subwindow-mode = ClipByChildren.
    state.resources.create_gc(
        ClientId(1),
        CreateGcRequest {
            gc: ResourceId(GC_XID),
            drawable: ResourceId(FRAME_XID),
            function: None,
            plane_mask: None,
            foreground: None,
            background: None,
            line_width: None,
            line_style: None,
            cap_style: None,
            join_style: None,
            fill_style: None,
            fill_rule: None,
            tile: None,
            stipple: None,
            tile_x_origin: None,
            tile_y_origin: None,
            font: None,
            subwindow_mode: None,
            graphics_exposures: None,
            clip_x_origin: None,
            clip_y_origin: None,
            clip_mask: None,
            dash_offset: None,
            dashes: None,
            arc_mode: None,
        },
    );

    // Build CopyArea body: src(4) dst(4) gc(4) src_x(2) src_y(2)
    //                      dst_x(2) dst_y(2) width(2) height(2).
    let mut body = Vec::with_capacity(24);
    body.extend_from_slice(&SRC_PIXMAP_XID.to_le_bytes());
    body.extend_from_slice(&FRAME_XID.to_le_bytes());
    body.extend_from_slice(&GC_XID.to_le_bytes());
    body.extend_from_slice(&0_i16.to_le_bytes()); // src_x
    body.extend_from_slice(&0_i16.to_le_bytes()); // src_y
    body.extend_from_slice(&0_i16.to_le_bytes()); // dst_x
    body.extend_from_slice(&0_i16.to_le_bytes()); // dst_y
    body.extend_from_slice(&997_u16.to_le_bytes()); // width
    body.extend_from_slice(&652_u16.to_le_bytes()); // height

    process_request(
        &mut state,
        &mut backend,
        ClientId(1),
        SequenceNumber(1),
        RequestHeader {
            opcode: 62, // CopyArea major opcode
            data: 0,
            length_units: 7, // 1 header + 6 body words = 7 (4-byte units)
        },
        &body,
        None,
    )
    .expect("dispatch CopyArea");

    let copy_calls: Vec<_> = backend
        .calls()
        .into_iter()
        .filter_map(|c| match c {
            RecordedCall::CopyArea {
                src_host_xid,
                dst_host_xid,
                src_x,
                src_y,
                dst_x,
                dst_y,
                width,
                height,
            } => Some((
                src_host_xid,
                dst_host_xid,
                src_x,
                src_y,
                dst_x,
                dst_y,
                width,
                height,
            )),
            _ => None,
        })
        .collect();

    // Pre-fix: a single 997×652 CopyArea covering CC's area.
    // Post-fix: four border strips that miss the (11, 41, 975, 600)
    // child rect entirely.
    assert_eq!(
        copy_calls.len(),
        4,
        "expected 4 border strips for ClipByChildren around the \
             mapped child; pre-fix this is 1 (the full-extent copy \
             that clobbers CC's area in the backing); got {copy_calls:?}",
    );

    // No copy may overlap the child rect (11, 41, 975, 600).
    let child = (11_i32, 41_i32, 11_i32 + 975, 41_i32 + 600);
    for (_, dst_host, _, _, dx, dy, w, h) in &copy_calls {
        let r = (
            i32::from(*dx),
            i32::from(*dy),
            i32::from(*dx) + i32::from(*w),
            i32::from(*dy) + i32::from(*h),
        );
        let overlaps = r.0 < child.2 && r.2 > child.0 && r.1 < child.3 && r.3 > child.1;
        assert!(
            !overlaps,
            "copy strip ({dx},{dy} {w}x{h}) overlaps the child rect (11,41 975x600); \
                 ClipByChildren must exclude mapped children",
        );
        // Preserve window identity for backend border translation.
        assert_eq!(
            *dst_host, FRAME_HOST,
            "ClipByChildren strips stay in window-local coordinates",
        );
    }
}

/// InputOnly children do not contribute visible pixels and must
/// not be subtracted by ClipByChildren.
#[test]
fn copy_area_clip_by_children_ignores_input_only_child() {
    use crate::resources::{MapState, WindowClass};
    use yserver_protocol::x11::{CreateWindowRequest, ResourceId};

    let mut state = ServerState::new();
    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(0x0020_0001),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 80,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        CreateWindowRequest {
            depth: 0,
            window: ResourceId(0x0020_0002),
            parent: ResourceId(0x0020_0001),
            x: 10,
            y: 10,
            width: 20,
            height: 20,
            border_width: 0,
            class: 2,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let child = state
            .resources
            .window_mut(ResourceId(0x0020_0002))
            .expect("child");
        child.map_state = MapState::Viewable;
        assert_eq!(child.class, WindowClass::InputOnly);
    }

    let rect = yserver_protocol::x11::CopyAreaRequest {
        src: ResourceId(0x1),
        dst: ResourceId(0x0020_0001),
        gc: ResourceId(0x1),
        src_x: 0,
        src_y: 0,
        dst_x: 0,
        dst_y: 0,
        width: 100,
        height: 80,
    };
    let draw_state = crate::backend::DrawState {
        subwindow_mode: crate::backend::SubwindowMode::ClipByChildren,
        ..Default::default()
    };

    let got = copy_area_effective_dst_rects(&state, ResourceId(0x0020_0001), &draw_state, &rect);
    assert_eq!(got.len(), 1);
    assert_eq!(got[0].x, 0);
    assert_eq!(got[0].y, 0);
    assert_eq!(got[0].width, 100);
    assert_eq!(got[0].height, 80);
}

/// A bounding-shaped child takes only its shape out of its parent
/// under ClipByChildren (Xorg subtracts its `borderSize`,
/// `dix/window.c:1747-1770`). xfce4-settings-manager's socket S at
/// (8,8) 730x531 is shaped to the 450 rows of its viewport, and the
/// manager repaints its button bar under S's rect but outside its
/// shape with `CopyArea(8,464 730x36)`; measured on Xorg 21.1 by
/// tools/vng-scenarios/xembed-scroll-probe.c, the bar is drawn.
#[test]
fn copy_area_clip_by_children_takes_out_only_a_shaped_childs_shape() {
    use crate::resources::MapState;
    use yserver_protocol::x11::{CreateWindowRequest, ResourceId, shape as x11shape};

    let mut state = ServerState::new();
    let (c, s) = (ResourceId(0x0020_0101), ResourceId(0x0020_0102));
    for (window, parent, x, y, width, height) in
        [(c, ROOT_WINDOW, 0, 0, 746, 500), (s, c, 8, 8, 730, 531)]
    {
        state.resources.create_window(
            yserver_protocol::x11::ClientId(1),
            CreateWindowRequest {
                depth: 24,
                window,
                parent,
                x,
                y,
                width,
                height,
                border_width: 0,
                class: 1,
                visual: crate::resources::ROOT_VISUAL,
                ..Default::default()
            },
        );
    }
    state.resources.window_mut(s).expect("socket").map_state = MapState::Viewable;
    crate::nested::set_shape_rects(
        &mut state,
        s,
        x11shape::KIND_BOUNDING,
        vec![yserver_protocol::x11::xfixes::RegionRect {
            x: 0,
            y: 0,
            width: 730,
            height: 450,
        }],
    );
    let request = yserver_protocol::x11::CopyAreaRequest {
        src: ResourceId(0x1),
        dst: c,
        gc: ResourceId(0x1),
        src_x: 0,
        src_y: 0,
        dst_x: 8,
        dst_y: 464,
        width: 730,
        height: 36,
    };
    let draw_state = crate::backend::DrawState {
        subwindow_mode: crate::backend::SubwindowMode::ClipByChildren,
        ..Default::default()
    };
    let got = copy_area_effective_dst_rects(&state, c, &draw_state, &request);
    assert_eq!(got.len(), 1);
    assert_eq!(
        (got[0].x, got[0].y, got[0].width, got[0].height),
        (8, 464, 730, 36)
    );
}

/// MANUALLY-redirected children must not be subtracted by
/// ClipByChildren. They don't claim the parent's pixmap real
/// estate — the redirecting compositor (which may be the
/// parent's own client) puts the children's pixels there
/// itself via subsequent ops. Subtracting them strips the
/// compositor's own composite-target rect to empty.
///
/// Live trigger: mate-panel notification-area-applet, which
/// calls `RedirectWindow(socket, Manual)` on each tray slot and
/// then `CopyArea` from each embedded applet's redirected
/// pixmap into its own visible top-level. Pre-fix every such
/// CopyArea is "fully clipped, no backend call" because the
/// manually-redirected socket children fully overlap the
/// destination — so the tray icons never make it into the
/// notification-area-applet's own backing, and mate-compositor
/// (which reads that backing via NameWindowPixmap) shows the
/// panel without icons.
#[test]
fn copy_area_clip_by_children_ignores_manually_redirected_child() {
    use crate::{
        resources::{MapState, WindowClass},
        server::{CompositeRedirectMode, RedirectRecord},
    };
    use yserver_protocol::x11::{ClientId, CreateWindowRequest, ResourceId};

    let mut state = ServerState::new();
    let parent_xid = ResourceId(0x0021_0003);
    let child_xid = ResourceId(0x0021_0013);

    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: parent_xid,
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 80,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: child_xid,
            parent: parent_xid,
            x: 0,
            y: 0,
            width: 100,
            height: 80,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let child = state.resources.window_mut(child_xid).expect("child");
        child.map_state = MapState::Viewable;
        assert_eq!(child.class, WindowClass::InputOutput);
    }
    // RedirectWindow(child, Manual). Key shape is
    // `(window, subwindows=false)` for per-window
    // RedirectWindow (vs `(parent, true)` for the inherited
    // RedirectSubwindows form).
    state
        .composite_redirects
        .redirect_window(
            child_xid,
            RedirectRecord {
                mode: CompositeRedirectMode::Manual,
                owner: ClientId(1),
            },
        )
        .unwrap();

    let rect = yserver_protocol::x11::CopyAreaRequest {
        src: ResourceId(0x1),
        dst: parent_xid,
        gc: ResourceId(0x1),
        src_x: 0,
        src_y: 0,
        dst_x: 0,
        dst_y: 0,
        width: 100,
        height: 80,
    };
    let draw_state = crate::backend::DrawState {
        subwindow_mode: crate::backend::SubwindowMode::ClipByChildren,
        ..Default::default()
    };

    let got = copy_area_effective_dst_rects(&state, parent_xid, &draw_state, &rect);
    assert_eq!(
        got.len(),
        1,
        "manual-redirected child must not be subtracted; got {got:?}"
    );
    assert_eq!(got[0].x, 0);
    assert_eq!(got[0].y, 0);
    assert_eq!(got[0].width, 100);
    assert_eq!(got[0].height, 80);
}

/// Regression guard: an AUTOMATIC-redirected child *must*
/// still be subtracted by ClipByChildren. With Automatic
/// redirect the X server auto-composites the child's backing
/// into the parent's pixmap; the parent's own paint then
/// clipping out the child's area is the correct shape (the
/// child's pixels arrive via the auto-composite, not via the
/// parent's paint). The manual-only exception above must not
/// loosen this case.
#[test]
fn copy_area_clip_by_children_still_subtracts_automatic_redirected_child() {
    use crate::{
        resources::{MapState, WindowClass},
        server::{CompositeRedirectMode, RedirectRecord},
    };
    use yserver_protocol::x11::{ClientId, CreateWindowRequest, ResourceId};

    let mut state = ServerState::new();
    let parent_xid = ResourceId(0x0022_0001);
    let child_xid = ResourceId(0x0022_0002);

    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: parent_xid,
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 80,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: child_xid,
            parent: parent_xid,
            x: 10,
            y: 10,
            width: 50,
            height: 50,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    {
        let child = state.resources.window_mut(child_xid).expect("child");
        child.map_state = MapState::Viewable;
        assert_eq!(child.class, WindowClass::InputOutput);
    }
    state
        .composite_redirects
        .redirect_window(
            child_xid,
            RedirectRecord {
                mode: CompositeRedirectMode::Automatic,
                owner: ClientId(1),
            },
        )
        .unwrap();

    let rect = yserver_protocol::x11::CopyAreaRequest {
        src: ResourceId(0x1),
        dst: parent_xid,
        gc: ResourceId(0x1),
        src_x: 0,
        src_y: 0,
        dst_x: 0,
        dst_y: 0,
        width: 100,
        height: 80,
    };
    let draw_state = crate::backend::DrawState {
        subwindow_mode: crate::backend::SubwindowMode::ClipByChildren,
        ..Default::default()
    };

    let got = copy_area_effective_dst_rects(&state, parent_xid, &draw_state, &rect);
    // Automatic-redirected child is still subtracted, so we
    // expect the original 100×80 rect to be split into four
    // border strips around the (10,10 50x50) child rect.
    assert!(
        got.len() >= 2,
        "automatic-redirected child must still be subtracted; expected > 1 \
             strip, got {got:?}"
    );
    let child = (10_i32, 10_i32, 60_i32, 60_i32);
    for r in &got {
        let rr = (
            i32::from(r.x),
            i32::from(r.y),
            i32::from(r.x) + i32::from(r.width),
            i32::from(r.y) + i32::from(r.height),
        );
        let overlaps = rr.0 < child.2 && rr.2 > child.0 && rr.1 < child.3 && rr.3 > child.1;
        assert!(
            !overlaps,
            "strip ({},{} {}x{}) overlaps automatic-redirected child (10,10 50x50)",
            r.x, r.y, r.width, r.height,
        );
    }
}

fn render_damage_fixture(
    render_return_region: Vec<yserver_protocol::x11::xfixes::RegionRect>,
) -> (ServerState, RecordingBackend) {
    use crate::{
        backend::PictureHandle,
        resources::{PictureKind, PictureState},
        server::DamageObject,
    };
    use yserver_protocol::x11::CreateWindowRequest;

    const COMPOSITOR: u32 = 7;
    const WIN_XID: u32 = 0x0020_0001;
    const SRC_PIC_XID: u32 = 0x0020_0010;
    const DST_PIC_XID: u32 = 0x0020_0011;
    const DAMAGE_XID: u32 = 0x0020_0020;
    const HOST_SRC: u32 = 0xAA01;
    const HOST_DST: u32 = 0xAA02;

    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();
    backend.render_return_region = render_return_region;
    let _peer = install_client(&mut state, COMPOSITOR);

    state.resources.create_window(
        ClientId(COMPOSITOR),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(WIN_XID),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 800,
            height: 600,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );

    state.resources.create_picture(
        ResourceId(SRC_PIC_XID),
        PictureState {
            client: ClientId(COMPOSITOR),
            host_picture_xid: Some(PictureHandle::from_raw_for_test(HOST_SRC)),
            host_owned_pixmap: None,
            kind: PictureKind::Drawable,
            drawable: Some(ResourceId(WIN_XID)),
            window: None,
        },
    );
    state.resources.create_picture(
        ResourceId(DST_PIC_XID),
        PictureState {
            client: ClientId(COMPOSITOR),
            host_picture_xid: Some(PictureHandle::from_raw_for_test(HOST_DST)),
            host_owned_pixmap: None,
            kind: PictureKind::Drawable,
            drawable: Some(ResourceId(WIN_XID)),
            window: None,
        },
    );
    // The dst window must be MAPPED for these tests to describe a real
    // situation. Damage is gated on viewability (issue #97): Xorg's
    // `checkPictureDamage` requires `RegionNotEmpty(pCompositeClip)`
    // (miext/damage/damage.c:474) and an unmapped window's clip is empty,
    // so a RENDER op into it damages nothing there either. Leaving the
    // window unmapped made these tests assert damage that Xorg would not
    // produce; mapping it keeps each test's real subject — "the render op
    // damages exactly the backend-returned region" — intact.
    let _ = state.resources.map_window(ResourceId(WIN_XID));

    state.damage_objects.insert(
        DAMAGE_XID,
        DamageObject {
            owner: ClientId(COMPOSITOR),
            drawable: ResourceId(WIN_XID),
            level: 3,
            rects: Vec::new(),
            pending_notify_fired: false,
            last_reported_geometry: None,
        },
    );

    (state, backend)
}

fn assert_damage_rects_exact(
    state: &ServerState,
    expected: &[(i16, i16, u16, u16)],
    message: &str,
) {
    const DAMAGE_XID: u32 = 0x0020_0020;
    let damage = state.damage_objects.get(&DAMAGE_XID).unwrap();
    let got: Vec<(i16, i16, u16, u16)> = damage
        .rects
        .iter()
        .map(|r| (r.x, r.y, r.width, r.height))
        .collect();
    assert_eq!(got, expected, "{message}");
}

/// RENDER Composite must damage exactly the backend-returned region on
/// the dst picture's underlying drawable.
#[test]
fn render_composite_emits_damage_on_dst_drawable() {
    const COMPOSITOR: u32 = 7;
    const SRC_PIC_XID: u32 = 0x0020_0010;
    const DST_PIC_XID: u32 = 0x0020_0011;
    let (mut state, mut backend) =
        render_damage_fixture(vec![yserver_protocol::x11::xfixes::RegionRect {
            x: 0,
            y: 0,
            width: 100,
            height: 80,
        }]);

    // RENDER Composite body (minor=8, total 32 bytes):
    // op(1) + pad(3) + src(4) + mask(4) + dst(4) + src_xy(4) +
    // mask_xy(4) + dst_xy(4) + size(4)
    let mut body = vec![0u8; 32];
    body[0] = 3; // PictOpOver
    body[4..8].copy_from_slice(&SRC_PIC_XID.to_le_bytes());
    body[8..12].copy_from_slice(&0u32.to_le_bytes()); // no mask
    body[12..16].copy_from_slice(&DST_PIC_XID.to_le_bytes());
    body[28..30].copy_from_slice(&100u16.to_le_bytes()); // width
    body[30..32].copy_from_slice(&80u16.to_le_bytes()); // height

    process_request(
        &mut state,
        &mut backend,
        ClientId(COMPOSITOR),
        SequenceNumber(1),
        RequestHeader {
            opcode: 133, // RENDER major opcode
            data: 8,     // minor: Composite
            length_units: u32::try_from(1 + 32 / 4).unwrap(),
        },
        &body,
        None,
    )
    .unwrap();

    assert_damage_rects_exact(
        &state,
        &[(0, 0, 100, 80)],
        "render_composite must damage exactly the backend-returned region",
    );
}

