    // Pre-seed: client is already subscribed.
    state.dpms.selected_by.insert(ClientId(1));
    assert!(state.dpms.selected_by.contains(&ClientId(1)));

    let header = RequestHeader {
        opcode: 134,
        data: 8,
        length_units: 2,
    }; // SelectInput
    let body = [0u8, 0, 0, 0]; // mask = 0 → unsubscribe
