    apply_screen_saver_transition(
        &mut state,
        &mut backend,
        ScreenSaverActive::On,
        /*forced=*/ true,
    );

    let bytes = read_all_available(&mut peer);
    let idx = bytes.iter().position(|&b| b == 92).unwrap();
