#[test]
fn evaluate_alarms_re_arm_overflow_transitions_alarm_to_inactive() {
    // Xorg sync.c:589-597 — re-arm overflow on i64::checked_add
    // must transition the alarm to Inactive and leave wait_value
    // unchanged.
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let counter = 0x1000;
    state.sync_counters.insert(
        counter,
        crate::server::SyncCounter {
            owner: ClientId(1),
            value: 0,
        },
    );
    let alarm_id = 0x2000;
    // Start near i64::MAX so adding delta overflows on the very
    // first re-arm step. Use PositiveTransition so the trigger fires
    // when new >= wait_value.
    let near_max = i64::MAX - 10;
    state.sync_alarms.insert(
        alarm_id,
        crate::server::SyncAlarm {
            owner: ClientId(1),
            counter,
            wait_value: near_max,
            delta: 100, // would overflow on first add
            test_type: x11sync::TEST_POSITIVE_TRANSITION,
            events: true,
            state: x11sync::ALARM_STATE_ACTIVE,
            event_clients: Vec::new(),
            value_type: 0,
            raw_wait: near_max,
            check_type: x11sync::TEST_POSITIVE_TRANSITION,
        },
    );

    // Crossing: old < wait_value, new >= wait_value → trigger fires.
    evaluate_alarms_for_counter(&mut state, counter, near_max - 1, near_max + 5);

    let after = &state.sync_alarms[&alarm_id];
    assert_eq!(
        after.state,
        x11sync::ALARM_STATE_INACTIVE,
        "overflow on re-arm → Inactive"
    );
    assert_eq!(
        after.wait_value, near_max,
        "wait_value unchanged on overflow (Xorg sync.c:589-597)"
    );
}

/// Encode an INT64 value in XSync wire format: hi(INT32 LE) || lo(CARD32 LE).
/// This is NOT the same as `i64::to_le_bytes()` (which is lo-first).
fn xsync_i64(v: i64) -> [u8; 8] {
    #[allow(clippy::cast_possible_truncation)]
    let hi = (v >> 32) as i32;
    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
    let lo = v as u32;
    let mut out = [0u8; 8];
    out[..4].copy_from_slice(&hi.to_le_bytes());
    out[4..].copy_from_slice(&lo.to_le_bytes());
    out
}

#[test]
fn relative_alarm_value_on_idletime_resolves_against_current_idle() {
    use std::time::Duration;
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    // Pre-condition: already idle 5s.
    state.dpms.last_activity = std::time::Instant::now() - Duration::from_secs(5);

    // CreateAlarm relative-value=10_000 → wait_value should resolve
    // to current_idle (~5_000) + 10_000 = ~15_000.
    let alarm_id: u32 = 0x2000_0002;
    let mut body = Vec::new();
    body.extend_from_slice(&alarm_id.to_le_bytes());
    let mask: u32 = x11sync::CA_COUNTER
        | x11sync::CA_VALUE_TYPE
        | x11sync::CA_VALUE
        | x11sync::CA_TEST_TYPE
        | x11sync::CA_DELTA
        | x11sync::CA_EVENTS;
    body.extend_from_slice(&mask.to_le_bytes());
    body.extend_from_slice(&x11sync::IDLETIME_COUNTER.to_le_bytes());
    body.extend_from_slice(&x11sync::VALUE_TYPE_RELATIVE.to_le_bytes()); // u32
    body.extend_from_slice(&xsync_i64(10_000)); // value = 10_000 relative
    body.extend_from_slice(&x11sync::TEST_POSITIVE_TRANSITION.to_le_bytes());
    body.extend_from_slice(&xsync_i64(0)); // delta = 0
    body.push(1); // events = true
    body.extend_from_slice(&[0u8; 3]);

    let header = RequestHeader {
        opcode: 142,
        data: x11sync::CREATE_ALARM,
        length_units: u32::try_from(2 + body.len() / 4).unwrap(),
    };
    let _ = handle_sync_request(
        &mut state,
        &mut backend,
        ClientId(1),
        SequenceNumber(1),
        header,
        &body,
    );

    let alarm = state.sync_alarms.get(&alarm_id).expect("alarm exists");
    assert!(
        alarm.wait_value >= 14_500 && alarm.wait_value <= 16_000,
        "wait_value ≈ current_idle(5000) + 10000 = 15000; got {}",
        alarm.wait_value
    );
}

#[test]
fn create_alarm_on_idletime_with_comparison_already_true_fires_immediately() {
    // Xorg sync.c:1772-1775 — create-time trigger eval passes
    // (old=current, new=current). PositiveTransition requires
    // `old < wait <= new` so it cannot fire on a same-value pair;
    // only Comparison test types can fire at create time.
    // PositiveComparison fires when `new >= wait`, which is
    // exactly the "client opens an alarm while user is already
    // idle past the threshold" smoke we want to verify.
    use std::time::Duration;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    // Pre-condition: already idle past the alarm threshold.
    state.dpms.last_activity = std::time::Instant::now() - Duration::from_secs(120);

    let alarm_id: u32 = 0x2000_0001;
    let mut body = Vec::new();
    body.extend_from_slice(&alarm_id.to_le_bytes());
    let mask: u32 = x11sync::CA_COUNTER
        | x11sync::CA_VALUE_TYPE
        | x11sync::CA_VALUE
        | x11sync::CA_TEST_TYPE
        | x11sync::CA_DELTA
        | x11sync::CA_EVENTS;
    body.extend_from_slice(&mask.to_le_bytes());
    body.extend_from_slice(&x11sync::IDLETIME_COUNTER.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // value_type = Absolute
    body.extend_from_slice(&xsync_i64(60_000)); // value = 60_000
    body.extend_from_slice(&x11sync::TEST_POSITIVE_COMPARISON.to_le_bytes());
    body.extend_from_slice(&xsync_i64(0)); // delta = 0 → goes Inactive on fire
    body.push(1); // events = true
    body.extend_from_slice(&[0u8; 3]);

    let header = RequestHeader {
        opcode: 142,
        data: x11sync::CREATE_ALARM,
        length_units: u32::try_from(2 + body.len() / 4).unwrap(),
    };
    let _ = handle_sync_request(
        &mut state,
        &mut backend,
        ClientId(1),
        SequenceNumber(1),
        header,
        &body,
    );

    let bytes = read_all_available(&mut peer);
    // AlarmNotify event: type = SYNC_FIRST_EVENT(83) + ALARM_NOTIFY_KIND(1) = 84
    assert!(
        bytes.contains(&84),
        "AlarmNotify must fire at create-time for an already-idle PositiveComparison alarm; got {:?}",
        bytes
    );
    // Comparison + delta=0 transitions to Inactive on fire.
    assert_eq!(
        state.sync_alarms[&alarm_id].state,
        x11sync::ALARM_STATE_INACTIVE
    );
}

#[test]
fn create_alarm_on_idletime_with_pos_transition_does_not_fire_at_create() {
    // Companion test: PositiveTransition cannot fire at create-time
    // (Xorg sync.c:1772-1775 — old==new). The alarm sits Active
    // waiting for the post-poll evaluator or input wake to drive
    // the (old, new) pair across the threshold.
    use std::time::Duration;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    state.dpms.last_activity = std::time::Instant::now() - Duration::from_secs(120);

    let alarm_id: u32 = 0x2000_0003;
    let mut body = Vec::new();
    body.extend_from_slice(&alarm_id.to_le_bytes());
    let mask: u32 = x11sync::CA_COUNTER
        | x11sync::CA_VALUE_TYPE
        | x11sync::CA_VALUE
        | x11sync::CA_TEST_TYPE
        | x11sync::CA_DELTA
        | x11sync::CA_EVENTS;
    body.extend_from_slice(&mask.to_le_bytes());
    body.extend_from_slice(&x11sync::IDLETIME_COUNTER.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes());
    body.extend_from_slice(&xsync_i64(60_000));
    body.extend_from_slice(&x11sync::TEST_POSITIVE_TRANSITION.to_le_bytes());
    body.extend_from_slice(&xsync_i64(0));
    body.push(1);
    body.extend_from_slice(&[0u8; 3]);

    let header = RequestHeader {
        opcode: 142,
        data: x11sync::CREATE_ALARM,
        length_units: u32::try_from(2 + body.len() / 4).unwrap(),
    };
    let _ = handle_sync_request(
        &mut state,
        &mut backend,
        ClientId(1),
        SequenceNumber(1),
        header,
        &body,
    );

    let bytes = read_all_available(&mut peer);
    assert!(
        !bytes.contains(&84),
        "PositiveTransition with old==new at create-time must not fire"
    );
    assert_eq!(
        state.sync_alarms[&alarm_id].state,
        x11sync::ALARM_STATE_ACTIVE,
        "alarm stays Active, waiting for evaluator/input to drive the transition"
    );
}

#[test]
fn suspend_release_resets_idletime_last_evaluated_and_per_device_baselines() {
    use std::time::Duration;
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    // Pre-seed: stale idletime cache from before suspend.
    state
        .idletime_last_evaluated
        .insert(x11sync::IDLETIME_COUNTER, 999_999);
    state
        .per_device_last_activity
        .insert(3, std::time::Instant::now() - Duration::from_secs(120));

    // Insert a suspending client, then drain via Suspend(false).
    state.screensaver.suspend_counts.insert(ClientId(1), 1);
    let header = RequestHeader {
        opcode: 150,
        data: x11screensaver::SUSPEND,
        length_units: 2,
    };
    let _ = handle_screen_saver_request(
        &mut state,
        &mut backend,
        ClientId(1),
        SequenceNumber(1),
        header,
        &[0u8, 0, 0, 0],
    );

    // The drain hit the (drained && empty && SS=Off && DPMS=On) guard
    // and must have reset both IDLETIME bookkeeping fields.
    assert!(
        state.idletime_last_evaluated.is_empty(),
        "idletime_last_evaluated must be cleared on suspend release"
    );
    let vck_baseline = state
        .per_device_last_activity
        .get(&3)
        .copied()
        .expect("per_device_last_activity[3] still present");
    let elapsed = std::time::Instant::now().duration_since(vck_baseline);
    assert!(
        elapsed < Duration::from_millis(100),
        "per_device_last_activity[3] must be reset to ~now; got elapsed {elapsed:?}"
    );
}

/// Per X11 spec (Xorg `dix/enterleave.c:606` →
/// `CoreEnterLeaveEvents` → `CoreEnterNotifies` →
/// `DeliverEventsToWindow`): grab-activation crossing events
/// flow through the normal event-delivery path, which filters
/// by the client's per-window event-mask selection. xts's
/// `GrabPointer` test opens a fresh connection, creates a
/// grab window WITHOUT selecting `EnterWindowMask` (0x10), and
/// expects the next thing on the wire after sending GrabPointer
/// to be the reply (opcode 1). Pre-fix yserver's
/// `emit_core_grab_activation_crossings` fanned `EnterNotify`
/// (event type 7) unconditionally to the grabber via
/// `fanout_event_to_clients(&[client_id], …)` regardless of
/// mask, so the event landed on the wire BEFORE the reply
/// and the test reported `wanted REPLY - X_GrabPointer , got
/// EVENT - EnterNotify` (xts Xproto run 2026-05-31-11:13:07:
/// 1 FAIL on `GrabPointer` + 1 FAIL on `GrabKeyboard` + 8
/// UNRESOLVED on `AllowEvents` / `ChangeActivePointerGrab`).
/// Marco / GTK3 popups still receive the crossings because
/// they select `EnterWindowMask` on their popup windows.
#[test]
fn grab_pointer_skips_synthesised_crossing_when_mask_unselected() {
    const CLIENT_ID: u32 = 1;
    const GRAB_WIN: u32 = 0x100_0007;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    // Create the grab window WITHOUT EnterWindowMask selected
    // (mirrors xts's fresh CreateWindow).
    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(GRAB_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(GRAB_WIN));

    // GrabPointer body: window(4) event-mask(2) pointer-mode(1)
    // keyboard-mode(1) confine-to(4) cursor(4) time(4) = 20.
    // event-mask=0, modes async, confine_to=None, cursor=None,
    // time=CurrentTime.
    let mut body = Vec::with_capacity(20);
    body.extend_from_slice(&GRAB_WIN.to_le_bytes());
    body.extend_from_slice(&0u16.to_le_bytes()); // event-mask
    body.push(0); // pointer-mode async
    body.push(0); // keyboard-mode async
    body.extend_from_slice(&0u32.to_le_bytes()); // confine-to None
    body.extend_from_slice(&0u32.to_le_bytes()); // cursor None
    body.extend_from_slice(&0u32.to_le_bytes()); // time CurrentTime

    handle_grab_pointer(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(11),
        RequestHeader {
            opcode: 26,
            data: 0, // owner_events false
            length_units: 6,
        },
        &body,
    )
    .expect("handle_grab_pointer");

    peer.set_nonblocking(true).unwrap();
    let mut tmp = [0u8; 1024];
    let mut wire = Vec::new();
    loop {
        match peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => wire.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    // First 32-byte chunk must be the reply (opcode 1), NOT an
    // EnterNotify (event type 7).
    assert!(
        wire.len() >= 32,
        "GrabPointer must produce at least the reply on the wire",
    );
    assert_ne!(
        wire[0] & 0x7f,
        7,
        "Pre-fix: EnterNotify (type 7) landed on the wire before \
             the GrabPointer reply because crossings were unconditionally \
             fanned to the grabber regardless of EnterWindowMask. xts \
             reports this as `wanted REPLY - X_GrabPointer , got EVENT - \
             EnterNotify` and marks dependent tests UNRESOLVED.",
    );
    assert_eq!(
        wire[0], 1,
        "GrabPointer must put the reply (opcode 1) first on the wire \
             when the grabber has not selected EnterWindowMask",
    );
    // No EnterNotify anywhere — the grabber didn't select it.
    let enter_notifies = wire.chunks_exact(32).filter(|c| c[0] & 0x7f == 7).count();
    assert_eq!(
        enter_notifies, 0,
        "EnterNotify must not be delivered to a grabber that didn't \
             select EnterWindowMask on the grab window",
    );
}

/// Positive companion to the test above: when the grabber HAS
/// selected `EnterWindowMask` on the grab window (the
/// marco / GTK3 popup-menu pattern), the synthesised crossing
/// must still fire. The grab fix is "respect the event-mask
/// filter", not "drop crossings entirely".
#[test]
fn grab_pointer_emits_crossing_when_grabber_selected_enter_mask() {
    const CLIENT_ID: u32 = 1;
    const GRAB_WIN: u32 = 0x100_0008;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(GRAB_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(GRAB_WIN));
    // marco/GTK3 popup pattern: the pointer is over the panel (the
    // root here), NOT over the popup being grabbed — grab
    // activation must emit Enter(NotifyGrab) on the popup for
    // GTK3's hover machinery. (With the pointer already inside the
    // grab window Xorg emits nothing: DoEnterLeaveEvents from==to.)
    state.pointer_root = (500, 500);
    state
        .clients
        .get_mut(&CLIENT_ID)
        .unwrap()
        .event_masks
        .insert(ResourceId(GRAB_WIN), 0x10);

    let mut body = Vec::with_capacity(20);
    body.extend_from_slice(&GRAB_WIN.to_le_bytes());
    body.extend_from_slice(&0u16.to_le_bytes());
    body.push(0);
    body.push(0);
    body.extend_from_slice(&0u32.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes());

    handle_grab_pointer(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(13),
        RequestHeader {
            opcode: 26,
            data: 0,
            length_units: 6,
        },
        &body,
    )
    .expect("handle_grab_pointer");

    peer.set_nonblocking(true).unwrap();
    let mut tmp = [0u8; 1024];
    let mut wire = Vec::new();
    loop {
        match peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => wire.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    let enter_notifies = wire.chunks_exact(32).filter(|c| c[0] & 0x7f == 7).count();
    assert!(
        enter_notifies >= 1,
        "EnterNotify must still fire to a grabber that selected \
             EnterWindowMask (marco/GTK3 popup-menu pattern)",
    );
}

/// Symmetric to the activation test: xts case 116
/// (`pUngrabPointer-1.(A)`) opens a connection with NO event
/// mask selected, grabs+ungrabs, and verifies the server
/// sends NOTHING. Pre-fix `emit_core_grab_deactivation_crossing`
/// fanned `LeaveNotify` unconditionally to the ungrabber; the
/// test reported `wanted NOTHING, got EVENT - LeaveNotify`.
/// Mirror fix: the deactivation crossing must respect
/// `LeaveWindowMask` (0x20) on the prior grab window.
#[test]
fn ungrab_pointer_skips_synthesised_leave_when_mask_unselected() {
    const CLIENT_ID: u32 = 1;
    const GRAB_WIN: u32 = 0x100_0009;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(CLIENT_ID),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(GRAB_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(GRAB_WIN));

    // Seed an active grab so handle_ungrab_pointer has
    // something to deactivate (mirrors xts's GrabPointer →
    // UngrabPointer sequence).
    state.active_pointer_grab = Some(crate::server::ActivePointerGrab {
        owner: ClientId(CLIENT_ID),
        grab_window: ResourceId(GRAB_WIN),
        event_mask: 0,
        cursor: ResourceId(0),
        time: 0,
        owner_events: false,
        via_xi2: false,
        implicit: false,
        passive: false,
        xi2_mask: 0,
    });

    handle_ungrab_pointer(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(17),
        &[0u8; 4],
    )
    .expect("handle_ungrab_pointer");

    peer.set_nonblocking(true).unwrap();
    let mut tmp = [0u8; 1024];
    let mut wire = Vec::new();
    loop {
        match peer.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => wire.extend_from_slice(&tmp[..n]),
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(_) => break,
        }
    }
    let leave_notifies = wire.chunks_exact(32).filter(|c| c[0] & 0x7f == 8).count();
    assert_eq!(
        leave_notifies, 0,
        "UngrabPointer from a client that did not select \
             LeaveWindowMask must not produce a LeaveNotify on the \
             wire (xts case 116 / `pUngrabPointer-1.(A)`)",
    );
    assert!(
        wire.is_empty(),
        "UngrabPointer with no event mask selected must produce \
             NOTHING on the wire; got {} bytes: {:?}",
        wire.len(),
        &wire[..wire.len().min(64)],
    );
}

/// xts5 Xlib4 (`EWin.mc`) creates a window, destroys it, then
/// invokes each window-manipulation request on the freed xid and
/// expects a `BadWindow` protocol error back. Before this fix,
/// every handler silently returned `RequestOutcome::Handled`,
/// causing ~24 FAILs across the Xlib4 cluster
/// (`Got Success, Expecting BadWindow`).
///
/// One test per affected handler so a regression names the
/// specific request rather than a single bundled failure.
#[test]
fn window_handlers_on_freed_xid_return_bad_window() {
    use std::io::Read;
    const APP: u32 = 200;
    const BAD: u32 = 0x0080_dead;

    // (opcode, header.data, body, label, requires_body_len)
    let cases: &[(u8, u8, Vec<u8>, &str)] = &[
        (
            1,
            24,
            create_window_body_with_parent(BAD),
            "CreateWindow(parent)",
        ),
        (
            2,
            0,
            change_window_attributes_body(BAD),
            "ChangeWindowAttributes",
        ),
        (4, 0, BAD.to_le_bytes().to_vec(), "DestroyWindow"),
        (5, 0, BAD.to_le_bytes().to_vec(), "DestroySubwindows"),
        (8, 0, BAD.to_le_bytes().to_vec(), "MapWindow"),
        (9, 0, BAD.to_le_bytes().to_vec(), "MapSubwindows"),
        (10, 0, BAD.to_le_bytes().to_vec(), "UnmapWindow"),
        (11, 0, BAD.to_le_bytes().to_vec(), "UnmapSubwindows"),
        (12, 0, configure_window_body(BAD), "ConfigureWindow"),
        (13, 0, BAD.to_le_bytes().to_vec(), "CirculateWindow"),
    ];

    for (i, (opcode, data, body, label)) in cases.iter().enumerate() {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, APP + i as u32);
        let mut backend = RecordingBackend::new();
        let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body length fits");
        let seq = SequenceNumber((i + 1) as u16);
        process_request(
            &mut state,
            &mut backend,
            ClientId(APP + i as u32),
            seq,
            RequestHeader {
                opcode: *opcode,
                data: *data,
                length_units,
            },
            body,
            None,
        )
        .expect("process_request");

        peer.set_nonblocking(true).unwrap();
        let mut buf = [0u8; 32];
        peer.read_exact(&mut buf).unwrap_or_else(|e| {
            panic!("{label}: expected 32-byte error reply, got {e:?}");
        });
        assert_eq!(
            buf[0], 0,
            "{label}: byte 0 = error class (0); got {}",
            buf[0]
        );
        assert_eq!(
            buf[1],
            yserver_protocol::x11::error::BAD_WINDOW,
            "{label}: expected BadWindow (3) for freed xid; got error code {}",
            buf[1],
        );
        // bytes [4..8] = error_value (the bad xid)
        let bad_value = u32::from_le_bytes([buf[4], buf[5], buf[6], buf[7]]);
        assert_eq!(
            bad_value, BAD,
            "{label}: error_value must echo the freed window xid"
        );
        // byte [10] = major_opcode (this is the request that errored)
        assert_eq!(
            buf[10], *opcode,
            "{label}: BadWindow error must carry the request's \
                 major opcode (expected {opcode}); got {}",
            buf[10],
        );
    }
}

fn create_window_body_with_parent(parent_xid: u32) -> Vec<u8> {
    // ProcCreateWindow body (header.data carries depth):
    //   wid u32, parent u32, x i16, y i16, width u16, height u16,
    //   border_width u16, class u16, visual u32, value_mask u32, …
    // Use class=CopyFromParent(0), visual=CopyFromParent(0), no
    // attributes — the parent BadWindow check fires first.
    let mut body = Vec::with_capacity(28);
    body.extend_from_slice(&0x0080_0001u32.to_le_bytes()); // new wid (will not be used)
    body.extend_from_slice(&parent_xid.to_le_bytes());
    body.extend_from_slice(&0i16.to_le_bytes()); // x
    body.extend_from_slice(&0i16.to_le_bytes()); // y
    body.extend_from_slice(&10u16.to_le_bytes()); // width
    body.extend_from_slice(&10u16.to_le_bytes()); // height
    body.extend_from_slice(&0u16.to_le_bytes()); // border_width
    body.extend_from_slice(&0u16.to_le_bytes()); // class
    body.extend_from_slice(&0u32.to_le_bytes()); // visual
    body.extend_from_slice(&0u32.to_le_bytes()); // value_mask
    body
}

fn change_window_attributes_body(window_xid: u32) -> Vec<u8> {
    // ProcChangeWindowAttributes body: window u32, value_mask u32,
    // values…  No values needed — the window BadWindow check
    // fires before attribute application.
    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&window_xid.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // value_mask
    body
}

fn configure_window_body(window_xid: u32) -> Vec<u8> {
    // ProcConfigureWindow body: window u32, value_mask u16, pad
    // u16, values…  No values needed — BadWindow check fires
    // before mask is read.
    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&window_xid.to_le_bytes());
    body.extend_from_slice(&0u16.to_le_bytes()); // value_mask
    body.extend_from_slice(&0u16.to_le_bytes()); // pad
    body
}

// ── Border attribute validation (#133, plan step 1.3 / 1.4) ────────

const CWA_BORDER_PIXMAP: u32 = 0x0004;
const CWA_BORDER_PIXEL: u32 = 0x0008;

/// CreateWindow body with an explicit class/visual and a value list.
/// `depth` travels in `header.data`, not the body.
fn border_create_body(wid: u32, parent: u32, value_mask: u32, values: &[u32]) -> Vec<u8> {
    let mut body = Vec::with_capacity(28 + values.len() * 4);
    body.extend_from_slice(&wid.to_le_bytes());
    body.extend_from_slice(&parent.to_le_bytes());
    body.extend_from_slice(&0i16.to_le_bytes()); // x
    body.extend_from_slice(&0i16.to_le_bytes()); // y
    body.extend_from_slice(&10u16.to_le_bytes()); // width
    body.extend_from_slice(&10u16.to_le_bytes()); // height
    body.extend_from_slice(&0u16.to_le_bytes()); // border_width
    body.extend_from_slice(&1u16.to_le_bytes()); // class = InputOutput
    body.extend_from_slice(&0u32.to_le_bytes()); // visual = CopyFromParent
    body.extend_from_slice(&value_mask.to_le_bytes());
    for v in values {
        body.extend_from_slice(&v.to_le_bytes());
    }
    body
}

fn border_cwa_body(window: u32, value_mask: u32, values: &[u32]) -> Vec<u8> {
    let mut body = Vec::with_capacity(8 + values.len() * 4);
    body.extend_from_slice(&window.to_le_bytes());
    body.extend_from_slice(&value_mask.to_le_bytes());
    for v in values {
        body.extend_from_slice(&v.to_le_bytes());
    }
    body
}

fn run_border_request(state: &mut ServerState, opcode: u8, depth: u8, body: &[u8]) {
    run_border_request_recording(state, opcode, depth, body);
}

/// Same as `run_border_request` but hands back what the backend
/// saw, for the #133 step 2 (P3) forward-path assertions.
fn run_border_request_recording(
    state: &mut ServerState,
    opcode: u8,
    depth: u8,
    body: &[u8],
) -> Vec<RecordedCall> {
    let mut backend = RecordingBackend::new();
    process_request(
        state,
        &mut backend,
        ClientId(1),
        SequenceNumber(1),
        RequestHeader {
            opcode,
            data: depth,
            length_units: u32::try_from(1 + body.len().div_ceil(4)).unwrap(),
        },
        body,
        None,
    )
    .expect("process_request");
    backend.calls()
}

/// Pick the border-source forward out of a recorded call list.
fn border_forwards(calls: &[RecordedCall]) -> Vec<(u32, u32, Vec<u32>)> {
    calls
        .iter()
        .filter_map(|c| match c {
            RecordedCall::ChangeSubwindowAttributes {
                host_xid,
                value_mask,
                values,
            } if value_mask & (CWA_BORDER_PIXMAP | CWA_BORDER_PIXEL) != 0 => {
                Some((*host_xid, *value_mask, values.clone()))
            }
            _ => None,
        })
        .collect()
}

fn assert_error_code(bytes: &[u8], expected: u8, what: &str) {
    assert!(
        bytes.len() >= 32,
        "{what}: expected a 32-byte error reply, got {} bytes: {:02x?}",
        bytes.len(),
        bytes
    );
    assert_eq!(bytes[0], 0, "{what}: expected an Error reply");
    assert_eq!(bytes[1], expected, "{what}: wrong error code");
}

fn assert_no_error(bytes: &[u8], what: &str) {
    assert!(
        bytes.is_empty() || bytes[0] != 0,
        "{what}: expected no error, got {:02x?}",
        bytes
    );
}

/// CWCursor on CreateWindow takes effect like ChangeWindowAttributes'
/// (Xorg `CreateWindow` → `ChangeWindowAttributes`): the window keeps
/// the cursor and the backend shows it; an unknown cursor is BadCursor.
#[test]
fn create_window_cursor_is_kept_and_forwarded() {
    const CURSOR: ResourceId = ResourceId(0x0080_0010);
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    state.resources.create_glyph_cursor(ClientId(1), CURSOR);
    state.resources.set_cursor_host_xid(
        CURSOR,
        crate::backend::CursorHandle::from_raw(0x00ab_0001).unwrap(),
    );
    let body = border_create_body(0x0080_0001, ROOT_WINDOW.0, 0x4000, &[CURSOR.0]);
    let calls = run_border_request_recording(&mut state, 1, 0, &body);
    assert_no_error(&read_all_available(&mut peer), "CreateWindow with a cursor");
    let window = state.resources.window(ResourceId(0x0080_0001)).unwrap();
    assert_eq!(window.cursor, Some(CURSOR));
    let host = window.host_xid.unwrap().as_raw();
    assert!(calls.contains(&RecordedCall::DefineCursor {
        host_window_xid: host,
        cursor_host_xid: 0x00ab_0001,
    }));

    let body = border_create_body(0x0080_0002, ROOT_WINDOW.0, 0x4000, &[0x0080_0011]);
    run_border_request(&mut state, 1, 0, &body);
    assert_error_code(
        &read_all_available(&mut peer),
        x11::error::BAD_CURSOR,
        "unknown cursor",
    );
}

/// #196: a window holds its cursor (Xorg `pCurs->refcnt`,
/// `dix/window.c:1536`), so FreeCursor of a cursor set by CreateWindow
/// keeps it — for an InputOutput and an InputOnly window alike, the
/// latter having no backend window to hold it — until the window
/// changes cursor (`:1559`) or is destroyed (`:968`); then it is freed
/// once.
#[test]
fn create_window_cursor_outlives_free_cursor_until_the_window_drops_it() {
    let host_frees = |calls: &[RecordedCall]| -> Vec<u32> {
        calls
            .iter()
            .filter_map(|c| match c {
                RecordedCall::FreeCursor(h) => Some(*h),
                _ => None,
            })
            .collect()
    };
    for (class, drop_by_destroy) in [(1u16, false), (1, true), (2, false), (2, true)] {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, 1);
        let cursor = ResourceId(0x0080_0010);
        let window = 0x0080_0001;
        state.resources.create_glyph_cursor(ClientId(1), cursor);
        state.resources.set_cursor_host_xid(
            cursor,
            crate::backend::CursorHandle::from_raw(0x00ab_0001).unwrap(),
        );
        let mut body = border_create_body(window, ROOT_WINDOW.0, 0x4000, &[cursor.0]);
        body[18..20].copy_from_slice(&class.to_le_bytes());
        run_border_request(&mut state, 1, 0, &body);
        assert_no_error(&read_all_available(&mut peer), "CreateWindow");

        let calls = run_border_request_recording(&mut state, 95, 0, &cursor.0.to_le_bytes());
        assert_eq!(host_frees(&calls), Vec::<u32>::new(), "class {class}: held");

        let calls = if drop_by_destroy {
            run_border_request_recording(&mut state, 4, 0, &window.to_le_bytes())
        } else {
            run_border_request_recording(&mut state, 2, 0, &border_cwa_body(window, 0x4000, &[0]))
        };
        assert_eq!(host_frees(&calls), vec![0x00ab_0001], "class {class}");
        assert_no_error(&read_all_available(&mut peer), "no error");
    }
}

/// The positive control: a cursor two windows hold goes with the last.
#[test]
fn freed_cursor_goes_with_the_last_window_holding_it() {
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let cursor = ResourceId(0x0080_0010);
    state.resources.create_glyph_cursor(ClientId(1), cursor);
    state.resources.set_cursor_host_xid(
        cursor,
        crate::backend::CursorHandle::from_raw(0x00ab_0001).unwrap(),
    );
    for w in [0x0080_0001u32, 0x0080_0002] {
        let body = border_create_body(w, ROOT_WINDOW.0, 0x4000, &[cursor.0]);
        run_border_request(&mut state, 1, 0, &body);
    }
    let mut calls = run_border_request_recording(&mut state, 95, 0, &cursor.0.to_le_bytes());
    calls.extend(run_border_request_recording(
        &mut state,
        4,
        0,
        &0x0080_0001u32.to_le_bytes(),
    ));
    assert!(!calls.contains(&RecordedCall::FreeCursor(0x00ab_0001)));
    let calls = run_border_request_recording(&mut state, 4, 0, &0x0080_0002u32.to_le_bytes());
    assert_eq!(
        calls
            .iter()
            .filter(|c| **c == RecordedCall::FreeCursor(0x00ab_0001))
            .count(),
        1
    );
}

/// Xorg `dix/window.c:818` — a depth that differs from the parent's
/// with NO border attribute is BadMatch, because the inherited border
/// (`:879`) would carry the parent's depth. This is why awesome sends
/// `border-pixel=0x00000000` on every depth-32 CreateWindow.
#[test]
fn create_window_depth_differs_without_border_attribute_is_bad_match() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let body = border_create_body(0x0080_0001, ROOT_WINDOW.0, 0, &[]);
    run_border_request(&mut state, 1, 32, &body);
    let bytes = read_all_available(&mut peer);
    assert_error_code(
        &bytes,
        x11::error::BAD_MATCH,
        "depth 32 under depth-24 parent",
    );
}

/// The same request WITH `CWBorderPixel` is legal — the awesome
/// pattern.
#[test]
fn create_window_depth_differs_with_border_pixel_is_accepted() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let body = border_create_body(0x0080_0001, ROOT_WINDOW.0, CWA_BORDER_PIXEL, &[0]);
    run_border_request(&mut state, 1, 32, &body);
    let bytes = read_all_available(&mut peer);
    assert_no_error(&bytes, "depth 32 with border-pixel");
    assert!(
        state.resources.window(ResourceId(0x0080_0001)).is_some(),
        "window should have been created"
    );
}

