/// #143 — THE regression gate for the awesome border flicker.
///
/// awesome recolours a focused/unfocused frame with a CWA carrying
/// only `CWBorderPixel`. We repainted the ring into the redirect
/// backing but reported no protocol DAMAGE for it, so picom — which
/// partial-repaints from `EXT_buffer_age` — kept one ring colour per
/// back buffer and alternated between them at frame rate. Xorg
/// reports it from `ChangeWindowAttributes` itself: `borderClip −
/// winSize` → `PaintWindow(..., PW_BORDER)` (`dix/window.c:1581-1589`)
/// → `PolyFillRect` on the window pixmap (`mi/miexpose.c:448-471`,
/// `:558`) → `damagePolyFillRect` (`miext/damage/damage.c:1194`).
///
/// Geometry is the captured one: 1276×704 at `border_width = 2`.
#[test]
fn change_window_attributes_border_pixel_damages_the_ring() {
    use crate::server::DamageObject;
    use yserver_protocol::x11::xfixes::RegionRect;
    const DAMAGE_XID: u32 = 0x0080_9143;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let win = ResourceId(0x0080_0001);
    seed_window(&mut state, win, ROOT_WINDOW, 1276, 704);
    if let Some(w) = state.resources.window_mut(win) {
        w.border_width = 2;
    }
    assert!(
        state.resources.map_window(win).mapping_changed,
        "window must map"
    );
    // Raw level: `area` on the wire then carries the real rect
    // instead of the NonEmpty full-extent substitute, so the test
    // can prove the negative origin survives the i16 encoding.
    state.damage_objects.insert(
        DAMAGE_XID,
        DamageObject {
            owner: ClientId(1),
            drawable: win,
            level: 0,
            rects: Vec::new(),
            pending_notify_fired: false,
            last_reported_geometry: None,
        },
    );

    let body = border_cwa_body(win.0, CWA_BORDER_PIXEL, &[0x0000_ff00]);
    run_border_request(&mut state, 2, 0, &body);

    let rects = state
        .damage_objects
        .get(&DAMAGE_XID)
        .expect("damage object")
        .rects
        .clone();
    assert_eq!(
        rects,
        vec![
            RegionRect {
                x: -2,
                y: -2,
                width: 1280,
                height: 2
            },
            RegionRect {
                x: -2,
                y: 0,
                width: 2,
                height: 704
            },
            RegionRect {
                x: 1276,
                y: 0,
                width: 2,
                height: 704
            },
            RegionRect {
                x: -2,
                y: 704,
                width: 1280,
                height: 2
            },
        ],
        "a border-source change must damage the whole ring, including the \
             negative-origin top and left strips",
    );

    // And it must reach the client as real DamageNotify events,
    // with the negative origin intact on the wire (`area.x` is
    // INT16 at byte 16).
    let bytes = read_all_available(&mut peer);
    let notifies: Vec<&[u8]> = bytes
        .chunks_exact(32)
        .filter(|c| c[0] == crate::nested::DAMAGE_FIRST_EVENT)
        .collect();
    assert_eq!(
        notifies.len(),
        4,
        "one DamageNotify per ring strip at ReportLevel Raw",
    );
    let areas: Vec<(i16, i16, u16, u16)> = notifies
        .iter()
        .map(|c| {
            (
                i16::from_le_bytes([c[16], c[17]]),
                i16::from_le_bytes([c[18], c[19]]),
                u16::from_le_bytes([c[20], c[21]]),
                u16::from_le_bytes([c[22], c[23]]),
            )
        })
        .collect();
    assert!(
        areas.contains(&(-2, -2, 1280, 2)),
        "the top strip must arrive at a NEGATIVE origin, got {areas:?}",
    );
    assert!(
        areas.contains(&(-2, 0, 2, 704)),
        "the left strip must arrive at a NEGATIVE x, got {areas:?}",
    );
}

/// The ring damage follows Xorg's two gates and no others: nothing
/// for an unbordered window (`HasBorder(pWin)`, `dix/window.c:1586`)
/// and nothing for a non-viewable one (`pWin->viewable`, same line).
#[test]
fn change_window_attributes_border_pixel_damages_nothing_unbordered_or_unmapped() {
    use crate::server::DamageObject;
    const DAMAGE_XID: u32 = 0x0080_9144;
    for (bw, map) in [(0u16, true), (2, false)] {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, 1);
        let win = ResourceId(0x0080_0001);
        seed_window(&mut state, win, ROOT_WINDOW, 64, 64);
        if let Some(w) = state.resources.window_mut(win) {
            w.border_width = bw;
        }
        if map {
            assert!(
                state.resources.map_window(win).mapping_changed,
                "window must map"
            );
        }
        state.damage_objects.insert(
            DAMAGE_XID,
            DamageObject {
                owner: ClientId(1),
                drawable: win,
                level: 0,
                rects: Vec::new(),
                pending_notify_fired: false,
                last_reported_geometry: None,
            },
        );

        let body = border_cwa_body(win.0, CWA_BORDER_PIXEL, &[0x0000_ff00]);
        run_border_request(&mut state, 2, 0, &body);
        assert_no_error(&read_all_available(&mut peer), "CWA border-pixel");

        assert!(
            state.damage_objects[&DAMAGE_XID].rects.is_empty(),
            "bw={bw} mapped={map}: no ring to report",
        );
    }
}

/// #143, the resize half. `5d7270c1` reported the ring on a
/// border-source change and on backing activation; a RESIZE
/// repaints it too — `rotate_redirected_backing_on_resize`
/// reallocates and `allocate_redirected_backing` paints the new
/// ring — and reported nothing, so a partial-repaint compositor
/// (picom on `EXT_buffer_age`) kept a ring at the OLD extent in one
/// back buffer and the new one in the other. The bottom and right
/// strips are the ones that move when a window is resized about a
/// fixed origin, which is exactly the observed fingerprint: those
/// two edges flickered at awesome's ~1 Hz clock tick and settled
/// gone.
///
/// Xorg reports it: `compReallocPixmap` reallocates whenever the
/// bordered extent differs (`composite/compalloc.c:698`) and that
/// branch alone calls `compSetPixmap` (`:700`), whose visitor
/// queues `compRepaintBorder` for `bw != 0`
/// (`composite/compwindow.c:137-139`) — a `PolyFillRect` on the
/// window pixmap (`mi/miexpose.c:558`) that `damagePolyFillRect`
/// (`miext/damage/damage.c:1194`) reports.
///
/// bw = 2 and the captured 1276x704, shrunk and grown.
#[test]
fn configure_window_resize_damages_the_ring_at_the_new_geometry() {
    use crate::{
        resources::RedirectedBacking,
        server::{CompositeRedirectMode, DamageObject, RedirectRecord},
    };
    use yserver_protocol::x11::xfixes::RegionRect;
    const DAMAGE_XID: u32 = 0x0080_9145;
    const BW: u16 = 2;
    // (old_w, old_h, new_w, new_h, label)
    for (old_w, old_h, new_w, new_h, label) in [
        (1276u16, 704u16, 636u16, 348u16, "shrink"),
        (636, 348, 1276, 704, "grow"),
    ] {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, 1);
        let win = ResourceId(0x0080_0001);
        seed_window(&mut state, win, ROOT_WINDOW, old_w, old_h);
        if let Some(w) = state.resources.window_mut(win) {
            w.border_width = BW;
            w.redirected_backing = Some(RedirectedBacking {
                host_pixmap: crate::backend::PixmapHandle::from_raw_for_test(0x0050_0001),
                width: old_w + 2 * BW,
                height: old_h + 2 * BW,
                depth: 24,
            });
        }
        assert!(
            state.resources.map_window(win).mapping_changed,
            "window must map"
        );
        state
            .composite_redirects
            .redirect_window(
                win,
                RedirectRecord {
                    mode: CompositeRedirectMode::Manual,
                    owner: ClientId(1),
                },
            )
            .unwrap();
        // ReportLevel Raw, so `rects` keeps the real strips instead
        // of the NonEmpty full-extent substitute.
        state.damage_objects.insert(
            DAMAGE_XID,
            DamageObject {
                owner: ClientId(1),
                drawable: win,
                level: 0,
                rects: Vec::new(),
                pending_notify_fired: false,
                last_reported_geometry: None,
            },
        );

        // ConfigureWindow, CWWidth | CWHeight.
        let mut body = Vec::with_capacity(16);
        body.extend_from_slice(&win.0.to_le_bytes());
        body.extend_from_slice(&0x000cu16.to_le_bytes());
        body.extend_from_slice(&[0u8; 2]);
        body.extend_from_slice(&u32::from(new_w).to_le_bytes());
        body.extend_from_slice(&u32::from(new_h).to_le_bytes());
        run_border_request(&mut state, 12, 0, &body);

        let rects = state.damage_objects[&DAMAGE_XID].rects.clone();
        let bw = i16::try_from(BW).unwrap();
        let ring = [
            RegionRect {
                x: -bw,
                y: -bw,
                width: new_w + 2 * BW,
                height: BW,
            },
            RegionRect {
                x: -bw,
                y: 0,
                width: BW,
                height: new_h,
            },
            RegionRect {
                x: i16::try_from(new_w).unwrap(),
                y: 0,
                width: BW,
                height: new_h,
            },
            RegionRect {
                x: -bw,
                y: i16::try_from(new_h).unwrap(),
                width: new_w + 2 * BW,
                height: BW,
            },
        ];
        assert_eq!(
            rects.get(..4),
            Some(&ring[..]),
            "{label}: a resize must damage the whole ring at the NEW \
                 geometry, before the full-extent configure damage, and the \
                 top/left strips carry NEGATIVE origins; got {rects:?}",
        );
        // The bottom and right strips are the ones whose position
        // MOVED — the #143 fingerprint. Spell them out so a
        // regression that reports the ring at the OLD extent fails
        // here and not only on the ordering assert above.
        assert!(
            rects.contains(&ring[2]) && rects.contains(&ring[3]),
            "{label}: the right and bottom strips must sit at the NEW \
                 extent ({new_w}x{new_h}), not the old one ({old_w}x{old_h})",
        );
        assert!(
            rects.contains(&RegionRect {
                x: 0,
                y: 0,
                width: new_w,
                height: new_h,
            }),
            "{label}: the pre-existing full-extent configure damage must \
                 still fire alongside the ring",
        );

        // And it reaches the client, negative origins intact on the
        // wire (`area.x`/`area.y` are INT16 at bytes 16..20).
        let bytes = read_all_available(&mut peer);
        let areas: Vec<(i16, i16, u16, u16)> = bytes
            .chunks_exact(32)
            .filter(|c| c[0] == crate::nested::DAMAGE_FIRST_EVENT)
            .map(|c| {
                (
                    i16::from_le_bytes([c[16], c[17]]),
                    i16::from_le_bytes([c[18], c[19]]),
                    u16::from_le_bytes([c[20], c[21]]),
                    u16::from_le_bytes([c[22], c[23]]),
                )
            })
            .collect();
        for r in &ring {
            assert!(
                areas.contains(&(r.x, r.y, r.width, r.height)),
                "{label}: ring strip {r:?} must arrive as a DamageNotify, got {areas:?}",
            );
        }
    }
}

/// The resize ring damage follows the same two Xorg gates as the
/// border-source one — nothing at `bw == 0` (`HasBorder(pWin)`) and
/// nothing for a non-viewable window (`pWin->viewable`,
/// `dix/window.c:1586`) — so an unbordered resize keeps reporting
/// exactly the one full-extent rect it always did.
#[test]
fn configure_window_resize_damages_no_ring_unbordered_or_unmapped() {
    use crate::{
        resources::RedirectedBacking,
        server::{CompositeRedirectMode, DamageObject, RedirectRecord},
    };
    use yserver_protocol::x11::xfixes::RegionRect;
    const DAMAGE_XID: u32 = 0x0080_9146;
    for (bw, map) in [(0u16, true), (2, false)] {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, 1);
        let win = ResourceId(0x0080_0001);
        seed_window(&mut state, win, ROOT_WINDOW, 128, 64);
        if let Some(w) = state.resources.window_mut(win) {
            w.border_width = bw;
            w.redirected_backing = Some(RedirectedBacking {
                host_pixmap: crate::backend::PixmapHandle::from_raw_for_test(0x0050_0001),
                width: 128 + 2 * bw,
                height: 64 + 2 * bw,
                depth: 24,
            });
        }
        if map {
            assert!(
                state.resources.map_window(win).mapping_changed,
                "window must map"
            );
        }
        state
            .composite_redirects
            .redirect_window(
                win,
                RedirectRecord {
                    mode: CompositeRedirectMode::Manual,
                    owner: ClientId(1),
                },
            )
            .unwrap();
        state.damage_objects.insert(
            DAMAGE_XID,
            DamageObject {
                owner: ClientId(1),
                drawable: win,
                level: 0,
                rects: Vec::new(),
                pending_notify_fired: false,
                last_reported_geometry: None,
            },
        );

        let mut body = Vec::with_capacity(16);
        body.extend_from_slice(&win.0.to_le_bytes());
        body.extend_from_slice(&0x000cu16.to_le_bytes());
        body.extend_from_slice(&[0u8; 2]);
        body.extend_from_slice(&64u32.to_le_bytes());
        body.extend_from_slice(&32u32.to_le_bytes());
        run_border_request(&mut state, 12, 0, &body);
        assert_no_error(&read_all_available(&mut peer), "ConfigureWindow resize");

        let expected: Vec<RegionRect> = if map {
            vec![RegionRect {
                x: 0,
                y: 0,
                width: 64,
                height: 32,
            }]
        } else {
            Vec::new()
        };
        assert_eq!(
            state.damage_objects[&DAMAGE_XID].rects, expected,
            "bw={bw} mapped={map}: no ring to report on a resize",
        );
    }
}

/// A tile with no host storage degrades to the pixel bit with a
/// defined value, mirroring the background block: a backend that
/// cannot sample the tile is better off with a solid colour than
/// with a dangling xid.
#[test]
fn change_window_attributes_border_pixmap_without_host_storage_degrades_to_pixel() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let win = ResourceId(0x0080_0001);
    seed_window(&mut state, win, ROOT_WINDOW, 10, 10);
    let host_xid = state
        .resources
        .window(win)
        .and_then(|w| w.host_xid)
        .expect("host xid")
        .as_raw();
    let tile = ResourceId(0x0080_1301);
    state.resources.create_pixmap(
        ClientId(1),
        CreatePixmapRequest {
            pixmap: tile,
            drawable: ROOT_WINDOW,
            width: 8,
            height: 8,
            depth: 24,
        },
    );

    let body = border_cwa_body(win.0, CWA_BORDER_PIXMAP, &[tile.0]);
    let calls = run_border_request_recording(&mut state, 2, 0, &body);
    assert_no_error(&read_all_available(&mut peer), "hostless border tile");
    assert_eq!(
        border_forwards(&calls),
        vec![(host_xid, CWA_BORDER_PIXEL, vec![0])],
    );
}

/// A CWA changing background AND border produces BOTH forwards —
/// the border block is a sibling of the background block, not a
/// replacement, and each carries only its own bits.
#[test]
fn change_window_attributes_background_and_border_forward_separately() {
    const CWA_BACK_PIXEL: u32 = 0x0002;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let win = ResourceId(0x0080_0001);
    seed_window(&mut state, win, ROOT_WINDOW, 10, 10);
    let host_xid = state
        .resources
        .window(win)
        .and_then(|w| w.host_xid)
        .expect("host xid")
        .as_raw();

    // Value list in ascending mask-bit order: back-pixel, then
    // border-pixel.
    let body = border_cwa_body(
        win.0,
        CWA_BACK_PIXEL | CWA_BORDER_PIXEL,
        &[0x0000_00ff, 0x00ff_0000],
    );
    let calls = run_border_request_recording(&mut state, 2, 0, &body);
    assert_no_error(&read_all_available(&mut peer), "bg + border in one CWA");
    let cwa: Vec<_> = calls
        .iter()
        .filter_map(|c| match c {
            RecordedCall::ChangeSubwindowAttributes {
                host_xid,
                value_mask,
                values,
            } => Some((*host_xid, *value_mask, values.clone())),
            _ => None,
        })
        .collect();
    assert_eq!(
        cwa,
        vec![
            (host_xid, CWA_BACK_PIXEL, vec![0x0000_00ff]),
            (host_xid, CWA_BORDER_PIXEL, vec![0x00ff_0000]),
        ],
        "background forward first, then the border forward"
    );
}

/// CreateWindow forwards the INITIAL border source too. Without it
/// a window created with a border pixel that is never changed again
/// would leave the backend mirror with no source at all — and
/// CreateWindow inherits the parent's border (`dix/window.c:879`),
/// so even a client supplying no border attribute can start out
/// with a non-default one.
#[test]
fn create_window_forwards_the_initial_border_source() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let body = border_create_body(0x0080_0001, ROOT_WINDOW.0, CWA_BORDER_PIXEL, &[0x00ff_0000]);
    let calls = run_border_request_recording(&mut state, 1, 24, &body);
    assert_no_error(&read_all_available(&mut peer), "create with border pixel");
    let host_xid = state
        .resources
        .window(ResourceId(0x0080_0001))
        .and_then(|w| w.host_xid)
        .expect("created window has a host xid")
        .as_raw();
    assert_eq!(
        border_forwards(&calls),
        vec![(host_xid, CWA_BORDER_PIXEL, vec![0x00ff_0000])],
    );
}

/// xts5 Xlib4 `XChangeWindowAttributes` 22-25 / Xlib4
/// `XCreateWindow` 20-22 set a CWBackPixmap / CWColormap /
/// CWCursor value to a freed xid and expect BadPixmap /
/// BadColormap / BadCursor. Mirrors Xorg's per-attribute
/// `dixLookupResource` order in `dix/window.c::CreateWindow` and
/// `ChangeWindowAttributes`.
#[test]
fn change_window_attributes_with_stale_value_returns_specific_bad_error() {
    use std::io::Read;
    const APP: u32 = 300;
    const WIN: u32 = 0x0090_0001;
    const BAD_PIX: u32 = 0x0090_dead;
    const BAD_CMAP: u32 = 0x0090_beef;
    const BAD_CURS: u32 = 0x0090_face;

    // (mask, value, expected_error, label)
    let cases: &[(u32, u32, u8, &str)] = &[
        (
            0x0001,
            BAD_PIX,
            yserver_protocol::x11::error::BAD_PIXMAP,
            "CWBackPixmap",
        ),
        (
            0x2000,
            BAD_CMAP,
            yserver_protocol::x11::error::BAD_COLORMAP,
            "CWColormap",
        ),
        (
            0x4000,
            BAD_CURS,
            yserver_protocol::x11::error::BAD_CURSOR,
            "CWCursor",
        ),
    ];

    for (i, (mask, value, expected_err, label)) in cases.iter().enumerate() {
        let mut state = ServerState::new();
        let app_id = APP + i as u32;
        let mut peer = install_client(&mut state, app_id);
        let mut backend = RecordingBackend::new();

        // Create a live target window owned by this client so the
        // BadWindow gate doesn't fire ahead of the value check.
        let win = WIN + i as u32;
        state.resources.create_window(
            ClientId(app_id),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(win),
                parent: crate::resources::ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 10,
                height: 10,
                border_width: 0,
                class: 1,
                visual: crate::resources::ROOT_VISUAL,
                ..Default::default()
            },
        );

        let mut body = Vec::with_capacity(12);
        body.extend_from_slice(&win.to_le_bytes());
        body.extend_from_slice(&mask.to_le_bytes());
        body.extend_from_slice(&value.to_le_bytes());
        let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body length fits");

        process_request(
            &mut state,
            &mut backend,
            ClientId(app_id),
            SequenceNumber(1),
            RequestHeader {
                opcode: 2,
                data: 0,
                length_units,
            },
            &body,
            None,
        )
        .expect("process_request");

        peer.set_nonblocking(true).unwrap();
        let mut buf = [0u8; 32];
        peer.read_exact(&mut buf).unwrap_or_else(|e| {
            panic!("{label}: expected 32-byte error reply, got {e:?}");
        });
        assert_eq!(
            buf[0], 0,
            "{label}: byte 0 = error class (0); got {}",
            buf[0]
        );
        assert_eq!(
            buf[1], *expected_err,
            "{label}: expected error code {expected_err} for stale xid; got {}",
            buf[1],
        );
        let bad_value = u32::from_le_bytes([buf[4], buf[5], buf[6], buf[7]]);
        assert_eq!(
            bad_value, *value,
            "{label}: error_value must echo the stale resource xid"
        );
        assert_eq!(
            buf[10], 2,
            "{label}: error must carry the ChangeWindowAttributes \
                 major opcode (2); got {}",
            buf[10],
        );
    }
}

/// xts5 Xlib4 ConfigureWindow validations beyond BadWindow.
/// Mirrors Xorg `dix/window.c::ConfigureWindow:2203-2266` — every
/// check fires *before* any state mutation.
#[test]
fn configure_window_validates_inputonly_sibling_and_size() {
    use std::io::Read;
    const APP: u32 = 400;
    const PARENT: u32 = 0x00a0_0001;
    const INPUT_ONLY: u32 = 0x00a0_0002;
    const SIB_A: u32 = 0x00a0_0003;
    const SIB_B: u32 = 0x00a0_0004;
    const ORPHAN: u32 = 0x00a0_0005;
    const BAD_SIB: u32 = 0x00a0_dead;
    const CW_X: u16 = 0x0001;
    const CW_WIDTH: u16 = 0x0004;
    const CW_HEIGHT: u16 = 0x0008;
    const CW_BORDER_WIDTH: u16 = 0x0010;
    const CW_SIBLING: u16 = 0x0020;
    const CW_STACK_MODE: u16 = 0x0040;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, APP);
    let mut backend = RecordingBackend::new();

    // Two siblings under PARENT and one orphan that's not their sibling.
    for (id, parent, class) in [
        (PARENT, crate::resources::ROOT_WINDOW.0, 1u16),
        (INPUT_ONLY, PARENT, 2u16),
        (SIB_A, PARENT, 1u16),
        (SIB_B, PARENT, 1u16),
        (ORPHAN, crate::resources::ROOT_WINDOW.0, 1u16),
    ] {
        state.resources.create_window(
            ClientId(APP),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(id),
                parent: ResourceId(parent),
                x: 0,
                y: 0,
                width: 50,
                height: 50,
                border_width: 0,
                class,
                visual: crate::resources::ROOT_VISUAL,
                ..Default::default()
            },
        );
    }

    // (label, body, expected_error)
    let cases: Vec<(&str, Vec<u8>, u8)> = vec![
        (
            "InputOnly + CWBorderWidth → BadMatch",
            build_configure_body(INPUT_ONLY, CW_BORDER_WIDTH, &[1u16.to_le_bytes()]),
            yserver_protocol::x11::error::BAD_MATCH,
        ),
        (
            "CWSibling without CWStackMode → BadMatch",
            build_configure_body(
                SIB_A,
                CW_SIBLING,
                [SIB_B.to_le_bytes(); 1]
                    .iter()
                    .map(|b| {
                        let mut buf = [0u8; 2];
                        buf.copy_from_slice(&b[..2]);
                        buf
                    })
                    .collect::<Vec<_>>()
                    .as_slice(),
            ),
            yserver_protocol::x11::error::BAD_MATCH,
        ),
        (
            "CWSibling with non-sibling → BadMatch",
            build_configure_body_u32(SIB_A, CW_SIBLING | CW_STACK_MODE, ORPHAN, 0),
            yserver_protocol::x11::error::BAD_MATCH,
        ),
        (
            "CWSibling with unknown xid → BadWindow",
            build_configure_body_u32(SIB_A, CW_SIBLING | CW_STACK_MODE, BAD_SIB, 0),
            yserver_protocol::x11::error::BAD_WINDOW,
        ),
        (
            "CWWidth=0 → BadValue",
            build_configure_body(SIB_A, CW_WIDTH, &[0u16.to_le_bytes()]),
            yserver_protocol::x11::error::BAD_VALUE,
        ),
        (
            "CWHeight=0 → BadValue",
            build_configure_body(SIB_A, CW_HEIGHT, &[0u16.to_le_bytes()]),
            yserver_protocol::x11::error::BAD_VALUE,
        ),
        (
            "CWX alone → no error (MOVE_WIN path)",
            build_configure_body(SIB_A, CW_X, &[5u16.to_le_bytes()]),
            0, // 0 means: expect NO error reply
        ),
    ];

    for (i, (label, body, expected_err)) in cases.iter().enumerate() {
        let seq = SequenceNumber((i + 1) as u16);
        let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body length fits");
        process_request(
            &mut state,
            &mut backend,
            ClientId(APP),
            seq,
            RequestHeader {
                opcode: 12,
                data: 0,
                length_units,
            },
            body,
            None,
        )
        .expect("process_request");

        peer.set_nonblocking(true).unwrap();
        let mut buf = [0u8; 32];
        match peer.read_exact(&mut buf) {
            Ok(()) => {
                if *expected_err == 0 {
                    panic!("{label}: did not expect an error reply, got {buf:?}");
                }
                assert_eq!(buf[0], 0, "{label}: byte 0 = error class (0)");
                assert_eq!(
                    buf[1], *expected_err,
                    "{label}: error code mismatch — got {}",
                    buf[1]
                );
            }
            Err(e) if *expected_err == 0 => {
                // Expected — no error reply.
                assert_eq!(e.kind(), std::io::ErrorKind::WouldBlock);
            }
            Err(e) => {
                panic!("{label}: expected error reply with code {expected_err}, got {e:?}")
            }
        }
    }
}

fn build_configure_body(window_xid: u32, value_mask: u16, values: &[[u8; 2]]) -> Vec<u8> {
    let mut body = Vec::with_capacity(8 + values.len() * 4);
    body.extend_from_slice(&window_xid.to_le_bytes());
    body.extend_from_slice(&value_mask.to_le_bytes());
    body.extend_from_slice(&0u16.to_le_bytes()); // pad
    for v in values {
        body.extend_from_slice(v);
        body.extend_from_slice(&0u16.to_le_bytes()); // each value is u32 on the wire
    }
    body
}

fn build_configure_body_u32(window_xid: u32, value_mask: u16, v0: u32, v1: u32) -> Vec<u8> {
    let mut body = Vec::with_capacity(16);
    body.extend_from_slice(&window_xid.to_le_bytes());
    body.extend_from_slice(&value_mask.to_le_bytes());
    body.extend_from_slice(&0u16.to_le_bytes()); // pad
    body.extend_from_slice(&v0.to_le_bytes());
    body.extend_from_slice(&v1.to_le_bytes());
    body
}

/// xts5 Xlib4 XCreateWindow CreateWindow class/border/depth rules:
/// parent InputOnly + child InputOutput → BadMatch (test 43),
/// InputOnly + non-zero border_width → BadMatch (test 31),
/// InputOnly + non-zero depth → BadMatch (test 44).
#[test]
fn create_window_validates_class_constraints() {
    use std::io::Read;
    const APP: u32 = 500;
    const PARENT_IPO: u32 = 0x00b0_0001;
    const PARENT_IPI: u32 = 0x00b0_0002;
    const CHILD: u32 = 0x00b0_0003;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, APP);
    let mut backend = RecordingBackend::new();

    // One InputOutput parent and one InputOnly parent.
    for (id, parent, class) in [
        (PARENT_IPO, crate::resources::ROOT_WINDOW.0, 1u16),
        (PARENT_IPI, crate::resources::ROOT_WINDOW.0, 2u16),
    ] {
        state.resources.create_window(
            ClientId(APP),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(id),
                parent: ResourceId(parent),
                x: 0,
                y: 0,
                width: 50,
                height: 50,
                border_width: 0,
                class,
                visual: crate::resources::ROOT_VISUAL,
                ..Default::default()
            },
        );
    }

    // (label, depth, parent, class, border_width, expected_err)
    let cases: &[(&str, u8, u32, u16, u16, u8)] = &[
        (
            "parent InputOnly + class InputOutput",
            24,
            PARENT_IPI,
            1,
            0,
            yserver_protocol::x11::error::BAD_MATCH,
        ),
        (
            "class InputOnly + non-zero border_width",
            0,
            PARENT_IPO,
            2,
            1,
            yserver_protocol::x11::error::BAD_MATCH,
        ),
        (
            "class InputOnly + non-zero depth",
            24,
            PARENT_IPO,
            2,
            0,
            yserver_protocol::x11::error::BAD_MATCH,
        ),
    ];

    for (i, (label, depth, parent, class, bw, expected_err)) in cases.iter().enumerate() {
        let mut body = Vec::with_capacity(32);
        body.extend_from_slice(&CHILD.to_le_bytes());
        body.extend_from_slice(&parent.to_le_bytes());
        body.extend_from_slice(&0i16.to_le_bytes()); // x
        body.extend_from_slice(&0i16.to_le_bytes()); // y
        body.extend_from_slice(&10u16.to_le_bytes()); // width
        body.extend_from_slice(&10u16.to_le_bytes()); // height
        body.extend_from_slice(&bw.to_le_bytes()); // border_width
        body.extend_from_slice(&class.to_le_bytes()); // class
        body.extend_from_slice(&0u32.to_le_bytes()); // visual = CopyFromParent
        body.extend_from_slice(&0u32.to_le_bytes()); // value_mask
        let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("body fits");
        let seq = SequenceNumber((i + 1) as u16);
        process_request(
            &mut state,
            &mut backend,
            ClientId(APP),
            seq,
            RequestHeader {
                opcode: 1,
                data: *depth,
                length_units,
            },
            &body,
            None,
        )
        .expect("process_request");

        peer.set_nonblocking(true).unwrap();
        let mut buf = [0u8; 32];
        peer.read_exact(&mut buf)
            .unwrap_or_else(|e| panic!("{label}: expected error reply, got {e:?}"));
        assert_eq!(buf[0], 0, "{label}: byte 0 = error class");
        assert_eq!(
            buf[1], *expected_err,
            "{label}: expected error code {expected_err}, got {}",
            buf[1]
        );
        assert_eq!(
            buf[10], 1,
            "{label}: BadMatch must carry CreateWindow opcode"
        );
    }
}

/// DRI3::BufferFromPixmap: when the backend's `dri3_export_pixmap`
/// returns Err (e.g. no exportable backing, Vulkan unavailable, or
/// any promotion failure), the dispatcher must emit `BadPixmap`
/// (error code 4) — matching Xorg `dri3/dri3_request.c:277`.
/// Previously this emitted `BadAlloc` (11).
#[test]
fn buffer_from_pixmap_export_failure_returns_bad_pixmap() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    // RecordingBackend does not override dri3_export_pixmap, so the
    // default trait implementation returns Err("DRI3 export unsupported
    // on this backend") — exactly the failure case we're testing.
    let mut backend = RecordingBackend::new();

    // Register a pixmap in the resource table with a valid host_xid so
    // the handler reaches the dri3_export_pixmap call (not the
    // BadDrawable path).
    let pixmap_xid: u32 = 0x1000;
    state.resources.create_pixmap(
        ClientId(1),
        CreatePixmapRequest {
            depth: 24,
            pixmap: ResourceId(pixmap_xid),
            drawable: ROOT_WINDOW,
            width: 16,
            height: 16,
        },
    );
    assert!(
        state.resources.set_pixmap_host_xid(
            ResourceId(pixmap_xid),
            crate::backend::PixmapHandle::from_raw(0xdead_cafe).unwrap(),
        ),
        "set_pixmap_host_xid must succeed"
    );

    // BufferFromPixmap body: 4-byte pixmap XID (little-endian).
    let body = pixmap_xid.to_le_bytes().to_vec();

    let outcome = process_request(
        &mut state,
        &mut backend,
        ClientId(1),
        SequenceNumber(7),
        RequestHeader {
            opcode: 147, // DRI3_MAJOR_OPCODE
            data: 3,     // BUFFER_FROM_PIXMAP
            length_units: 2,
        },
        &body,
        None,
    )
    .expect("process_request should not hard-error");

    assert!(
        matches!(outcome, RequestOutcome::Handled),
        "expected Handled, got {outcome:?}"
    );

    // Read the 32-byte X error packet from the peer socket.
    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf)
        .expect("BadPixmap error packet must be delivered to client");
    assert_eq!(buf[0], 0, "byte 0 must be 0 (Error class)");
    assert_eq!(
        buf[1],
        x11::error::BAD_PIXMAP,
        "expected BadPixmap ({}), got {}",
        x11::error::BAD_PIXMAP,
        buf[1]
    );
}

/// DRI3::BuffersFromPixmap (op 8): like op 3, a backend export
/// failure must emit `BadPixmap` (the modifier-aware multi-plane
/// reply shares op 3's error contract). The default RecordingBackend
/// returns Err from `dri3_export_pixmap_buffers`.
#[test]
fn buffers_from_pixmap_export_failure_returns_bad_pixmap() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    let pixmap_xid: u32 = 0x1000;
    state.resources.create_pixmap(
        ClientId(1),
        CreatePixmapRequest {
            depth: 24,
            pixmap: ResourceId(pixmap_xid),
            drawable: ROOT_WINDOW,
            width: 16,
            height: 16,
        },
    );
    assert!(state.resources.set_pixmap_host_xid(
        ResourceId(pixmap_xid),
        crate::backend::PixmapHandle::from_raw(0xdead_cafe).unwrap(),
    ));

    let body = pixmap_xid.to_le_bytes().to_vec();
    let outcome = process_request(
        &mut state,
        &mut backend,
        ClientId(1),
        SequenceNumber(7),
        RequestHeader {
            opcode: 147, // DRI3_MAJOR_OPCODE
            data: 8,     // BUFFERS_FROM_PIXMAP
            length_units: 2,
        },
        &body,
        None,
    )
    .expect("process_request should not hard-error");

    assert!(
        matches!(outcome, RequestOutcome::Handled),
        "expected Handled, got {outcome:?}"
    );

    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf)
        .expect("BadPixmap error packet must be delivered to client");
    assert_eq!(buf[0], 0, "byte 0 must be 0 (Error class)");
    assert_eq!(
        buf[1],
        x11::error::BAD_PIXMAP,
        "expected BadPixmap ({}), got {}",
        x11::error::BAD_PIXMAP,
        buf[1]
    );
}

#[test]
fn glx_extension_string_includes_tfp_only_when_capable() {
    let with = glx_extension_string(true);
    let without = glx_extension_string(false);
    assert!(with.contains("GLX_EXT_texture_from_pixmap"));
    assert!(!without.contains("GLX_EXT_texture_from_pixmap"));
    // Base extensions always present.
    assert!(with.contains("GLX_ARB_create_context"));
    assert!(without.contains("GLX_ARB_create_context"));
}

/// Xorg writes a space after **every** enabled extension
/// (`glx/extension_string.c:144-145`), so its GLX extension string
/// always ends with `' '` before the NUL. yserver's did not, and
/// `libGLX_nvidia` responds by losing the final token *and* dropping
/// `GLX_ARB_get_proc_address` from the client extension string — which
/// makes libepoxy abort and takes `kwin_x11` down with SIGABRT.
///
/// Measured 2026-08-07; see
/// `docs/superpowers/specs/2026-08-07-glx-extension-string-terminator-design.md`
/// and `~/yserver-glx-logs/2026-08-07-terminator-evidence/`.
#[test]
fn glx_extension_string_is_space_terminated() {
    for tfp_supported in [false, true] {
        let s = glx_extension_string(tfp_supported);
        assert!(
            s.ends_with(' '),
            "GLX extension string must end with Xorg's space terminator; \
                 tfp_supported={tfp_supported} produced {s:?}"
        );
    }
}

/// Companion to `glx_extension_string_is_space_terminated`: the
/// terminator must not come at the cost of the token list. Green both
/// before and after that fix — this is a guard, not a regression test.
#[test]
fn glx_extension_string_tokens_match_advertised_constants() {
    use yserver_protocol::x11::glx as g;
    for tfp_supported in [false, true] {
        let s = glx_extension_string(tfp_supported);
        assert!(
            !s.starts_with(' '),
            "no leading separator; tfp_supported={tfp_supported} produced {s:?}"
        );
        assert!(
            !s.contains("  "),
            "no doubled separator; tfp_supported={tfp_supported} produced {s:?}"
        );
        let mut expected: Vec<&str> = g::SERVER_EXTENSIONS.split_whitespace().collect();
        expected.push(g::SGIX_FBCONFIG_EXTENSION);
        if tfp_supported {
            expected.push(g::TFP_EXTENSION);
        }
        let tokens: Vec<&str> = s.split_whitespace().collect();
        assert_eq!(
            tokens, expected,
            "token list must be the advertised constants, in order; \
                 tfp_supported={tfp_supported}"
        );
    }
}

#[test]
fn fbconfigs_emit_bind_to_texture_pairs_in_xorg_order() {
    use yserver_protocol::x11::glx as g;
    let configs = synthesise_glx_fb_configs(true);
    // All configs same length (wire encoder requirement).
    let len = configs[0].len();
    assert!(configs.iter().all(|c| c.len() == len));

    for c in &configs {
        // Find the bind-to-texture block; it must appear as a contiguous run in this order.
        let idx = c
            .iter()
            .position(|(k, _)| *k == g::GLX_BIND_TO_TEXTURE_RGB_EXT)
            .expect("RGB present");
        let order = [
            g::GLX_BIND_TO_TEXTURE_RGB_EXT,
            g::GLX_BIND_TO_TEXTURE_RGBA_EXT,
            g::GLX_BIND_TO_MIPMAP_TEXTURE_EXT,
            g::GLX_BIND_TO_TEXTURE_TARGETS_EXT,
            g::GLX_Y_INVERTED_EXT,
        ];
        for (i, key) in order.iter().enumerate() {
            assert_eq!(c[idx + i].0, *key, "wrong order at offset {i}");
        }
        // Values:
        assert_eq!(c[idx + 2].1, 0, "MIPMAP must be 0/false");
        assert_eq!(
            c[idx + 3].1,
            g::GLX_DONT_CARE,
            "BIND_TO_TEXTURE_TARGETS is GLX_DONT_CARE so it matches any \
                 client-driver target bitmask (driConfigEqual)"
        );
        assert_eq!(
            c[idx + 4].1,
            g::GLX_DONT_CARE,
            "Y_INVERTED in FBConfig is GLX_DONT_CARE"
        );
    }

    // Both depths advertise RGB=true RGBA=true, matching radeonsi's
    // TFP configs (HW-verified). RGBA=true on depth-24 is correct:
    // opaque windows sample as α=1.
    let depth24 = configs
        .iter()
        .find(|c| c.iter().any(|(k, v)| *k == g::GLX_VISUAL_ID && *v == 0x102))
        .unwrap();
    let d24 = depth24
        .iter()
        .position(|(k, _)| *k == g::GLX_BIND_TO_TEXTURE_RGB_EXT)
        .unwrap();
    assert_eq!(depth24[d24].1, 1); // RGB true
    assert_eq!(depth24[d24 + 1].1, 1); // RGBA true on depth-24 (match radeonsi)

    let depth32 = configs
        .iter()
        .find(|c| c.iter().any(|(k, v)| *k == g::GLX_VISUAL_ID && *v == 0x103))
        .unwrap();
    let d32 = depth32
        .iter()
        .position(|(k, _)| *k == g::GLX_BIND_TO_TEXTURE_RGB_EXT)
        .unwrap();
    assert_eq!(depth32[d32 + 1].1, 1); // RGBA true on depth-32
}

#[test]
fn fbconfigs_omit_bind_to_texture_when_tfp_unsupported() {
    use yserver_protocol::x11::glx as g;
    let configs = synthesise_glx_fb_configs(false);
    assert!(
        configs
            .iter()
            .all(|c| c.iter().all(|(k, _)| *k != g::GLX_BIND_TO_TEXTURE_RGB_EXT))
    );
    // Still equal length across configs.
    let len = configs[0].len();
    assert!(configs.iter().all(|c| c.len() == len));
}

/// GLX Task 3.4: `glXCreatePixmap` records the X drawable in
/// `glx_drawables`, calls `acquire_glx_pixmap_export` on the backend,
/// and `glXDestroyPixmap` clears the entry and calls
/// `release_glx_pixmap_export`.
#[test]
fn glx_create_pixmap_records_x_drawable_and_destroy_clears_it() {
    use crate::backend::recording::RecordedCall;
    use yserver_protocol::x11::glx as x11glx;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    // Register an X pixmap in the resource table with a known host_xid.
    let x_pixmap_xid: u32 = 0x2000;
    let host_xid_raw: u32 = 0xdead_0001;
    state.resources.create_pixmap(
        client_id,
        yserver_protocol::x11::CreatePixmapRequest {
            depth: 24,
            pixmap: ResourceId(x_pixmap_xid),
            drawable: ROOT_WINDOW,
            width: 64,
            height: 32,
        },
    );
    assert!(
        state.resources.set_pixmap_host_xid(
            ResourceId(x_pixmap_xid),
            crate::backend::PixmapHandle::from_raw(host_xid_raw).unwrap(),
        ),
        "set_pixmap_host_xid must succeed"
    );

    let glx_xid: u32 = 0x4000_0001;
    let fbconfig: u32 = 0x101;

    // Build a GLX CREATE_PIXMAP request body:
    // [screen(u32)][fbconfig(u32)][x_window(u32)][glx_window(u32)]
    let mut create_body = Vec::new();
    create_body.extend_from_slice(&0u32.to_le_bytes()); // screen = 0
    create_body.extend_from_slice(&fbconfig.to_le_bytes());
    create_body.extend_from_slice(&x_pixmap_xid.to_le_bytes());
    create_body.extend_from_slice(&glx_xid.to_le_bytes());

    let length_units = u32::try_from(1 + create_body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,                 // GLX_MAJOR_OPCODE
            data: x11glx::CREATE_PIXMAP, // minor = 22
            length_units,
        },
        &create_body,
        None,
    )
    .expect("process_request CREATE_PIXMAP");

    // Verify the GlxDrawable was recorded.
    let d = state
        .glx_drawables
        .get(&glx_xid)
        .expect("GlxDrawable must be present after CreatePixmap");
    assert_eq!(
        d.x_drawable, x_pixmap_xid,
        "x_drawable must point to the X pixmap"
    );
    assert_eq!(d.fbconfig, fbconfig);

    // Verify acquire was forwarded to the backend.
    assert!(
        backend
            .calls()
            .contains(&RecordedCall::AcquireGlxPixmapExport(host_xid_raw)),
        "AcquireGlxPixmapExport must be recorded after CreatePixmap"
    );

    // Build a GLX DESTROY_PIXMAP request body: [glx_xid(u32)]
    let destroy_body = glx_xid.to_le_bytes().to_vec();
    let length_units = u32::try_from(1 + destroy_body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(2),
        RequestHeader {
            opcode: 148,
            data: x11glx::DESTROY_PIXMAP, // minor = 23
            length_units,
        },
        &destroy_body,
        None,
    )
    .expect("process_request DESTROY_PIXMAP");

    // GlxDrawable must be removed.
    assert!(
        !state.glx_drawables.contains_key(&glx_xid),
        "GlxDrawable must be removed after DestroyPixmap"
    );

    // Verify release was forwarded to the backend.
    assert!(
        backend
            .calls()
            .contains(&RecordedCall::ReleaseGlxPixmapExport(host_xid_raw)),
        "ReleaseGlxPixmapExport must be recorded after DestroyPixmap"
    );
}

// ─── GLX 1.0 CreateGLXPixmap / DestroyGLXPixmap, QueryContext, IsDirect ───
//
// Expected wire behaviour is Xorg's, captured from Xvfb 21.1.24
// (llvmpipe GLX) with an xcb probe on 2026-09-26. Xvfb's GLX visual 0x21
// carries FBConfig 0x88; the yserver counterpart used below is
// ROOT_VISUAL 0x102 carrying FBConfig 0x101 (synthesise_glx_fb_configs).
// Error values, minors and the order in which the checks fire are
// Xvfb's, verbatim.

const GLX_TEST_XID_BASE: u32 = 0x0020_0000;
const GLX_TEST_XID_MASK: u32 = 0x001f_ffff;

/// A client whose XID range is `0x0020_0000 | 0x001f_ffff`, the range
/// Xvfb handed the capture probe, so `LEGAL_NEW_RESOURCE` is exercised.
fn glx_legacy_fixture() -> (ServerState, RecordingBackend, UnixStream) {
    let mut state = ServerState::new();
    let peer = install_client(&mut state, 1);
    let client = state.clients.get_mut(&1).expect("test client");
    client.resource_id_base = GLX_TEST_XID_BASE;
    client.resource_id_mask = GLX_TEST_XID_MASK;
    (state, RecordingBackend::new(), peer)
}

fn glx_legacy_x_pixmap(state: &mut ServerState, xid: u32, depth: u8, host: Option<u32>) {
    state.resources.create_pixmap(
        ClientId(1),
        CreatePixmapRequest {
            depth,
            pixmap: ResourceId(xid),
            drawable: ROOT_WINDOW,
            width: 64,
            height: 32,
        },
    );
    if let Some(host) = host {
        assert!(state.resources.set_pixmap_host_xid(
            ResourceId(xid),
            crate::backend::PixmapHandle::from_raw(host).expect("non-zero host xid"),
        ));
    }
}

fn glx_legacy_words(words: &[u32]) -> Vec<u8> {
    words.iter().flat_map(|v| v.to_le_bytes()).collect()
}

/// Run one request for `client` and return every byte it wrote.
fn glx_legacy_send_major(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    peer: &mut UnixStream,
    client: u32,
    (opcode, minor): (u8, u8),
    body: &[u8],
) -> Vec<u8> {
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("fits");
    process_request(
        state,
        backend,
        ClientId(client),
        SequenceNumber(7),
        RequestHeader {
            opcode,
            data: minor,
            length_units,
        },
        body,
        None,
    )
    .expect("process_request");
    read_all_or_buffered(state, client, peer)
}

/// Run one GLX request for `client` and return every byte it wrote.
fn glx_legacy_send(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    peer: &mut UnixStream,
    client: u32,
    minor: u8,
    body: &[u8],
) -> Vec<u8> {
    glx_legacy_send_major(
        state,
        backend,
        peer,
        client,
        (crate::nested::GLX_MAJOR_OPCODE, minor),
        body,
    )
}

/// Assert `bytes` is exactly one X error with this code, bad value and
/// minor opcode on the GLX major opcode.
fn assert_glx_legacy_error(what: &str, bytes: &[u8], code: u8, value: u32, minor: u8) {
    assert_eq!(bytes.len(), 32, "{what}: expected exactly one error packet");
    assert_eq!(bytes[0], 0, "{what}: expected an X error");
    assert_eq!(bytes[1], code, "{what}: error code");
    assert_eq!(
        u32::from_le_bytes(bytes[4..8].try_into().unwrap()),
        value,
        "{what}: bad value"
    );
    assert_eq!(
        u16::from_le_bytes([bytes[8], bytes[9]]),
        u16::from(minor),
        "{what}: minor opcode"
    );
    assert_eq!(
        bytes[10],
        crate::nested::GLX_MAJOR_OPCODE,
        "{what}: major opcode"
    );
}

fn create_glx_pixmap_body(screen: u32, visual: u32, pixmap: u32, glx_pixmap: u32) -> Vec<u8> {
    glx_legacy_words(&[screen, visual, pixmap, glx_pixmap])
}

/// Decode the (attribute, value) pairs of a GetDrawableAttributes /
/// QueryContext reply, checking the header's length and count agree.
fn glx_legacy_reply_pairs(bytes: &[u8]) -> Vec<(u32, u32)> {
    assert_eq!(bytes[0], 1, "expected a reply, got {bytes:02x?}");
    let length = u32::from_le_bytes(bytes[4..8].try_into().unwrap()) as usize;
    let n = u32::from_le_bytes(bytes[8..12].try_into().unwrap()) as usize;
    assert_eq!(length, 2 * n, "reply length must be 2 * n");
    assert_eq!(bytes.len(), 32 + 8 * n, "reply size");
    (0..n)
        .map(|i| {
            let at = 32 + 8 * i;
            (
                u32::from_le_bytes(bytes[at..at + 4].try_into().unwrap()),
                u32::from_le_bytes(bytes[at + 4..at + 8].try_into().unwrap()),
            )
        })
        .collect()
}

/// GLX 1.0 `glXCreateGLXPixmap` (minor 13) used to hit the
/// `GLXBadRenderRequest` catch-all, so Xlib's default handler killed the
/// app. It must create the same GLXPixmap record GLX 1.3 `CreatePixmap`
/// does (config = the visual's FBConfig), hold the export ref, report
/// Xorg's drawable attributes, and `DestroyGLXPixmap` (15) must release
/// the ref — also after the X pixmap was freed first (Xorg bumps the
/// pixmap refcount, glxcmds.c `DoCreateGLXPixmap`).
#[test]
fn glx10_create_glx_pixmap_records_pixmap_and_destroy_releases_it() {
    use crate::backend::recording::RecordedCall;
    use yserver_protocol::x11::glx as g;

    let (mut state, mut backend, mut peer) = glx_legacy_fixture();
    let pixmap = GLX_TEST_XID_BASE | 0x01;
    let glx_pixmap = GLX_TEST_XID_BASE | 0x02;
    let host = 0xdead_0001;
    glx_legacy_x_pixmap(&mut state, pixmap, 24, Some(host));

    let out = glx_legacy_send(
        &mut state,
        &mut backend,
        &mut peer,
        1,
        g::CREATE_GLX_PIXMAP,
        &create_glx_pixmap_body(0, crate::resources::ROOT_VISUAL.0, pixmap, glx_pixmap),
    );
    assert!(
        out.is_empty(),
        "CreateGLXPixmap succeeds silently, got {out:02x?}"
    );
    let record = state
        .glx_drawables
        .get(&glx_pixmap)
        .expect("GLXPixmap recorded");
    assert_eq!(record.kind, crate::server::GlxDrawableKind::Pixmap);
    assert_eq!(record.x_drawable, pixmap);
    assert_eq!(record.fbconfig, 0x101, "the visual's FBConfig");
    assert_eq!(record.glx_export_host_xid, Some(host));
    assert!(
        backend
            .calls()
            .contains(&RecordedCall::AcquireGlxPixmapExport(host))
    );

    // Xvfb: 0x20d4=0 0x801d=64 0x801e=32 0x800c=0 0x20d6=0x20dd
    //       0x801f=0 0x8013=<fbconfig> 0x8010=GLX_PIXMAP_BIT
    let out = glx_legacy_send(
        &mut state,
        &mut backend,
        &mut peer,
        1,
        g::GET_DRAWABLE_ATTRIBUTES,
        &glx_pixmap.to_le_bytes(),
    );
    assert_eq!(
        glx_legacy_reply_pairs(&out),
        vec![
            (g::GLX_Y_INVERTED_EXT, 0),
            (g::GLX_WIDTH, 64),
            (g::GLX_HEIGHT, 32),
            (g::GLX_SCREEN, 0),
            (g::GLX_TEXTURE_TARGET_EXT, g::GLX_TEXTURE_RECTANGLE_EXT),
            (g::GLX_EVENT_MASK, 0),
            (g::GLX_FBCONFIG_ID, 0x101),
            (g::GLX_DRAWABLE_TYPE, g::GLX_PIXMAP_BIT),
        ]
    );

    // FreePixmap first, then DestroyGLXPixmap: both Success on Xvfb.
    let out = glx_legacy_send_major(
        &mut state,
        &mut backend,
        &mut peer,
        1,
        (54, 0),
        &pixmap.to_le_bytes(),
    );
    assert!(out.is_empty(), "FreePixmap: got {out:02x?}");
    let out = glx_legacy_send(
        &mut state,
        &mut backend,
        &mut peer,
        1,
        g::DESTROY_GLX_PIXMAP,
        &glx_pixmap.to_le_bytes(),
    );
    assert!(
        out.is_empty(),
        "DestroyGLXPixmap succeeds silently, got {out:02x?}"
    );
    assert!(!state.glx_drawables.contains_key(&glx_pixmap));
    assert!(
        backend
            .calls()
            .contains(&RecordedCall::ReleaseGlxPixmapExport(host))
    );
}

/// Every CreateGLXPixmap failure Xvfb produced, with its error code,
/// bad value and the precedence between checks: size, then the new
/// XID (`LEGAL_NEW_RESOURCE`), then the screen (GLXVND: BadMatch), then
/// the visual (BadValue), then the pixmap (core BadDrawable, or core
/// BadPixmap for a window). A failed request creates nothing.
#[test]
fn glx10_create_glx_pixmap_errors_match_xorg() {
    use yserver_protocol::x11::{error, glx as g};

    let (mut state, mut backend, mut peer) = glx_legacy_fixture();
    let pixmap = GLX_TEST_XID_BASE | 0x01;
    let other_pixmap = GLX_TEST_XID_BASE | 0x03;
    let existing_glx = GLX_TEST_XID_BASE | 0x04;
    let fresh = GLX_TEST_XID_BASE | 0x05;
    let vis = crate::resources::ROOT_VISUAL.0;
    glx_legacy_x_pixmap(&mut state, pixmap, 24, None);
    glx_legacy_x_pixmap(&mut state, other_pixmap, 32, None);
    let out = glx_legacy_send(
        &mut state,
        &mut backend,
        &mut peer,
        1,
        g::CREATE_GLX_PIXMAP,
        &create_glx_pixmap_body(0, vis, pixmap, existing_glx),
    );
    assert!(out.is_empty());

    let bad_id = error::BAD_ID_CHOICE;
    let unknown = 0x5a_5a5a;
    let root = ROOT_WINDOW.0;
    let cases: &[(&str, [u32; 4], u8, u32)] = &[
        (
            "glx id in use",
            [0, vis, pixmap, existing_glx],
            bad_id,
            existing_glx,
        ),
        (
            "glx id = X pixmap",
            [0, vis, pixmap, other_pixmap],
            bad_id,
            other_pixmap,
        ),
        (
            "glx id out of range",
            [0, vis, pixmap, 0x07f0_0001],
            bad_id,
            0x07f0_0001,
        ),
        ("screen 1", [1, vis, pixmap, fresh], error::BAD_MATCH, 1),
        (
            "unknown visual",
            [0, 0xdead, pixmap, fresh],
            error::BAD_VALUE,
            0xdead,
        ),
        // An FBConfig ID is not a GLX visual (Xvfb: its visual-less
        // FBConfig 0x41 → BadValue 0x41).
        (
            "visual-less fbconfig id",
            [0, 0x104, pixmap, fresh],
            error::BAD_VALUE,
            0x104,
        ),
        (
            "fbconfig id of a visual",
            [0, 0x101, pixmap, fresh],
            error::BAD_VALUE,
            0x101,
        ),
        (
            "screen 1 + bad visual",
            [1, 0xdead, pixmap, fresh],
            error::BAD_MATCH,
            1,
        ),
        (
            "root window as pixmap",
            [0, vis, root, fresh],
            error::BAD_PIXMAP,
            root,
        ),
        (
            "unknown pixmap",
            [0, vis, unknown, fresh],
            error::BAD_DRAWABLE,
            unknown,
        ),
        (
            "bad visual + bad pixmap",
            [0, 0xdead, unknown, fresh],
            error::BAD_VALUE,
            0xdead,
        ),
        (
            "bad pixmap + glx id in use",
            [0, vis, unknown, existing_glx],
            bad_id,
            existing_glx,
        ),
    ];
    for (what, [screen, visual, pix, glx], code, value) in cases {
        let out = glx_legacy_send(
            &mut state,
            &mut backend,
            &mut peer,
            1,
            g::CREATE_GLX_PIXMAP,
            &create_glx_pixmap_body(*screen, *visual, *pix, *glx),
        );
        assert_glx_legacy_error(what, &out, *code, *value, g::CREATE_GLX_PIXMAP);
    }
    assert!(!state.glx_drawables.contains_key(&fresh));
    assert!(!state.glx_drawables.contains_key(&other_pixmap));
    assert_eq!(state.glx_drawables.len(), 1);
}

/// Xorg does not compare the pixmap depth with the visual: Xvfb accepted
/// depth-32, depth-8 and depth-1 pixmaps for its depth-24 visual.
#[test]
fn glx10_create_glx_pixmap_accepts_any_pixmap_depth() {
    use yserver_protocol::x11::glx as g;

    let (mut state, mut backend, mut peer) = glx_legacy_fixture();
    for (i, depth) in (0_u32..).zip([32_u8, 8, 1]) {
        let pixmap = GLX_TEST_XID_BASE | (0x10 + i);
        let glx_pixmap = GLX_TEST_XID_BASE | (0x20 + i);
        glx_legacy_x_pixmap(&mut state, pixmap, depth, None);
        let out = glx_legacy_send(
            &mut state,
            &mut backend,
            &mut peer,
            1,
            g::CREATE_GLX_PIXMAP,
            &create_glx_pixmap_body(0, crate::resources::ROOT_VISUAL.0, pixmap, glx_pixmap),
        );
        assert!(out.is_empty(), "depth {depth}: got {out:02x?}");
        assert!(state.glx_drawables.contains_key(&glx_pixmap));
    }
}

/// DestroyGLXPixmap takes only a live GLX *pixmap*: anything else is
/// `GLXBadPixmap` with the XID as bad value (GLXVND's XID map, then
/// `validGlxDrawable`'s type check). GLX 1.0 and GLX 1.3 pixmaps are the
/// same resource type, so either destroy request frees either.
#[test]
fn glx10_destroy_glx_pixmap_errors_and_cross_version_destroy_match_xorg() {
    use yserver_protocol::x11::glx as g;

    let (mut state, mut backend, mut peer) = glx_legacy_fixture();
    let bad_pixmap = crate::nested::GLX_FIRST_ERROR + g::ERROR_GLX_BAD_PIXMAP;
    let pixmap = GLX_TEST_XID_BASE | 0x01;
    glx_legacy_x_pixmap(&mut state, pixmap, 24, None);
    let legacy = GLX_TEST_XID_BASE | 0x02;
    let modern = GLX_TEST_XID_BASE | 0x03;
    let glx_window = GLX_TEST_XID_BASE | 0x04;
    let pbuffer = GLX_TEST_XID_BASE | 0x05;
    let vis = crate::resources::ROOT_VISUAL.0;

    let mut send = |state: &mut ServerState, minor: u8, body: &[u8]| {
        glx_legacy_send(state, &mut backend, &mut peer, 1, minor, body)
    };
    let window_body = glx_legacy_words(&[0, 0x101, ROOT_WINDOW.0, glx_window]);
    assert!(send(&mut state, g::CREATE_WINDOW, &window_body).is_empty());
    let pbuffer_body = glx_legacy_words(&[0, 0x101, pbuffer, 0]);
    assert!(send(&mut state, g::CREATE_PBUFFER, &pbuffer_body).is_empty());

    for (what, xid) in [
        ("unknown xid", 0x5a_5a5a),
        ("X pixmap", pixmap),
        ("GLX window", glx_window),
        ("GLX pbuffer", pbuffer),
    ] {
        let out = send(&mut state, g::DESTROY_GLX_PIXMAP, &xid.to_le_bytes());
        assert_glx_legacy_error(what, &out, bad_pixmap, xid, g::DESTROY_GLX_PIXMAP);
    }
    assert!(state.glx_drawables.contains_key(&glx_window));
    assert!(state.glx_drawables.contains_key(&pbuffer));

    // GLX 1.0 pixmap destroyed by GLX 1.3 DestroyPixmap; a second
    // destroy through DestroyGLXPixmap is GLXBadPixmap.
    let body = create_glx_pixmap_body(0, vis, pixmap, legacy);
    assert!(send(&mut state, g::CREATE_GLX_PIXMAP, &body).is_empty());
    assert!(send(&mut state, g::DESTROY_PIXMAP, &legacy.to_le_bytes()).is_empty());
    assert!(!state.glx_drawables.contains_key(&legacy));
    let out = send(&mut state, g::DESTROY_GLX_PIXMAP, &legacy.to_le_bytes());
    assert_glx_legacy_error(
        "destroyed twice",
        &out,
        bad_pixmap,
        legacy,
        g::DESTROY_GLX_PIXMAP,
    );

    // GLX 1.3 pixmap destroyed by GLX 1.0 DestroyGLXPixmap.
    let body = glx_legacy_words(&[0, 0x101, pixmap, modern, 0]);
    assert!(send(&mut state, g::CREATE_PIXMAP, &body).is_empty());
    assert!(send(&mut state, g::DESTROY_GLX_PIXMAP, &modern.to_le_bytes()).is_empty());
    assert!(!state.glx_drawables.contains_key(&modern));
}

/// CreateGLXPixmap, DestroyGLXPixmap, QueryContext and IsDirect are all
/// `REQUEST_SIZE_MATCH` in Xorg's GLXVND stubs: a short or long request
/// is core `BadLength`, and nothing is created.
#[test]
fn glx10_fixed_size_requests_reject_wrong_length() {
    use yserver_protocol::x11::{error, glx as g};

    let (mut state, mut backend, mut peer) = glx_legacy_fixture();
    let pixmap = GLX_TEST_XID_BASE | 0x01;
    glx_legacy_x_pixmap(&mut state, pixmap, 24, None);
    let mut long_create = create_glx_pixmap_body(
        0,
        crate::resources::ROOT_VISUAL.0,
        pixmap,
        GLX_TEST_XID_BASE | 0x02,
    );
    long_create.extend_from_slice(&[0; 4]);
    let short_create = &long_create[..12];
    for (what, minor, body) in [
        (
            "CreateGLXPixmap long",
            g::CREATE_GLX_PIXMAP,
            long_create.as_slice(),
        ),
        ("CreateGLXPixmap short", g::CREATE_GLX_PIXMAP, short_create),
        ("DestroyGLXPixmap long", g::DESTROY_GLX_PIXMAP, &[0; 8][..]),
        ("DestroyGLXPixmap empty", g::DESTROY_GLX_PIXMAP, &[][..]),
        ("QueryContext long", g::QUERY_CONTEXT, &[0; 8][..]),
        ("QueryContext empty", g::QUERY_CONTEXT, &[][..]),
        ("IsDirect long", g::IS_DIRECT, &[0; 8][..]),
        ("IsDirect empty", g::IS_DIRECT, &[][..]),
    ] {
        let out = glx_legacy_send(&mut state, &mut backend, &mut peer, 1, minor, body);
        assert_glx_legacy_error(what, &out, error::BAD_LENGTH, 0, minor);
    }
    assert!(state.glx_drawables.is_empty());
}

/// `QueryContext` (GLX_EXT_import_context) answers Xorg's five
/// attributes in Xorg's order (glxcmds.c `DoQueryContext`) for every
/// creation request, to any client, and `GLXBadContext` for an XID that
/// is not a live context. `IsDirect` reports the creation request's
/// `isDirect` and shares the `GLXBadContext` rule.
#[test]
fn glx_query_context_and_is_direct_match_xorg() {
    use yserver_protocol::x11::glx as g;

    let (mut state, mut backend, mut peer) = glx_legacy_fixture();
    let mut peer2 = install_client(&mut state, 2);
    let bad_context = crate::nested::GLX_FIRST_ERROR + g::ERROR_GLX_BAD_CONTEXT;
    let root_visual = crate::resources::ROOT_VISUAL.0;
    let ctx1 = GLX_TEST_XID_BASE | 0x11;
    let ctx2 = GLX_TEST_XID_BASE | 0x12;
    let ctx3 = GLX_TEST_XID_BASE | 0x13;
    let ctx4 = GLX_TEST_XID_BASE | 0x14;
    let ctx5 = GLX_TEST_XID_BASE | 0x15;

    let creates: [(u8, Vec<u32>); 5] = [
        // CreateContext: context visual screen share isDirect
        (g::CREATE_CONTEXT, vec![ctx1, root_visual, 0, 0, 1]),
        // CreateNewContext (visual-less FBConfig, share ctx1):
        // context fbconfig screen renderType share isDirect
        (
            g::CREATE_NEW_CONTEXT,
            vec![ctx2, 0x104, 0, g::GLX_RGBA_TYPE, ctx1, 1],
        ),
        // CreateContextAttribsARB (share ctx1, GL 3.0):
        // context fbconfig screen share isDirect numAttribs attribs
        (
            g::CREATE_CONTEXT_ATTRIBS_ARB,
            vec![ctx3, 0x101, 0, ctx1, 1, 2, 0x2091, 3, 0x2092, 0],
        ),
        // CreateContextAttribsARB with GLX_RENDER_TYPE = GLX_RGBA_TYPE.
        (
            g::CREATE_CONTEXT_ATTRIBS_ARB,
            vec![
                ctx4,
                0x101,
                0,
                0,
                1,
                1,
                g::GLX_RENDER_TYPE,
                g::GLX_RGBA_TYPE,
            ],
        ),
        // CreateContext asking for an indirect context (isDirect 0).
        (g::CREATE_CONTEXT, vec![ctx5, root_visual, 0, 0, 0]),
    ];
    for (minor, words) in &creates {
        let body = glx_legacy_words(words);
        let out = glx_legacy_send(&mut state, &mut backend, &mut peer, 1, *minor, &body);
        assert!(out.is_empty(), "create minor {minor}: got {out:02x?}");
    }

    let expect = |share: u32, visual: u32, fbconfig: u32| {
        vec![
            (g::GLX_SHARE_CONTEXT_EXT, share),
            (g::GLX_VISUAL_ID, visual),
            (g::GLX_SCREEN, 0),
            (g::GLX_FBCONFIG_ID, fbconfig),
            (g::GLX_RENDER_TYPE, g::GLX_RGBA_TYPE),
        ]
    };
    for (ctx, share, visual, fbconfig) in [
        // Xvfb: 0x800a=0 0x800b=0x21 0x800c=0 0x8013=0x88 0x8011=0x8014
        (ctx1, 0, root_visual, 0x101),
        // Xvfb: 0x800a=ctx1 0x800b=0 0x800c=0 0x8013=0x41 0x8011=0x8014
        (ctx2, ctx1, 0, 0x104),
        // Xvfb: 0x800a=ctx1 0x800b=0x21 0x800c=0 0x8013=0x88 0x8011=0x8014
        (ctx3, ctx1, root_visual, 0x101),
        // Xvfb: 0x800a=0 0x800b=0x21 0x800c=0 0x8013=0x88 0x8011=0x8014
        (ctx4, 0, root_visual, 0x101),
        // Xvfb +iglx: 0x800a=0 0x800b=0x21 0x800c=0 0x8013=0x88 0x8011=0x8014
        (ctx5, 0, root_visual, 0x101),
    ] {
        let out = glx_legacy_send(
            &mut state,
            &mut backend,
            &mut peer,
            1,
            g::QUERY_CONTEXT,
            &ctx.to_le_bytes(),
        );
        assert_eq!(
            glx_legacy_reply_pairs(&out),
            expect(share, visual, fbconfig),
            "QueryContext(0x{ctx:x})"
        );
    }

    // Another client may query and IsDirect it: that is what
    // import_context is for.
    let ctx1_body = ctx1.to_le_bytes();
    let out = glx_legacy_send(
        &mut state,
        &mut backend,
        &mut peer2,
        2,
        g::QUERY_CONTEXT,
        &ctx1_body,
    );
    assert_eq!(glx_legacy_reply_pairs(&out), expect(0, root_visual, 0x101));
    let out = glx_legacy_send(
        &mut state,
        &mut backend,
        &mut peer2,
        2,
        g::IS_DIRECT,
        &ctx1_body,
    );
    assert_eq!(out.len(), 32, "IsDirect reply is 32 bytes");
    assert_eq!(out[0], 1, "IsDirect reply");
    assert_eq!(&out[4..8], &[0; 4], "IsDirect reply length 0");
    assert_eq!(out[8], 1, "IsDirect(ctx1) = True");
    // Xvfb +iglx: IsDirect of a context created with isDirect 0 is 0.
    // (Without +iglx Xorg refuses that CreateContext with BadValue.)
    let out = glx_legacy_send(
        &mut state,
        &mut backend,
        &mut peer,
        1,
        g::IS_DIRECT,
        &ctx5.to_le_bytes(),
    );
    assert_eq!((out.len(), out[0], out[8]), (32, 1, 0), "IsDirect(ctx5)");

    let pixmap = GLX_TEST_XID_BASE | 0x01;
    let glx_pixmap = GLX_TEST_XID_BASE | 0x02;
    glx_legacy_x_pixmap(&mut state, pixmap, 24, None);
    let body = create_glx_pixmap_body(0, root_visual, pixmap, glx_pixmap);
    let out = glx_legacy_send(
        &mut state,
        &mut backend,
        &mut peer,
        1,
        g::CREATE_GLX_PIXMAP,
        &body,
    );
    assert!(out.is_empty());
    for (what, xid) in [
        ("unknown", 0x5a_5a5a),
        ("GLX pixmap", glx_pixmap),
        ("None", 0),
    ] {
        for minor in [g::QUERY_CONTEXT, g::IS_DIRECT] {
            let out = glx_legacy_send(
                &mut state,
                &mut backend,
                &mut peer,
                1,
                minor,
                &xid.to_le_bytes(),
            );
            assert_glx_legacy_error(what, &out, bad_context, xid, minor);
        }
    }

    let ctx2_body = ctx2.to_le_bytes();
    let out = glx_legacy_send(
        &mut state,
        &mut backend,
        &mut peer,
        1,
        g::DESTROY_CONTEXT,
        &ctx2_body,
    );
    assert!(out.is_empty());
    let out = glx_legacy_send(
        &mut state,
        &mut backend,
        &mut peer,
        1,
        g::QUERY_CONTEXT,
        &ctx2_body,
    );
    assert_glx_legacy_error(
        "destroyed context",
        &out,
        bad_context,
        ctx2,
        g::QUERY_CONTEXT,
    );
}

/// `GetDrawableAttributes` on a GLXPixmap/GLXWindow must report the
/// geometry of the *backing* X drawable. The GLX XID is a fresh
/// client-allocated id with no X resource behind it, so resolving the
/// geometry from the GLX XID itself always missed and fell through to
/// `unwrap_or((0, 0))`. Measured on the wire against `libGLX_nvidia`
/// (2026-08-03): a 64×32 backing drawable was reported as
/// `GLX_WIDTH`/`GLX_HEIGHT` = 0. Xorg reads `pGlxDraw->pDraw->width` /
/// `->height` (glxcmds.c:1891). Against the old logic this test FAILS
/// with 0×0.
#[test]
fn glx_drawable_attributes_report_backing_drawable_geometry() {
    use yserver_protocol::x11::glx as g;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    let x_pixmap_xid: u32 = 0x2000;
    state.resources.create_pixmap(
        client_id,
        yserver_protocol::x11::CreatePixmapRequest {
            depth: 24,
            pixmap: ResourceId(x_pixmap_xid),
            drawable: ROOT_WINDOW,
            width: 64,
            height: 32,
        },
    );

    let glx_xid: u32 = 0x4000_0001;
    let fbconfig: u32 = 0x101;
    let mut create_body = Vec::new();
    create_body.extend_from_slice(&0u32.to_le_bytes()); // screen = 0
    create_body.extend_from_slice(&fbconfig.to_le_bytes());
    create_body.extend_from_slice(&x_pixmap_xid.to_le_bytes());
    create_body.extend_from_slice(&glx_xid.to_le_bytes());
    let length_units = u32::try_from(1 + create_body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,
            data: g::CREATE_PIXMAP,
            length_units,
        },
        &create_body,
        None,
    )
    .expect("process_request CREATE_PIXMAP");

    let attribs = drawable_attributes_for(&state, glx_xid);
    let get = |key: u32| {
        attribs
            .iter()
            .find(|(k, _)| *k == key)
            .map(|(_, v)| *v)
            .unwrap_or_else(|| panic!("attribute 0x{key:x} must be present"))
    };
    assert_eq!(get(g::GLX_WIDTH), 64, "GLX_WIDTH must track the X pixmap");
    assert_eq!(get(g::GLX_HEIGHT), 32, "GLX_HEIGHT must track the X pixmap");
    assert_eq!(
        get(g::GLX_FBCONFIG_ID),
        fbconfig,
        "a registered GLX drawable must report its real fbconfig"
    );
}

/// Naked X window (GLX 1.2 pattern, no GLX record): Xorg skips the
/// whole `pGlxDraw` block — `GLX_FBCONFIG_ID` / `GLX_TEXTURE_TARGET_EXT`
/// / `GLX_EVENT_MASK` must be **absent**, not present-and-zero — and
/// still ends with `GLX_DRAWABLE_TYPE = GLX_WINDOW_BIT`
/// (glxcmds.c:1875-1914). Asserts exact set and order.
#[test]
fn glx_drawable_attributes_naked_window_matches_xorg() {
    use yserver_protocol::x11::glx as g;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let client_id = ClientId(1);
    let window_xid: u32 = 0x2000;
    state.resources.create_window(
        client_id,
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(window_xid),
            parent: ROOT_WINDOW,
            width: 64,
            height: 32,
            ..Default::default()
        },
    );

    let attribs = drawable_attributes_for(&state, window_xid);
    assert_eq!(
        attribs,
        vec![
            (g::GLX_Y_INVERTED_EXT, 0),
            (g::GLX_WIDTH, 64),
            (g::GLX_HEIGHT, 32),
            (g::GLX_SCREEN, 0),
            (g::GLX_DRAWABLE_TYPE, g::GLX_WINDOW_BIT),
        ],
        "naked-window attribute set and order must match glxcmds.c:1889-1914"
    );
}

/// Registered GLXWindow: the `pGlxDraw` block is present, in Xorg's
