/// Request-level wire test: `GET_DRAWABLE_ATTRIBUTES` on a naked X
/// window must deliver a well-formed reply — `length = 2n` 4-byte
/// units, `numAttribs = n`, pairs in Xorg order — with no
/// `GLX_FBCONFIG_ID` anywhere in the payload.
#[test]
fn glx_get_drawable_attributes_naked_window_wire_reply() {
    use yserver_protocol::x11::glx as g;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    let window_xid: u32 = 0x2000;
    state.resources.create_window(
        client_id,
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(window_xid),
            parent: ROOT_WINDOW,
            width: 64,
            height: 32,
            ..Default::default()
        },
    );

    let body = window_xid.to_le_bytes().to_vec();
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(7),
        RequestHeader {
            opcode: 148,
            data: g::GET_DRAWABLE_ATTRIBUTES,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request GET_DRAWABLE_ATTRIBUTES");

    let expected: [(u32, u32); 5] = [
        (g::GLX_Y_INVERTED_EXT, 0),
        (g::GLX_WIDTH, 64),
        (g::GLX_HEIGHT, 32),
        (g::GLX_SCREEN, 0),
        (g::GLX_DRAWABLE_TYPE, g::GLX_WINDOW_BIT),
    ];
    let n = u32::try_from(expected.len()).expect("fits");

    peer.set_nonblocking(true).unwrap();
    let mut header = [0u8; 32];
    peer.read_exact(&mut header)
        .expect("reply header delivered");
    assert_eq!(header[0], 1, "byte 0 must be 1 (Reply)");
    assert_eq!(u16::from_le_bytes([header[2], header[3]]), 7, "sequence");
    assert_eq!(
        u32::from_le_bytes([header[4], header[5], header[6], header[7]]),
        2 * n,
        "length must be 2 * numAttribs 4-byte units"
    );
    assert_eq!(
        u32::from_le_bytes([header[8], header[9], header[10], header[11]]),
        n,
        "numAttribs"
    );

    let mut pairs = vec![0u8; (2 * n) as usize * 4];
    peer.read_exact(&mut pairs)
        .expect("attribute pairs delivered");
    for (i, &(key, value)) in expected.iter().enumerate() {
        let got_key = u32::from_le_bytes([
            pairs[i * 8],
            pairs[i * 8 + 1],
            pairs[i * 8 + 2],
            pairs[i * 8 + 3],
        ]);
        let got_value = u32::from_le_bytes([
            pairs[i * 8 + 4],
            pairs[i * 8 + 5],
            pairs[i * 8 + 6],
            pairs[i * 8 + 7],
        ]);
        assert_eq!((got_key, got_value), (key, value), "pair {i}");
    }
}

#[test]
fn glx_vendor_names_query_answers_from_server_state() {
    use yserver_protocol::x11::glx as g;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    // The value the backend derived at startup, not the constant.
    state.glx_vendor_names = "nvidia mesa".to_string();

    // QueryServerString body: screen (u32), name (u32).
    let mut body = Vec::new();
    body.extend_from_slice(&0u32.to_le_bytes());
    body.extend_from_slice(&g::VENDOR_NAMES_EXT.to_le_bytes());
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("fits");

    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(9),
        RequestHeader {
            opcode: 148,
            data: g::QUERY_SERVER_STRING,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request QUERY_SERVER_STRING");

    peer.set_nonblocking(true).unwrap();
    let mut header = [0u8; 32];
    peer.read_exact(&mut header)
        .expect("reply header delivered");
    assert_eq!(header[0], 1, "byte 0 must be 1 (Reply)");
    assert_eq!(u16::from_le_bytes([header[2], header[3]]), 9, "sequence");

    // Reply layout, read off encode_string_reply (glx.rs:267-291):
    //   0      1 (Reply)      1      0 (pad)
    //   2..4   sequence       4..8   length_units = padded / 4
    //   8..12  pad1           12..16 n (string length INCLUDING NUL)
    //   16..32 pad3..pad6     then bytes + NUL + zero padding
    // Note n sits at 12, not 8 -- offset 8 is pad1. The
    // GetDrawableAttributes reply carries numAttribs at 8, which is a
    // different reply shape; do not copy that offset here.
    let n = u32::from_le_bytes([header[12], header[13], header[14], header[15]]);
    assert_eq!(n as usize, "nvidia mesa".len() + 1, "n counts the NUL");

    let padded = u32::from_le_bytes([header[4], header[5], header[6], header[7]]) as usize * 4;
    assert_eq!(padded, 12, "11 bytes + NUL, already 4-aligned");
    let mut tail = vec![0u8; padded];
    peer.read_exact(&mut tail).expect("reply tail delivered");
    let s = String::from_utf8_lossy(&tail);
    assert!(
        s.starts_with("nvidia mesa"),
        "arm must read state, not the VENDOR_NAMES constant; got {s:?}"
    );
}

/// Error arm 1: a naked X **pixmap** (resolvable as a drawable but not
/// a window, no GLX record) gets the extension error `GLXBadDrawable`
/// (`GLX_FIRST_ERROR + 2`) — GLXVND forwards pixmaps because they carry
/// RC_DRAWABLE, then `dixLookupWindow` fails (glxcmds.c:1873-1880).
#[test]
fn glx_get_drawable_attributes_naked_pixmap_returns_glx_bad_drawable() {
    use yserver_protocol::x11::glx as g;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    let pixmap_xid: u32 = 0x2000;
    state.resources.create_pixmap(
        client_id,
        CreatePixmapRequest {
            depth: 24,
            pixmap: ResourceId(pixmap_xid),
            drawable: ROOT_WINDOW,
            width: 64,
            height: 32,
        },
    );

    let body = pixmap_xid.to_le_bytes().to_vec();
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,
            data: g::GET_DRAWABLE_ATTRIBUTES,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request should not hard-error");

    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf)
        .expect("GLXBadDrawable error packet must be delivered");
    assert_eq!(buf[0], 0, "byte 0 must be 0 (Error class)");
    let expected_code =
        crate::nested::GLX_FIRST_ERROR + yserver_protocol::x11::glx::ERROR_GLX_BAD_DRAWABLE;
    assert_eq!(
        buf[1], expected_code,
        "expected GLXBadDrawable ({}), got {}",
        expected_code, buf[1]
    );
}

/// Error arm 2: an XID that is not a drawable at all gets **core
/// `BadDrawable` (9)** — GLXVND's XID-map lookup returns NULL and the
/// dispatch stub errors out before `DoGetDrawableAttributes` is ever
/// reached (glx/vnd_dispatch_stubs.c:456-472). The two error arms must
/// not be collapsed.
#[test]
fn glx_get_drawable_attributes_unknown_xid_returns_core_bad_drawable() {
    use yserver_protocol::x11::glx as g;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    let unknown_xid: u32 = 0x9999;
    let body = unknown_xid.to_le_bytes().to_vec();
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,
            data: g::GET_DRAWABLE_ATTRIBUTES,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request should not hard-error");

    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf)
        .expect("core BadDrawable error packet must be delivered");
    assert_eq!(buf[0], 0, "byte 0 must be 0 (Error class)");
    assert_eq!(
        buf[1],
        yserver_protocol::x11::error::BAD_DRAWABLE,
        "expected core BadDrawable (9), got {}",
        buf[1]
    );
    assert_eq!(
        u16::from_le_bytes([buf[8], buf[9]]),
        u16::from(g::GET_DRAWABLE_ATTRIBUTES),
        "error must identify GLX::GetDrawableAttributes as the minor opcode"
    );
    assert_eq!(
        buf[10],
        crate::nested::GLX_MAJOR_OPCODE,
        "error must identify GLX as the major opcode"
    );
}

/// Read the `contextTag` field (bytes 8..12) out of a 32-byte
/// `MakeCurrent` reply.
fn make_current_reply_tag(buf: &[u8; 32]) -> u32 {
    u32::from_le_bytes([buf[8], buf[9], buf[10], buf[11]])
}

/// Drive a `MakeCurrent`/`MakeContextCurrent` request and return the
/// 32-byte reply. `context` is placed at the minor-specific offset.
fn drive_make_current(minor: u8, context: u32) -> [u8; 32] {
    use yserver_protocol::x11::glx as g;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    // Layouts (glxproto.h:225-233, :471-481), body-relative:
    //   minor 5  MakeCurrent:         drawable, context, oldContextTag
    //   minor 26 MakeContextCurrent:  oldContextTag, drawable, readdrawable, context
    let mut body = Vec::new();
    if minor == g::MAKE_CURRENT {
        body.extend_from_slice(&0x2000u32.to_le_bytes()); // drawable
        body.extend_from_slice(&context.to_le_bytes()); // context
        body.extend_from_slice(&0u32.to_le_bytes()); // oldContextTag
    } else {
        body.extend_from_slice(&0u32.to_le_bytes()); // oldContextTag
        body.extend_from_slice(&0x2000u32.to_le_bytes()); // drawable
        body.extend_from_slice(&0x2000u32.to_le_bytes()); // readdrawable
        body.extend_from_slice(&context.to_le_bytes()); // context
    }
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,
            data: minor,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request MakeCurrent");

    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf)
        .expect("MakeCurrent reply delivered");
    assert_eq!(buf[0], 1, "byte 0 must be 1 (Reply)");
    buf
}

/// D6: the release form (`context == None`) must return
/// `contextTag = 0` — tag 0 is reserved by the protocol to mean "no
/// context current" (Xorg vndcmds.c:232-234, :271-273). Both minors.
#[test]
fn glx_make_current_release_returns_zero_tag() {
    use yserver_protocol::x11::glx as g;

    let buf = drive_make_current(g::MAKE_CURRENT, 0);
    assert_eq!(
        make_current_reply_tag(&buf),
        0,
        "MakeCurrent release must return contextTag = 0"
    );
}

#[test]
fn glx_make_context_current_release_returns_zero_tag() {
    use yserver_protocol::x11::glx as g;

    let buf = drive_make_current(g::MAKE_CONTEXT_CURRENT, 0);
    assert_eq!(
        make_current_reply_tag(&buf),
        0,
        "MakeContextCurrent release must return contextTag = 0"
    );
}

/// D6: a non-null context still gets a fresh non-zero tag, for both
/// minors (regression guard on the release fix).
#[test]
fn glx_make_current_non_null_context_returns_nonzero_tag() {
    use yserver_protocol::x11::glx as g;

    let buf = drive_make_current(g::MAKE_CURRENT, 0x3000);
    assert_ne!(
        make_current_reply_tag(&buf),
        0,
        "MakeCurrent with a context must return a non-zero tag"
    );
}

#[test]
fn glx_make_context_current_non_null_context_returns_nonzero_tag() {
    use yserver_protocol::x11::glx as g;

    let buf = drive_make_current(g::MAKE_CONTEXT_CURRENT, 0x3000);
    assert_ne!(
        make_current_reply_tag(&buf),
        0,
        "MakeContextCurrent with a context must return a non-zero tag"
    );
}

/// GLX Task 3.4 regression: the export ref must be released on
/// `glXDestroyPixmap` even when the client called X11 `FreePixmap` on
/// the underlying X pixmap FIRST (a common compositor ordering). The
/// release site must use the host_xid stored at acquire time, NOT a
/// re-resolution via `resources.pixmap(x_drawable)` (which is gone after
/// FreePixmap). Against the old re-resolving logic this test FAILS:
/// ReleaseGlxPixmapExport is never recorded → the export ref leaks.
#[test]
fn glx_destroy_releases_export_even_after_free_pixmap() {
    use crate::backend::recording::RecordedCall;
    use yserver_protocol::x11::glx as x11glx;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    // Register an X pixmap with a known host_xid.
    let x_pixmap_xid: u32 = 0x3000;
    let host_xid_raw: u32 = 0xdead_0002;
    state.resources.create_pixmap(
        client_id,
        yserver_protocol::x11::CreatePixmapRequest {
            depth: 24,
            pixmap: ResourceId(x_pixmap_xid),
            drawable: ROOT_WINDOW,
            width: 64,
            height: 32,
        },
    );
    assert!(state.resources.set_pixmap_host_xid(
        ResourceId(x_pixmap_xid),
        crate::backend::PixmapHandle::from_raw(host_xid_raw).unwrap(),
    ));

    let glx_xid: u32 = 0x4000_0003;

    // glXCreatePixmap — acquire.
    let mut create_body = Vec::new();
    create_body.extend_from_slice(&0u32.to_le_bytes()); // screen
    create_body.extend_from_slice(&0x101u32.to_le_bytes()); // fbconfig
    create_body.extend_from_slice(&x_pixmap_xid.to_le_bytes());
    create_body.extend_from_slice(&glx_xid.to_le_bytes());
    let length_units = u32::try_from(1 + create_body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,
            data: x11glx::CREATE_PIXMAP,
            length_units,
        },
        &create_body,
        None,
    )
    .expect("process_request CREATE_PIXMAP");
    assert!(
        backend
            .calls()
            .contains(&RecordedCall::AcquireGlxPixmapExport(host_xid_raw)),
        "AcquireGlxPixmapExport must be recorded"
    );

    // X11 FreePixmap on the underlying X pixmap BEFORE glXDestroyPixmap.
    // This removes the pixmap from the resource table — any subsequent
    // re-resolution of x_drawable→host_xid would fail.
    let free_body = x_pixmap_xid.to_le_bytes().to_vec();
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(2),
        RequestHeader {
            opcode: 54, // FreePixmap
            data: 0,
            length_units: 2,
        },
        &free_body,
        None,
    )
    .expect("process_request FreePixmap");
    // Sanity: the pixmap resource is really gone.
    assert!(
        state.resources.pixmap(ResourceId(x_pixmap_xid)).is_none(),
        "X pixmap must be freed by FreePixmap"
    );

    // glXDestroyPixmap — must still release using the stored host_xid.
    let destroy_body = glx_xid.to_le_bytes().to_vec();
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(3),
        RequestHeader {
            opcode: 148,
            data: x11glx::DESTROY_PIXMAP,
            length_units: 2,
        },
        &destroy_body,
        None,
    )
    .expect("process_request DESTROY_PIXMAP");

    assert!(
        !state.glx_drawables.contains_key(&glx_xid),
        "GlxDrawable must be removed after DestroyPixmap"
    );
    // THE REGRESSION ASSERTION: release must fire despite the early FreePixmap.
    assert!(
        backend
            .calls()
            .contains(&RecordedCall::ReleaseGlxPixmapExport(host_xid_raw)),
        "ReleaseGlxPixmapExport must be recorded even after the X pixmap was \
             freed before glXDestroyPixmap (no export-ref leak)"
    );
}

/// GLX Task 3.4: `glXCreatePixmap` with a non-existent X pixmap XID
/// must reply with a GLXBadPixmap error rather than silently inserting.
#[test]
fn glx_create_pixmap_with_missing_x_pixmap_returns_glx_bad_pixmap() {
    use yserver_protocol::x11::glx as x11glx;
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    // Use an XID that was never registered.
    let bad_x_pixmap_xid: u32 = 0x9999;
    let glx_xid: u32 = 0x4000_0002;

    let mut create_body = Vec::new();
    create_body.extend_from_slice(&0u32.to_le_bytes()); // screen
    create_body.extend_from_slice(&0x101u32.to_le_bytes()); // fbconfig
    create_body.extend_from_slice(&bad_x_pixmap_xid.to_le_bytes());
    create_body.extend_from_slice(&glx_xid.to_le_bytes());
    let length_units = u32::try_from(1 + create_body.len().div_ceil(4)).expect("fits");

    let outcome = process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,
            data: x11glx::CREATE_PIXMAP,
            length_units,
        },
        &create_body,
        None,
    )
    .expect("process_request should not hard-error");
    assert!(matches!(outcome, RequestOutcome::Handled));

    // Nothing inserted in glx_drawables.
    assert!(
        !state.glx_drawables.contains_key(&glx_xid),
        "GlxDrawable must NOT be inserted when X pixmap does not exist"
    );

    // Error packet must be delivered: GLXBadPixmap = GLX_FIRST_ERROR + 3 = 172.
    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    peer.read_exact(&mut buf)
        .expect("GLXBadPixmap error packet must be delivered");
    assert_eq!(buf[0], 0, "byte 0 must be 0 (Error class)");
    let expected_code =
        crate::nested::GLX_FIRST_ERROR + yserver_protocol::x11::glx::ERROR_GLX_BAD_PIXMAP;
    assert_eq!(
        buf[1], expected_code,
        "expected GLXBadPixmap ({}), got {}",
        expected_code, buf[1]
    );
}

/// GLX Task 3.5: `VendorPrivate` with vendor_code 1330 (`BindTexImageEXT`)
/// over a valid GLXPixmap must NOT be rejected with
/// `GLXUnsupportedPrivateRequest`; it must succeed (return `Handled`
/// with no error packet delivered to the client).
///
/// Secondary assertion: an unknown vendor code still gets
/// `GLXUnsupportedPrivateRequest` (preservation of the fallthrough).
#[test]
fn bind_tex_image_ext_is_dispatched_not_rejected() {
    use yserver_protocol::x11::glx as x11glx;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    // Register an X pixmap with a known host_xid — mirrors the
    // Task 3.4 test setup so we can get a GlxDrawable into state.
    let x_pixmap_xid: u32 = 0x2000;
    let host_xid_raw: u32 = 0xdead_1330;
    state.resources.create_pixmap(
        client_id,
        yserver_protocol::x11::CreatePixmapRequest {
            depth: 24,
            pixmap: yserver_protocol::x11::ResourceId(x_pixmap_xid),
            drawable: ROOT_WINDOW,
            width: 32,
            height: 32,
        },
    );
    assert!(
        state.resources.set_pixmap_host_xid(
            yserver_protocol::x11::ResourceId(x_pixmap_xid),
            crate::backend::PixmapHandle::from_raw(host_xid_raw).unwrap(),
        ),
        "set_pixmap_host_xid must succeed"
    );

    // First, call GLX::CreatePixmap to insert a GlxDrawable.
    let glx_xid: u32 = 0x4000_0002;
    let fbconfig: u32 = 0x101;
    let mut create_body = Vec::new();
    create_body.extend_from_slice(&0u32.to_le_bytes()); // screen = 0
    create_body.extend_from_slice(&fbconfig.to_le_bytes());
    create_body.extend_from_slice(&x_pixmap_xid.to_le_bytes());
    create_body.extend_from_slice(&glx_xid.to_le_bytes());
    let length_units = u32::try_from(1 + create_body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,
            data: x11glx::CREATE_PIXMAP,
            length_units,
        },
        &create_body,
        None,
    )
    .expect("process_request CREATE_PIXMAP");

    // Build a VendorPrivate body for BindTexImageEXT (1330):
    //   [vendor_code=1330][context_tag=0][glx_drawable=glx_xid][buffer=GLX_FRONT_LEFT_EXT]
    let mut bind_body = Vec::new();
    bind_body.extend_from_slice(&x11glx::VENDOR_CODE_BIND_TEX_IMAGE.to_le_bytes());
    bind_body.extend_from_slice(&0u32.to_le_bytes()); // context_tag
    bind_body.extend_from_slice(&glx_xid.to_le_bytes());
    bind_body.extend_from_slice(&x11glx::GLX_FRONT_LEFT_EXT.to_le_bytes());
    let length_units = u32::try_from(1 + bind_body.len().div_ceil(4)).expect("fits");
    let outcome = process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(2),
        RequestHeader {
            opcode: 148,
            data: x11glx::VENDOR_PRIVATE, // minor = 16
            length_units,
        },
        &bind_body,
        None,
    )
    .expect("process_request VENDOR_PRIVATE BindTexImageEXT must not hard-error");
    assert!(
        matches!(outcome, RequestOutcome::Handled),
        "BindTexImageEXT must return Handled, got {outcome:?}"
    );

    // No error packet must be delivered to the client.
    peer.set_nonblocking(true).unwrap();
    let mut buf = [0u8; 32];
    match peer.read(&mut buf) {
        Ok(0) | Err(_) => { /* no data written — correct */ }
        Ok(n) => {
            assert_ne!(
                buf[0], 0,
                "BindTexImageEXT must not deliver an X11 error packet; \
                     got {n} bytes, first byte={} (0=Error)",
                buf[0]
            );
        }
    }
    peer.set_nonblocking(false).unwrap();

    // The unsupported-private rejection must still fire for unknown codes.
    let mut unknown_body = Vec::new();
    unknown_body.extend_from_slice(&9999u32.to_le_bytes()); // unknown vendor code
    unknown_body.extend_from_slice(&0u32.to_le_bytes());
    unknown_body.extend_from_slice(&0u32.to_le_bytes());
    unknown_body.extend_from_slice(&0u32.to_le_bytes());
    let length_units = u32::try_from(1 + unknown_body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(3),
        RequestHeader {
            opcode: 148,
            data: x11glx::VENDOR_PRIVATE,
            length_units,
        },
        &unknown_body,
        None,
    )
    .expect("process_request VENDOR_PRIVATE unknown must not hard-error");

    // Error packet for the unknown vendor code.
    peer.set_nonblocking(true).unwrap();
    let mut buf2 = [0u8; 32];
    peer.read_exact(&mut buf2)
        .expect("GLXUnsupportedPrivateRequest error packet must be delivered");
    assert_eq!(buf2[0], 0, "byte 0 must be 0 (Error class)");
    let expected_unsupported = crate::nested::GLX_FIRST_ERROR
        + yserver_protocol::x11::glx::ERROR_GLX_UNSUPPORTED_PRIVATE_REQUEST;
    assert_eq!(
        buf2[1], expected_unsupported,
        "expected GLXUnsupportedPrivateRequest ({expected_unsupported}), got {}",
        buf2[1]
    );
    peer.set_nonblocking(false).unwrap();
}

/// GLX Task 3.5 regression (codex review): `BindTexImageEXT` /
/// `ReleaseTexImageEXT` must be DECOUPLED from the GLXPixmap LIFETIME
/// refcount (`glx_refs`).
///
/// Bind uses the promote-only hook (`promote_pixmap_exportable`),
/// idempotently, taking NO lifetime ref — so repeated rebinds (the
/// normal TFP per-frame pattern) do not grow `glx_refs` and leak the
/// backing. Release is a lifetime no-op — it must NOT call
/// `release_glx_pixmap_export`, or a release without a matching bind
/// would tear the backing down while the GLXPixmap is still alive.
///
/// Against the OLD acquire/release-based logic this test FAILS: the
/// three binds would record three `AcquireGlxPixmapExport` (and no
/// `PromotePixmapExportable`), and the release would record a
/// `ReleaseGlxPixmapExport`.
#[test]
fn bind_release_tex_image_do_not_touch_lifetime_refcount() {
    use crate::backend::recording::RecordedCall;
    use yserver_protocol::x11::glx as x11glx;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    // Register an X pixmap with a known host_xid.
    let x_pixmap_xid: u32 = 0x2100;
    let host_xid_raw: u32 = 0xdead_1331;
    state.resources.create_pixmap(
        client_id,
        yserver_protocol::x11::CreatePixmapRequest {
            depth: 24,
            pixmap: yserver_protocol::x11::ResourceId(x_pixmap_xid),
            drawable: ROOT_WINDOW,
            width: 32,
            height: 32,
        },
    );
    assert!(
        state.resources.set_pixmap_host_xid(
            yserver_protocol::x11::ResourceId(x_pixmap_xid),
            crate::backend::PixmapHandle::from_raw(host_xid_raw).unwrap(),
        ),
        "set_pixmap_host_xid must succeed"
    );

    // glXCreatePixmap inserts the GlxDrawable and takes the ONE lifetime
    // acquire ref (this is the legitimate AcquireGlxPixmapExport).
    let glx_xid: u32 = 0x4000_0003;
    let mut create_body = Vec::new();
    create_body.extend_from_slice(&0u32.to_le_bytes()); // screen
    create_body.extend_from_slice(&0x101u32.to_le_bytes()); // fbconfig
    create_body.extend_from_slice(&x_pixmap_xid.to_le_bytes());
    create_body.extend_from_slice(&glx_xid.to_le_bytes());
    let length_units = u32::try_from(1 + create_body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,
            data: x11glx::CREATE_PIXMAP,
            length_units,
        },
        &create_body,
        None,
    )
    .expect("process_request CREATE_PIXMAP");

    // Exactly one acquire (the lifetime ref) so far; no promote yet.
    let after_create = backend.calls();
    assert_eq!(
        after_create
            .iter()
            .filter(|c| matches!(c, RecordedCall::AcquireGlxPixmapExport(_)))
            .count(),
        1,
        "glXCreatePixmap must take exactly one lifetime acquire ref"
    );
    let acquires_before_binds = after_create
        .iter()
        .filter(|c| matches!(c, RecordedCall::AcquireGlxPixmapExport(_)))
        .count();
    let releases_before_binds = after_create
        .iter()
        .filter(|c| matches!(c, RecordedCall::ReleaseGlxPixmapExport(_)))
        .count();

    // Build a BindTexImageEXT VendorPrivate body.
    let mut bind_body = Vec::new();
    bind_body.extend_from_slice(&x11glx::VENDOR_CODE_BIND_TEX_IMAGE.to_le_bytes());
    bind_body.extend_from_slice(&0u32.to_le_bytes()); // context_tag
    bind_body.extend_from_slice(&glx_xid.to_le_bytes());
    bind_body.extend_from_slice(&x11glx::GLX_FRONT_LEFT_EXT.to_le_bytes());
    let bind_units = u32::try_from(1 + bind_body.len().div_ceil(4)).expect("fits");

    // Bind THREE times (compositor per-frame / implicit-rebind pattern).
    for seq in 2u16..=4 {
        process_request(
            &mut state,
            &mut backend,
            client_id,
            SequenceNumber(seq),
            RequestHeader {
                opcode: 148,
                data: x11glx::VENDOR_PRIVATE,
                length_units: bind_units,
            },
            &bind_body,
            None,
        )
        .expect("process_request BindTexImageEXT");
    }

    let after_binds = backend.calls();
    // Each bind recorded a PromotePixmapExportable (the lightweight hook).
    assert_eq!(
        after_binds
            .iter()
            .filter(|c| matches!(
                c,
                RecordedCall::PromotePixmapExportable(h) if *h == host_xid_raw
            ))
            .count(),
        3,
        "each BindTexImageEXT must record PromotePixmapExportable, not Acquire"
    );
    // The binds must NOT have taken any extra lifetime ref.
    assert_eq!(
        after_binds
            .iter()
            .filter(|c| matches!(c, RecordedCall::AcquireGlxPixmapExport(_)))
            .count(),
        acquires_before_binds,
        "BindTexImageEXT must NOT take a lifetime acquire ref (no leak on rebind)"
    );
    assert_eq!(
        after_binds
            .iter()
            .filter(|c| matches!(c, RecordedCall::ReleaseGlxPixmapExport(_)))
            .count(),
        releases_before_binds,
        "BindTexImageEXT must NOT change the lifetime release count"
    );

    // Now ReleaseTexImageEXT — must be a lifetime no-op.
    let mut rel_body = Vec::new();
    rel_body.extend_from_slice(&x11glx::VENDOR_CODE_RELEASE_TEX_IMAGE.to_le_bytes());
    rel_body.extend_from_slice(&0u32.to_le_bytes()); // context_tag
    rel_body.extend_from_slice(&glx_xid.to_le_bytes());
    rel_body.extend_from_slice(&x11glx::GLX_FRONT_LEFT_EXT.to_le_bytes());
    let rel_units = u32::try_from(1 + rel_body.len().div_ceil(4)).expect("fits");
    process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(5),
        RequestHeader {
            opcode: 148,
            data: x11glx::VENDOR_PRIVATE,
            length_units: rel_units,
        },
        &rel_body,
        None,
    )
    .expect("process_request ReleaseTexImageEXT");

    // THE REGRESSION ASSERTION: release must NOT have dropped the
    // lifetime ref — the backing survives until glXDestroyPixmap.
    let after_release = backend.calls();
    assert_eq!(
        after_release
            .iter()
            .filter(|c| matches!(c, RecordedCall::ReleaseGlxPixmapExport(_)))
            .count(),
        releases_before_binds,
        "ReleaseTexImageEXT must NOT call release_glx_pixmap_export \
             (lifetime ref untouched; backing survives until glXDestroyPixmap)"
    );
}

// ── RENDER::CreateAnimCursor (opcode 133 / minor 31) helpers ─────────────

fn anim_cursor_body(cid: u32, elts: &[(u32, u32)]) -> Vec<u8> {
    let mut b = cid.to_le_bytes().to_vec();
    for (cur, delay) in elts {
        b.extend_from_slice(&cur.to_le_bytes());
        b.extend_from_slice(&delay.to_le_bytes());
    }
    b
}

fn seed_cursor(state: &mut ServerState, raw: u32, host: u32) {
    state.resources.create_cursor(ClientId(1), ResourceId(raw));
    state.resources.set_cursor_host_xid(
        ResourceId(raw),
        crate::backend::CursorHandle::from_raw(host).unwrap(),
    );
}

fn send_anim_cursor(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    seq: u16,
    body: &[u8],
) {
    process_request(
        state,
        backend,
        ClientId(1),
        SequenceNumber(seq),
        RequestHeader {
            opcode: 133,
            data: 31,
            length_units: u32::try_from(1 + body.len().div_ceil(4)).unwrap(),
        },
        body,
        None,
    )
    .expect("process_request");
}

#[test]
fn create_anim_cursor_empty_list_returns_bad_value() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let body = anim_cursor_body(0x4000, &[]);
    send_anim_cursor(&mut state, &mut backend, 1, &body);
    let bytes = read_all_available(&mut peer);
    assert!(bytes.len() >= 32, "expected error reply, got {bytes:02x?}");
    assert_eq!(bytes[1], x11::error::BAD_VALUE);
    assert_eq!(&bytes[8..10], &31u16.to_le_bytes());
    assert_eq!(bytes[10], 133);
    assert!(!state.resources.cursor_exists(ResourceId(0x4000)));
}

#[test]
fn create_anim_cursor_odd_pairs_returns_bad_length() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    seed_cursor(&mut state, 0x3000, 0x77);
    // One full pair + 4 trailing bytes = not a multiple of 8.
    let mut body = anim_cursor_body(0x4000, &[(0x3000, 50)]);
    body.extend_from_slice(&0x3000u32.to_le_bytes());
    send_anim_cursor(&mut state, &mut backend, 1, &body);
    let bytes = read_all_available(&mut peer);
    assert!(bytes.len() >= 32);
    assert_eq!(bytes[1], x11::error::BAD_LENGTH);
    assert_eq!(&bytes[8..10], &31u16.to_le_bytes());
    assert_eq!(bytes[10], 133);
    assert!(!state.resources.cursor_exists(ResourceId(0x4000)));
}

#[test]
fn create_anim_cursor_nested_anim_returns_bad_match() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    seed_cursor(&mut state, 0x3000, 0x77);
    // First anim cursor (fallback path on RecordingBackend).
    let body = anim_cursor_body(0x4000, &[(0x3000, 50)]);
    send_anim_cursor(&mut state, &mut backend, 1, &body);
    let _ = read_all_available(&mut peer); // no error expected
    assert!(state.resources.cursor_is_anim(ResourceId(0x4000)));
    // Second anim cursor referencing the first → BadMatch.
    let body2 = anim_cursor_body(0x4001, &[(0x4000, 50)]);
    send_anim_cursor(&mut state, &mut backend, 2, &body2);
    let bytes = read_all_available(&mut peer);
    assert!(bytes.len() >= 32);
    assert_eq!(bytes[1], x11::error::BAD_MATCH);
    // Xorg's AnimCursorCreate returns BadMatch without setting
    // client->errorValue → value field must be zero.
    assert_eq!(&bytes[4..8], &0u32.to_le_bytes());
    assert_eq!(&bytes[8..10], &31u16.to_le_bytes());
    assert_eq!(bytes[10], 133);
    assert!(!state.resources.cursor_exists(ResourceId(0x4001)));
}

#[test]
fn create_anim_cursor_fallback_aliases_first_frame_and_sets_anim() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    seed_cursor(&mut state, 0x3000, 0x77);
    seed_cursor(&mut state, 0x3001, 0x78);
    let body = anim_cursor_body(0x4000, &[(0x3000, 50), (0x3001, 75)]);
    send_anim_cursor(&mut state, &mut backend, 1, &body);
    let bytes = read_all_available(&mut peer);
    assert!(bytes.is_empty(), "no error expected, got {bytes:02x?}");
    assert_eq!(
        state.resources.cursor_host_xid(ResourceId(0x4000)),
        Some(0x77)
    );
    assert!(state.resources.cursor_is_anim(ResourceId(0x4000)));
}

// ── GLX_SGIX_fbconfig dispatch tests ─────────────────────────────────────

/// Build a VendorPrivateWithReply body for `GetFBConfigsSGIX` (vendor
/// code 65540):
///   [0..4]  vendorCode
///   [4..8]  pad1 = 0
///   [8..12] screen = 0
fn build_get_fb_configs_sgix_body(screen: u32) -> Vec<u8> {
    use yserver_protocol::x11::glx as x11glx;
    let mut body = Vec::new();
    body.extend_from_slice(&x11glx::VENDOR_CODE_GET_FB_CONFIGS_SGIX.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // pad1
    body.extend_from_slice(&screen.to_le_bytes());
    body
}

/// `VendorPrivateWithReply` with vendor_code `GetFBConfigsSGIX` (65540)
/// must NOT be rejected with `GLXUnsupportedPrivateRequest`; it must
/// return a non-empty GetFBConfigs reply (real configs, not a stub).
#[test]
fn get_fb_configs_sgix_is_dispatched_not_rejected() {
    use yserver_protocol::x11::glx as x11glx;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    let body = build_get_fb_configs_sgix_body(0);
    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("fits");

    let outcome = process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,
            data: x11glx::VENDOR_PRIVATE_WITH_REPLY,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request must not hard-error");

    assert!(
        matches!(outcome, RequestOutcome::Handled),
        "GetFBConfigsSGIX must return Handled, got {outcome:?}"
    );

    // Must NOT deliver an error packet.
    peer.set_nonblocking(true).unwrap();
    let bytes = read_all_available(&mut peer);
    assert!(
        !bytes.is_empty(),
        "GetFBConfigsSGIX must deliver a reply packet"
    );
    assert_ne!(
        bytes[0], 0,
        "byte 0 must not be 0 (Error); got {bytes:02x?}"
    );
    // byte 0 = 1 (Reply), byte 8..12 = num_FB_configs > 0.
    assert_eq!(bytes[0], 1, "byte 0 must be Reply type");
    let num_configs = u32::from_le_bytes(bytes[8..12].try_into().unwrap());
    assert!(
        num_configs > 0,
        "GetFBConfigsSGIX must return at least one FBConfig, got {num_configs}"
    );
    peer.set_nonblocking(false).unwrap();
}

/// `VendorPrivate` with vendor_code `CreateContextWithConfigSGIX`
/// (65541) must insert a `GlxContext` entry (no reply, no error).
#[test]
fn create_context_with_config_sgix_inserts_context() {
    use yserver_protocol::x11::glx as x11glx;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    let context_xid: u32 = 0xABCD_0001;
    let fbconfig: u32 = 0x101;

    // Build CreateContextWithConfigSGIX body:
    //   [0..4]  vendorCode = 65541
    //   [4..8]  pad1 = 0
    //   [8..12] context = context_xid
    //   [12..16] fbconfig = 0x101
    //   [16..20] screen = 0
    //   [20..24] renderType = 1
    //   [24..28] shareList = 0
    //   [28] isDirect = 1
    //   [29..32] reserved = 0
    let mut body = Vec::new();
    body.extend_from_slice(&x11glx::VENDOR_CODE_CREATE_CONTEXT_WITH_CONFIG_SGIX.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // pad1
    body.extend_from_slice(&context_xid.to_le_bytes());
    body.extend_from_slice(&fbconfig.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // screen
    body.extend_from_slice(&1u32.to_le_bytes()); // renderType
    body.extend_from_slice(&0u32.to_le_bytes()); // shareList
    body.push(1u8); // isDirect
    body.push(0u8); // reserved1
    body.extend_from_slice(&0u16.to_le_bytes()); // reserved2

    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("fits");

    let outcome = process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,
            data: x11glx::VENDOR_PRIVATE,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request must not hard-error");

    assert!(
        matches!(outcome, RequestOutcome::Handled),
        "CreateContextWithConfigSGIX must return Handled, got {outcome:?}"
    );

    // GlxContext must be inserted.
    assert!(
        state.glx_contexts.contains_key(&context_xid),
        "GlxContext must be inserted for xid=0x{context_xid:x}"
    );
    let ctx = &state.glx_contexts[&context_xid];
    assert_eq!(ctx.fbconfig, fbconfig, "fbconfig must be recorded");

    // No error packet.
    peer.set_nonblocking(true).unwrap();
    let bytes = read_all_available(&mut peer);
    assert!(
        bytes.is_empty(),
        "CreateContextWithConfigSGIX must not deliver an error; got {bytes:02x?}"
    );
    peer.set_nonblocking(false).unwrap();
}

/// `VendorPrivate` with vendor_code `CreateGLXPixmapWithConfigSGIX`
/// (65542) must insert a `GlxDrawable` entry and call
/// `acquire_glx_pixmap_export` — same semantics as `CREATE_PIXMAP`.
#[test]
fn create_glx_pixmap_with_config_sgix_inserts_drawable_and_acquires() {
    use crate::backend::recording::RecordedCall;
    use yserver_protocol::x11::glx as x11glx;

    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let client_id = ClientId(1);

    // Register an X pixmap with a known host_xid.
    let x_pixmap_xid: u32 = 0x3000;
    let host_xid_raw: u32 = 0xdead_5542;
    state.resources.create_pixmap(
        client_id,
        yserver_protocol::x11::CreatePixmapRequest {
            depth: 24,
            pixmap: yserver_protocol::x11::ResourceId(x_pixmap_xid),
            drawable: ROOT_WINDOW,
            width: 64,
            height: 64,
        },
    );
    assert!(
        state.resources.set_pixmap_host_xid(
            yserver_protocol::x11::ResourceId(x_pixmap_xid),
            crate::backend::PixmapHandle::from_raw(host_xid_raw).unwrap(),
        ),
        "set_pixmap_host_xid must succeed"
    );

    let glx_xid: u32 = 0x5000_0010;
    let fbconfig: u32 = 0x101;

    // Build CreateGLXPixmapWithConfigSGIX body:
    //   [0..4]  vendorCode = 65542
    //   [4..8]  pad1 = 0
    //   [8..12]  screen = 0
    //   [12..16] fbconfig = 0x101
    //   [16..20] pixmap = x_pixmap_xid
    //   [20..24] glxpixmap = glx_xid
    let mut body = Vec::new();
    body.extend_from_slice(&x11glx::VENDOR_CODE_CREATE_GLX_PIXMAP_WITH_CONFIG_SGIX.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes()); // pad1
    body.extend_from_slice(&0u32.to_le_bytes()); // screen
    body.extend_from_slice(&fbconfig.to_le_bytes());
    body.extend_from_slice(&x_pixmap_xid.to_le_bytes());
    body.extend_from_slice(&glx_xid.to_le_bytes());

    let length_units = u32::try_from(1 + body.len().div_ceil(4)).expect("fits");

    let outcome = process_request(
        &mut state,
        &mut backend,
        client_id,
        SequenceNumber(1),
        RequestHeader {
            opcode: 148,
            data: x11glx::VENDOR_PRIVATE,
            length_units,
        },
        &body,
        None,
    )
    .expect("process_request must not hard-error");

    assert!(
        matches!(outcome, RequestOutcome::Handled),
        "CreateGLXPixmapWithConfigSGIX must return Handled, got {outcome:?}"
    );

    // GlxDrawable must be inserted.
    assert!(
        state.glx_drawables.contains_key(&glx_xid),
        "GlxDrawable must be inserted for glx_xid=0x{glx_xid:x}"
    );
    let drawable = &state.glx_drawables[&glx_xid];
    assert_eq!(drawable.x_drawable, x_pixmap_xid, "x_drawable must be set");
    assert_eq!(drawable.fbconfig, fbconfig, "fbconfig must be recorded");
    assert_eq!(
        drawable.glx_export_host_xid,
        Some(host_xid_raw),
        "host_xid must be stored for later release"
    );

    // acquire_glx_pixmap_export must have been called (same as CREATE_PIXMAP).
    assert!(
        backend
            .calls()
            .contains(&RecordedCall::AcquireGlxPixmapExport(host_xid_raw)),
        "AcquireGlxPixmapExport must be recorded"
    );

    // No error packet.
    peer.set_nonblocking(true).unwrap();
    let bytes = read_all_available(&mut peer);
    assert!(
        bytes.is_empty(),
        "CreateGLXPixmapWithConfigSGIX must not deliver an error; got {bytes:02x?}"
    );
    peer.set_nonblocking(false).unwrap();
}

/// After both dispatch and extension-string advertisement are live,
/// the computed GLX extension string must advertise
/// `GLX_SGIX_fbconfig` as a whole token, under both TFP settings.
///
/// This test used to re-implement `glx_extension_string`'s body and
/// assert against its own copy, so it would have passed even if the
/// builder were deleted. It calls the real function now.
#[test]
fn glx_extension_string_contains_sgix_fbconfig() {
    use yserver_protocol::x11::glx as x11glx;
    for tfp_supported in [false, true] {
        let s = glx_extension_string(tfp_supported);
        assert!(
            s.split_whitespace()
                .any(|token| token == x11glx::SGIX_FBCONFIG_EXTENSION),
            "glx_extension_string must advertise GLX_SGIX_fbconfig as a \
                 whole token; tfp_supported={tfp_supported} produced {s:?}"
        );
    }
}

// NOTE: the 3rd argument is the SEQUENCE number, not a client id —
// every request in these tests comes from ClientId(1).
fn send_xcmisc(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    seq: u16,
    minor: u8,
    body: &[u8],
) {
    process_request(
        state,
        backend,
        ClientId(1),
        SequenceNumber(seq),
        RequestHeader {
            opcode: 152,
            data: minor,
            length_units: u32::try_from(1 + body.len().div_ceil(4)).unwrap(),
        },
        body,
        None,
    )
    .expect("process_request");
}

#[test]
fn xcmisc_get_version_replies_1_1() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    // GetVersion body: client major(2), minor(2) — values ignored.
    let body = [0u8, 0, 0, 0];
    send_xcmisc(&mut state, &mut backend, 1, 0, &body);
    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes.len(), 32, "fixed 32-byte reply, got {bytes:02x?}");
    assert_eq!(bytes[0], 1, "X_Reply");
    assert_eq!(&bytes[2..4], &1u16.to_le_bytes(), "sequence");
    assert_eq!(&bytes[8..10], &1u16.to_le_bytes(), "major=1");
    assert_eq!(&bytes[10..12], &1u16.to_le_bytes(), "minor=1");
}

#[test]
fn xcmisc_bad_length_and_unknown_minor() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    // GetVersion with wrong body size → BadLength.
    send_xcmisc(&mut state, &mut backend, 1, 0, &[0u8; 8]);
    let bytes = read_all_available(&mut peer);
    assert!(bytes.len() >= 32);
    assert_eq!(bytes[1], x11::error::BAD_LENGTH);
    assert_eq!(bytes[10], 152, "major opcode");
    assert_eq!(&bytes[8..10], &0u16.to_le_bytes(), "minor 0 echoed");
    // Unknown minor 3 → BadRequest (Xorg dispatcher default).
    send_xcmisc(&mut state, &mut backend, 2, 3, &[]);
    let bytes = read_all_available(&mut peer);
    assert!(bytes.len() >= 32);
    assert_eq!(bytes[1], x11::error::BAD_REQUEST);
    assert_eq!(&bytes[8..10], &3u16.to_le_bytes(), "minor 3 echoed");
}

#[test]
fn xcmisc_advertised_in_query_and_list_extensions() {
    // QueryExtension "XC-MISC" → present with major 152; covered via
    // extension_query_reply + advertised_extension_names directly
    // (cheaper than wire round-trips; they are what the handlers use).
    let mut backend = RecordingBackend::new();
    let reply = extension_query_reply("XC-MISC", &mut backend);
    assert_eq!(reply, Some((152, 0, 0)));
    assert!(advertised_extension_names(&mut backend).contains(&"XC-MISC"));
}

#[test]
fn xcmisc_get_xid_range_skips_used_ids() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    // Give the test client a realistic base/mask (install_client
    // defaults to base=0, mask=u32::MAX).
    {
        let c = state.clients.get_mut(&1).unwrap();
        c.resource_id_base = 0x0010_0000;
        c.resource_id_mask = 0x000F_FFFF;
    }
    // Occupy the low end of the range.
    for i in 0..4u32 {
        state
            .resources
            .create_cursor(ClientId(1), ResourceId(0x0010_0000 + i));
    }
    send_xcmisc(&mut state, &mut backend, 1, 1, &[]);
    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes.len(), 32);
    assert_eq!(bytes[0], 1);
    let start = u32::from_le_bytes(bytes[8..12].try_into().unwrap());
    let count = u32::from_le_bytes(bytes[12..16].try_into().unwrap());
    assert_eq!(start, 0x0010_0004, "range starts after the used prefix");
    assert_eq!(count, 0x000F_FFFF - 4 + 1);
    // Wrong length → BadLength.
    send_xcmisc(&mut state, &mut backend, 2, 1, &[0u8; 4]);
    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes[1], x11::error::BAD_LENGTH);
}

#[test]
fn xcmisc_get_xid_list_returns_free_ids() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    {
        let c = state.clients.get_mut(&1).unwrap();
        c.resource_id_base = 0x0010_0000;
        c.resource_id_mask = 0x000F_FFFF;
    }
    // Occupy ids 0,2 in the range; ask for 4 ids.
    state
        .resources
        .create_cursor(ClientId(1), ResourceId(0x0010_0000));
    state
        .resources
        .create_cursor(ClientId(1), ResourceId(0x0010_0002));
    send_xcmisc(&mut state, &mut backend, 1, 2, &4u32.to_le_bytes());
    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes.len(), 32 + 16, "32 header + 4 ids");
    let count = u32::from_le_bytes(bytes[8..12].try_into().unwrap());
    assert_eq!(count, 4);
    let length = u32::from_le_bytes(bytes[4..8].try_into().unwrap());
    assert_eq!(length, 4, "reply length in words = id count");
    let ids: Vec<u32> = bytes[32..]
        .chunks_exact(4)
        .map(|c| u32::from_le_bytes(c.try_into().unwrap()))
        .collect();
    assert_eq!(
        ids,
        vec![0x0010_0001, 0x0010_0003, 0x0010_0004, 0x0010_0005],
        "skips occupied 0x...0 and 0x...2"
    );
    // Huge count is clamped to the RANGE size, not allocated. Shrink
    // the client's range first so the reply stays ~1 KiB — a 1M-id
    // reply would block the test's unread socketpair (write_or_buffer
    // does a synchronous write; OUTBOUND_CAP would trip the
    // disconnect path).
    state.clients.get_mut(&1).unwrap().resource_id_mask = 0xFF;
    send_xcmisc(&mut state, &mut backend, 2, 2, &u32::MAX.to_le_bytes());
    let bytes = read_all_available(&mut peer);
    let count = u32::from_le_bytes(bytes[8..12].try_into().unwrap());
    assert_eq!(count, 0x100 - 2, "256-id range minus 2 occupied");
    // BadLength on wrong size.
    send_xcmisc(&mut state, &mut backend, 3, 2, &[]);
    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes[1], x11::error::BAD_LENGTH);
}

/// `RRSetScreenSize` with the cursor stranded off the shrunken screen
/// must trigger a `warp_pointer_root` call that clamps it inside.
/// Also verifies the basic success path and per-dimension errorValue.
#[test]
fn screen_shrink_warps_stranded_cursor_inside() {
    use crate::randr::{RandrOutput, RandrState};

    const CLIENT_ID: u32 = 1;
    // One enabled 1920×1080 output at (0,0).
    let outputs = vec![RandrOutput {
        name: "eDP-1".into(),
        output_id: 1,
        crtc_id: 2,
        mode_id: 3,
        connected: true,
        x: 0,
        y: 0,
        width: 1920,
        height: 1080,
        vrefresh: 60,
        timing: None,
        mm_width: 0,
        mm_height: 0,
        mode_ids: vec![3],
        num_preferred: 1,
        pending_transform: Default::default(),
        current_transform: Default::default(),
        rotation: crate::randr::RR_ROTATE_0,
    }];
    let mut state = ServerState::new();
    state.randr = RandrState::from_outputs(0, outputs);
    // Park the cursor at (2000, 1500) — valid under the old larger screen.
    state.pointer_root = (2000, 1500);
    let mut backend = RecordingBackend::new();
    let _peer = install_client(&mut state, CLIENT_ID);

    // Build a SetScreenSize body: window(4) width(2) height(2)
    // mm_width(4) mm_height(4).
    fn build_body(width: u16, height: u16, mm_w: u32, mm_h: u32) -> Vec<u8> {
        let mut b = Vec::with_capacity(16);
        b.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
        b.extend_from_slice(&width.to_le_bytes());
        b.extend_from_slice(&height.to_le_bytes());
        b.extend_from_slice(&mm_w.to_le_bytes());
        b.extend_from_slice(&mm_h.to_le_bytes());
        b
    }

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 128, // RANDR major opcode
        data: yserver_protocol::x11::randr::RR_SET_SCREEN_SIZE,
        length_units: 5,
    };

    // Shrink to 1920×1080 (same as output — no crop) with real mm values.
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &build_body(1920, 1080, 527, 296),
    )
    .expect("valid shrink");

    // RRSetScreenSize is void — no reply on the wire.
    // The cursor at (2000, 1500) is outside 1920×1080, so a warp must fire.
    assert_eq!(
        backend.warped_to,
        Some((1919, 1079)),
        "cursor must be warped to (w-1, h-1) when stranded off-screen"
    );
    // RandrState must reflect the new logical size.
    assert_eq!(state.randr.screen_width, 1920);
    assert_eq!(state.randr.screen_height, 1080);
    assert_eq!(state.randr.width_mm, 527, "mm verbatim from client");
    assert_eq!(state.randr.height_mm, 296, "mm verbatim from client");
}

/// A compositor that renders through the Composite Overlay Window
/// typically backs it with DRI3/Present buffers. `RRSetScreenSize`
/// resizes the root and COW outside the normal `ConfigureWindow` path,
/// so it must still emit both core ConfigureNotify and
/// Present::ConfigureNotify for the materialized COW. Otherwise the
/// compositor can keep presenting its old smaller swap buffers after a
/// shrink-grow cycle, leaving the desktop in the upper-left corner while
/// input/RandR already use the full screen.
#[test]
fn screen_resize_notifies_materialized_cow_present_subscriber() {
    use crate::{
        backend::WindowHandle,
        randr::{RandrOutput, RandrState},
        resources::COMPOSITE_OVERLAY_WINDOW,
        server::PresentEventSelection,
    };
    use yserver_protocol::x11::present as x11present;

    const CLIENT_ID: u32 = 1;
    const PRESENT_EID: u32 = 0x0010_0042;

    let outputs = vec![RandrOutput {
        name: "DP-4".into(),
        output_id: 1,
        crtc_id: 2,
        mode_id: 3,
        connected: true,
        x: 0,
        y: 0,
        width: 1680,
        height: 1050,
        vrefresh: 100,
        timing: None,
        mm_width: 0,
        mm_height: 0,
        mode_ids: vec![3],
        num_preferred: 1,
        pending_transform: Default::default(),
        current_transform: Default::default(),
        rotation: crate::randr::RR_ROTATE_0,
    }];
    let mut state = ServerState::new();
    state.randr = RandrState::from_outputs(0, outputs);
    let mut peer = install_client(&mut state, CLIENT_ID);
    let mut backend = RecordingBackend::new();

    state
        .resources
        .materialize_cow_resource(WindowHandle::from_raw_for_test(COMPOSITE_OVERLAY_WINDOW.0));
    state
        .clients
        .get_mut(&CLIENT_ID)
        .unwrap()
        .event_masks
        .insert(COMPOSITE_OVERLAY_WINDOW, 0x0002_0000);
    state.present_event_selections.insert(
        PRESENT_EID,
        PresentEventSelection {
            owner: ClientId(CLIENT_ID),
            window: COMPOSITE_OVERLAY_WINDOW,
            event_mask: x11present::EVENT_MASK_CONFIGURE_NOTIFY,
        },
    );
    assert_eq!(
        crate::core_loop::fanout::subscribers_by_id(&state, COMPOSITE_OVERLAY_WINDOW, 0x0002_0000,),
        vec![ClientId(CLIENT_ID)],
        "COW StructureNotify subscription visible before resize",
    );
    assert_eq!(
        state
            .present_event_selections
            .get(&PRESENT_EID)
            .unwrap()
            .window,
        COMPOSITE_OVERLAY_WINDOW,
        "Present Configure subscription visible before resize",
    );

    let mut body = Vec::with_capacity(16);
    body.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
    body.extend_from_slice(&3440u16.to_le_bytes());
    body.extend_from_slice(&1440u16.to_le_bytes());
    body.extend_from_slice(&910u32.to_le_bytes());
    body.extend_from_slice(&381u32.to_le_bytes());

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 128,
        data: yserver_protocol::x11::randr::RR_SET_SCREEN_SIZE,
        length_units: 5,
    };
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("RRSetScreenSize grow");

    assert_eq!(state.randr.screen_width, 3440, "RandR width updated");
    assert_eq!(state.randr.screen_height, 1440, "RandR height updated");
    let cow = state
        .resources
        .window(COMPOSITE_OVERLAY_WINDOW)
        .expect("COW still materialized");
    assert_eq!(cow.width, 3440, "COW width updated");
    assert_eq!(cow.height, 1440, "COW height updated");
    assert_eq!(
        crate::core_loop::fanout::subscribers_by_id(&state, COMPOSITE_OVERLAY_WINDOW, 0x0002_0000,),
        vec![ClientId(CLIENT_ID)],
        "COW StructureNotify subscription still visible after resize",
    );
    assert_eq!(
        state
            .present_event_selections
            .get(&PRESENT_EID)
            .unwrap()
            .window,
        COMPOSITE_OVERLAY_WINDOW,
        "Present Configure subscription still visible after resize",
    );
    assert_eq!(
        state.clients.get(&CLIENT_ID).unwrap().outbound.len(),
        0,
        "small COW resize notifications should not be stuck in outbound",
    );

    let bytes = read_all_available(&mut peer);
    assert_eq!(
        bytes.len(),
        32 + 40,
        "COW subscriber should receive core ConfigureNotify plus \
             Present::ConfigureNotify only; got {bytes:?}",
    );

    let core = &bytes[..32];
    assert_eq!(core[0] & 0x7f, 22, "first event must be ConfigureNotify");
    assert_eq!(
        u32::from_le_bytes(core[4..8].try_into().unwrap()),
        COMPOSITE_OVERLAY_WINDOW.0,
        "ConfigureNotify event window must be COW",
    );
    assert_eq!(
        u32::from_le_bytes(core[8..12].try_into().unwrap()),
        COMPOSITE_OVERLAY_WINDOW.0,
        "ConfigureNotify target window must be COW",
    );
    assert_eq!(u16::from_le_bytes(core[20..22].try_into().unwrap()), 3440);
    assert_eq!(u16::from_le_bytes(core[22..24].try_into().unwrap()), 1440);

    let present = &bytes[32..];
    assert_eq!(present[0], 35, "second event must be GenericEvent");
    assert_eq!(present[1], 145, "GenericEvent extension must be PRESENT");
    assert_eq!(
        u16::from_le_bytes(present[8..10].try_into().unwrap()),
        u16::from(x11present::EVENT_CONFIGURE_NOTIFY),
    );
    assert_eq!(
        u32::from_le_bytes(present[12..16].try_into().unwrap()),
        PRESENT_EID,
    );
    assert_eq!(
        u32::from_le_bytes(present[16..20].try_into().unwrap()),
        COMPOSITE_OVERLAY_WINDOW.0,
    );
    assert_eq!(
        u16::from_le_bytes(present[24..26].try_into().unwrap()),
        3440,
        "Present ConfigureNotify width must track the grown COW",
    );
    assert_eq!(
        u16::from_le_bytes(present[26..28].try_into().unwrap()),
        1440,
        "Present ConfigureNotify height must track the grown COW",
    );
    assert_eq!(
        u16::from_le_bytes(present[32..34].try_into().unwrap()),
        3440,
        "Present pixmap width must ask Mesa/KWin to reallocate full-size buffers",
    );
    assert_eq!(
        u16::from_le_bytes(present[34..36].try_into().unwrap()),
        1440,
        "Present pixmap height must ask Mesa/KWin to reallocate full-size buffers",
    );

    super::super::run::emit_screen_resize_window_notifications_if_outputs_caught_up(
        &mut state,
        Some((1680, 1050)),
    );
    assert!(
        read_all_available(&mut peer).is_empty(),
        "a stale output bbox must not re-emit full-size configure notifications",
    );

    state.randr.outputs[0].width = 3440;
    state.randr.outputs[0].height = 1440;
    super::super::run::emit_screen_resize_window_notifications_if_outputs_caught_up(
        &mut state,
        Some((1680, 1050)),
    );
    let caught_up = read_all_available(&mut peer);
    assert_eq!(
        caught_up.len(),
        32 + 40,
        "matching output bbox must re-emit core and Present COW configure notifications",
    );
    assert_eq!(caught_up[0] & 0x7f, 22);
    assert_eq!(caught_up[32], 35);
    assert_eq!(
        u16::from_le_bytes(caught_up[32 + 32..32 + 34].try_into().unwrap()),
        3440,
    );
    assert_eq!(
        u16::from_le_bytes(caught_up[32 + 34..32 + 36].try_into().unwrap()),
        1440,
    );

    super::super::run::emit_screen_resize_window_notifications_if_outputs_caught_up(
        &mut state,
        Some((3440, 1440)),
    );
    assert!(
        read_all_available(&mut peer).is_empty(),
        "an unchanged output bbox must not re-emit configure notifications",
    );
}

/// `RRSetScreenSize` validation: crop check returns BadMatch; zero-mm
/// returns BadValue; out-of-range width/height each report the offending
/// dimension as errorValue.
#[test]
fn screen_set_size_validation_errors() {
    use crate::randr::{RandrOutput, RandrState};
    use yserver_protocol::x11::randr as x11randr;

    const CLIENT_ID: u32 = 1;
    let outputs = vec![RandrOutput {
        name: "eDP-1".into(),
        output_id: 1,
        crtc_id: 2,
        mode_id: 3,
        connected: true,
        x: 0,
        y: 0,
        width: 1920,
        height: 1080,
        vrefresh: 60,
        timing: None,
        mm_width: 0,
        mm_height: 0,
        mode_ids: vec![3],
        num_preferred: 1,
        pending_transform: Default::default(),
        current_transform: Default::default(),
        rotation: crate::randr::RR_ROTATE_0,
    }];
    let mut state = ServerState::new();
    state.randr = RandrState::from_outputs(0, outputs);
    let mut backend = RecordingBackend::new();
    let mut peer = install_client(&mut state, CLIENT_ID);

    fn build_body(width: u16, height: u16, mm_w: u32, mm_h: u32) -> Vec<u8> {
        let mut b = Vec::with_capacity(16);
        b.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
        b.extend_from_slice(&width.to_le_bytes());
        b.extend_from_slice(&height.to_le_bytes());
        b.extend_from_slice(&mm_w.to_le_bytes());
        b.extend_from_slice(&mm_h.to_le_bytes());
        b
    }

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 128,
        data: x11randr::RR_SET_SCREEN_SIZE,
        length_units: 5,
    };

    // width=0 → out-of-range (< min=1) → BadValue with errorValue=0.
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(1),
        header,
        &build_body(0, 1080, 527, 296),
    )
    .unwrap();
    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes[1], x11::error::BAD_VALUE, "width=0 → BadValue");
    // errorValue for the offending width is 0 (the bad width).
    let ev = u32::from_le_bytes(bytes[4..8].try_into().unwrap());
    assert_eq!(ev, 0u32, "errorValue = offending width");

    // height=0 → out-of-range → BadValue with errorValue=height.
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(2),
        header,
        &build_body(1920, 0, 527, 296),
    )
    .unwrap();
    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes[1], x11::error::BAD_VALUE, "height=0 → BadValue");
    let ev = u32::from_le_bytes(bytes[4..8].try_into().unwrap());
    assert_eq!(ev, 0u32, "errorValue = offending height");

    // Crop: 1280×720 crops the 1920×1080 output → BadMatch.
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(3),
        header,
        &build_body(1280, 720, 527, 296),
    )
    .unwrap();
    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes[1], x11::error::BAD_MATCH, "crop → BadMatch");

    // mm_width=0 → BadValue.
    handle_randr_request(
        &mut state,
        &mut backend,
        ClientId(CLIENT_ID),
        SequenceNumber(4),
        header,
        &build_body(1920, 1080, 0, 296),
    )
    .unwrap();
    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes[1], x11::error::BAD_VALUE, "mm_width=0 → BadValue");
}

/// `RRSetScreenSize` sends ScreenChangeNotify only when pixel size or mm
/// differ from the current ones (`RRScreenSizeNotify`, rrscreen.c); a
/// repeated size and a rejected crop send nothing, as measured on Xorg
/// 21.1.24 by the xrandr-rotate vng scenario.
#[test]
fn screen_set_size_notifies_only_on_change() {
    use crate::randr::{RandrOutput, RandrState};
    use yserver_protocol::x11::randr as x11randr;

    const CLIENT_ID: u32 = 1;
    let outputs = vec![RandrOutput {
        name: "Virtual-1".into(),
        output_id: 1,
        crtc_id: 2,
        mode_id: 3,
        connected: true,
        x: 0,
        y: 0,
        width: 1280,
        height: 800,
        vrefresh: 60,
        timing: None,
        mm_width: 0,
        mm_height: 0,
        mode_ids: vec![3],
        num_preferred: 1,
        pending_transform: Default::default(),
        current_transform: Default::default(),
        rotation: crate::randr::RR_ROTATE_0,
    }];
    let mut state = ServerState::new();
    state.randr = RandrState::from_outputs(0, outputs);
    let mut backend = RecordingBackend::new();
    let mut peer = install_client(&mut state, CLIENT_ID);
    state.randr_select_masks.insert(
        (CLIENT_ID, ROOT_WINDOW),
        x11randr::NOTIFY_MASK_SCREEN_CHANGE,
    );

    let header = yserver_protocol::x11::RequestHeader {
        opcode: 128,
        data: x11randr::RR_SET_SCREEN_SIZE,
        length_units: 5,
    };
    let mut set = |state: &mut ServerState, seq: u16, w: u16, h: u16, mm_w: u32, mm_h: u32| {
        let mut b = Vec::with_capacity(16);
        b.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
        b.extend_from_slice(&w.to_le_bytes());
        b.extend_from_slice(&h.to_le_bytes());
        b.extend_from_slice(&mm_w.to_le_bytes());
        b.extend_from_slice(&mm_h.to_le_bytes());
        handle_randr_request(
            state,
            &mut backend,
            ClientId(CLIENT_ID),
            SequenceNumber(seq),
            header,
            &b,
        )
        .unwrap();
    };
    // RRScreenChangeNotify is RANDR event base 89 + 0.
    let screen_changes =
        |bytes: &[u8]| bytes.chunks_exact(32).filter(|e| e[0] & 0x7f == 89).count();

    set(&mut state, 1, 1280, 800, 300, 200);
    assert_eq!(
        screen_changes(&read_all_available(&mut peer)),
        1,
        "mm changed"
    );
    set(&mut state, 2, 1280, 800, 300, 200);
    assert_eq!(
        screen_changes(&read_all_available(&mut peer)),
        0,
        "unchanged"
    );
    set(&mut state, 3, 1279, 800, 300, 200);
    let bytes = read_all_available(&mut peer);
    assert_eq!(bytes[1], x11::error::BAD_MATCH, "crop → BadMatch");
    assert_eq!(screen_changes(&bytes), 0, "rejected crop");
    set(&mut state, 4, 4000, 4000, 300, 200);
    assert_eq!(screen_changes(&read_all_available(&mut peer)), 1, "grown");
    set(&mut state, 5, 1280, 800, 300, 200);
    assert_eq!(
        screen_changes(&read_all_available(&mut peer)),
        1,
        "restored"
    );
}

// DRIFT 1 + Multi-monitor Bug A regression: the Bounding-shape mirror
// must distinguish three states via the Option API —
//   unset    → None    (drop the entry; scene tracks live geometry —
//                        the multi-monitor Bug A fix), NOT the
//                        materialized default geometry rect;
//   empty    → Some(0)  (explicit empty region — distinct from unset);
//   concrete → Some(n)  (the real rects).
#[test]
fn bounding_shape_mirror_distinguishes_unset_empty_and_concrete() {
    use yserver_protocol::x11::shape as x11shape;

    const WINDOW_XID: u32 = 0x0010_0001;
    const HOST_XID: u32 = 0x0040_0001;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 2560,
            height: 1440,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    state
        .resources
        .window_mut(ResourceId(WINDOW_XID))
        .expect("window installed")
        .host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));

    // No explicit Bounding shape set → mirror must push empty rects.
    mirror_shape_to_host_state(
        &state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        x11shape::KIND_BOUNDING,
    );
    assert_eq!(
        backend.calls().last(),
        Some(
            &crate::backend::recording::RecordedCall::SetShapeRectangles {
                host_xid: HOST_XID,
                kind: x11shape::KIND_BOUNDING,
                rects: None,
            }
        ),
        "unset Bounding shape must mirror None (drop backend entry), \
             not the materialized 2560x1440 default geometry rect, and NOT \
             an explicit empty region (Some(0)) — DRIFT 1 distinction",
    );

    // An explicitly-set EMPTY Bounding shape is a DISTINCT state from
    // unset: it mirrors Some(0), not None. This is the DRIFT 1 fix —
    // the old &[]-based API collapsed both to a zero-length call.
    crate::nested::set_shape_rects(
        &mut state,
        ResourceId(WINDOW_XID),
        x11shape::KIND_BOUNDING,
        vec![],
    );
    mirror_shape_to_host_state(
        &state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        x11shape::KIND_BOUNDING,
    );
    assert_eq!(
        backend.calls().last(),
        Some(
            &crate::backend::recording::RecordedCall::SetShapeRectangles {
                host_xid: HOST_XID,
                kind: x11shape::KIND_BOUNDING,
                rects: Some(0),
            }
        ),
        "explicit EMPTY Bounding shape must mirror Some(0) (an empty \
             region), distinct from unset's None",
    );

    // After an explicit non-empty Bounding shape, mirror the concrete rect(s).
    crate::nested::set_shape_rects(
        &mut state,
        ResourceId(WINDOW_XID),
        x11shape::KIND_BOUNDING,
        vec![yserver_protocol::x11::xfixes::RegionRect {
            x: 0,
            y: 0,
            width: 100,
            height: 100,
        }],
    );
    mirror_shape_to_host_state(
        &state,
        &mut backend,
        None,
        ResourceId(WINDOW_XID),
        x11shape::KIND_BOUNDING,
    );
    assert_eq!(
        backend.calls().last(),
        Some(
            &crate::backend::recording::RecordedCall::SetShapeRectangles {
                host_xid: HOST_XID,
                kind: x11shape::KIND_BOUNDING,
                rects: Some(1),
            }
        ),
        "explicitly-set Bounding shape must mirror the concrete rect",
    );
}

/// Cinnamon's lock screen, as muffin sends it: an XFIXES region that
/// `InvertRegion` empties, set as the COW's Bounding shape, must reach the
/// backend as an explicit EMPTY region, and region None as unset — the
/// two stay distinct (`ProcXFixesSetWindowShapeRegion`, `xfixes/region.c`:
/// a NULL region pointer unshapes, a copied empty region shapes to
/// nothing).
#[test]
fn xfixes_set_window_shape_region_keeps_empty_distinct_from_none() {
    use yserver_protocol::x11::{shape as x11shape, xfixes as x11xfixes};

    const REGION: u32 = 0x0010_0042;
    let cow = crate::resources::COMPOSITE_OVERLAY_WINDOW;
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    state
        .resources
        .materialize_cow_resource(crate::backend::WindowHandle::from_raw_for_test(cow.0));

    let mut send = |state: &mut ServerState, minor: u8, body: Vec<u8>| {
        let header = yserver_protocol::x11::RequestHeader {
            opcode: XFIXES_MAJOR_OPCODE,
            data: minor,
            length_units: u32::try_from(1 + body.len() / 4).unwrap(),
        };
        handle_xfixes_request(
            state,
            &mut backend,
            None,
            ClientId(1),
            SequenceNumber(1),
            header,
            &body,
        )
        .expect("XFIXES request");
    };
    let full = [0_i16, 0, 5120, 1440]
        .iter()
        .flat_map(|v| v.to_le_bytes())
        .collect::<Vec<u8>>();
    let shape_body = |region: u32| {
        let mut body = cow.0.to_le_bytes().to_vec();
        body.extend_from_slice(&[x11shape::KIND_BOUNDING, 0, 0, 0, 0, 0, 0, 0]);
        body.extend_from_slice(&region.to_le_bytes());
        body
    };

    let mut create = REGION.to_le_bytes().to_vec();
    create.extend_from_slice(&full);
    send(&mut state, x11xfixes::CREATE_REGION, create);
    let mut invert = REGION.to_le_bytes().to_vec();
    invert.extend_from_slice(&full);
    invert.extend_from_slice(&REGION.to_le_bytes());
    send(&mut state, x11xfixes::INVERT_REGION, invert);
    send(
        &mut state,
        x11xfixes::SET_WINDOW_SHAPE_REGION,
        shape_body(REGION),
    );
    assert!(crate::nested::shape_kind_is_set(
        &state,
        cow,
        x11shape::KIND_BOUNDING
    ));
    assert!(crate::nested::shape_rects_for(&state, cow, x11shape::KIND_BOUNDING).is_empty());

    send(
        &mut state,
        x11xfixes::SET_WINDOW_SHAPE_REGION,
        shape_body(0),
    );
    assert!(!crate::nested::shape_kind_is_set(
        &state,
        cow,
        x11shape::KIND_BOUNDING
    ));

    let mirrored: Vec<_> = backend
        .calls()
        .into_iter()
        .filter_map(|call| match call {
            crate::backend::recording::RecordedCall::SetShapeRectangles {
                host_xid,
                kind: x11shape::KIND_BOUNDING,
                rects,
            } if host_xid == cow.0 => Some(rects),
            _ => None,
        })
        .collect();
    assert_eq!(mirrored, vec![Some(0), None]);
}

// #133: the CLIP mirror must make the same unset/empty/concrete
// distinction as Bounding. Before step 5 the scene only consulted the
// bounding shape, so freezing the geometry rect for an unset clip shape
// was inert; step 5 clips descendants to the parent's clip shape, and a
// frozen rect then truncates the children after the parent resizes. That
// is the wezterm white block: awesome resets its frame's clip shape at
// 820x583, the frame later becomes 608x734, and 168 rows of the client
// vanished. Input is deliberately NOT in the guard — it feeds the cursor
// hit-test, which wants a concrete region.
#[test]
fn clip_shape_mirror_leaves_an_unset_region_unmaterialized() {
    use yserver_protocol::x11::shape as x11shape;

    const WINDOW_XID: u32 = 0x0010_0002;
    const HOST_XID: u32 = 0x0040_0002;

    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        yserver_protocol::x11::ClientId(1),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WINDOW_XID),
            parent: crate::resources::ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 820,
            height: 583,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    state
        .resources
        .window_mut(ResourceId(WINDOW_XID))
        .expect("window installed")
        .host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(HOST_XID));

    let mirror = |state: &ServerState, backend: &mut RecordingBackend, kind: u8| {
        mirror_shape_to_host_state(state, backend, None, ResourceId(WINDOW_XID), kind);
    };

    mirror(&state, &mut backend, x11shape::KIND_CLIP);
    assert_eq!(
        backend.calls().last(),
        Some(
            &crate::backend::recording::RecordedCall::SetShapeRectangles {
                host_xid: HOST_XID,
                kind: x11shape::KIND_CLIP,
                rects: None,
            }
        ),
        "an unset Clip shape must mirror None, not the 820x583 geometry \
             rect that goes stale on the next resize",
    );

    // Input keeps materializing the default rect — the cursor hit-test
    // consumes a concrete region and does not clip descendants.
    mirror(&state, &mut backend, x11shape::KIND_INPUT);
    assert_eq!(
        backend.calls().last(),
        Some(
            &crate::backend::recording::RecordedCall::SetShapeRectangles {
                host_xid: HOST_XID,
                kind: x11shape::KIND_INPUT,
                rects: Some(1),
            }
        ),
        "an unset Input shape still mirrors the default geometry rect",
    );

    // An explicit EMPTY clip region is a distinct state from unset.
    crate::nested::set_shape_rects(
        &mut state,
        ResourceId(WINDOW_XID),
        x11shape::KIND_CLIP,
        vec![],
    );
    mirror(&state, &mut backend, x11shape::KIND_CLIP);
    assert_eq!(
        backend.calls().last(),
        Some(
            &crate::backend::recording::RecordedCall::SetShapeRectangles {
                host_xid: HOST_XID,
                kind: x11shape::KIND_CLIP,
                rects: Some(0),
            }
        ),
        "explicit EMPTY Clip shape mirrors Some(0), distinct from unset",
    );

    // And a real clip shape is still mirrored through.
    crate::nested::set_shape_rects(
        &mut state,
        ResourceId(WINDOW_XID),
        x11shape::KIND_CLIP,
        vec![yserver_protocol::x11::xfixes::RegionRect {
            x: 0,
            y: 0,
            width: 100,
            height: 100,
        }],
    );
    mirror(&state, &mut backend, x11shape::KIND_CLIP);
    assert_eq!(
        backend.calls().last(),
        Some(
            &crate::backend::recording::RecordedCall::SetShapeRectangles {
                host_xid: HOST_XID,
                kind: x11shape::KIND_CLIP,
                rects: Some(1),
            }
        ),
        "explicitly-set Clip shape must mirror the concrete rect",
    );
}

/// #94 fast-click acceptance: press withheld by muffin's sync XI2
/// passive grab; the RELEASE arrives during the freeze and is queued;
/// XIAllowEvents(ReplayDevice) replays the press (installing the
/// implicit grab on the natural recipient) and the queue drain must
/// deliver the release UNDER that grab (Xorg PlayReleasedEvents →
/// DeliverGrabbedEvent) — not re-hit-test it.
#[test]
fn xi_replay_device_then_queued_release_follows_implicit_grab() {
    use crate::{
        backend::Backend,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
    };
    const WM: u32 = 1;
    const APP: u32 = 2;
    const GRAB_WIN: u32 = 0x0010_0051;
    const APP_WIN: u32 = 0x0020_0052;
    const HOST_XID: u32 = 0xCAFE_0001;

    let mut state = ServerState::new();
    let _wm_peer = install_client(&mut state, WM);
    let mut app_peer = install_client(&mut state, APP);
    let mut backend = RecordingBackend::new();
    app_peer.set_nonblocking(true).expect("nonblocking");

    for (client, win) in [(WM, GRAB_WIN), (APP, APP_WIN)] {
        state.resources.create_window(
            ClientId(client),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(win),
                parent: ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(ResourceId(win));
    }
    state
        .clients
        .get_mut(&APP)
        .expect("app client")
        .event_masks
        .insert(ResourceId(APP_WIN), 0x0000_000c); // press|release
    Backend::register_top_level(&mut backend, None, ResourceId(APP_WIN), HOST_XID)
        .expect("register host xid");

    // Frozen sync passive grab held by the WM, activating press stored,
    // and the fast release already QUEUED (it arrived mid-freeze; the
    // queue gate decremented buttons_down and withheld it).
    set_test_pointer_grab(&mut state, WM, GRAB_WIN, true, false);
    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_XID,
        detail: 1,
        time: 1000,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    {
        let f = state
            .xi1_frozen
            .entry(crate::xinput::DEVICEID_MASTER_POINTER)
            .or_default();
        f.state = crate::server::Xi1SyncState::FrozenWithEvent;
        f.stored = Some(crate::server::QueuedInputEvent::HostPointer(press));
    }
    let release = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonRelease,
        time: 1010,
        state: 0x100,
        ..press
    };
    state
        .sync_pending
        .push_back(crate::server::PendingSyncEvent {
            device: crate::xinput::DEVICEID_MASTER_POINTER,
            event: crate::server::QueuedInputEvent::HostPointer(release),
        });

    // XIAllowEvents(ReplayDevice) from the WM.
    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&0u32.to_le_bytes()); // time
    body.extend_from_slice(&2u16.to_le_bytes()); // deviceid = master ptr
    body.push(2); // mode = ReplayDevice
    body.push(0); // pad
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 131,
        data: 53,
        length_units: 3,
    };
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(WM),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("allow events");

    // The replayed press delivered to APP + the queued release drained
    // UNDER the freshly-installed implicit grab.
    let bytes = read_all_available(&mut app_peer);
    let (mut saw_press, mut saw_release) = (false, false);
    let mut off = 0usize;
    while off + 32 <= bytes.len() {
        match bytes[off] & 0x7F {
            4 => saw_press = true,
            5 => {
                saw_release = true;
                assert_eq!(
                    &bytes[off + 12..off + 16],
                    &APP_WIN.to_le_bytes(),
                    "queued release must deliver on the implicit grab window"
                );
            }
            _ => {}
        }
        off += 32;
    }
    assert!(saw_press, "replayed press must reach the natural target");
    assert!(
        saw_release,
        "queued release must follow the implicit grab owner (fast click)"
    );
    assert!(
        state.active_pointer_grab.is_none(),
        "release completes the click — implicit grab torn down"
    );
    assert_eq!(
        state.buttons_down, 0,
        "the queued release leaves the master clear"
    );
    assert_eq!(
        state.xi_devices.device(4).unwrap().buttons_down,
        0,
        "the queued release leaves XTEST 4 clear"
    );
}

/// An implicit grab is a REAL grab for request purposes (Xorg shares
/// deviceGrab.grab): another client's GrabPointer during it fails
/// AlreadyGrabbed (events.c:5240-5243); the owner's GrabPointer
/// replaces it; the owner's UngrabPointer releases it (events.c:5155).
#[test]
fn implicit_grab_interacts_with_grab_requests_like_a_real_grab() {
    use crate::server::ActivePointerGrab;
    const OWNER: u32 = 1;
    const INTRUDER: u32 = 2;
    const WIN: u32 = 0x0010_0001;

    let mut state = ServerState::new();
    let mut backend = RecordingBackend::new();
    let mut owner_peer = install_client(&mut state, OWNER);
    let mut intruder_peer = install_client(&mut state, INTRUDER);
    owner_peer.set_nonblocking(true).unwrap();
    intruder_peer.set_nonblocking(true).unwrap();
    state.resources.create_window(
        ClientId(OWNER),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(WIN));

    let install_implicit = |state: &mut ServerState| {
        state.active_pointer_grab = Some(ActivePointerGrab {
            owner: ClientId(OWNER),
            grab_window: ResourceId(WIN),
            event_mask: 0x000c,
            cursor: ResourceId(0),
            time: 1000,
            owner_events: false,
            via_xi2: false,
            implicit: true,
            passive: false,
            xi2_mask: 0,
        });
        state.last_pointer_grab_time = 1000;
    };
    let grab_body = || {
        let mut body = Vec::with_capacity(20);
        body.extend_from_slice(&WIN.to_le_bytes());
        body.extend_from_slice(&0u16.to_le_bytes()); // event-mask
        body.push(1); // pointer-mode async
        body.push(1); // keyboard-mode async
        body.extend_from_slice(&0u32.to_le_bytes()); // confine-to
        body.extend_from_slice(&0u32.to_le_bytes()); // cursor
        body.extend_from_slice(&0u32.to_le_bytes()); // time CurrentTime
        body
    };
    let header = RequestHeader {
        opcode: 26,
        data: 0,
        length_units: 6,
    };
    let grab_status = |peer: &mut std::os::unix::net::UnixStream| -> u8 {
        let wire = read_all_available(peer);
        assert!(wire.len() >= 32, "expected a GrabPointer reply");
        assert_eq!(wire[0], 1, "reply, not an event/error");
        wire[1]
    };

    // (a) Another client's GrabPointer → AlreadyGrabbed, state untouched.
    install_implicit(&mut state);
    handle_grab_pointer(
        &mut state,
        &mut backend,
        ClientId(INTRUDER),
        SequenceNumber(1),
        header,
        &grab_body(),
    )
    .expect("grab pointer");
    assert_eq!(grab_status(&mut intruder_peer), 1, "AlreadyGrabbed");
    assert!(
        state
            .active_pointer_grab
            .is_some_and(|g| g.implicit && g.owner == ClientId(OWNER)),
        "implicit grab untouched by the failed request"
    );

    // (b) The owner's GrabPointer replaces its implicit grab.
    handle_grab_pointer(
        &mut state,
        &mut backend,
        ClientId(OWNER),
        SequenceNumber(2),
        header,
        &grab_body(),
    )
    .expect("grab pointer");
    assert_eq!(grab_status(&mut owner_peer), 0, "GrabSuccess");
    assert!(
        state.active_pointer_grab.is_some_and(|g| !g.implicit),
        "explicit grab replaced the implicit one"
    );

    // (c) Owner's UngrabPointer releases its own implicit grab; a
    // non-owner's UngrabPointer is a no-op.
    install_implicit(&mut state);
    let ungrab_body = 0u32.to_le_bytes(); // time CurrentTime
    handle_ungrab_pointer(
        &mut state,
        &mut backend,
        ClientId(INTRUDER),
        SequenceNumber(3),
        &ungrab_body,
    )
    .expect("ungrab pointer");
    assert!(
        state.active_pointer_grab.is_some(),
        "non-owner UngrabPointer must not touch the implicit grab"
    );
    handle_ungrab_pointer(
        &mut state,
        &mut backend,
        ClientId(OWNER),
        SequenceNumber(4),
        &ungrab_body,
    )
    .expect("ungrab pointer");
    assert!(
        state.active_pointer_grab.is_none(),
        "owner UngrabPointer releases the implicit grab (Xorg SameClient)"
    );
}

/// #94 slow-click acceptance (the traced Cinnamon shape): muffin's
/// sync XI2 passive grab withholds the press; XIAllowEvents(
/// XIReplayDevice) re-delivers it to Steam (XI2-only selector),
/// installing the implicit grab; muffin then MUTATES THE TREE
/// (click-to-focus reparents/restacks) before the user releases.
/// The release must follow the implicit grab to Steam — pre-fix it
/// was re-hit-tested against the mutated tree and lost (steam.xtrace:
/// 164 XI2 presses vs 28 releases → stuck button).
#[test]
fn xi_replay_device_press_then_tree_mutation_release_follows_grab() {
    use crate::{
        backend::Backend,
        core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
    };
    const WM: u32 = 1;
    const APP: u32 = 2;
    const GRAB_WIN: u32 = 0x0010_0051; // WM's passive-grab window
    const APP_WIN: u32 = 0x0020_0052; // Steam-like, XI2-only selector
    const FRAME_WIN: u32 = 0x0010_0060; // WM frame created mid-click
    const COVER_WIN: u32 = 0x0010_0061; // WM window the release re-hits
    const HOST_APP: u32 = 0xCAFE_0001;
    const HOST_COVER: u32 = 0xCAFE_0002;
    const XI2_MASTER: u16 = 2;

    let mut state = ServerState::new();
    let mut wm_peer = install_client(&mut state, WM);
    let mut app_peer = install_client(&mut state, APP);
    let mut backend = RecordingBackend::new();
    wm_peer.set_nonblocking(true).unwrap();
    app_peer.set_nonblocking(true).unwrap();

    for (client, win) in [
        (WM, GRAB_WIN),
        (APP, APP_WIN),
        (WM, FRAME_WIN),
        (WM, COVER_WIN),
    ] {
        state.resources.create_window(
            ClientId(client),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(win),
                parent: ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(ResourceId(win));
    }
    // Steam shape: cooked XI2 buttons, NO core mask.
    state
        .clients
        .get_mut(&APP)
        .expect("app")
        .xi2_masks
        .insert((ResourceId(APP_WIN), XI2_MASTER), (1 << 4) | (1 << 5));
    // The WM selects XI2 buttons on the covering window — a re-hit-test
    // would deliver the release THERE.
    state
        .clients
        .get_mut(&WM)
        .expect("wm")
        .xi2_masks
        .insert((ResourceId(COVER_WIN), XI2_MASTER), (1 << 4) | (1 << 5));
    Backend::register_top_level(&mut backend, None, ResourceId(APP_WIN), HOST_APP)
        .expect("register app");
    Backend::register_top_level(&mut backend, None, ResourceId(COVER_WIN), HOST_COVER)
        .expect("register cover");

    // Frozen sync passive grab held by the WM, press stored.
    set_test_pointer_grab(&mut state, WM, GRAB_WIN, true, false);
    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_APP,
        detail: 1,
        time: 1000,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    {
        let f = state
            .xi1_frozen
            .entry(crate::xinput::DEVICEID_MASTER_POINTER)
            .or_default();
        f.state = crate::server::Xi1SyncState::FrozenWithEvent;
        f.stored = Some(crate::server::QueuedInputEvent::HostPointer(press));
    }

    // XIAllowEvents(ReplayDevice) from the WM.
    let mut body = Vec::with_capacity(8);
    body.extend_from_slice(&0u32.to_le_bytes());
    body.extend_from_slice(&2u16.to_le_bytes());
    body.push(2); // ReplayDevice
    body.push(0);
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(WM),
        SequenceNumber(1),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 53,
            length_units: 3,
        },
        &body,
    )
    .expect("allow events");

    let xge_events = |bytes: &[u8]| -> Vec<(u16, u32)> {
        let mut found = Vec::new();
        let mut off = 0usize;
        while off + 32 <= bytes.len() {
            let advance = if bytes[off] == 35 {
                found.push((
                    u16::from_le_bytes([bytes[off + 8], bytes[off + 9]]),
                    u32::from_le_bytes(bytes[off + 24..off + 28].try_into().unwrap()),
                ));
                32 + u32::from_le_bytes(bytes[off + 4..off + 8].try_into().unwrap()) as usize * 4
            } else {
                32
            };
            off += advance;
        }
        found
    };
    assert!(
        xge_events(&read_all_available(&mut app_peer)).contains(&(4, APP_WIN)),
        "replayed press must reach APP as XI2 on its window"
    );
    assert!(
        state.active_pointer_grab.is_some_and(|g| g.implicit
            && g.via_xi2
            && g.owner == ClientId(APP)
            && g.grab_window == ResourceId(APP_WIN)),
        "replayed press installs the via_xi2 implicit grab (#94 crux)"
    );

    // muffin-style mutation between press and release: reparent the
    // app window into a WM frame and let a WM window cover the spot.
    let _ = state
        .resources
        .reparent_window(yserver_protocol::x11::ReparentWindowRequest {
            window: ResourceId(APP_WIN),
            parent: ResourceId(FRAME_WIN),
            x: 0,
            y: 0,
        });
    let _ = state.resources.map_window(ResourceId(APP_WIN));

    // Natural release now resolves over the WM's covering window.
    let xid_map = backend.xid_map().clone();
    let release = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonRelease,
        host_xid: HOST_COVER,
        time: 1200,
        state: 0x100,
        ..press
    };
    let _ = pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, release, true, false);

    assert!(
        xge_events(&read_all_available(&mut app_peer)).contains(&(5, APP_WIN)),
        "release must follow the implicit grab to APP on the grab window"
    );
    assert!(
        !xge_events(&read_all_available(&mut wm_peer))
            .iter()
            .any(|(evtype, _)| *evtype == 5),
        "the grab captures the release away from the re-hit-tested window"
    );
    assert!(
        state.active_pointer_grab.is_none(),
        "click complete — implicit grab torn down"
    );
}

/// Xorg oracle from `steam-xorg.xtrace` connection 019 — the canonical
/// Steam-webhelper click. The client selects XI2 Button{Press,Release}+
/// Motion on its window W (`XISelectEvents win=W device=0 mask=0x001c0ff2`),
/// receives the `ButtonPress`, then establishes its OWN grab on the master
/// pointer BEFORE the release (`XIGrabDevice grab_window=W device=2
/// grab_mode=Async owner_events=true masks=0x001c0070`), and Xorg still
/// delivers the matching `ButtonRelease` to the client on W — press count
/// equals release count — after which the client `XIUngrabDevice`s.
///
/// This encodes Xorg's observed behavior ONLY. On yserver a delivered
/// press installs an implicit pointer grab, and the client's mid-click
/// `XIGrabDevice` overwrites that slot; the question this pins is whether
/// the release survives that overlap the way it does under Xorg.
#[test]
fn xi_client_grab_device_mid_click_delivers_release_xorg_conn019() {
    use crate::{
        backend::Backend,
        core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
    };
    const APP: u32 = 1;
    const APP_WIN: u32 = 0x0044_000b; // window id shape from the trace
    const HOST_APP: u32 = 0xCAFE_0001;
    const XI2_MASTER: u16 = 2;

    let mut state = ServerState::new();
    let mut app_peer = install_client(&mut state, APP);
    app_peer.set_nonblocking(true).unwrap();
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        ClientId(APP),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(APP_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(APP_WIN));
    // Xorg XISelectEvents mask 0x001c0ff2 → Button{Press,Release}+Motion (+more).
    state.clients.get_mut(&APP).expect("app").xi2_masks.insert(
        (ResourceId(APP_WIN), XI2_MASTER),
        (1 << 4) | (1 << 5) | (1 << 6),
    );
    Backend::register_top_level(&mut backend, None, ResourceId(APP_WIN), HOST_APP)
        .expect("register app");
    let xid_map = backend.xid_map().clone();

    let xge = |bytes: &[u8]| -> Vec<(u16, u32)> {
        let mut found = Vec::new();
        let mut off = 0usize;
        while off + 32 <= bytes.len() {
            let advance = if bytes[off] == 35 {
                found.push((
                    u16::from_le_bytes([bytes[off + 8], bytes[off + 9]]),
                    u32::from_le_bytes(bytes[off + 24..off + 28].try_into().unwrap()),
                ));
                32 + u32::from_le_bytes(bytes[off + 4..off + 8].try_into().unwrap()) as usize * 4
            } else {
                32
            };
            off += advance;
        }
        found
    };

    // 1. ButtonPress @ W (Xorg: delivered to the selector on its window).
    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_APP,
        detail: 1,
        time: 1000,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let _ = pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, press, true, false);
    let after_press = xge(&read_all_available(&mut app_peer));
    let presses = after_press.iter().filter(|(t, _)| *t == 4).count();
    assert!(
        after_press.contains(&(4, APP_WIN)),
        "Xorg: the ButtonPress is delivered to the XI2 selector on its own window"
    );

    // 2. Client's own XIGrabDevice on the master pointer, owner_events=true,
    //    grab_window=W, mask=Button{Press,Release}+Motion (Xorg masks=0x001c0070).
    let mut body = Vec::with_capacity(28);
    body.extend_from_slice(&APP_WIN.to_le_bytes()); // grab_window
    body.extend_from_slice(&0u32.to_le_bytes()); // time = CurrentTime
    body.extend_from_slice(&0u32.to_le_bytes()); // cursor = None
    body.extend_from_slice(&2u16.to_le_bytes()); // device = master pointer
    body.extend_from_slice(&[1, 1, 1, 0]); // async, async, owner_events=1, pad
    body.extend_from_slice(&1u16.to_le_bytes()); // mask_len (one 4-byte unit)
    body.extend_from_slice(&[0u8; 2]); // pad
    body.extend_from_slice(&((1u32 << 4) | (1 << 5) | (1 << 6)).to_le_bytes());
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(APP),
        SequenceNumber(2),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 51, // XIGrabDevice
            length_units: 8,
        },
        &body,
    )
    .expect("XIGrabDevice");
    let _ = read_all_available(&mut app_peer); // drain grab reply, if any

    // 3. ButtonRelease @ W, still over W (Xorg: delivered to the client on W,
    //    even though the client established its own grab mid-click).
    let release = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonRelease,
        time: 1100,
        state: 0x100,
        ..press
    };
    let _ = pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, release, true, false);
    let after_release = xge(&read_all_available(&mut app_peer));
    let releases = after_release.iter().filter(|(t, _)| *t == 5).count();

    assert!(
        after_release.contains(&(5, APP_WIN)),
        "Xorg: the ButtonRelease must still reach the client on its window even \
             though the client established its own XIGrabDevice mid-click \
             (steam-xorg.xtrace conn 019); got events {after_release:?}"
    );
    assert_eq!(
        presses, releases,
        "Xorg: press count equals release count for the grab client \
             (presses={presses}, releases={releases})"
    );

    // 4. Client XIUngrabDevice(device=2) — grab released.
    let mut ungrab = Vec::with_capacity(8);
    ungrab.extend_from_slice(&0u32.to_le_bytes()); // time
    ungrab.extend_from_slice(&2u16.to_le_bytes()); // device = master pointer
    ungrab.extend_from_slice(&[0u8; 2]); // pad
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(APP),
        SequenceNumber(3),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 52, // XIUngrabDevice
            length_units: 3,
        },
        &ungrab,
    )
    .expect("XIUngrabDevice");
    assert!(
        state.active_pointer_grab.is_none(),
        "after the client ungrabs, no pointer grab remains"
    );
}

/// Xorg oracle: `steam-xorg.xtrace` conn 019 repeats the grab-dance click
/// (`ButtonPress → XIGrabDevice → ButtonRelease → XIUngrabDevice`) ~40
/// times, and EVERY click delivers a matched press+release with no residue.
/// The GH #94 report ("several clicks before one registers, growing
/// backlog") is a state-accumulation symptom, so this drives the same
/// cycle N times and asserts each click stays balanced and leaves no
/// stuck grab / lingering pointer-button state behind.
#[test]
fn xi_repeated_grab_dance_clicks_stay_balanced_xorg_conn019() {
    use crate::{
        backend::Backend,
        core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
    };
    const APP: u32 = 1;
    const APP_WIN: u32 = 0x0044_000b;
    const HOST_APP: u32 = 0xCAFE_0001;
    const XI2_MASTER: u16 = 2;

    let mut state = ServerState::new();
    let mut app_peer = install_client(&mut state, APP);
    app_peer.set_nonblocking(true).unwrap();
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        ClientId(APP),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: ResourceId(APP_WIN),
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 100,
            height: 100,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(ResourceId(APP_WIN));
    state.clients.get_mut(&APP).expect("app").xi2_masks.insert(
        (ResourceId(APP_WIN), XI2_MASTER),
        (1 << 4) | (1 << 5) | (1 << 6),
    );
    Backend::register_top_level(&mut backend, None, ResourceId(APP_WIN), HOST_APP)
        .expect("register app");
    let xid_map = backend.xid_map().clone();

    let xge = |bytes: &[u8]| -> Vec<(u16, u32)> {
        let mut found = Vec::new();
        let mut off = 0usize;
        while off + 32 <= bytes.len() {
            let advance = if bytes[off] == 35 {
                found.push((
                    u16::from_le_bytes([bytes[off + 8], bytes[off + 9]]),
                    u32::from_le_bytes(bytes[off + 24..off + 28].try_into().unwrap()),
                ));
                32 + u32::from_le_bytes(bytes[off + 4..off + 8].try_into().unwrap()) as usize * 4
            } else {
                32
            };
            off += advance;
        }
        found
    };

    let grab_body = |window: u32| {
        let mut body = Vec::with_capacity(28);
        body.extend_from_slice(&window.to_le_bytes());
        body.extend_from_slice(&0u32.to_le_bytes());
        body.extend_from_slice(&0u32.to_le_bytes());
        body.extend_from_slice(&2u16.to_le_bytes());
        body.extend_from_slice(&[1, 1, 1, 0]);
        body.extend_from_slice(&1u16.to_le_bytes());
        body.extend_from_slice(&[0u8; 2]);
        body.extend_from_slice(&((1u32 << 4) | (1 << 5) | (1 << 6)).to_le_bytes());
        body
    };
    let ungrab_body = || {
        let mut body = Vec::with_capacity(8);
        body.extend_from_slice(&0u32.to_le_bytes());
        body.extend_from_slice(&2u16.to_le_bytes());
        body.extend_from_slice(&[0u8; 2]);
        body
    };

    for i in 0..10u32 {
        let seq = i * 4;
        let base_time = 1000 + i * 100;
        let press = HostPointerEvent {
            origin: crate::core_loop::message::InputOrigin::XTest(4),
            kind: PointerEventKind::ButtonPress,
            host_xid: HOST_APP,
            detail: 1,
            time: base_time,
            root_x: 10,
            root_y: 10,
            event_x: 10,
            event_y: 10,
            state: 0,
            crossing_mode: 0,
            child: 0,
            raw_dx: 0,
            raw_dy: 0,
            tree_change: false,
        };
        let _ =
            pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, press, true, false);

        handle_xi2_request(
            &mut state,
            &mut backend,
            None,
            ClientId(APP),
            SequenceNumber((seq + 2) as u16),
            yserver_protocol::x11::RequestHeader {
                opcode: 131,
                data: 51,
                length_units: 8,
            },
            &grab_body(APP_WIN),
        )
        .expect("XIGrabDevice");

        let release = HostPointerEvent {
            origin: crate::core_loop::message::InputOrigin::XTest(4),
            kind: PointerEventKind::ButtonRelease,
            time: base_time + 50,
            state: 0x100,
            ..press
        };
        let _ =
            pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, release, true, false);

        handle_xi2_request(
            &mut state,
            &mut backend,
            None,
            ClientId(APP),
            SequenceNumber((seq + 3) as u16),
            yserver_protocol::x11::RequestHeader {
                opcode: 131,
                data: 52,
                length_units: 3,
            },
            &ungrab_body(),
        )
        .expect("XIUngrabDevice");

        let evs = xge(&read_all_available(&mut app_peer));
        let presses = evs.iter().filter(|(t, _)| *t == 4).count();
        let releases = evs.iter().filter(|(t, _)| *t == 5).count();
        assert!(
            evs.contains(&(4, APP_WIN)) && evs.contains(&(5, APP_WIN)),
            "click {i}: both press and release must reach the client on its window; \
                 got {evs:?}"
        );
        assert_eq!(
            (presses, releases),
            (1, 1),
            "click {i}: exactly one press and one release must be delivered — \
                 balanced-but-duplicated (e.g. 2/2) is also a bug \
                 (presses={presses}, releases={releases})"
        );
        assert!(
            state.active_pointer_grab.is_none(),
            "click {i}: no stuck grab may accumulate between clicks"
        );
        assert_eq!(
            state.buttons_down, 0,
            "click {i}: logical button state must return to 0 after the release"
        );
    }
}

/// Xorg oracle from the FAILING `cinnamon.xtrace` (one Steam click) +
/// `dix/events.c:5240`. The traced sequence that swallows the click:
///   muffin sync-passive-grabs the press, `XIAllowEvents(ReplayDevice)`
///   replays it to Steam; Steam (conn 105) `XIGrabDevice`s the master
///   pointer (device=2, grab_window=its own window, first, never ungrabs);
///   muffin (conn 026) THEN `XIGrabDevice`s the SAME master pointer
///   (device=2, different client); the ButtonRelease is delivered to
///   muffin, and Steam never sees it → the click never completes.
///
/// Xorg rejects the second grab with `AlreadyGrabbed`
/// (`grab && !SameClient`, dix/events.c:5240), so the first grabber keeps
/// the device and the release follows it. This test encodes that rule: a
/// second client's `XIGrabDevice` while another client holds the pointer
/// grab must NOT steal it, and the release must reach the first grabber.
#[test]
fn xi_grab_device_by_other_client_must_not_steal_held_grab_cinnamon_xtrace() {
    use crate::{
        backend::Backend,
        core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
    };
    const STEAM: u32 = 1;
    const MUFFIN: u32 = 2;
    const STEAM_WIN: u32 = 0x0260_000d; // conn 105 grab_window
    const MUFFIN_WIN: u32 = 0x00e0_0011; // conn 026 grab_window
    const HOST_STEAM: u32 = 0xCAFE_0001;
    const XI2_MASTER: u16 = 2;

    let mut state = ServerState::new();
    let mut steam_peer = install_client(&mut state, STEAM);
    let mut muffin_peer = install_client(&mut state, MUFFIN);
    steam_peer.set_nonblocking(true).unwrap();
    muffin_peer.set_nonblocking(true).unwrap();
    let mut backend = RecordingBackend::new();

    for (client, win, x) in [(STEAM, STEAM_WIN, 0i16), (MUFFIN, MUFFIN_WIN, 500i16)] {
        state.resources.create_window(
            ClientId(client),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(win),
                parent: ROOT_WINDOW,
                x,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(ResourceId(win));
    }
    // Both select XI2 Button{Press,Release} on their own windows, so a
    // misrouted release to muffin would be observable on its wire.
    state
        .clients
        .get_mut(&STEAM)
        .unwrap()
        .xi2_masks
        .insert((ResourceId(STEAM_WIN), XI2_MASTER), (1 << 4) | (1 << 5));
    state
        .clients
        .get_mut(&MUFFIN)
        .unwrap()
        .xi2_masks
        .insert((ResourceId(MUFFIN_WIN), XI2_MASTER), (1 << 4) | (1 << 5));
    Backend::register_top_level(&mut backend, None, ResourceId(STEAM_WIN), HOST_STEAM)
        .expect("register steam");
    let xid_map = backend.xid_map().clone();

    let xge = |bytes: &[u8]| -> Vec<(u16, u32)> {
        let mut found = Vec::new();
        let mut off = 0usize;
        while off + 32 <= bytes.len() {
            let advance = if bytes[off] == 35 {
                found.push((
                    u16::from_le_bytes([bytes[off + 8], bytes[off + 9]]),
                    u32::from_le_bytes(bytes[off + 24..off + 28].try_into().unwrap()),
                ));
                32 + u32::from_le_bytes(bytes[off + 4..off + 8].try_into().unwrap()) as usize * 4
            } else {
                32
            };
            off += advance;
        }
        found
    };
    let grab_body = |window: u32, owner_events: u8| {
        let mut body = Vec::with_capacity(28);
        body.extend_from_slice(&window.to_le_bytes());
        body.extend_from_slice(&0u32.to_le_bytes()); // time
        body.extend_from_slice(&0u32.to_le_bytes()); // cursor
        body.extend_from_slice(&2u16.to_le_bytes()); // device = master pointer
        body.extend_from_slice(&[1, 1, owner_events, 0]);
        body.extend_from_slice(&1u16.to_le_bytes()); // mask_len
        body.extend_from_slice(&[0u8; 2]);
        body.extend_from_slice(&((1u32 << 4) | (1 << 5) | (1 << 6)).to_le_bytes());
        body
    };
    let do_grab = |state: &mut ServerState,
                   backend: &mut RecordingBackend,
                   client: u32,
                   seq: u16,
                   window: u32,
                   owner_events: u8| {
        handle_xi2_request(
            state,
            backend,
            None,
            ClientId(client),
            SequenceNumber(seq),
            yserver_protocol::x11::RequestHeader {
                opcode: 131,
                data: 51,
                length_units: 8,
            },
            &grab_body(window, owner_events),
        )
        .expect("XIGrabDevice");
    };

    // Press @ STEAM_WIN (post-ReplayDevice replay to Steam): Steam gets it,
    // installs the implicit grab.
    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_STEAM,
        detail: 1,
        time: 0xa040,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let _ = pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, press, true, false);
    let _ = read_all_available(&mut steam_peer);

    // Steam grabs the master pointer FIRST (conn 105, never ungrabs).
    do_grab(&mut state, &mut backend, STEAM, 10, STEAM_WIN, 1);
    assert_eq!(
        state
            .active_pointer_grab
            .map(|grab| (grab.owner, grab.grab_window)),
        Some((ClientId(STEAM), ResourceId(STEAM_WIN))),
        "precondition: Steam holds the master-pointer grab"
    );

    // Muffin then grabs the SAME master pointer (conn 026). Xorg:
    // AlreadyGrabbed → rejected; Steam keeps the grab.
    do_grab(&mut state, &mut backend, MUFFIN, 20, MUFFIN_WIN, 0);
    assert_eq!(
        state
            .active_pointer_grab
            .map(|grab| (grab.owner, grab.grab_window)),
        Some((ClientId(STEAM), ResourceId(STEAM_WIN))),
        "Xorg (dix/events.c:5240): a second client's XIGrabDevice while \
             another client holds the pointer grab must return AlreadyGrabbed \
             and must NOT steal the grab"
    );
    // The rejected grab's reply must carry status=1 (AlreadyGrabbed) at
    // byte offset 8 (xXIGrabDeviceReply). muffin has received nothing else
    // yet (the press went to Steam), so its wire starts with this reply.
    let muffin_reply = read_all_available(&mut muffin_peer);
    assert!(
        muffin_reply.len() >= 9 && muffin_reply[0] == 1 && muffin_reply[8] == 1,
        "muffin's contending XIGrabDevice must reply AlreadyGrabbed(1) at \
             offset 8; got {:?}",
        &muffin_reply[..muffin_reply.len().min(12)]
    );

    // Release over Steam's window — must reach the grab holder (Steam),
    // not muffin.
    let release = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonRelease,
        time: 0xa0e3,
        state: 0x100,
        ..press
    };
    let _ = pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, release, true, false);

    let steam_evs = xge(&read_all_available(&mut steam_peer));
    let muffin_evs = xge(&read_all_available(&mut muffin_peer));
    assert!(
        steam_evs.iter().any(|(t, _)| *t == 5),
        "the ButtonRelease must be delivered to the grab holder (Steam); \
             got steam={steam_evs:?} muffin={muffin_evs:?}"
    );
    assert!(
        !muffin_evs.iter().any(|(t, _)| *t == 5),
        "the release must NOT be stolen by the second (rejected) grabber; \
             muffin={muffin_evs:?}"
    );
}

/// Cinnamon dialog acceptance pin. The shell activates a synchronous XI2
/// passive pointer grab, then issues XIReplayDevice. Xorg transitions the
/// device to NOT_GRABBED before replay (`dix/events.c:1898`), so the app's
/// later XIGrabDevice must succeed without superseding a foreign grab.
#[test]
fn xi_dialog_grab_succeeds_over_foreign_passive_grab_cinnamon() {
    use crate::{
        backend::Backend,
        core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::{HostPointerEvent, PointerEventKind},
        server::PassiveButtonGrab,
    };
    const SHELL: u32 = 1;
    const APP: u32 = 2;
    const GRAB_WIN: u32 = 0x0070_0003;
    const APP_WIN: u32 = 0x0080_0003; // the app dialog's popup
    const HOST_XID: u32 = 0xCAFE_0001;

    let mut state = ServerState::new();
    let _shell_peer = install_client(&mut state, SHELL);
    let mut app_peer = install_client(&mut state, APP);
    app_peer.set_nonblocking(true).unwrap();
    let mut backend = RecordingBackend::new();

    for (client, win) in [(SHELL, GRAB_WIN), (APP, APP_WIN)] {
        state.resources.create_window(
            ClientId(client),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(win),
                parent: ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: crate::resources::ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(ResourceId(win));
    }
    state.button_grabs.push(PassiveButtonGrab {
        device_id: 0,
        owner: ClientId(SHELL),
        grab_window: ResourceId(GRAB_WIN),
        button: 1,
        modifiers: 0x8000,
        owner_events: false,
        event_mask: (1 << 4) | (1 << 5),
        pointer_mode: 0,
        keyboard_mode: 1,
        confine_to: ResourceId(0),
        via_xi2: true,
    });
    Backend::register_top_level(&mut backend, None, ResourceId(GRAB_WIN), HOST_XID)
        .expect("register");
    let xid_map = backend.xid_map().clone();
    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_XID,
        detail: 1,
        time: 0x1c33,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let _ = pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, press, true, false);
    assert!(
        state
            .active_pointer_grab
            .is_some_and(|grab| { grab.owner == ClientId(SHELL) && grab.passive && grab.via_xi2 })
    );

    let mut allow_body = Vec::with_capacity(8);
    allow_body.extend_from_slice(&0u32.to_le_bytes());
    allow_body.extend_from_slice(&2u16.to_le_bytes());
    allow_body.push(2); // XIReplayDevice
    allow_body.push(0);
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(SHELL),
        SequenceNumber(1),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 53,
            length_units: 3,
        },
        &allow_body,
    )
    .expect("XIAllowEvents ReplayDevice");
    assert!(
        !state
            .active_pointer_grab
            .is_some_and(|grab| grab.owner == ClientId(SHELL)),
        "ReplayDevice must deactivate the foreign passive pointer grab"
    );
    assert!(
        !state
            .active_keyboard_grab
            .is_some_and(|grab| grab.owner == ClientId(SHELL)),
        "no foreign keyboard grab is held at grab time"
    );

    let mut grab_body = Vec::with_capacity(28);
    grab_body.extend_from_slice(&APP_WIN.to_le_bytes());
    grab_body.extend_from_slice(&0u32.to_le_bytes());
    grab_body.extend_from_slice(&0u32.to_le_bytes());
    grab_body.extend_from_slice(&2u16.to_le_bytes());
    grab_body.extend_from_slice(&[1, 1, 1, 0]);
    grab_body.extend_from_slice(&1u16.to_le_bytes());
    grab_body.extend_from_slice(&[0u8; 2]);
    grab_body.extend_from_slice(&((1u32 << 4) | (1 << 5) | (1 << 6)).to_le_bytes());
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(APP),
        SequenceNumber(2),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 51,
            length_units: 8,
        },
        &grab_body,
    )
    .expect("XIGrabDevice");
    let ptr_reply = read_all_available(&mut app_peer);
    let reply_start = ptr_reply.len().saturating_sub(32);
    assert!(
        ptr_reply.len() >= 32 && ptr_reply[reply_start] == 1 && ptr_reply[reply_start + 8] == 0,
        "pointer XIGrabDevice must return Success(0), not AlreadyGrabbed(1), \
             over a foreign passive grab; got {:?}",
        &ptr_reply[..ptr_reply.len().min(12)]
    );
}

/// Pure Xorg guard: an implicit grab held by another client is still an
/// active grab and must return AlreadyGrabbed. The real MATE combo works
/// because its deeper XI2 leaf delivery attributes the implicit grab to
/// the app itself, covered by `mate_combo_implicit_grab_attributed_to_app_leaf_xi2`.
#[test]
fn xi_grab_device_over_foreign_implicit_grab_returns_already_grabbed() {
    use crate::server::ActivePointerGrab;
    const CORE_ANCESTOR: u32 = 13; // implicit-grab owner (core-first)
    const APP: u32 = 46; // the GTK app opening the combo
    const IMPLICIT_WIN: u32 = 0x0050_069b;
    const COMBO_WIN: u32 = 0x0150_0ac3;

    let mut state = ServerState::new();
    let mut app_peer = install_client(&mut state, APP);
    let _anc_peer = install_client(&mut state, CORE_ANCESTOR);
    app_peer.set_nonblocking(true).unwrap();
    let mut backend = RecordingBackend::new();

    for (client, win) in [(CORE_ANCESTOR, IMPLICIT_WIN), (APP, COMBO_WIN)] {
        state.resources.create_window(
            ClientId(client),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: ResourceId(win),
                parent: ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: crate::resources::ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(ResourceId(win));
    }

    // A core-first implicit grab attributed to the ancestor's core client.
    state.active_pointer_grab = Some(ActivePointerGrab {
        owner: ClientId(CORE_ANCESTOR),
        grab_window: ResourceId(IMPLICIT_WIN),
        event_mask: 0x000c,
        cursor: ResourceId(0),
        time: 100,
        owner_events: false,
        via_xi2: false,
        implicit: true,
        passive: false,
        xi2_mask: 0,
    });

    // The app's combo XIGrabDevice on the master pointer.
    let mut body = Vec::with_capacity(28);
    body.extend_from_slice(&COMBO_WIN.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes());
    body.extend_from_slice(&2u16.to_le_bytes());
    body.extend_from_slice(&[1, 1, 1, 0]);
    body.extend_from_slice(&1u16.to_le_bytes());
    body.extend_from_slice(&[0u8; 2]);
    body.extend_from_slice(&((1u32 << 4) | (1 << 5) | (1 << 6)).to_le_bytes());
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(APP),
        SequenceNumber(1),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 51,
            length_units: 8,
        },
        &body,
    )
    .expect("XIGrabDevice");

    assert_eq!(
        state.active_pointer_grab.map(|grab| grab.owner),
        Some(ClientId(CORE_ANCESTOR)),
        "the foreign implicit grab must remain untouched"
    );
    let reply = read_all_available(&mut app_peer);
    let reply_start = reply.len().saturating_sub(32);
    assert!(
        reply.len() >= 32 && reply[reply_start] == 1 && reply[reply_start + 8] == 1,
        "grab over a foreign implicit grab must return AlreadyGrabbed(1); got {:?}",
        &reply[..reply.len().min(12)]
    );
}

/// MATE combo regression: Xorg's `DeliverDeviceEvents` walks from the
/// leaf toward root and tries XI2 before core at each window. An XI2
/// selector on the app leaf therefore owns the implicit grab instead of
/// a core selector on its ancestor. The app's popup grab is SameClient.
#[test]
fn mate_combo_implicit_grab_attributed_to_app_leaf_xi2() {
    use crate::{
        backend::Backend,
        core_loop::pointer_fanout::pointer_event_fanout_to_state,
        host_x11::{HostPointerEvent, PointerEventKind},
        resources::ROOT_VISUAL,
    };
    const CORE_ANCESTOR: u32 = 13;
    const APP: u32 = 46;
    let parent = ResourceId(0x0050_069b); // core-ancestor selector window
    let leaf = ResourceId(0x0150_0007); // the XI2 app's window (hit)
    let combo = ResourceId(0x0150_0ac3); // the app's combo popup
    const HOST_LEAF: u32 = 0xCAFE_0001;
    const XI2_ALL_MASTER: u16 = 1;

    let mut state = ServerState::new();
    let _anc_peer = install_client(&mut state, CORE_ANCESTOR);
    let mut app_peer = install_client(&mut state, APP);
    app_peer.set_nonblocking(true).unwrap();
    let mut backend = RecordingBackend::new();

    state.resources.create_window(
        ClientId(CORE_ANCESTOR),
        yserver_protocol::x11::CreateWindowRequest {
            depth: 24,
            window: parent,
            parent: ROOT_WINDOW,
            x: 0,
            y: 0,
            width: 200,
            height: 200,
            border_width: 0,
            class: 1,
            visual: ROOT_VISUAL,
            ..Default::default()
        },
    );
    let _ = state.resources.map_window(parent);
    for (client, win, par) in [(APP, leaf, parent), (APP, combo, ROOT_WINDOW)] {
        state.resources.create_window(
            ClientId(client),
            yserver_protocol::x11::CreateWindowRequest {
                depth: 24,
                window: win,
                parent: par,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                class: 1,
                visual: ROOT_VISUAL,
                ..Default::default()
            },
        );
        let _ = state.resources.map_window(win);
    }
    // Ancestor: CORE press|release. App leaf: XI2 under XIAllMasterDevices.
    state
        .clients
        .get_mut(&CORE_ANCESTOR)
        .unwrap()
        .event_masks
        .insert(parent, 0x0000_000c);
    state
        .clients
        .get_mut(&APP)
        .unwrap()
        .xi2_masks
        .insert((leaf, XI2_ALL_MASTER), (1 << 4) | (1 << 5));
    Backend::register_top_level(&mut backend, None, leaf, HOST_LEAF).expect("register");
    let xid_map = backend.xid_map().clone();

    // Real click over the app's leaf.
    let press = HostPointerEvent {
        origin: crate::core_loop::message::InputOrigin::XTest(4),
        kind: PointerEventKind::ButtonPress,
        host_xid: HOST_LEAF,
        detail: 1,
        time: 0x7e1b,
        root_x: 10,
        root_y: 10,
        event_x: 10,
        event_y: 10,
        state: 0,
        crossing_mode: 0,
        child: 0,
        raw_dx: 0,
        raw_dy: 0,
        tree_change: false,
    };
    let _ = pointer_event_fanout_to_state(&mut state, &mut backend, &xid_map, press, true, false);
    assert_eq!(
        state.active_pointer_grab.map(|grab| grab.owner),
        Some(ClientId(APP)),
        "the deeper XI2 leaf delivery must own the implicit grab"
    );
    assert!(
        state
            .active_pointer_grab
            .is_some_and(|grab| grab.implicit && grab.via_xi2)
    );
    let _ = read_all_available(&mut app_peer);

    // The app opens its combo → XIGrabDevice on the master pointer.
    let mut body = Vec::with_capacity(28);
    body.extend_from_slice(&combo.0.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes());
    body.extend_from_slice(&0u32.to_le_bytes());
    body.extend_from_slice(&2u16.to_le_bytes());
    body.extend_from_slice(&[1, 1, 1, 0]);
    body.extend_from_slice(&1u16.to_le_bytes());
    body.extend_from_slice(&[0u8; 2]);
    body.extend_from_slice(&((1u32 << 4) | (1 << 5) | (1 << 6)).to_le_bytes());
    handle_xi2_request(
        &mut state,
        &mut backend,
        None,
        ClientId(APP),
        SequenceNumber(1),
        yserver_protocol::x11::RequestHeader {
            opcode: 131,
            data: 51,
            length_units: 8,
        },
        &body,
    )
    .expect("XIGrabDevice");

    assert_eq!(
        state
            .active_pointer_grab
            .map(|grab| (grab.owner, grab.grab_window)),
        Some((ClientId(APP), combo)),
        "the app's SameClient XIGrabDevice must replace its implicit grab"
    );
    let reply = read_all_available(&mut app_peer);
    let reply_start = reply.len().saturating_sub(32);
    assert!(
        reply.len() >= 32 && reply[reply_start] == 1 && reply[reply_start + 8] == 0,
        "combo grab reply must be Success (0), not AlreadyGrabbed (1); got {:?}",
        &reply[..reply.len().min(12)]
    );
}

#[test]
fn present_async_may_tear_bit_is_0x10() {
    // presenttokens.h: PresentOptionAsyncMayTear = (1 << 4).
    assert_eq!(0x10u32, 1u32 << 4);
    // Stripping AsyncMayTear must NOT strip Suboptimal (0x8) or Async (0x1).
    let opts = 0x1 | 0x8 | 0x10;
    assert_eq!(opts & !0x10u32, 0x1 | 0x8);
}

#[test]
fn xkb_get_kbd_by_name_also_broadcasts_legacy_mapping_notify() {
    // Real `setxkbmap` loads a layout via XkbGetKeyboardByName (minor
    // 23), not by writing `_XKB_RULES_NAMES`. A plain-X11 client (any
    // WM that never calls XkbSelectEvents and only understands core
    // events — e.g. one resolving keybinds via XKeysymToKeycode once
    // at startup) relies on the legacy MappingNotify event to know
    // when to re-resolve its keysym-based key grabs. Without it, the
    // WM's shortcuts stay bound to the pre-switch keycodes forever
    // even though per-keystroke translation (and thus typing) already
    // reflects the new layout.
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    // Stale ChangeKeyboardMapping row from before the switch — must
    // not keep shadowing the freshly loaded keymap either.
    state.keymap_overrides.insert(38, vec![0x0071]);

    let mut reply = vec![0u8; 32];
    reply[0] = 1; // X_Reply
    assert!(crate::core_loop::xkb_select::use_extension(
        &mut state,
        ClientId(1),
        &[1, 0, 0, 0]
    ));
    let mut backend = RecordingBackend::new().with_kbd_by_name_result(
        reply,
        Some(crate::backend::XkbNewKeyboardInfo {
            min_keycode: 8,
            max_keycode: 255,
            old_min_keycode: 8,
            old_max_keycode: 255,
            changed: 0x0001,
        }),
    );

    handle_xkb_request(
        &mut state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(1),
        RequestHeader {
            opcode: 136,
            data: 23,
            length_units: 2,
        },
        &[],
    )
    .expect("XkbGetKbdByName");

    assert!(
        state.keymap_overrides.is_empty(),
        "a full XkbGetKeyboardByName load must drop stale ChangeKeyboardMapping rows too"
    );

    let bytes = read_all_available(&mut peer);
    let mapping_notify_count = bytes
        .chunks(32)
        .filter(
            |chunk| chunk.len() == 32 && chunk[0] == 34, /* MappingNotify */
        )
        .count();
    assert!(
        mapping_notify_count >= 2,
        "expected legacy MappingNotify(Keyboard) + MappingNotify(Modifier) \
             alongside XkbNewKeyboardNotify, got {mapping_notify_count} in {bytes:02x?}"
    );
    let keyboard_mapping_notify = bytes
        .chunks(32)
        .find(|chunk| chunk.len() == 32 && chunk[0] == 34 && chunk[4] == 1);
    assert!(
        keyboard_mapping_notify.is_some(),
        "expected a MappingNotify with request=Keyboard(1): {bytes:02x?}"
    );
}

fn xkb_request(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    client: u32,
    minor: u8,
    body: &[u8],
) {
    handle_xkb_request(
        state,
        backend,
        None,
        ClientId(client),
        SequenceNumber(1),
        RequestHeader {
            opcode: 136,
            data: minor,
            length_units: u32::try_from(1 + body.len().div_ceil(4)).unwrap(),
        },
        body,
    )
    .expect("XKB request");
}

/// Xvfb 21.1.24, XkbUseExtension(1, 0) at sequence 2 from a
/// little-endian client: `01010200 00000000 01000000 00…`
/// (supported, server 1.0).
#[test]
fn xkb_use_extension_replies_like_xorg() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    handle_xkb_request(
        &mut state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(2),
        RequestHeader {
            opcode: 136,
            data: 0,
            length_units: 2,
        },
        &[1, 0, 0, 0],
    )
    .expect("XkbUseExtension");
    let reply = read_all_available(&mut peer);
    let mut expected = [0u8; 32];
    expected[..10].copy_from_slice(&[1, 1, 2, 0, 0, 0, 0, 0, 1, 0]);
    assert_eq!(reply, expected);
    assert!(crate::core_loop::xkb_select::xkb_initialized(
        &state,
        ClientId(1)
    ));
}

/// yserver's XKB request parsers and reply encoders are little-endian
/// only, so a big-endian client is refused the way Xorg refuses a
/// client it can't serve: XkbUseExtension answers supported=False
/// (the bytes are Xvfb's big-endian answer to an unsupported version,
/// `01000002 00000000 00010000 00…`), and every other XKB request is
/// then BadAccess, as Xorg answers an uninitialised client (Xvfb:
/// GetState → BadAccess, value 0, minor 4). All of it in the client's
/// byte order.
#[test]
fn xkb_refuses_big_endian_clients_cleanly() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    state.clients.get_mut(&1).unwrap().byte_order = ClientByteOrder::BigEndian;
    // XKB request bodies are not swapped: wantedMajor=1, wantedMinor=0
    // as a big-endian client sends them.
    handle_xkb_request(
        &mut state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(2),
        RequestHeader {
            opcode: 136,
            data: 0,
            length_units: 2,
        },
        &[0, 1, 0, 0],
    )
    .expect("XkbUseExtension");
    let reply = read_all_available(&mut peer);
    let mut expected = [0u8; 32];
    expected[..10].copy_from_slice(&[1, 0, 0, 2, 0, 0, 0, 0, 0, 1]);
    assert_eq!(reply, expected);
    assert!(!crate::core_loop::xkb_select::xkb_initialized(
        &state,
        ClientId(1)
    ));
    handle_xkb_request(
        &mut state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(3),
        RequestHeader {
            opcode: 136,
            data: 4,
            length_units: 2,
        },
        &[1, 0, 0, 0],
    )
    .expect("XkbGetState");
    let err = read_all_available(&mut peer);
    assert_eq!(err.len(), 32);
    assert_eq!((err[0], err[1]), (0, x11::error::BAD_ACCESS));
    assert_eq!(&err[2..4], &[0, 3], "big-endian sequence");
    assert_eq!(&err[8..10], &[0, 4], "big-endian minor opcode");
}

/// Golden (`xorg-xkb-setmap-errors.txt`, Xvfb 21.1.24: `access`,
/// `access-getmap`, `access-selectevents`): an XKB request from a client
/// that never called XkbUseExtension answers BadAccess (value 0, minor =
/// the request's), and changes nothing; after UseExtension the same
/// requests go through.
#[test]
fn xkb_requests_need_use_extension() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let select_all = [0x00, 0x01, 0xff, 0x0f, 0, 0, 0xff, 0x0f, 0xff, 0, 0xff, 0];
    for (minor, body) in [
        (8u8, vec![0u8; 24]),
        (1, select_all.to_vec()),
        (9, vec![0; 32]),
    ] {
        xkb_request(&mut state, &mut backend, 1, minor, &body);
        let err = read_all_available(&mut peer);
        assert_eq!(err.len(), 32, "minor {minor}: one error");
        assert_eq!(
            (err[0], err[1], &err[4..8], err[8], err[10]),
            (0, x11::error::BAD_ACCESS, &[0u8, 0, 0, 0][..], minor, 136),
            "minor {minor}"
        );
    }
    assert!(
        state
            .xkb_clients
            .get(&1)
            .is_none_or(|c| c.map_notify_mask == 0)
    );
    xkb_request(&mut state, &mut backend, 1, 0, &[1, 0, 0, 0]);
    assert!(crate::core_loop::xkb_select::xkb_initialized(
        &state,
        ClientId(1)
    ));
    let _ = read_all_available(&mut peer);
    xkb_request(&mut state, &mut backend, 1, 1, &select_all);
    assert!(
        read_all_available(&mut peer).is_empty(),
        "SelectEvents: no error"
    );
    assert_eq!(state.xkb_clients[&1].map_notify_mask, 0xff);
}

/// `ProcXkbUseExtension`: an unsupported version (2.0) leaves the client
/// uninitialised.
#[test]
fn xkb_use_extension_unsupported_version_stays_uninitialised() {
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    xkb_request(&mut state, &mut backend, 1, 0, &[2, 0, 0, 0]);
    assert!(!crate::core_loop::xkb_select::xkb_initialized(
        &state,
        ClientId(1)
    ));
}

/// `XkbSendLegacyMapNotify` (xkb/xkbEvents.c): a MapNotify's core
/// MappingNotify goes to non-XKB clients and to XKB clients whose map
/// details include a change; a NewKeyboardNotify's only to non-XKB
/// clients.
#[test]
fn legacy_map_notify_filters_xkb_clients() {
    use crate::core_loop::xkb_select::{
        LegacyCause, send_legacy_core_map_notify, xkb_select_events,
    };
    let mut state = ServerState::new();
    let mut plain = install_client(&mut state, 1);
    let mut xkb_keysyms = install_client(&mut state, 2);
    let mut xkb_none = install_client(&mut state, 3);
    xkb_select_events(&mut state, 2, 0x100, 0x0002);
    xkb_select_events(&mut state, 3, 0x100, 0x0004);
    let _ = send_legacy_core_map_notify(&mut state, LegacyCause::MapNotify, 0x0002, 8, 248);
    let count = |b: Vec<u8>| b.chunks(32).filter(|e| e[0] == 34).count();
    assert_eq!(count(read_all_available(&mut plain)), 1);
    assert_eq!(count(read_all_available(&mut xkb_keysyms)), 1);
    assert_eq!(count(read_all_available(&mut xkb_none)), 0);
    let _ = send_legacy_core_map_notify(&mut state, LegacyCause::NewKeyboardNotify, 0x0001, 8, 248);
    assert_eq!(
        count(read_all_available(&mut plain)),
        2,
        "Keyboard + Modifier"
    );
    assert_eq!(count(read_all_available(&mut xkb_keysyms)), 0);
    assert_eq!(count(read_all_available(&mut xkb_none)), 0);
}

// ── Step 3 (window-storage lifecycle): Pictures on windows ──────────

const PIC_A: u32 = 0x0030_0000;
const PIC_B: u32 = 0x0040_0000;
const PIC_WIN: u32 = PIC_A | 1;
const PIC_WIN_HOST: u32 = 0x00E0_0001;
const PIC_ON_WIN: u32 = PIC_B | 1;
const PIC_PIXMAP: u32 = PIC_B | 2;
const PIC_ON_PIXMAP: u32 = PIC_B | 3;

fn picture_request(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    client: u32,
    opcode: u8,
    data: u8,
    body: &[u8],
) {
    process_request(
        state,
        backend,
        ClientId(client),
        SequenceNumber(1),
        RequestHeader {
            opcode,
            data,
            length_units: u32::try_from(1 + body.len().div_ceil(4)).unwrap(),
        },
        body,
        None,
    )
    .unwrap();
}

/// `(error code, bad value)` of every error queued on `peer`.
fn drain_errors(peer: &mut UnixStream) -> Vec<(u8, u32)> {
    peer.set_nonblocking(true).unwrap();
    let mut out = Vec::new();
    let mut buf = [0u8; 32];
    while peer.read_exact(&mut buf).is_ok() {
        if buf[0] == 0 {
            out.push((buf[1], u32::from_le_bytes([buf[4], buf[5], buf[6], buf[7]])));
        }
    }
    out
}

fn create_render_picture(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    client: u32,
    pic: u32,
    drawable: u32,
) {
    let mut body = Vec::new();
    for v in [pic, drawable, 0, 0] {
        body.extend_from_slice(&v.to_le_bytes());
    }
    picture_request(state, backend, client, 133, 4, &body);
}

fn render_fill(state: &mut ServerState, backend: &mut RecordingBackend, client: u32, dst: u32) {
    let mut body = vec![1u8, 0, 0, 0];
    body.extend_from_slice(&dst.to_le_bytes());
    body.extend_from_slice(&[0xff; 8]);
    for v in [0i16, 0] {
        body.extend_from_slice(&v.to_le_bytes());
    }
    for v in [8u16, 8] {
        body.extend_from_slice(&v.to_le_bytes());
    }
    picture_request(state, backend, client, 133, 26, &body);
}

fn render_composite_pics(
    state: &mut ServerState,
    backend: &mut RecordingBackend,
    client: u32,
    src: u32,
    dst: u32,
) {
    let mut body = vec![0u8; 32];
    body[0] = 3;
    body[4..8].copy_from_slice(&src.to_le_bytes());
    body[12..16].copy_from_slice(&dst.to_le_bytes());
    body[28..30].copy_from_slice(&8u16.to_le_bytes());
    body[30..32].copy_from_slice(&8u16.to_le_bytes());
    picture_request(state, backend, client, 133, 8, &body);
}

fn render_free(state: &mut ServerState, backend: &mut RecordingBackend, client: u32, pic: u32) {
    picture_request(state, backend, client, 133, 7, &pic.to_le_bytes());
}

fn host_pic_of(state: &ServerState, pic: u32) -> u32 {
    state
        .resources
        .picture(ResourceId(pic))
        .expect("picture exists")
        .host_picture_xid
        .expect("backed picture")
        .as_raw()
}

fn render_paints(backend: &RecordingBackend) -> Vec<RecordedCall> {
    backend
        .calls()
        .into_iter()
        .filter(|c| {
            matches!(
                c,
                RecordedCall::RenderComposite { .. } | RecordedCall::RenderFillRectangles { .. }
            )
        })
        .collect()
}

/// Client A owns a mapped top-level `PIC_WIN`; client B holds a Picture on it and
/// one on its own pixmap.
fn cross_client_picture_fixture() -> (ServerState, RecordingBackend, UnixStream, UnixStream) {
    let mut state = ServerState::new();
    let peer_a = install_client(&mut state, 1);
    let peer_b = install_client(&mut state, 2);
    let mut backend = RecordingBackend::new();
    create_pic_test_window(&mut state, PIC_WIN, PIC_WIN_HOST);
    state.resources.create_pixmap(
        ClientId(2),
        CreatePixmapRequest {
            pixmap: ResourceId(PIC_PIXMAP),
            drawable: ROOT_WINDOW,
            width: 16,
            height: 16,
            depth: 24,
        },
    );
    assert!(state.resources.set_pixmap_host_xid(
        ResourceId(PIC_PIXMAP),
        crate::backend::PixmapHandle::from_raw_for_test(0x00E0_0100),
    ));
    create_render_picture(&mut state, &mut backend, 2, PIC_ON_WIN, PIC_WIN);
    create_render_picture(&mut state, &mut backend, 2, PIC_ON_PIXMAP, PIC_PIXMAP);
    (state, backend, peer_a, peer_b)
}

fn create_pic_test_window(state: &mut ServerState, xid: u32, host: u32) {
    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(xid),
            parent: ROOT_WINDOW,
            width: 64,
            height: 64,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    state
        .resources
        .window_mut(ResourceId(xid))
        .unwrap()
        .host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(host));
    let _ = state.resources.map_window(ResourceId(xid));
}

/// B's Picture on A's window is dead once the window is gone: every use and
/// its FreePicture are BadPicture, its pixmap Picture is untouched, and a new
/// window on the same xid and host storage does not revive it.
fn assert_window_picture_dead_after(destroy: impl FnOnce(&mut ServerState, &mut RecordingBackend)) {
    let bad_picture = crate::nested::RENDER_FIRST_ERROR + 1;
    let (mut state, mut backend, _peer_a, mut peer_b) = cross_client_picture_fixture();
    let host_on_win = host_pic_of(&state, PIC_ON_WIN);
    let host_on_pixmap = host_pic_of(&state, PIC_ON_PIXMAP);

    destroy(&mut state, &mut backend);

    assert!(state.resources.picture(ResourceId(PIC_ON_WIN)).is_none());
    let freed: Vec<u32> = backend
        .calls()
        .into_iter()
        .filter_map(|c| match c {
            RecordedCall::RenderFreePicture { host_pic } => Some(host_pic),
            _ => None,
        })
        .collect();
    assert_eq!(
        freed,
        vec![host_on_win],
        "only the window Picture's backend record is freed"
    );
    assert_eq!(host_pic_of(&state, PIC_ON_PIXMAP), host_on_pixmap);
    backend.calls.lock().unwrap().clear();

    create_pic_test_window(&mut state, PIC_WIN, PIC_WIN_HOST);
    render_fill(&mut state, &mut backend, 2, PIC_ON_WIN);
    render_composite_pics(&mut state, &mut backend, 2, PIC_ON_WIN, PIC_ON_PIXMAP);
    render_free(&mut state, &mut backend, 2, PIC_ON_WIN);
    assert_eq!(
        drain_errors(&mut peer_b),
        vec![(bad_picture, PIC_ON_WIN); 3],
        "FillRectangles, Composite and FreePicture on the dead Picture",
    );
    assert!(render_paints(&backend).is_empty());
    assert!(
        !backend
            .calls()
            .iter()
            .any(|c| matches!(c, RecordedCall::RenderFreePicture { .. }))
    );

    render_fill(&mut state, &mut backend, 2, PIC_ON_PIXMAP);
    assert_eq!(
        render_paints(&backend),
        vec![RecordedCall::RenderFillRectangles {
            host_dst: host_on_pixmap
        }],
    );
    assert!(drain_errors(&mut peer_b).is_empty());
}

#[test]
fn destroy_window_frees_other_clients_pictures_on_it() {
    assert_window_picture_dead_after(|state, backend| {
        picture_request(state, backend, 1, 4, 0, &PIC_WIN.to_le_bytes());
    });
}

#[test]
fn owner_disconnect_frees_other_clients_pictures_on_its_windows() {
    assert_window_picture_dead_after(|state, backend| {
        crate::core_loop::process_disconnect::process_disconnect(state, backend, ClientId(1));
        let _peer = install_client(state, 1);
    });
}

#[test]
fn destroying_a_parent_frees_pictures_on_its_descendants() {
    let (mut state, mut backend, _peer_a, mut peer_b) = cross_client_picture_fixture();
    const CHILD: u32 = PIC_A | 2;
    const PIC_ON_CHILD: u32 = PIC_B | 4;
    state.resources.create_window(
        ClientId(1),
        CreateWindowRequest {
            depth: 24,
            window: ResourceId(CHILD),
            parent: ResourceId(PIC_WIN),
            width: 8,
            height: 8,
            class: 1,
            visual: crate::resources::ROOT_VISUAL,
            ..Default::default()
        },
    );
    state
        .resources
        .window_mut(ResourceId(CHILD))
        .unwrap()
        .host_xid = Some(crate::backend::WindowHandle::from_raw_for_test(0x00E0_0002));
    create_render_picture(&mut state, &mut backend, 2, PIC_ON_CHILD, CHILD);
    assert!(state.resources.picture(ResourceId(PIC_ON_CHILD)).is_some());

    picture_request(&mut state, &mut backend, 1, 4, 0, &PIC_WIN.to_le_bytes());

    assert!(state.resources.picture(ResourceId(PIC_ON_CHILD)).is_none());
    assert!(state.resources.picture(ResourceId(PIC_ON_WIN)).is_none());
    assert!(state.resources.picture(ResourceId(PIC_ON_PIXMAP)).is_some());
    assert!(drain_errors(&mut peer_b).is_empty());
}

/// Xorg: an unviewable window's clipList is empty, so a Picture on it as the
/// destination draws nothing; the same Picture draws again after remap.
#[test]
fn window_picture_draws_nothing_while_unmapped_and_again_after_remap() {
    let (mut state, mut backend, _peer_a, mut peer_b) = cross_client_picture_fixture();
    let host_on_win = host_pic_of(&state, PIC_ON_WIN);
    let host_on_pixmap = host_pic_of(&state, PIC_ON_PIXMAP);
    let fill = RecordedCall::RenderFillRectangles {
        host_dst: host_on_win,
    };

    render_fill(&mut state, &mut backend, 2, PIC_ON_WIN);
    assert_eq!(render_paints(&backend), vec![fill.clone()]);
    backend.calls.lock().unwrap().clear();

    picture_request(&mut state, &mut backend, 1, 10, 0, &PIC_WIN.to_le_bytes());
    render_fill(&mut state, &mut backend, 2, PIC_ON_WIN);
    render_composite_pics(&mut state, &mut backend, 2, PIC_ON_PIXMAP, PIC_ON_WIN);
    assert!(
        render_paints(&backend).is_empty(),
        "unmapped: nothing drawn"
    );
    // As a source the hidden window's contents are undefined, not an error.
    render_composite_pics(&mut state, &mut backend, 2, PIC_ON_WIN, PIC_ON_PIXMAP);
    assert_eq!(
        render_paints(&backend),
        vec![RecordedCall::RenderComposite {
            host_src: host_on_win,
            host_dst: host_on_pixmap,
        }],
    );
    backend.calls.lock().unwrap().clear();

    picture_request(&mut state, &mut backend, 1, 8, 0, &PIC_WIN.to_le_bytes());
    render_fill(&mut state, &mut backend, 2, PIC_ON_WIN);
    assert_eq!(render_paints(&backend), vec![fill]);
    assert!(drain_errors(&mut peer_b).is_empty());
}

/// A Picture on a redirected window names the window, not the backing it
/// has at creation time, so it follows backing rotations.
#[test]
fn create_picture_on_redirected_window_names_the_window() {
    let mut state = ServerState::new();
    let _peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    create_pic_test_window(&mut state, PIC_WIN, PIC_WIN_HOST);
    state
        .resources
        .window_mut(ResourceId(PIC_WIN))
        .unwrap()
        .redirected_backing = Some(crate::resources::RedirectedBacking {
        host_pixmap: crate::backend::PixmapHandle::from_raw_for_test(0x00E0_0200),
        width: 64,
        height: 64,
        depth: 24,
    });
    create_render_picture(&mut state, &mut backend, 1, PIC_A | 5, PIC_WIN);
    let host_drawables: Vec<crate::backend::AnyHandle> = backend
        .calls()
        .into_iter()
        .filter_map(|c| match c {
            RecordedCall::RenderCreatePicture { host_drawable, .. } => Some(host_drawable),
            _ => None,
        })
        .collect();
    assert_eq!(
        host_drawables,
        vec![crate::backend::AnyHandle::Window(
            crate::backend::WindowHandle::from_raw_for_test(PIC_WIN_HOST)
        )],
    );
    assert_eq!(
        state
            .resources
            .picture(ResourceId(PIC_A | 5))
            .unwrap()
            .window,
        Some(ResourceId(PIC_WIN)),
    );
}

/// Xorg `compDestroyOverlayWindow` frees the overlay through DeleteWindow, so
/// Pictures on it are freed with it (`composite/compoverlay.c:167-172`).
#[test]
fn overlay_release_frees_pictures_on_the_overlay() {
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let cow = crate::resources::COMPOSITE_OVERLAY_WINDOW;
    let mut body = vec![0u8; 4];
    body[0..4].copy_from_slice(&ROOT_WINDOW.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        1,
        yserver_protocol::x11::composite::GET_OVERLAY_WINDOW,
        &body,
    );
    drain_errors(&mut peer);
    create_render_picture(&mut state, &mut backend, 1, PIC_A | 6, cow.0);
    assert!(state.resources.picture(ResourceId(PIC_A | 6)).is_some());
    body[0..4].copy_from_slice(&cow.0.to_le_bytes());
    dispatch_composite_minor(
        &mut state,
        &mut backend,
        ClientId(1),
        2,
        yserver_protocol::x11::composite::RELEASE_OVERLAY_WINDOW,
        &body,
    );
    assert!(state.resources.window(cow).is_none());
    assert!(state.resources.picture(ResourceId(PIC_A | 6)).is_none());
}

/// CreateConicalGradient registers a Picture: usable as a source without an
/// error (drawing with it stays unimplemented) and freeable.
#[test]
fn conical_gradient_picture_is_usable_as_source_and_freeable() {
    let (mut state, mut backend, _peer_a, mut peer_b) = cross_client_picture_fixture();
    const CONICAL: u32 = PIC_B | 9;
    let mut body = Vec::new();
    body.extend_from_slice(&CONICAL.to_le_bytes());
    body.extend_from_slice(&[0u8; 16]); // center, angle, nstops = 0
    picture_request(&mut state, &mut backend, 2, 133, 36, &body);
    assert!(state.resources.picture(ResourceId(CONICAL)).is_some());
    backend.calls.lock().unwrap().clear();
    render_composite_pics(&mut state, &mut backend, 2, CONICAL, PIC_ON_PIXMAP);
    assert!(
        render_paints(&backend).is_empty(),
        "unbacked source draws nothing"
    );
    render_free(&mut state, &mut backend, 2, CONICAL);
    assert!(state.resources.picture(ResourceId(CONICAL)).is_none());
    assert!(drain_errors(&mut peer_b).is_empty());
}

/// A CreatePicture the backend could not back still succeeds at protocol level:
/// ops on the Picture are silent no-ops and FreePicture is valid. An id that was
/// never created is still BadPicture.
#[test]
fn unbacked_picture_ops_are_silent_no_ops() {
    let (mut state, mut backend, _peer_a, mut peer_b) = cross_client_picture_fixture();
    const UNBACKED: u32 = PIC_B | 10;
    backend.render_create_picture_fails = true;
    create_render_picture(&mut state, &mut backend, 2, UNBACKED, PIC_PIXMAP);
    backend.render_create_picture_fails = false;
    let st = state
        .resources
        .picture(ResourceId(UNBACKED))
        .expect("registered");
    assert!(st.host_picture_xid.is_none());
    backend.calls.lock().unwrap().clear();

    render_fill(&mut state, &mut backend, 2, UNBACKED);
    render_composite_pics(&mut state, &mut backend, 2, UNBACKED, PIC_ON_PIXMAP);
    render_composite_pics(&mut state, &mut backend, 2, PIC_ON_PIXMAP, UNBACKED);
    render_free(&mut state, &mut backend, 2, UNBACKED);
    assert!(drain_errors(&mut peer_b).is_empty());
    assert!(state.resources.picture(ResourceId(UNBACKED)).is_none());
    assert!(backend.calls().iter().all(|c| !matches!(
        c,
        RecordedCall::RenderComposite { .. }
            | RecordedCall::RenderFillRectangles { .. }
            | RecordedCall::RenderFreePicture { .. }
    )));

    const NEVER: u32 = PIC_B | 11;
    render_fill(&mut state, &mut backend, 2, NEVER);
    assert_eq!(
        drain_errors(&mut peer_b),
        vec![(crate::nested::RENDER_FIRST_ERROR + 1, NEVER)],
    );
}

/// Xorg dixLookupDrawable: CreatePicture on an unknown drawable is BadDrawable
/// and registers nothing.
#[test]
fn create_picture_on_unknown_drawable_is_bad_drawable() {
    let (mut state, mut backend, _peer_a, mut peer_b) = cross_client_picture_fixture();
    const PIC: u32 = PIC_B | 12;
    create_render_picture(&mut state, &mut backend, 2, PIC, 0x00DE_AD00);
    assert_eq!(
        drain_errors(&mut peer_b),
        vec![(x11::error::BAD_DRAWABLE, 0x00DE_AD00)],
    );
    assert!(state.resources.picture(ResourceId(PIC)).is_none());
}

/// GDK clips a native child of a client-side window with its bounding
/// shape and shifts the shape when it scrolls. Xorg's `miSetShape`
/// (`mi/miwindow.c:637-677`) then exposes what the window no longer
/// covers to its parent and what it newly covers to itself — the
/// parent's button bar is repainted only on that Expose. Measured on
/// Xorg 21.1 by tools/vng-scenarios/child-clip-probe.c: the shape
/// (0,0 170x60) of V at (10,10) becoming (0,30 170x60) exposes
/// P 10,10 170x30 and V 0,60 170x30.
#[test]
fn bounding_shape_change_exposes_what_it_uncovers_and_covers() {
    use yserver_protocol::x11::{shape as x11shape, xfixes::RegionRect};
    let mut state = ServerState::new();
    let mut peer = install_client(&mut state, 1);
    let mut backend = RecordingBackend::new();
    let (p, v) = (ResourceId(0x1c0_0001), ResourceId(0x1c0_0002));
    seed_window(&mut state, p, ROOT_WINDOW, 190, 100);
    seed_window(&mut state, v, p, 170, 120);
    for w in [p, v] {
        state.resources.window_mut(w).unwrap().map_state = crate::resources::MapState::Viewable;
    }
    let vw = state.resources.window_mut(v).unwrap();
    (vw.x, vw.y) = (10, 10);
    crate::nested::set_shape_rects(
        &mut state,
        v,
        x11shape::KIND_BOUNDING,
        vec![RegionRect {
            x: 0,
            y: 0,
            width: 170,
            height: 60,
        }],
    );
    let client = state.clients.get_mut(&1).unwrap();
    client.event_masks.insert(p, 0x0000_8000);
    client.event_masks.insert(v, 0x0000_8000);

    // RECTANGLES body: op kind ordering pad dest(4) x_off(2) y_off(2) rects.
    let mut body = vec![x11shape::OP_SET, x11shape::KIND_BOUNDING, 0, 0];
    body.extend_from_slice(&v.0.to_le_bytes());
    body.extend_from_slice(&[0; 4]);
    for field in [0u16, 30, 170, 60] {
        body.extend_from_slice(&field.to_le_bytes());
    }
    let header = yserver_protocol::x11::RequestHeader {
        opcode: 129,
        data: x11shape::RECTANGLES,
        length_units: 6,
    };
    handle_shape_request(
        &mut state,
        &mut backend,
        None,
        ClientId(1),
        SequenceNumber(1),
        header,
        &body,
    )
    .expect("ShapeRectangles");

    let exposes: Vec<(u32, [u16; 4])> = read_all_available(&mut peer)
        .chunks_exact(32)
        .filter(|e| e[0] & 0x7f == 12)
        .map(|e| {
            let at = |i: usize| u16::from_le_bytes([e[i], e[i + 1]]);
            (
                u32::from_le_bytes([e[4], e[5], e[6], e[7]]),
                [at(8), at(10), at(12), at(14)],
            )
        })
        .collect();
    assert_eq!(
        exposes,
        vec![(p.0, [10, 10, 170, 30]), (v.0, [0, 60, 170, 30])]
    );
}
